#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;

public static class PossedeCreateMenu
{
    [MenuItem("GameObject/Possede/Item Spawn Point", false, 10)]
    private static void CreateItemSpawnPoint(MenuCommand menuCommand)
    {
        var go = new GameObject("ItemSpawnPoint");

        // Parent (si clic droit sur un parent dans la Hierarchy)
        GameObjectUtility.SetParentAndAlign(go, menuCommand.context as GameObject);

        // Ajoute tes composants
        go.AddComponent<PropSpawnPoint>();

        // (Optionnel) layer automatique si tu as un layer "Interactable"
        int layer = LayerMask.NameToLayer("Interactable");
        if (layer != -1) go.layer = layer;

        // Undo + s�lection
        Undo.RegisterCreatedObjectUndo(go, "Create Item Spawn Point");
        Selection.activeGameObject = go;
    }
}
