#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;
using System.Linq;

public static class PossedeEnsureHitboxTool
{
    [MenuItem("Tools/Possede/Ensure Interaction Hitbox On Spawn Prefabs")]
    private static void EnsureHitboxOnPrefabs()
    {
        // Si tu s�lectionnes des spawnpoints -> on ne traite que ceux-l�
        var selectedSpawnPoints = Selection.gameObjects
            .SelectMany(go => go.GetComponentsInChildren<PropSpawnPoint>(true))
            .ToArray();

        var spawnPoints = selectedSpawnPoints.Length > 0
            ? selectedSpawnPoints
            : Object.FindObjectsOfType<PropSpawnPoint>(true);

        int changed = 0;

        foreach (var sp in spawnPoints)
        {
            if (sp == null || sp.options == null) continue;

            foreach (var opt in sp.options)
            {
                if (opt == null || opt.prefab == null) continue;

                // On veut modifier L�ASSET prefab, pas une instance
                var prefabRoot = PrefabUtility.GetCorrespondingObjectFromSource(opt.prefab) ?? opt.prefab;
                if (!PrefabUtility.IsPartOfPrefabAsset(prefabRoot)) continue;

                var path = AssetDatabase.GetAssetPath(prefabRoot);
                if (string.IsNullOrEmpty(path)) continue;

                var contentsRoot = PrefabUtility.LoadPrefabContents(path);
                if (contentsRoot == null) continue;

                bool dirty = false;

                // 1) PropPickup (si tu veux garantir qu�il existe)
                if (contentsRoot.GetComponent<PropPickup>() == null)
                {
                    contentsRoot.AddComponent<PropPickup>();
                    dirty = true;
                }

                // 2) Hitbox interaction
                var hitbox = contentsRoot.GetComponent<PropPickupInteractionHitbox>();
                if (hitbox == null)
                {
                    hitbox = contentsRoot.AddComponent<PropPickupInteractionHitbox>();
                    // Valeur par d�faut (adapte si tu veux)
                    hitbox.minSize = 0.2f; // au lieu de 0.6f
                    dirty = true;
                }

                if (dirty)
                {
                    PrefabUtility.SaveAsPrefabAsset(contentsRoot, path);
                    changed++;
                }

                PrefabUtility.UnloadPrefabContents(contentsRoot);
            }
        }

        Debug.Log($"[Possede] Ensure Hitbox: modified {changed} prefab(s).");
    }
}
