#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;

[CustomEditor(typeof(PropSpawnPoint))]
public class PropSpawnPointEditor : Editor
{
    private const string PreviewRootName = "__PROP_SPAWN_PREVIEW__";

    private SerializedProperty _optionsProp;
    private SerializedProperty _previewEnabledProp;
    private SerializedProperty _previewIndexProp;

    private void OnEnable()
    {
        _optionsProp = serializedObject.FindProperty("options");
        _previewEnabledProp = serializedObject.FindProperty("editorPreviewEnabled");
        _previewIndexProp = serializedObject.FindProperty("editorPreviewIndex");

        UpdatePreviewInstance();
    }

    private void OnDisable()
    {
        CleanupPreviewInstance();
    }

    public override void OnInspectorGUI()
    {
        serializedObject.Update();

        // Inspector normal
        DrawDefaultInspector();

        EditorGUILayout.Space(12);
        EditorGUILayout.LabelField("Editor Preview", EditorStyles.boldLabel);

        if (_optionsProp == null || _optionsProp.arraySize == 0)
        {
            EditorGUILayout.HelpBox("Aucune option à prévisualiser.", MessageType.Info);
            serializedObject.ApplyModifiedProperties();
            CleanupPreviewInstance();
            return;
        }

        EditorGUILayout.PropertyField(_previewEnabledProp, new GUIContent("Preview Enabled"));
        using (new EditorGUI.DisabledScope(!_previewEnabledProp.boolValue))
        {
            int max = Mathf.Max(0, _optionsProp.arraySize - 1);
            _previewIndexProp.intValue = Mathf.Clamp(_previewIndexProp.intValue, 0, max);

            EditorGUILayout.BeginHorizontal();
            if (GUILayout.Button("◀", GUILayout.Width(30)))
                _previewIndexProp.intValue = Mathf.Max(0, _previewIndexProp.intValue - 1);

            EditorGUILayout.IntSlider(_previewIndexProp, 0, max, new GUIContent("Preview Index"));

            if (GUILayout.Button("▶", GUILayout.Width(30)))
                _previewIndexProp.intValue = Mathf.Min(max, _previewIndexProp.intValue + 1);
            EditorGUILayout.EndHorizontal();

            if (GUILayout.Button("Refresh Preview"))
                UpdatePreviewInstance();
        }

        serializedObject.ApplyModifiedProperties();

        // Met à jour le preview si changement
        if (GUI.changed)
            UpdatePreviewInstance();
    }

    public void OnSceneGUI()
    {
        var sp = (PropSpawnPoint)target;
        if (sp == null) return;

        if (!sp.editorPreviewEnabled) return;
        if (sp.options == null || sp.options.Count == 0) return;

        int idx = Mathf.Clamp(sp.editorPreviewIndex, 0, sp.options.Count - 1);
        var opt = sp.options[idx];
        if (opt == null || opt.prefab == null) return;

        // Position handle (offset local)
        EditorGUI.BeginChangeCheck();
        Vector3 worldPos = sp.transform.TransformPoint(opt.positionOffset);
        Vector3 newWorldPos = Handles.PositionHandle(worldPos, GetWorldRotation(sp, opt));
        if (EditorGUI.EndChangeCheck())
        {
            Undo.RecordObject(sp, "Move Spawn Option Offset");
            opt.positionOffset = sp.transform.InverseTransformPoint(newWorldPos);
            EditorUtility.SetDirty(sp);
            UpdatePreviewInstance();
        }

        // Rotation handle (offset euler)
        EditorGUI.BeginChangeCheck();
        Quaternion worldRot = GetWorldRotation(sp, opt);
        Quaternion newWorldRot = Handles.RotationHandle(worldRot, newWorldPos);
        if (EditorGUI.EndChangeCheck())
        {
            Undo.RecordObject(sp, "Rotate Spawn Option Offset");

            if (opt.usePointRotation)
            {
                Quaternion local = Quaternion.Inverse(sp.transform.rotation) * newWorldRot;
                opt.rotationOffsetEuler = NormalizeEuler(local.eulerAngles);
            }
            else
            {
                opt.rotationOffsetEuler = NormalizeEuler(newWorldRot.eulerAngles);
            }

            EditorUtility.SetDirty(sp);
            UpdatePreviewInstance();
        }
    }

    private static Quaternion GetWorldRotation(PropSpawnPoint sp, PropSpawnPoint.SpawnOption opt)
    {
        Quaternion off = Quaternion.Euler(opt.rotationOffsetEuler);
        return opt.usePointRotation ? (sp.transform.rotation * off) : off;
    }

    private static Vector3 NormalizeEuler(Vector3 e)
    {
        // Pour éviter des valeurs type 720, -450 etc.
        e.x = Mathf.Repeat(e.x + 180f, 360f) - 180f;
        e.y = Mathf.Repeat(e.y + 180f, 360f) - 180f;
        e.z = Mathf.Repeat(e.z + 180f, 360f) - 180f;
        return e;
    }

    private void UpdatePreviewInstance()
    {
        var sp = (PropSpawnPoint)target;
        if (sp == null) return;

        if (!sp.editorPreviewEnabled || sp.options == null || sp.options.Count == 0)
        {
            CleanupPreviewInstance();
            return;
        }

        int idx = Mathf.Clamp(sp.editorPreviewIndex, 0, sp.options.Count - 1);
        var opt = sp.options[idx];
        if (opt == null || opt.prefab == null)
        {
            CleanupPreviewInstance();
            return;
        }

        var root = EnsurePreviewRoot(sp.transform);

        // Nettoie l'ancien preview
        for (int i = root.transform.childCount - 1; i >= 0; i--)
            DestroyImmediate(root.transform.GetChild(i).gameObject);

        // Instancie le prefab (editor only)
        GameObject instance = (GameObject)PrefabUtility.InstantiatePrefab(opt.prefab);
        if (instance == null)
            instance = Instantiate(opt.prefab);

        instance.name = $"Preview_{opt.prefab.name}";
        instance.transform.SetParent(root.transform, false);

        // Applique offsets
        instance.transform.localPosition = opt.positionOffset;

        if (opt.usePointRotation)
        {
            instance.transform.localRotation = Quaternion.Euler(opt.rotationOffsetEuler);
        }
        else
        {
            // Contre-rotation pour ignorer la rotation du point (car on est parenté)
            Quaternion desiredWorld = Quaternion.Euler(opt.rotationOffsetEuler);
            instance.transform.localRotation = Quaternion.Inverse(sp.transform.rotation) * desiredWorld;
        }

        // Applique scale multiplier (sur le scale prefab)
        instance.transform.localScale = Vector3.Scale(instance.transform.localScale, opt.scaleMultiplier);

        // Désactive les scripts / physics pour éviter effets en edit mode
        foreach (var mb in instance.GetComponentsInChildren<MonoBehaviour>(true))
            mb.enabled = false;
        foreach (var col in instance.GetComponentsInChildren<Collider>(true))
            col.enabled = false;
        foreach (var rb in instance.GetComponentsInChildren<Rigidbody>(true))
            rb.isKinematic = true;

        // Ne pas sauver dans la scène
        root.hideFlags = HideFlags.DontSaveInBuild | HideFlags.DontSaveInEditor;
        instance.hideFlags = HideFlags.DontSaveInBuild | HideFlags.DontSaveInEditor;

        SceneView.RepaintAll();
    }

    private void CleanupPreviewInstance()
    {
        var sp = (PropSpawnPoint)target;
        if (sp == null) return;

        var t = sp.transform.Find(PreviewRootName);
        if (t != null)
            DestroyImmediate(t.gameObject);

        SceneView.RepaintAll();
    }

    private static GameObject EnsurePreviewRoot(Transform parent)
    {
        var existing = parent.Find(PreviewRootName);
        if (existing != null) return existing.gameObject;

        var go = new GameObject(PreviewRootName);
        go.transform.SetParent(parent, false);
        go.transform.localPosition = Vector3.zero;
        go.transform.localRotation = Quaternion.identity;
        go.transform.localScale = Vector3.one;
        return go;
    }
}
#endif

#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;

[CustomEditor(typeof(RoomDatabase))]
public class RoomDatabaseEditor : Editor
{
    SerializedProperty _mapDatabase;
    SerializedProperty _maps;
    bool _removeMissingMaps = true;

    void OnEnable()
    {
        _mapDatabase = serializedObject.FindProperty("mapDatabase");
        _maps = serializedObject.FindProperty("maps");
    }

    public override void OnInspectorGUI()
    {
        serializedObject.Update();

        EditorGUILayout.PropertyField(_mapDatabase, new GUIContent("Map Database"));

        var db = (RoomDatabase)target;

        if (_mapDatabase.objectReferenceValue == null)
        {
            EditorGUILayout.HelpBox("Assigne ton MapDatabase puis clique 'Sync from MapDatabase'.", MessageType.Info);
            serializedObject.ApplyModifiedProperties();
            return;
        }

        EditorGUILayout.Space(6);

        using (new EditorGUILayout.HorizontalScope())
        {
            _removeMissingMaps = EditorGUILayout.ToggleLeft("Remove maps not found in MapDatabase", _removeMissingMaps);
            if (GUILayout.Button("Sync from MapDatabase", GUILayout.Height(22)))
            {
                Undo.RecordObject(db, "Sync RoomDatabase");
                db.SyncFromMapDatabase(_removeMissingMaps);
                EditorUtility.SetDirty(db);
            }
        }

        EditorGUILayout.Space(8);

        for (int i = 0; i < _maps.arraySize; i++)
        {
            var mapElem = _maps.GetArrayElementAtIndex(i);

            var mapIdProp = mapElem.FindPropertyRelative("mapId");
            var mapNameProp = mapElem.FindPropertyRelative("mapName");
            var roomsProp = mapElem.FindPropertyRelative("rooms");

            EditorGUILayout.BeginVertical("box");
            EditorGUILayout.LabelField($"Map => {mapNameProp.stringValue} ({mapIdProp.intValue})", EditorStyles.boldLabel);
            EditorGUILayout.PropertyField(roomsProp, new GUIContent("Rooms"), true);
            EditorGUILayout.EndVertical();

            EditorGUILayout.Space(4);
        }

        serializedObject.ApplyModifiedProperties();
    }
}
#endif

