using Unity.Netcode;
using UnityEngine;

public struct InteractContext
{
    public NetworkPlayerState ActorPs;   // état réseau du joueur local
    public NetworkObject ActorNo;        // NetworkObject du joueur local
    public NetworkGameController Game;   // accès au controller (blackout, etc.)
    public Camera Cam;                  // caméra FPS (pour info si besoin)

    public bool IsValid => ActorPs != null && ActorNo != null && Game != null;
}

