[CreateAssetMenu(menuName = "Possede/Item Database", fileName = "ItemDatabase")]
public class ItemDatabase : ScriptableObject
{
    [Serializable]
    public class ItemDef
    {
        public ItemId id;
        public string displayName;
        public Sprite icon;

        [Header("Stack")]
        public bool stackable = false;

        [Min(1)]
        public int maxStack = 1;
    }

    public List<ItemDef> items = new();

    private Dictionary<ItemId, ItemDef> _byId;

    private void OnEnable() => BuildIndex();
    private void OnValidate() => BuildIndex();

    private void BuildIndex()
    {
        if (_byId == null) _byId = new Dictionary<ItemId, ItemDef>();
        else _byId.Clear();

        if (items == null) return;

        foreach (var it in items)
        {
            if (it == null) continue;
            _byId[it.id] = it;
        }
    }

    public bool TryGet(ItemId id, out ItemDef def)
    {
        if (_byId == null || _byId.Count == 0)
            BuildIndex();

        return _byId.TryGetValue(id, out def);
    }

    public int GetMaxStack(ItemId id)
    {
        if (TryGet(id, out var def) && def != null && def.stackable)
            return Mathf.Max(1, def.maxStack);

        return 1;
    }

    public bool IsStackable(ItemId id) => GetMaxStack(id) > 1;
}

