using UnityEngine;

[CreateAssetMenu(menuName = "Possede/Room Database")]
public class RoomDatabase : ScriptableObject
{
    [Header("Source of truth")]
    public ScriptableObject mapDatabase; // ton asset MapDatabase

    [Header("Rooms per map (auto-synced from MapDatabase)")]
    public List<MapRooms> maps = new();

    [Serializable]
    public class MapRooms
    {
        public int mapId;
        public string mapName;
        public List<RoomEntry> rooms = new();
    }

    [Serializable]
    public class RoomEntry
    {
        public int id;
        public string displayName;
    }

    public string GetRoomName(int mapId, int roomId)
    {
        var mr = GetMapRooms(mapId);
        if (mr == null) return $"Map#{mapId}:Room#{roomId}";

        for (int i = 0; i < mr.rooms.Count; i++)
            if (mr.rooms[i].id == roomId)
                return mr.rooms[i].displayName;

        return $"Room#{roomId}";
    }

    public MapRooms GetMapRooms(int mapId)
    {
        for (int i = 0; i < maps.Count; i++)
            if (maps[i].mapId == mapId)
                return maps[i];
        return null;
    }

#if UNITY_EDITOR
    // Appelé par l'editor custom (bouton Sync)
    public void SyncFromMapDatabase(bool removeMissingMaps)
    {
        if (mapDatabase == null) return;

        if (!TryExtractMapsFromMapDatabase(mapDatabase, out var extracted))
            return;

        var byId = new Dictionary<int, MapRooms>();
        for (int i = 0; i < maps.Count; i++)
            byId[maps[i].mapId] = maps[i];

        var newList = new List<MapRooms>(extracted.Count);
        for (int i = 0; i < extracted.Count; i++)
        {
            var (id, name) = extracted[i];

            if (!byId.TryGetValue(id, out var mr) || mr == null)
            {
                mr = new MapRooms
                {
                    mapId = id,
                    mapName = name,
                    rooms = new List<RoomEntry>()
                };
            }
            else
            {
                mr.mapName = name; // sync rename
            }

            newList.Add(mr);
        }

        if (!removeMissingMaps)
        {
            var keep = new HashSet<int>();
            for (int i = 0; i < newList.Count; i++) keep.Add(newList[i].mapId);

            for (int i = 0; i < maps.Count; i++)
            {
                var old = maps[i];
                if (old != null && !keep.Contains(old.mapId))
                    newList.Add(old);
            }
        }

        maps = newList;
    }

    private static bool TryExtractMapsFromMapDatabase(ScriptableObject db, out List<(int id, string name)> mapsOut)
    {
        mapsOut = new List<(int, string)>();

        var t = db.GetType();
        object mapsObj = null;

        var fMaps = t.GetField("Maps") ?? t.GetField("maps");
        if (fMaps != null) mapsObj = fMaps.GetValue(db);

        if (mapsObj == null)
        {
            var pMaps = t.GetProperty("Maps") ?? t.GetProperty("maps");
            if (pMaps != null) mapsObj = pMaps.GetValue(db);
        }

        if (mapsObj == null)
        {
            Debug.LogWarning($"[RoomDatabase] Impossible de lire 'Maps' sur {t.Name}. Attendu un champ/propriété 'Maps' ou 'maps'.", db);
            return false;
        }

        if (mapsObj is System.Collections.IEnumerable enumerable)
        {
            foreach (var entry in enumerable)
            {
                if (entry == null) continue;

                var et = entry.GetType();
                int id = ReadInt(et, entry, "Id", "id");
                string name = ReadString(et, entry, "DisplayName", "displayName", "Name", "name");

                mapsOut.Add((id, string.IsNullOrWhiteSpace(name) ? $"Map#{id}" : name));
            }

            return true;
        }

        Debug.LogWarning($"[RoomDatabase] 'Maps' n'est pas enumerable sur {t.Name}.", db);
        return false;
    }

private static int ReadInt(Type et, object entry, params string[] names)
{
    for (int i = 0; i < names.Length; i++)
    {
        var f = et.GetField(names[i]);
        if (f != null)
        {
            var v = f.GetValue(entry);
            if (v != null)
            {
                try { return Convert.ToInt32(v); } catch { }
            }
        }

        var p = et.GetProperty(names[i]);
        if (p != null)
        {
            var v = p.GetValue(entry);
            if (v != null)
            {
                try { return Convert.ToInt32(v); } catch { }
            }
        }
    }
    return 0;
}


    private static string ReadString(Type et, object entry, params string[] names)
    {
        for (int i = 0; i < names.Length; i++)
        {
            var f = et.GetField(names[i]);
            if (f != null && f.FieldType == typeof(string)) return (string)f.GetValue(entry);

            var p = et.GetProperty(names[i]);
            if (p != null && p.PropertyType == typeof(string)) return (string)p.GetValue(entry);
        }
        return null;
    }
#endif
}

