    private NetworkObject _no;

    void Awake()
    {
        _no = GetComponentInParent<NetworkObject>();
    }

    void OnEnable()
    {
        EnableAction(forcePossedeAction);
        EnableAction(forceSurvivantAction);
    }

    void OnDisable()
    {
        DisableAction(forcePossedeAction);
        DisableAction(forceSurvivantAction);
    }

    static void EnableAction(InputActionReference r)
    {
        var a = r != null ? r.action : null;
        if (a != null && !a.enabled) a.Enable();
    }

    static void DisableAction(InputActionReference r)
    {
        var a = r != null ? r.action : null;
        if (a != null && a.enabled) a.Disable();
    }

    bool Pressed(InputActionReference r, Key fallback)
    {
        var a = r != null ? r.action : null;
        if (a != null && a.WasPressedThisFrame())
            return true;

        if (fallback != Key.None)
        {
            var kb = Keyboard.current;
            if (kb != null && kb[fallback].wasPressedThisFrame)
                return true;
        }

        return false;
    }

