    {
#if !UNITY_EDITOR && !DEVELOPMENT_BUILD
        return;
#else
        if (_no == null || !_no.IsOwner) return;

        var gc = NetworkGameController.Instance;
        if (gc == null) return;

        ulong targetClientId = _no.OwnerClientId;

        if (Pressed(forcePossedeAction, forcePossedeFallbackKey))
            gc.DebugForcePossedeServerRpc(targetClientId);

        if (Pressed(forceSurvivantAction, forceSurvivantFallbackKey))
            gc.DebugForceSurvivantServerRpc(targetClientId);
#endif
    }
}

