    {
        _t += Time.unscaledDeltaTime;
        if (_t < logEverySeconds) return;
        _t = 0f;

        var active = SceneManager.GetActiveScene();
        var sb = new StringBuilder(256);

        sb.Append("[LightingDebug] ActiveScene=").Append(active.name)
          .Append(" loaded=").Append(active.isLoaded);

        sb.Append(" | Skybox=").Append(RenderSettings.skybox ? RenderSettings.skybox.name : "null");
        sb.Append(" | AmbientMode=").Append(RenderSettings.ambientMode);
        sb.Append(" | AmbientIntensity=").Append(RenderSettings.ambientIntensity.ToString("0.###"));

        // Compte les lights actives
#if UNITY_6000_0_OR_NEWER || UNITY_2023_1_OR_NEWER
        var lights = Object.FindObjectsByType<Light>(FindObjectsInactive.Exclude, FindObjectsSortMode.None);
#else
        var lights = Object.FindObjectsOfType<Light>();
#endif
        int on = 0;
        for (int i = 0; i < lights.Length; i++)
            if (lights[i] != null && lights[i].enabled) on++;

        sb.Append(" | LightsEnabled=").Append(on).Append("/").Append(lights.Length);

        Debug.Log(sb.ToString());
    }
}

