using System.Collections;
using UnityEngine;

[DisallowMultipleComponent]
public class StateLightGate : MonoBehaviour
{
    [Header("Enable Light when...")]
    public bool enableInLobby = true;
    public bool enableInLoading = false;
    public bool enableInRunning = false;
    public bool enableInEnded = false;

    [Header("Target")]
    [Tooltip("Si vide => prend automatiquement le Light sur ce GameObject (si présent).")]
    public Light targetLight;

    [Tooltip("Si true, désactive/active aussi les children Lights.")]
    public bool includeChildren = false;

    [Tooltip("Fréquence de vérification (s)")]
    [Min(0.05f)] public float pollInterval = 0.25f;

    private MatchLoadingCoordinator _coord;

    private void Awake()
    {
        if (targetLight == null) targetLight = GetComponent<Light>();
    }

    private void OnEnable()
    {
        StartCoroutine(Loop());
    }

    private IEnumerator Loop()
    {
        var wait = new WaitForSeconds(pollInterval);

        while (true)
        {
            if (_coord == null)
                _coord = MatchLoadingCoordinator.Instance != null
                    ? MatchLoadingCoordinator.Instance
                    : FindUtil.FindFirst<MatchLoadingCoordinator>(includeInactive: true);

            if (_coord == null)
            {
                Apply(false);
                yield return wait;
                continue;
            }

            var st = (MatchState)_coord.State.Value;

            bool enable =
                (st == MatchState.Lobby && enableInLobby) ||
                (st == MatchState.Loading && enableInLoading) ||
                (st == MatchState.Running && enableInRunning) ||
                (st == MatchState.Ended && enableInEnded);

            Apply(enable);

            yield return wait;
        }
    }

    private void Apply(bool enable)
    {
        if (includeChildren)
        {
            var lights = GetComponentsInChildren<Light>(true);
            for (int i = 0; i < lights.Length; i++)
                if (lights[i] != null) lights[i].enabled = enable;
        }
        else
        {
            if (targetLight != null) targetLight.enabled = enable;
        }
    }
}

