    [Range(0f, 100f)] public float houseKillChanceEnd = 18f;
    public bool houseTargetsOnlyIsolated = true;

    [Header("Rules - Kill Possédé")]
    public bool possedeKillsOnlyDuringBlackout = true;
    [Min(0)] public int maxKillsPerMatchForPossede = 999;

    private readonly Dictionary<ulong, int> _possedeKills = new();
    private Coroutine _matchCo, _blackoutCo;

    void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
    }

    public override void OnNetworkSpawn()
    {
        base.OnNetworkSpawn();
        GameStarted.OnValueChanged += (_, n) =>
        {
            if (n) OnGameStartedClientRpc();
        };
    }

    // -------------------------
    // UTIL
    // -------------------------
    public float RollFuelCanFillPercentServer()
    {
        float min = Mathf.Clamp(Mathf.Min(fuelCanMinFillPercent, fuelCanMaxFillPercent), 0f, 100f);
        float max = Mathf.Clamp(Mathf.Max(fuelCanMinFillPercent, fuelCanMaxFillPercent), 0f, 100f);
        return Random.Range(min, max);
    }

    double ServerNow()
    {
        var nm = NetworkManager.Singleton;
        return (nm != null) ? nm.ServerTime.Time : Time.timeAsDouble;
    }

    float MatchProgress01_Server()
    {
        if (MatchStartTime.Value <= 0 || MatchEndTime.Value <= MatchStartTime.Value) return 0f;
        double now = ServerNow();
        double t = (now - MatchStartTime.Value) / (MatchEndTime.Value - MatchStartTime.Value);
        return Mathf.Clamp01((float)t);
    }

    bool ShouldSpawnPlayersManually()
    {
        var nm = NetworkManager.Singleton;
        if (nm == null || nm.NetworkConfig == null) return true;
        return nm.NetworkConfig.PlayerPrefab == null;
    }

    bool IsInSafeWindowServer()
    {
        if (!IsServer) return false;
        if (safeSeconds <= 0f) return false;
        double now = ServerNow();
        return SafeEndTime.Value > 0d && now < SafeEndTime.Value;
    }

    // -------------------------
    // MATCH FLOW (server)
    // -------------------------
    public void PrepareMatchServer()
    {
        if (!IsServer) return;
        var nm = NetworkManager.Singleton;
        if (nm == null || !nm.IsListening) return;
        if (GameStarted.Value) return;

        State.Value = (int)MatchState.Loading;

        // 1) config voiture
        int req = Random.Range(
            Mathf.Min(carCablesMin, carCablesMax),
            Mathf.Max(carCablesMin, carCablesMax) + 1
        );
        CarCablesRequired.Value = req;
        var car = FindUtil.FindFirst<CarObjective>(includeInactive: true);
        if (car != null)
        {
            car.CablesRequired.Value = req;
            car.ResetForMatchServer();
        }

        // 2) spawn players (legacy)
        if (ShouldSpawnPlayersManually())
            SpawnPlayersIfNeededServer();

        // 3) skins lobby -> ingame
        var lobby = LobbyState.Instance != null ? LobbyState.Instance : FindUtil.FindFirst<LobbyState>(includeInactive: true);
        if (lobby != null)
        {
            for (int i = 0; i < lobby.Players.Count; i++)
            {
                var lp = lobby.Players[i];
                ulong clientId = lp.ClientId;
                if (!nm.ConnectedClients.TryGetValue(clientId, out var client)) continue;
                var po = client.PlayerObject;
                if (po == null) continue;
                var ps = po.GetComponent<NetworkPlayerState>();
                if (ps == null) continue;
                ps.SkinId.Value = lp.SkinId;
            }
        }

        // 4) teleport spawn rooms
        AssignSpawnRoomsAndTeleportServer();

        // 5) spawn props
        if (spawnPropsAtMatchStart)
        {
            var spawner = FindUtil.FindFirst<PropRandomSpawner>(includeInactive: true);
            if (spawner != null) spawner.SpawnForMatch();
        }
    }

    public void StartMatchServer()
    {
        if (!IsServer) return;
        var nm = NetworkManager.Singleton;
        if (nm == null || !nm.IsListening) return;
        if (GameStarted.Value) return;

        GameStarted.Value = true;
        State.Value = (int)MatchState.Running;

        double now = nm.ServerTime.Time;
        MatchStartTime.Value = now;
        MatchEndTime.Value = now + matchDurationSeconds;

        // SAFE
        SafeEndTime.Value = now + Mathf.Max(0f, safeSeconds);

        // Reset exclusive threat
        ThreatMode.Value = (int)MatchThreatMode.Undecided;
        _pendingPossedeClientId = ulong.MaxValue;

        WinnerSide.Value = (int)WinSide.None;

        IsBlackout.Value = false;
        BlackoutEndTime.Value = 0d;

        _houseDecisionDoneThisBlackout = false;
        if (_houseKillPendingCo != null) { StopCoroutine(_houseKillPendingCo); _houseKillPendingCo = null; }

        StopAllMatchCoroutinesServer();

        _matchCo = StartCoroutine(MatchLoopServer());

        // Blackouts "normaux" (pas de premier blackout spécial)
        _blackoutCo = StartCoroutine(BlackoutLoopServer());

        CacheDoorsServer();

        // Safe phase : décide pendant safe, applique possédé à la fin du safe, et débloque house-kill ensuite
        _safeCo = StartCoroutine(SafePhaseServer());

        Debug.Log("[MATCH] Match démarré ! (Safe=0 mort, blackouts normaux, ThreatMode exclusif)");
    }

    [Rpc(SendTo.Server)]
    public void StartGameServerRpc(RpcParams rpcParams = default)
    {
        if (!IsServer) return;
        PrepareMatchServer();
        StartMatchServer();
    }

    void StopAllMatchCoroutinesServer()
    {
        if (_matchCo != null) { StopCoroutine(_matchCo); _matchCo = null; }
        if (_blackoutCo != null) { StopCoroutine(_blackoutCo); _blackoutCo = null; }
        if (_safeCo != null) { StopCoroutine(_safeCo); _safeCo = null; }

        if (_houseKillPendingCo != null) { StopCoroutine(_houseKillPendingCo); _houseKillPendingCo = null; }
    }

    // -------------------------
    // EXCLUSIVE THREAT (safe -> decide -> apply)
    // -------------------------
    void DecideThreatModeServer()
    {
        if (!IsServer) return;
        if ((MatchThreatMode)ThreatMode.Value != MatchThreatMode.Undecided) return;

        bool pickPossede = Random.Range(0f, 100f) < matchPossedeChance;
        ThreatMode.Value = (int)(pickPossede ? MatchThreatMode.Possede : MatchThreatMode.House);

        _pendingPossedeClientId = ulong.MaxValue;

        if ((MatchThreatMode)ThreatMode.Value == MatchThreatMode.Possede)
        {
            // Choisir un survivant comme "pending" (standby), MAIS NE PAS le passer possédé maintenant.
            if (!TryPickPendingPossedeServer(out _pendingPossedeClientId))
            {
                // Pas de candidat -> bascule en Maison
                ThreatMode.Value = (int)MatchThreatMode.House;
                _pendingPossedeClientId = ulong.MaxValue;
            }
        }

        Debug.Log($"[MATCH] ThreatMode décidé: {(MatchThreatMode)ThreatMode.Value} (pendingPossede={_pendingPossedeClientId})");
    }

    bool TryPickPendingPossedeServer(out ulong chosenClientId)
    {
        chosenClientId = ulong.MaxValue;

        var nm = NetworkManager.Singleton;
        if (nm == null) return false;

        List<ulong> candidates = new();
        foreach (var clientId in nm.ConnectedClientsIds)
        {
            var ps = GetPlayerStateServer(clientId);
            if (ps == null) continue;
            if (!ps.Alive.Value || ps.Escaped.Value) continue;
            if ((PlayerRole)ps.Role.Value != PlayerRole.Survivant) continue;
            candidates.Add(clientId);
        }

        if (candidates.Count == 0) return false;
        chosenClientId = candidates[Random.Range(0, candidates.Count)];
        return true;
    }

    IEnumerator SafePhaseServer()
    {
        if (!IsServer) yield break;

        // Décision "pendant safe" (immédiatement)
        DecideThreatModeServer();

        float safe = Mathf.Max(0f, safeSeconds);
        if (safe > 0f)
            yield return new WaitForSeconds(safe);

        if (!IsServer) yield break;
        if ((MatchState)State.Value != MatchState.Running) yield break;
        if (WinnerSide.Value != (int)WinSide.None) yield break;

        // Fin safe -> appliquer possédé si mode Possédé
        if ((MatchThreatMode)ThreatMode.Value == MatchThreatMode.Possede)
        {
            if (_pendingPossedeClientId != ulong.MaxValue)
            {
                var ps = GetPlayerStateServer(_pendingPossedeClientId);
                if (ps != null && ps.Alive.Value && !ps.Escaped.Value)
                {
                    ps.Role.Value = (int)PlayerRole.Possede;
                    Debug.Log($"[MATCH] Safe terminé -> {_pendingPossedeClientId} devient Possédé.");
                }
                else
                {
                    // fallback: repick
                    if (TryPickPendingPossedeServer(out var repick))
                    {
                        var repickPs = GetPlayerStateServer(repick);
                        if (repickPs != null && repickPs.Alive.Value && !repickPs.Escaped.Value)
                        {
                            repickPs.Role.Value = (int)PlayerRole.Possede;
                            Debug.Log($"[MATCH] Safe terminé -> repick {repick} devient Possédé.");
                        }
                    }
                }
            }
        }
        else
        {
            // Mode Maison: s'assurer qu'il n'y a aucun possédé
            var nm = NetworkManager.Singleton;
            if (nm != null)
            {
                foreach (var clientId in nm.ConnectedClientsIds)
                {
                    var ps = GetPlayerStateServer(clientId);
                    if (ps == null) continue;
                    if ((PlayerRole)ps.Role.Value == PlayerRole.Possede)
                        ps.Role.Value = (int)PlayerRole.Survivant;
                }
            }

            Debug.Log("[MATCH] Safe terminé -> mode Maison (aucun possédé).");
        }

        // Si un blackout est en cours et mode Maison -> décider maintenant (safe terminé)
        if ((MatchThreatMode)ThreatMode.Value == MatchThreatMode.House && IsBlackout.Value)
        {
            TryHouseDecisionForCurrentBlackoutServer();
        }
    }

    // -------------------------
    // SPAWN / TELEPORT
    // -------------------------
    void SpawnPlayersIfNeededServer()
    {
        if (!IsServer) return;
        var nm = NetworkManager.Singleton;
        if (nm == null) return;
        if (playerPrefab == null)
        {
            Debug.LogError("[SERVER] playerPrefab est NULL (legacy manual spawn).");
            return;
        }

        foreach (var clientId in nm.ConnectedClientsIds)
        {
            if (!nm.ConnectedClients.TryGetValue(clientId, out var client))
                continue;
            if (client.PlayerObject != null)
                continue;

            var go = Instantiate(playerPrefab, Vector3.zero, Quaternion.identity);
            var no = go.GetComponent<NetworkObject>();
            if (no == null)
            {
                Debug.LogError("[SERVER] playerPrefab n'a pas de NetworkObject.");
                Destroy(go);
                continue;
            }
            no.SpawnAsPlayerObject(clientId, true);
        }
    }

    void AssignSpawnRoomsAndTeleportServer()
    {
        if (!IsServer) return;
        var nm = NetworkManager.Singleton;
        if (nm == null) return;
        var rm = RoomManager.Instance != null ? RoomManager.Instance : FindUtil.FindFirst<RoomManager>(includeInactive: true);
        if (rm == null)
        {
            Debug.LogError("[SERVER] RoomManager introuvable (scene Mapping chargee ?).");
            return;
        }

        var validRooms = rm.GetRoomsWithSpawn();
        if (validRooms == null || validRooms.Count == 0)
        {
            Debug.LogError("[SERVER] Aucune room avec spawnPoint dans RoomManager.");
            return;
        }

        var bag = new List<int>(validRooms);
        for (int i = 0; i < bag.Count; i++)
        {
            int j = Random.Range(i, bag.Count);
            (bag[i], bag[j]) = (bag[j], bag[i]);
        }

        int idx = 0;
        foreach (var clientId in nm.ConnectedClientsIds)
        {
            if (!nm.ConnectedClients.TryGetValue(clientId, out var client))
                continue;
            if (client.PlayerObject == null)
                continue;

            int spawnRoomId;
            if (!randomSpawn)
            {
                spawnRoomId = fixedSpawnRoomId;
                if (!bag.Contains(spawnRoomId))
                    spawnRoomId = bag[Random.Range(0, bag.Count)];
            }
            else
            {
                if (uniqueRoomsIfPossible && idx < bag.Count)
                {
                    spawnRoomId = bag[idx];
                    idx++;
                }
                else
                {
                    spawnRoomId = bag[Random.Range(0, bag.Count)];
                }
            }
            SetRoomAndTeleportOwner(clientId, spawnRoomId);
        }
    }

    void SetRoomAndTeleportOwner(ulong clientId, int roomId)
    {
        if (!IsServer) return;
        var nm = NetworkManager.Singleton;
        if (nm == null) return;
        if (!nm.ConnectedClients.TryGetValue(clientId, out var client)) return;
        var po = client.PlayerObject;
        if (po == null) return;
        var ps = po.GetComponent<NetworkPlayerState>();
        if (ps == null) return;
        if (!ps.Alive.Value) return;
        if (ps.Escaped.Value) return;

        ps.CurrentRoom.Value = roomId;
        TeleportToRoomTargetClientRpc(roomId, RpcTarget.Single(clientId, RpcTargetUse.Temp));
    }

    // -------------------------
    // PICKUP
    // -------------------------
    public void TryPickup(ulong pickerClientId, ulong propNetworkObjectId)
    {
        if (!IsServer) return;
        if (NetworkManager.Singleton == null) return;

        // 1) Récupère le joueur (serveur)
        var ps = GetPlayerStateServer(pickerClientId);
        if (ps == null) return;

        if (!ps.Alive.Value || ps.Escaped.Value) return;

        // 2) Récupère l’objet réseau à ramasser
        if (!NetworkManager.Singleton.SpawnManager.SpawnedObjects.TryGetValue(propNetworkObjectId, out var propNo))
            return;

        var prop = propNo.GetComponent<PropPickup>();
        if (prop == null) return;

        // 3) Distance anti-triche
        float maxDist = Mathf.Max(0.1f, prop.maxPickupDistance);
        if ((ps.transform.position - prop.transform.position).sqrMagnitude > maxDist * maxDist)
            return;

        // 4) Vérifie la place (stack-aware)
        // IMPORTANT: ça dépend de serverItemDb dans NetworkPlayerState.
        if (!ps.HasSpaceServerFor(prop.itemId, 1))
            return;

        // 5) Ajoute vraiment l’item (stack-aware)
        // (value inutilisé pour cables, utile pour essence/huile si un jour tu pickup des bidons)
        bool ok = ps.TryAddItemServer(prop.itemId, 1, 0f);
        if (!ok)
            return;

        // 6) Despawn de l’objet pickup
        if (propNo.IsSpawned)
            propNo.Despawn(true);
    }

    static bool IsKey(ItemId id)
    {
        int v = (int)id;
        return v >= 20 && v < 30;
    }

    static bool InventoryContains(NetworkPlayerState ps, ItemId id)
    {
        int v = (int)id;
        for (int i = 0; i < ps.Inventory.Count; i++)
        {
            int raw = ps.Inventory[i];
            if (raw < 0) continue;
            if (raw == v) return true;
        }
        return false;
    }

    static bool InventoryHasAnyKey(NetworkPlayerState ps)
    {
        for (int i = 0; i < ps.Inventory.Count; i++)
        {
            int raw = ps.Inventory[i];
            if (raw < 0) continue;
            var it = (ItemId)raw;
            if (IsKey(it)) return true;
        }
        return false;
    }

    // -------------------------
    // KILL / ESCAPE
    // -------------------------
    public void TryKill(ulong killerClientId, ulong targetClientId)
    {
        if (!IsServer) return;
        if ((MatchState)State.Value != MatchState.Running) return;
        if (WinnerSide.Value != (int)WinSide.None) return;

        // Pendant safe => 0 mort (peu importe la source, blackout ou non)
        if (IsInSafeWindowServer())
            return;

        var nm = NetworkManager.Singleton;
        if (nm == null) return;
        if (!nm.ConnectedClients.TryGetValue(targetClientId, out var targetClient)) return;
        var targetObj = targetClient.PlayerObject;
        if (targetObj == null) return;
        var targetPs = targetObj.GetComponent<NetworkPlayerState>();
        if (targetPs == null) return;
        if (!targetPs.Alive.Value) return;
        if (targetPs.Escaped.Value) return;

        targetPs.Alive.Value = false;
        KillAnnounceClientRpc(targetClientId, "killed");
    }

    public void TryEscape(ulong clientId)
    {
        if (!IsServer) return;
        if ((MatchState)State.Value != MatchState.Running) return;
        if (WinnerSide.Value != (int)WinSide.None) return;

        var nm = NetworkManager.Singleton;
        if (nm == null) return;
        if (!nm.ConnectedClients.TryGetValue(clientId, out var client)) return;
        var po = client.PlayerObject;
        if (po == null) return;
        var ps = po.GetComponent<NetworkPlayerState>();
        if (ps == null) return;
        if (!ps.Alive.Value) return;
        if (ps.Escaped.Value) return;

        ps.Escaped.Value = true;
    }

    // -------------------------
    // BLACKOUT LOOP (NORMAL)
    // -------------------------
    IEnumerator BlackoutLoopServer()
    {
        while (true)
        {
            if (!IsServer) yield break;
            if ((MatchState)State.Value != MatchState.Running) yield break;
            if (WinnerSide.Value != (int)WinSide.None) yield break;

            float t = MatchProgress01_Server();
            float intervalMin = Mathf.Lerp(intervalEarly.x, intervalLate.x, t);
            float intervalMax = Mathf.Lerp(intervalEarly.y, intervalLate.y, t);
            float durationMin = Mathf.Lerp(durationEarly.x, durationLate.x, t);
            float durationMax = Mathf.Lerp(durationEarly.y, durationLate.y, t);

            intervalMin = Mathf.Max(0.25f, intervalMin);
            intervalMax = Mathf.Max(intervalMin, intervalMax);
            durationMin = Mathf.Max(0.25f, durationMin);
            durationMax = Mathf.Max(durationMin, durationMax);

            float wait = Random.Range(intervalMin, intervalMax);
            yield return new WaitForSeconds(wait);

            if (!IsServer) yield break;
            if ((MatchState)State.Value != MatchState.Running) yield break;
            if (WinnerSide.Value != (int)WinSide.None) yield break;

            float dur = Random.Range(durationMin, durationMax);
            StartBlackoutServer(dur);
            yield return new WaitForSeconds(dur);
            EndBlackoutServer();
        }
    }

    void StartBlackoutServer(float duration)
    {
        if (!IsServer) return;

        duration = Mathf.Max(0.1f, duration);

        IsBlackout.Value = true;
        BlackoutEndTime.Value = ServerNow() + duration;

        // reset "une décision par blackout"
        _houseDecisionDoneThisBlackout = false;
        if (_houseKillPendingCo != null) { StopCoroutine(_houseKillPendingCo); _houseKillPendingCo = null; }

        Debug.Log($"[BLACKOUT] ⚡ BLACKOUT DÉCLENCHÉ ! Durée: {duration:F1}s");

        // Si mode Maison + safe terminé -> décider UNE FOIS (target + roll) sur ce blackout
        TryHouseDecisionForCurrentBlackoutServer();
    }

    void EndBlackoutServer()
    {
        if (!IsServer) return;

        IsBlackout.Value = false;
        BlackoutEndTime.Value = 0d;

        Debug.Log("[BLACKOUT] ✓ BLACKOUT TERMINÉ");

        if (_houseKillPendingCo != null) { StopCoroutine(_houseKillPendingCo); _houseKillPendingCo = null; }
        ClearHouseKillDesignationServer();
    }

    // -------------------------
    // HOUSE KILL
    // -------------------------
    void TryHouseDecisionForCurrentBlackoutServer()
    {
        if (!IsServer) return;

        if (!houseKillsOnlyDuringBlackout) return;
        if (!IsBlackout.Value) return;
        if ((MatchThreatMode)ThreatMode.Value != MatchThreatMode.House) return;

        // Jamais pendant safe
        if (IsInSafeWindowServer()) return;

        if (_houseDecisionDoneThisBlackout) return;
        _houseDecisionDoneThisBlackout = true;

        if (!TryAssignHouseTargetForCurrentBlackoutServer())
        {
            Debug.Log("[HOUSE KILL] Aucun candidat -> pas de kill sur ce blackout.");
            return;
        }

        float t = MatchProgress01_Server();
        float chance = Mathf.Lerp(houseKillChanceStart, houseKillChanceEnd, t);
        float roll = Random.Range(0f, 100f);

        ulong targetId = HouseKillTargetClientId.Value;
        int roomId = HouseKillRoomId.Value;

        Debug.Log($"[HOUSE KILL] Décision blackout: target={targetId} room={roomId} chance={chance:F1}% roll={roll:F1}%");

        if (roll >= chance)
        {
            ClearHouseKillDesignationServer();
            Debug.Log("[HOUSE KILL] Décision: PAS DE KILL sur ce blackout.");
            return;
        }

        double remaining = BlackoutEndTime.Value - ServerNow();
        float remainingF = Mathf.Max(0.05f, (float)remaining);
        float delay = Random.Range(0f, remainingF);

        if (_houseKillPendingCo != null) { StopCoroutine(_houseKillPendingCo); _houseKillPendingCo = null; }
        _houseKillPendingCo = StartCoroutine(ExecuteHouseKillAtRandomTimeServer(targetId, roomId, delay));

        Debug.Log($"[HOUSE KILL] Décision: KILL OUI -> exécution dans {delay:F2}s (reste blackout {remainingF:F2}s).");
    }

    bool TryAssignHouseTargetForCurrentBlackoutServer()
    {
        if (!IsServer) return false;

        if ((MatchThreatMode)ThreatMode.Value != MatchThreatMode.House) return false;
        if (!houseKillsOnlyDuringBlackout || !IsBlackout.Value) return false;
        if (IsInSafeWindowServer()) return false;

        if (HouseKillRoomId.Value >= 0)
            ClearHouseKillDesignationServer();

        var nm = NetworkManager.Singleton;
        if (nm == null) return false;

        List<ulong> candidates = new();
        foreach (var clientId in nm.ConnectedClientsIds)
        {
            var ps = GetPlayerStateServer(clientId);
            if (ps == null) continue;
            if (!ps.Alive.Value || ps.Escaped.Value) continue;

            int roomId = ps.CurrentRoom.Value;
            int playersInRoom = CountAliveNonEscapedInRoomServer(roomId);

            if (houseTargetsOnlyIsolated && playersInRoom != 1)
                continue;

            candidates.Add(clientId);
        }

        if (candidates.Count == 0)
            return false;

        ulong targetId = candidates[Random.Range(0, candidates.Count)];
        var targetPs = GetPlayerStateServer(targetId);
        if (targetPs == null) return false;

        int targetRoom = targetPs.CurrentRoom.Value;

        HouseKillTargetClientId.Value = targetId;
        HouseKillRoomId.Value = targetRoom;

        SetDoorsLockedForRoomServer(targetRoom, true);

        Debug.Log($"[HOUSE KILL] 🎯 CIBLE DÉSIGNÉE (blackout): Client={targetId} Room={targetRoom} (portes verrouillées)");
        return true;
    }

    IEnumerator ExecuteHouseKillAtRandomTimeServer(ulong targetId, int roomId, float delay)
    {
        if (!IsServer) yield break;

        delay = Mathf.Max(0f, delay);

        if (delay > 0f)
            yield return new WaitForSeconds(delay);

        if (!IsServer) yield break;

        if ((MatchState)State.Value != MatchState.Running) yield break;
        if (WinnerSide.Value != (int)WinSide.None) yield break;

        if (IsInSafeWindowServer())
        {
            Debug.Log("[HOUSE KILL] Safe actif au moment du kill -> annulé");
            ClearHouseKillDesignationServer();
            yield break;
        }

        if (!IsBlackout.Value)
        {
            Debug.Log("[HOUSE KILL] Blackout terminé avant exécution -> annulé");
            ClearHouseKillDesignationServer();
            yield break;
        }

        if ((MatchThreatMode)ThreatMode.Value != MatchThreatMode.House)
        {
            Debug.Log("[HOUSE KILL] ThreatMode != House au moment du kill -> annulé");
            ClearHouseKillDesignationServer();
            yield break;
        }

        var nm = NetworkManager.Singleton;
        if (nm == null || !nm.ConnectedClients.ContainsKey(targetId))
        {
            Debug.Log($"[HOUSE KILL] Client {targetId} absent -> annulé");
            ClearHouseKillDesignationServer();
            yield break;
        }

        var targetPs = GetPlayerStateServer(targetId);
        if (targetPs == null || !targetPs.Alive.Value || targetPs.Escaped.Value)
        {
            Debug.Log($"[HOUSE KILL] Cible {targetId} invalide (mort/échappé) -> annulé");
            ClearHouseKillDesignationServer();
            yield break;
        }

        if (targetPs.CurrentRoom.Value != roomId)
        {
            Debug.Log($"[HOUSE KILL] Cible {targetId} a quitté la room ({roomId} -> {targetPs.CurrentRoom.Value}) -> annulé");
            ClearHouseKillDesignationServer();
            yield break;
        }

        if (houseTargetsOnlyIsolated && CountAliveNonEscapedInRoomServer(roomId) != 1)
        {
            Debug.Log($"[HOUSE KILL] Cible {targetId} n'est plus isolée -> annulé");
            ClearHouseKillDesignationServer();
            yield break;
        }

        Debug.Log($"[HOUSE KILL] 💀 KILL EXÉCUTÉ ! Client {targetId} tué par la maison !");
        targetPs.Alive.Value = false;
        KillAnnounceClientRpc(targetId, "house_killed");
        ClearHouseKillDesignationServer();

        _houseKillPendingCo = null;
    }

    // -------------------------
    // DOORS / HOUSE DESIGNATION
    // -------------------------
    void CacheDoorsServer()
    {
        _doorsCache.Clear();
        var doors = FindObjectsByType<NetworkDoor>(FindObjectsSortMode.None);
        if (doors != null)
        {
            _doorsCache.AddRange(doors);
            Debug.Log($"[DOORS] {doors.Length} portes trouvées dans le cache");
        }
        else
        {
            Debug.LogWarning("[DOORS] Aucune porte trouvée !");
        }
    }

    int CountAliveNonEscapedInRoomServer(int roomId)
    {
        var nm = NetworkManager.Singleton;
        if (nm == null) return 0;
        int count = 0;
        foreach (var clientId in nm.ConnectedClientsIds)
        {
            if (!nm.ConnectedClients.TryGetValue(clientId, out var c) || c.PlayerObject == null) continue;
            var ps = c.PlayerObject.GetComponent<NetworkPlayerState>();
            if (ps == null) continue;
            if (!ps.Alive.Value || ps.Escaped.Value) continue;
            if (ps.CurrentRoom.Value == roomId) count++;
        }
        return count;
    }

    private NetworkPlayerState GetPlayerStateServer(ulong clientId)
    {
        if (NetworkManager.Singleton == null) return null;

        if (!NetworkManager.Singleton.ConnectedClients.TryGetValue(clientId, out var client))
            return null;

        var playerObj = client.PlayerObject;
        if (playerObj == null) return null;

        return playerObj.GetComponent<NetworkPlayerState>();
    }

    void SetDoorsLockedForRoomServer(int roomId, bool locked)
    {
        if (!IsServer) return;
        if (roomId < 0) return;
        if (_doorsCache.Count == 0) CacheDoorsServer();

        int doorCount = 0;
        foreach (var d in _doorsCache)
        {
            if (d == null) continue;
            if (!d.lockIfHouseKillRoom) continue;
            if (d.BelongsToRoom(roomId))
            {
                d.SetLockedServer(locked);
                doorCount++;
                Debug.Log($"[DOORS] Porte '{d.name}' room={roomId} locked={locked}");
            }
        }

        if (doorCount == 0)
        {
            Debug.LogWarning($"[DOORS] Aucune porte trouvée pour room {roomId} ! Vérifie roomAId/roomBId sur les NetworkDoor.");
        }
        else
        {
            Debug.Log($"[DOORS] {doorCount} porte(s) {(locked ? "verrouillée(s)" : "déverrouillée(s)")} pour room {roomId}");
        }
    }

    void ClearHouseKillDesignationServer()
    {
        if (!IsServer) return;

        int prevRoom = HouseKillRoomId.Value;
        if (prevRoom >= 0)
        {
            SetDoorsLockedForRoomServer(prevRoom, false);
            Debug.Log($"[HOUSE KILL] 🔓 Libération de la room {prevRoom}");
        }

        HouseKillRoomId.Value = -1;
        HouseKillTargetClientId.Value = 0;
    }

    // -------------------------
    // TIMER UI
    // -------------------------
    public float GetRemainingSeconds()
    {
        double now = (NetworkManager.Singleton != null)
            ? NetworkManager.Singleton.LocalTime.Time
            : Time.timeAsDouble;
        double end = MatchEndTime.Value;
        if (end <= 0) return 0f;
        return Mathf.Max(0f, (float)(end - now));
    }

    // -------------------------
    // MATCH LOOP
    // -------------------------
    private IEnumerator MatchLoopServer()
    {
        while (true)
        {
            if (!IsServer) yield break;
            if ((MatchState)State.Value != MatchState.Running) yield break;
            if (WinnerSide.Value != (int)WinSide.None) yield break;

            var nm = NetworkManager.Singleton;
            if (nm == null || !nm.IsListening)
                yield break;

            if (MatchEndTime.Value > 0 && nm.ServerTime.Time >= MatchEndTime.Value)
            {
                WinnerSide.Value = (int)WinSide.Possede;
                EndMatchFromServer_Announce("time");
                yield break;
            }

            yield return null;
        }
    }

    // -------------------------
    // END MATCH
    // -------------------------
    public void EndMatchFromServer_Announce(string reason)
    {
        if (!IsServer) return;
        if (WinnerSide.Value == (int)WinSide.None) return;

        StopAllMatchCoroutinesServer();

        IsBlackout.Value = false;
        BlackoutEndTime.Value = 0d;

        if (_houseKillPendingCo != null) { StopCoroutine(_houseKillPendingCo); _houseKillPendingCo = null; }
        ClearHouseKillDesignationServer();

        EndMatchClientRpc(WinnerSide.Value, reason);
    }

    // -------------------------
    // RPC client (UNITY 6)
    // -------------------------
    [Rpc(SendTo.SpecifiedInParams)]
    void TeleportToRoomTargetClientRpc(int roomId, RpcParams rpcParams = default)
    {
        var rm = RoomManager.Instance != null ? RoomManager.Instance : FindUtil.FindFirst<RoomManager>(includeInactive: true);
        if (rm == null) return;
        rm.ApplyTeleportLocalFromServer(roomId);
    }

    [Rpc(SendTo.ClientsAndHost)]
    void OnGameStartedClientRpc()
    {
        Debug.Log("[CLIENT] GameStarted -> switch UI lobby -> in-game ici si besoin.");
    }

    [Rpc(SendTo.ClientsAndHost)]
    void HouseKillImminentClientRpc(ulong targetClientId, float delaySeconds)
    {
        Debug.Log($"[GAME] ⚠️ HouseKill programmé: target={targetClientId} dans {delaySeconds:F2}s");
    }

    [Rpc(SendTo.ClientsAndHost)]
    void KillAnnounceClientRpc(ulong deadClientId, string reason)
    {
        Debug.Log($"[GAME] 💀 Mort → Fantôme. id={deadClientId} reason={reason}");
    }

    [Rpc(SendTo.ClientsAndHost)]
    void EndMatchClientRpc(int winnerSide, string reason)
    {
        Debug.Log($"[GAME] FIN DE PARTIE winner={(WinSide)winnerSide} reason={reason}");
        var ui = FindUtil.FindFirst<EndScreenUI>(includeInactive: true);
        if (ui != null) ui.Show((WinSide)winnerSide);
    }

    // -------------------------
    // DEBUG (UNITY 6) - FIX
    // -------------------------

    [Rpc(SendTo.Server, RequireOwnership = false)]
    public void DebugTeleportToRoomServerRpc(int roomId, RpcParams rpcParams = default)
    {
#if !UNITY_EDITOR && !DEVELOPMENT_BUILD
        return;
#else
    if (!IsServer) return;
    if ((MatchState)State.Value != MatchState.Running) return;

    var rm = RoomManager.Instance != null ? RoomManager.Instance : FindUtil.FindFirst<RoomManager>(includeInactive: true);
    if (rm == null) return;
    var valid = rm.GetRoomsWithSpawn();
    if (valid == null || valid.Count == 0 || !valid.Contains(roomId))
    {
        Debug.LogWarning($"[SERVER] DEBUG TELEPORT refused: roomId={roomId} not found (or missing spawnPoint).");
        return;
    }

    SetRoomAndTeleportOwner(rpcParams.Receive.SenderClientId, roomId);
#endif
    }

    [Rpc(SendTo.Server, RequireOwnership = false)]
    public void DebugForcePossedeServerRpc(ulong targetClientId, RpcParams rpcParams = default)
    {
#if !UNITY_EDITOR && !DEVELOPMENT_BUILD
        return;
#else
    if (!IsServer) return;

    // Si 0 / MaxValue => "moi"
    if (targetClientId == 0 || targetClientId == ulong.MaxValue)
        targetClientId = rpcParams.Receive.SenderClientId;

    var ps = GetPlayerStateServer(targetClientId);
    if (ps == null) return;

    // Empêche SafePhaseServer() de retransformer en Survivant si le match était parti en "House"
    ThreatMode.Value = (int)MatchThreatMode.Possede;
    _pendingPossedeClientId = ulong.MaxValue;

    ps.Alive.Value = true;
    ps.Escaped.Value = false;
    ps.Role.Value = (int)PlayerRole.Possede;

    Debug.Log($"[DEBUG] ForcePossede -> client={targetClientId} (sender={rpcParams.Receive.SenderClientId}) ThreatMode=Possede");
#endif
    }

    [Rpc(SendTo.Server, RequireOwnership = false)]
    public void DebugForceSurvivantServerRpc(ulong targetClientId, RpcParams rpcParams = default)
    {
#if !UNITY_EDITOR && !DEVELOPMENT_BUILD
        return;
#else
    if (!IsServer) return;

    if (targetClientId == 0 || targetClientId == ulong.MaxValue)
        targetClientId = rpcParams.Receive.SenderClientId;

    var ps = GetPlayerStateServer(targetClientId);
    if (ps == null) return;

    ps.Alive.Value = true;
    ps.Escaped.Value = false;
    ps.Role.Value = (int)PlayerRole.Survivant;

    Debug.Log($"[DEBUG] ForceSurvivant -> client={targetClientId} (sender={rpcParams.Receive.SenderClientId})");
#endif
    }
}

