using System.Collections;
using Unity.Netcode;
using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>
/// Active/désactive scripts + GameObjects selon Owner / GameStarted,
/// et reporte "client ready" pendant le loading.
/// </summary>
public class NetworkPlayerSetup : NetworkBehaviour
{
    [Header("Owner only (toujours ON pour owner, OFF pour non-owner)")]
    public MonoBehaviour[] ownerOnlyScripts;

    [Tooltip("GameObjects actifs uniquement pour l'owner (ex: PF_SyntyCamera, PlayerCanvas, AudioListener, etc.)")]
    public GameObject[] ownerOnlyObjects;

    [Header("Owner gameplay (ON seulement quand GameStarted = true)")]
    public bool gateGameplayByGameStarted = true;
    public MonoBehaviour[] ownerGameplayScripts;

    [Tooltip("GameObjects gameplay actifs uniquement quand GameStarted = true (pour l'owner)")]
    public GameObject[] ownerGameplayObjects;

    [Header("Loading Barrier (client -> server)")]
    public bool reportClientReadyDuringLoading = true;
    [Min(0f)] public float clientReadyExtraDelaySeconds = 0.25f;

    Coroutine _waitGcCo;
    Coroutine _waitLcCo;
    Coroutine _readyCo;

    bool _gcSubscribed;
    bool _lcSubscribed;

    NetworkGameController _gc;
    MatchLoadingCoordinator _lc;

    int _lastReadyToken = -1;

    void Awake()
    {
        ApplyOwnerOnlyState(false);
        ApplyGameplayState(false);
    }

    public override void OnNetworkSpawn()
    {
        base.OnNetworkSpawn();

        if (!IsOwner)
        {
            StopAllLocal();
            ApplyOwnerOnlyState(false);
            ApplyGameplayState(false);
            return;
        }

        ApplyOwnerOnlyState(true);

        HookGameControllerOrWait();
        HookLoadingCoordinatorOrWait();

        if (!gateGameplayByGameStarted)
            ApplyGameplayState(true);
    }

    public override void OnNetworkDespawn()
    {
        UnhookGameController();
        UnhookLoadingCoordinator();
        StopAllLocal();
        base.OnNetworkDespawn();
    }

    void HookGameControllerOrWait()
    {
        UnhookGameController();

        _gc = NetworkGameController.Instance != null
            ? NetworkGameController.Instance
            : FindUtil.FindFirst<NetworkGameController>(includeInactive: true);

        if (_gc != null)
        {
            SubscribeToGameStarted(_gc);
            ApplyGameplayState(!gateGameplayByGameStarted || _gc.GameStarted.Value);
        }
        else
        {
            _waitGcCo = StartCoroutine(WaitForGameController());
        }
    }

    IEnumerator WaitForGameController()
    {
        while (true)
        {
            if (!IsSpawned || !IsOwner) yield break;

            _gc = NetworkGameController.Instance != null
                ? NetworkGameController.Instance
                : FindUtil.FindFirst<NetworkGameController>(includeInactive: true);

            if (_gc != null)
            {
                SubscribeToGameStarted(_gc);
                ApplyGameplayState(!gateGameplayByGameStarted || _gc.GameStarted.Value);
                yield break;
            }

            yield return null;
        }
    }

    void SubscribeToGameStarted(NetworkGameController gc)
    {
        if (gc == null || _gcSubscribed) return;
        gc.GameStarted.OnValueChanged += OnGameStartedChanged;
        _gcSubscribed = true;
    }

    void UnhookGameController()
    {
        if (_gc != null && _gcSubscribed)
            _gc.GameStarted.OnValueChanged -= OnGameStartedChanged;

        _gcSubscribed = false;
        _gc = null;
    }

    void OnGameStartedChanged(bool previous, bool next)
    {
        if (!IsOwner) return;
        if (!gateGameplayByGameStarted) return;
        ApplyGameplayState(next);
    }

    void HookLoadingCoordinatorOrWait()
    {
        UnhookLoadingCoordinator();

        _lc = MatchLoadingCoordinator.Instance != null
            ? MatchLoadingCoordinator.Instance
            : FindUtil.FindFirst<MatchLoadingCoordinator>(includeInactive: true);

        if (_lc != null)
        {
            SubscribeToLoading(_lc);
            TryStartReadyRoutine();
        }
        else
        {
            _waitLcCo = StartCoroutine(WaitForLoadingCoordinator());
        }
    }

    IEnumerator WaitForLoadingCoordinator()
    {
        while (true)
        {
            if (!IsSpawned || !IsOwner) yield break;

            _lc = MatchLoadingCoordinator.Instance != null
                ? MatchLoadingCoordinator.Instance
                : FindUtil.FindFirst<MatchLoadingCoordinator>(includeInactive: true);

            if (_lc != null)
            {
                SubscribeToLoading(_lc);
                TryStartReadyRoutine();
                yield break;
            }

            yield return null;
        }
    }

    void SubscribeToLoading(MatchLoadingCoordinator lc)
    {
        if (lc == null || _lcSubscribed) return;

        lc.State.OnValueChanged += OnLoadingStateChanged;
        lc.LoadToken.OnValueChanged += OnLoadTokenChanged;

        _lcSubscribed = true;
    }

    void UnhookLoadingCoordinator()
    {
        if (_lc != null && _lcSubscribed)
        {
            _lc.State.OnValueChanged -= OnLoadingStateChanged;
            _lc.LoadToken.OnValueChanged -= OnLoadTokenChanged;
        }

        _lcSubscribed = false;
        _lc = null;
    }

    void OnLoadingStateChanged(int prev, int next)
    {
        if (!IsOwner) return;
        TryStartReadyRoutine();
    }

    void OnLoadTokenChanged(int prev, int next)
    {
        if (!IsOwner) return;
        TryStartReadyRoutine();
    }

    void TryStartReadyRoutine()
    {
        if (!reportClientReadyDuringLoading) return;
        if (!IsOwner || !IsSpawned) return;
        if (_lc == null) return;

        if ((MatchState)_lc.State.Value != MatchState.Loading)
            return;

        int token = _lc.LoadToken.Value;
        if (token == _lastReadyToken) return;

        if (_readyCo != null)
        {
            StopCoroutine(_readyCo);
            _readyCo = null;
        }

        _readyCo = StartCoroutine(ReportReadyWhenLocalReady(token));
    }

    IEnumerator ReportReadyWhenLocalReady(int token)
    {
        while (true)
        {
            if (!IsOwner || !IsSpawned) yield break;
            if (_lc == null) yield break;
            if ((MatchState)_lc.State.Value != MatchState.Loading) yield break;
            if (_lc.LoadToken.Value != token) yield break;

            string mapping = _lc.MappingScene.Value.ToString();
            string lighting = _lc.LightingScene.Value.ToString();
            string gameplay = _lc.GameplayScene.Value.ToString();

            bool mappingOk = string.IsNullOrWhiteSpace(mapping) || (SceneManager.GetSceneByName(mapping).IsValid() && SceneManager.GetSceneByName(mapping).isLoaded);
            bool lightingOk = string.IsNullOrWhiteSpace(lighting) || (SceneManager.GetSceneByName(lighting).IsValid() && SceneManager.GetSceneByName(lighting).isLoaded);
            bool gameplayOk = string.IsNullOrWhiteSpace(gameplay) || (SceneManager.GetSceneByName(gameplay).IsValid() && SceneManager.GetSceneByName(gameplay).isLoaded);

            if (mappingOk && lightingOk && gameplayOk)
                break;

            yield return null;
        }

        var ps = GetComponent<NetworkPlayerState>();
        if (ps != null)
        {
            while (true)
            {
                if (!IsOwner || !IsSpawned) yield break;
                if (_lc == null) yield break;
                if ((MatchState)_lc.State.Value != MatchState.Loading) yield break;
                if (_lc.LoadToken.Value != token) yield break;

                if (ps.CurrentRoom.Value >= 0)
                    break;

                yield return null;
            }
        }

        while (true)
        {
            if (!IsOwner || !IsSpawned) yield break;
            if (_lc == null) yield break;
            if ((MatchState)_lc.State.Value != MatchState.Loading) yield break;
            if (_lc.LoadToken.Value != token) yield break;

            var rm = RoomManager.Instance != null ? RoomManager.Instance : FindUtil.FindFirst<RoomManager>(includeInactive: true);
            if (rm != null)
                break;

            yield return null;
        }

        yield return null;
        yield return new WaitForEndOfFrame();

        if (clientReadyExtraDelaySeconds > 0f)
            yield return new WaitForSeconds(clientReadyExtraDelaySeconds);

        if (!IsOwner || !IsSpawned) yield break;
        if (_lc == null) yield break;
        if ((MatchState)_lc.State.Value != MatchState.Loading) yield break;
        if (_lc.LoadToken.Value != token) yield break;

        _lc.ReportClientReadyServerRpc(token);
        _lastReadyToken = token;
    }

    void StopAllLocal()
    {
        if (_waitGcCo != null) { StopCoroutine(_waitGcCo); _waitGcCo = null; }
        if (_waitLcCo != null) { StopCoroutine(_waitLcCo); _waitLcCo = null; }
        if (_readyCo != null) { StopCoroutine(_readyCo); _readyCo = null; }
    }

    void ApplyOwnerOnlyState(bool enabled)
    {
        if (ownerOnlyScripts != null)
            foreach (var s in ownerOnlyScripts)
                if (s != null) s.enabled = enabled;

        if (ownerOnlyObjects != null)
            foreach (var go in ownerOnlyObjects)
                if (go != null) go.SetActive(enabled);
    }

    void ApplyGameplayState(bool enabled)
    {
        if (ownerGameplayScripts != null)
            foreach (var s in ownerGameplayScripts)
                if (s != null) s.enabled = enabled;

        if (ownerGameplayObjects != null)
            foreach (var go in ownerGameplayObjects)
                if (go != null) go.SetActive(enabled);
    }
}

