// NetworkPlayerState.cs
using System.Collections.Generic;
using Unity.Netcode;
using UnityEngine;

public class NetworkPlayerState : NetworkBehaviour
{
    public NetworkVariable<int> CurrentRoom = new(
        -1,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    public NetworkVariable<bool> Alive = new(
        true,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    public NetworkVariable<bool> Escaped = new(
        false,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    public NetworkVariable<int> Role = new(
        (int)PlayerRole.Survivant,
        NetworkVariableReadPermission.Owner,
        NetworkVariableWritePermission.Server
    );

    // -------------------------
    // SKIN (réseau)
    // -------------------------
    public NetworkVariable<int> SkinId = new(
        0,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    [Header("Debug")]
    public bool debugRoomLogs = true;

    private int _lastReportedRoom = int.MinValue;
    private float _lastReportTime = -999f;

    // -------------------------
    // STACK / ITEM DB (serveur)
    // -------------------------
    [Header("Server Item Database (stack rules)")]
    [Tooltip("Optionnel mais recommandé: ItemDatabase accessible côté serveur pour GetMaxStack().")]
    [SerializeField] private ItemDatabase serverItemDb;

    private ItemDatabase ResolveItemDb()
    {
        if (serverItemDb != null) return serverItemDb;

        // Fallback si tu mets l'asset ItemDatabase dans un dossier Resources avec le nom "ItemDatabase"
        serverItemDb = Resources.Load<ItemDatabase>("ItemDatabase");
        return serverItemDb;
    }

    private int GetMaxStackServer(ItemId id)
    {
        // Liquides non-stack (valeur en % dans InventoryValue)
        if (IsLiquid(id)) return 1;

        var db = ResolveItemDb();
        if (db != null) return Mathf.Max(1, db.GetMaxStack(id));
        return 1; // fallback: non-stack si DB introuvable
    }

    private static bool IsLiquid(ItemId id) =>
        id == ItemId.Essence || id == ItemId.HuileMoteur;

    // -------------------------
    // ROOT MOTION (ghost)
    // -------------------------
    private readonly Dictionary<int, bool> _animRootMotionDefaults = new();

    // -------------------------
    // RENDERER DEFAULTS (escape)
    // -------------------------
    private readonly Dictionary<int, bool> _rendererEnabledDefaults = new();

    // -------------------------
    // GHOST PHYSICS LAYER
    // -------------------------
    [Header("Ghost Physics Layer (collision / passthrough)")]
    [SerializeField] private bool _useGhostLayer = true;

    [Tooltip("Name of the layer to switch to when dead (physics/collision). Example: 'Ghost'")]
    [SerializeField] private string _ghostLayerName = "Ghost";

    [Tooltip("Optional: set this if your colliders/CC are not under the same root as this component.")]
    [SerializeField] private Transform _layerRootOverride;

    private int _originalLayer;
    private bool _originalLayerCached;

    private Transform LayerRoot => _layerRootOverride != null ? _layerRootOverride : transform;

    // -------------------------
    // GHOST VISUAL LAYER
    // -------------------------
    [Header("Ghost Visual Layer (render only)")]
    [SerializeField] private bool _useGhostVisualLayer = true;

    [Tooltip("Name of the layer used ONLY for rendering ghost skins. Example: 'GhostVisual'")]
    [SerializeField] private string _ghostVisualLayerName = "GhostVisual";

    [Tooltip("Root du visuel (skin/mesh). Exemple: SkinVisualRoot. Si null -> transform (moins recommandé).")]
    [SerializeField] private Transform _visualRootOverride;

    private int _originalVisualLayer;
    private bool _originalVisualLayerCached;

    private Transform VisualRoot => _visualRootOverride != null ? _visualRootOverride : transform;

    // -------------------------
    // INVENTAIRE (3 slots fixes)
    // -------------------------
    public const int SlotCount = 3;
    public const int SLOT_EMPTY = (int)ItemId.Junk; // 0
    public const int SLOT_RESERVED = -1;

    public NetworkList<int> Inventory;        // ItemId (ou EMPTY/RESERVED)
    public NetworkList<float> InventoryValue; // Liquides (0..100), sinon 0
    public NetworkList<int> InventoryCount;   // Stack count (>=1), sinon 0

    public NetworkPlayerState()
    {
        Inventory = new NetworkList<int>(
            new List<int>(),
            NetworkVariableReadPermission.Owner,
            NetworkVariableWritePermission.Server
        );

        InventoryValue = new NetworkList<float>(
            new List<float>(),
            NetworkVariableReadPermission.Owner,
            NetworkVariableWritePermission.Server
        );

        InventoryCount = new NetworkList<int>(
            new List<int>(),
            NetworkVariableReadPermission.Owner,
            NetworkVariableWritePermission.Server
        );
    }

    public override void OnNetworkSpawn()
    {
        base.OnNetworkSpawn();

        CacheOriginalLayerIfNeeded();
        CacheOriginalVisualLayerIfNeeded();
        CacheRendererDefaultsIfNeeded();

        CurrentRoom.OnValueChanged += (oldV, newV) =>
        {
            if (!debugRoomLogs) return;
            Debug.Log($"[Room][CLIENT] CurrentRoom {oldV} -> {newV} (owner={OwnerClientId}) isOwner={IsOwner} isServer={IsServer}");
        };

        Escaped.OnValueChanged += OnEscapedChanged;
        ApplyEscapedVisuals(Escaped.Value);

        Alive.OnValueChanged += OnAliveChanged;
        ApplyAliveState(Alive.Value);

        if (IsServer)
        {
            EnsureSlotsServer();

            if (SkinSelectionCache.ServerTryGet(OwnerClientId, out var selectedSkin))
            {
                SkinId.Value = selectedSkin;
                Debug.Log($"[NetworkPlayerState][SERVER] Init SkinId from cache owner={OwnerClientId} skinId={selectedSkin}");
            }
        }

        SkinId.OnValueChanged += OnSkinChanged;
        ApplySkinNow();
    }

    public override void OnNetworkDespawn()
    {
        Escaped.OnValueChanged -= OnEscapedChanged;
        SkinId.OnValueChanged -= OnSkinChanged;
        Alive.OnValueChanged -= OnAliveChanged;

        base.OnNetworkDespawn();
    }

    private void OnSkinChanged(int prev, int next) => ApplySkinNow();

    private void ApplySkinNow()
    {
        var swapper = GetComponentInChildren<PlayerSkinSwapper>(true);
        if (swapper == null)
        {
            Debug.LogError("[NetworkPlayerState] PlayerSkinSwapper not found on player prefab.");
            return;
        }

        swapper.ApplySkin(SkinId.Value);

        // Un skin peut ajouter des renderers -> recache + réapplique états
        CacheRendererDefaultsIfNeeded();
        ApplyAliveState(Alive.Value);
        ApplyEscapedVisuals(Escaped.Value);
    }

    // -------------------------
    // GHOST / ROOT MOTION / LAYERS
    // -------------------------
    private void OnAliveChanged(bool previous, bool next) => ApplyAliveState(next);

    private void ApplyAliveState(bool alive)
    {
        bool isGhost = !alive;

        ApplyAnimatorRootMotionForGhost(isGhost);
        ApplyGhostPhysicsLayerState(isGhost);
        ApplyGhostVisualLayerState(isGhost);
    }

    private void ApplyAnimatorRootMotionForGhost(bool isGhost)
    {
        var animators = GetComponentsInChildren<Animator>(true);
        for (int i = 0; i < animators.Length; i++)
        {
            var a = animators[i];
            if (a == null) continue;

            int id = a.GetInstanceID();

            if (!_animRootMotionDefaults.ContainsKey(id))
                _animRootMotionDefaults[id] = a.applyRootMotion;

            if (isGhost)
            {
                if (a.applyRootMotion) a.applyRootMotion = false;
            }
            else
            {
                bool original = _animRootMotionDefaults[id];
                if (a.applyRootMotion != original) a.applyRootMotion = original;
            }
        }
    }

    private void CacheOriginalLayerIfNeeded()
    {
        if (_originalLayerCached) return;
        _originalLayer = LayerRoot.gameObject.layer;
        _originalLayerCached = true;
    }

    private void CacheOriginalVisualLayerIfNeeded()
    {
        if (_originalVisualLayerCached) return;
        _originalVisualLayer = VisualRoot.gameObject.layer;
        _originalVisualLayerCached = true;
    }

    private int GetLayerOrError(string layerName)
    {
        int l = LayerMask.NameToLayer(layerName);
        if (l < 0)
            Debug.LogError($"[NetworkPlayerState] Layer '{layerName}' introuvable. Crée-le dans Unity (Tags & Layers).");
        return l;
    }

    private void ApplyGhostPhysicsLayerState(bool isGhost)
    {
        if (!_useGhostLayer) return;

        CacheOriginalLayerIfNeeded();

        int ghostLayer = GetLayerOrError(_ghostLayerName);
        if (ghostLayer < 0) return;

        if (isGhost)
            SetLayerRecursively(LayerRoot.gameObject, ghostLayer);
        else
            SetLayerRecursively(LayerRoot.gameObject, _originalLayer);
    }

    private void ApplyGhostVisualLayerState(bool isGhost)
    {
        if (!_useGhostVisualLayer) return;

        CacheOriginalVisualLayerIfNeeded();

        int ghostVisualLayer = GetLayerOrError(_ghostVisualLayerName);
        if (ghostVisualLayer < 0) return;

        if (isGhost)
            SetLayerRecursively(VisualRoot.gameObject, ghostVisualLayer);
        else
            SetLayerRecursively(VisualRoot.gameObject, _originalVisualLayer);
    }

    private static void SetLayerRecursively(GameObject go, int layer)
    {
        go.layer = layer;
        foreach (Transform child in go.transform)
            SetLayerRecursively(child.gameObject, layer);
    }

    // -------------------------
    // ESCAPE visuals
    // -------------------------
    private void OnEscapedChanged(bool previous, bool next) => ApplyEscapedVisuals(next);

    private void CacheRendererDefaultsIfNeeded()
    {
        var renderers = GetComponentsInChildren<Renderer>(true);
        for (int i = 0; i < renderers.Length; i++)
        {
            var r = renderers[i];
            if (r == null) continue;

            int id = r.GetInstanceID();
            if (!_rendererEnabledDefaults.ContainsKey(id))
                _rendererEnabledDefaults[id] = r.enabled;
        }
    }

    private void ApplyEscapedVisuals(bool escaped)
    {
        CacheRendererDefaultsIfNeeded();

        var renderers = GetComponentsInChildren<Renderer>(true);
        for (int i = 0; i < renderers.Length; i++)
        {
            var r = renderers[i];
            if (r == null) continue;

            if (escaped)
            {
                if (r.enabled) r.enabled = false;
            }
            else
            {
                int id = r.GetInstanceID();
                if (_rendererEnabledDefaults.TryGetValue(id, out bool original))
                {
                    if (r.enabled != original) r.enabled = original;
                }
            }
        }

        var colliders = GetComponentsInChildren<Collider>(true);
        for (int i = 0; i < colliders.Length; i++)
            colliders[i].enabled = !escaped;

        var cc = GetComponent<CharacterController>();
        if (cc != null) cc.enabled = !escaped;
    }

    // -------------------------
    // Slots init (serveur)
    // -------------------------
    private void EnsureSlotsServer()
    {
        if (!IsServer) return;

        while (Inventory.Count < SlotCount) Inventory.Add(SLOT_EMPTY);
        while (InventoryValue.Count < SlotCount) InventoryValue.Add(0f);
        while (InventoryCount.Count < SlotCount) InventoryCount.Add(0);

        while (Inventory.Count > SlotCount) Inventory.RemoveAt(Inventory.Count - 1);
        while (InventoryValue.Count > SlotCount) InventoryValue.RemoveAt(InventoryValue.Count - 1);
        while (InventoryCount.Count > SlotCount) InventoryCount.RemoveAt(InventoryCount.Count - 1);
    }

    private void ClearSlotServer(int i)
    {
        Inventory[i] = SLOT_EMPTY;
        InventoryValue[i] = 0f;
        InventoryCount[i] = 0;
    }

    // -------------------------
    // Helpers (client/local)
    // -------------------------
    public bool HasItemLocal(int itemId)
    {
        if (Inventory == null) return false;

        for (int i = 0; i < Inventory.Count && i < SlotCount; i++)
        {
            if (Inventory[i] != itemId) continue;

            if (InventoryCount != null && i < InventoryCount.Count)
            {
                if (InventoryCount[i] <= 0) continue;
            }

            return true;
        }

        return false;
    }

    public bool HasFuelLocal()
    {
        if (Inventory == null || InventoryValue == null) return false;

        for (int i = 0; i < SlotCount && i < Inventory.Count && i < InventoryValue.Count; i++)
            if (Inventory[i] == (int)ItemId.Essence && InventoryValue[i] > 0.01f)
                return true;

        return false;
    }

    // Backward-compatible (ancienne signature)
    public bool HasSpaceLocalFor(ItemId id)
    {
        return HasSpaceLocalFor(id, null, 1);
    }

    // Nouvelle version stack-aware
    public bool HasSpaceLocalFor(ItemId id, ItemDatabase db, int amount)
    {
        if (Inventory == null) return false;
        if (Inventory.Count < SlotCount) return true;

        amount = Mathf.Max(1, amount);

        int cost = SlotCost(id);
        if (cost != 1)
        {
            // multi-slot => ancienne logique stricte
            if (cost == 3)
                return Inventory[0] == SLOT_EMPTY && Inventory[1] == SLOT_EMPTY && Inventory[2] == SLOT_EMPTY;

            if (cost == 2)
                return (Inventory[0] == SLOT_EMPTY && Inventory[1] == SLOT_EMPTY) ||
                       (Inventory[1] == SLOT_EMPTY && Inventory[2] == SLOT_EMPTY);

            for (int i = 0; i < SlotCount; i++)
                if (Inventory[i] == SLOT_EMPTY) return true;

            return false;
        }

        // cost==1 : stack possible
        int maxStack = 1;
        if (!IsLiquid(id) && db != null) maxStack = Mathf.Max(1, db.GetMaxStack(id));
        if (IsLiquid(id)) maxStack = 1;

        if (maxStack <= 1)
        {
            for (int i = 0; i < SlotCount; i++)
                if (Inventory[i] == SLOT_EMPTY) return true;
            return false;
        }

        int remaining = amount;

        // remplir stacks existants
        for (int i = 0; i < SlotCount; i++)
        {
            if (Inventory[i] != (int)id) continue;

            int cur = (InventoryCount != null && i < InventoryCount.Count) ? InventoryCount[i] : 1;
            cur = Mathf.Max(1, cur);

            int cap = maxStack - cur;
            if (cap <= 0) continue;

            int take = Mathf.Min(remaining, cap);
            remaining -= take;
            if (remaining <= 0) return true;
        }

        // utiliser slots vides (peut split si besoin)
        for (int i = 0; i < SlotCount; i++)
        {
            if (Inventory[i] != SLOT_EMPTY) continue;

            remaining -= maxStack;
            if (remaining <= 0) return true;
        }

        return false;
    }

    private static int SlotCost(ItemId id)
    {
        return id switch
        {
            ItemId.Moteur => 3,
            ItemId.Batterie => 2,
            _ => 1,
        };
    }

    // -------------------------
    // Serveur: espaces / add / consume
    // -------------------------

    // RESTAURÉ (utilisé par NetworkGameController.cs)
    public bool HasSpaceServerFor(ItemId id)
    {
        if (!IsServer) return false;
        EnsureSlotsServer();

        // côté serveur on utilise DB si dispo
        var db = ResolveItemDb();
        return HasSpaceLocalFor(id, db, 1);
    }

    // option: vérifier pour N items
    public bool HasSpaceServerFor(ItemId id, int amount)
    {
        if (!IsServer) return false;
        EnsureSlotsServer();

        var db = ResolveItemDb();
        return HasSpaceLocalFor(id, db, amount);
    }

    // compat: ancienne signature
    public bool TryAddItemServer(ItemId id, float value = 0f)
    {
        return TryAddItemServer(id, 1, value);
    }

    // stack-aware
    public bool TryAddItemServer(ItemId id, int amount, float value = 0f)
    {
        if (!IsServer) return false;
        EnsureSlotsServer();

        amount = Mathf.Max(1, amount);

        int cost = SlotCost(id);

        // multi-slot: pas de stack
        if (cost == 3)
        {
            if (!(Inventory[0] == SLOT_EMPTY && Inventory[1] == SLOT_EMPTY && Inventory[2] == SLOT_EMPTY))
                return false;

            Inventory[0] = (int)id;
            InventoryValue[0] = IsLiquid(id) ? Mathf.Clamp(value, 0f, 100f) : 0f;
            InventoryCount[0] = 1;

            Inventory[1] = SLOT_RESERVED; InventoryValue[1] = 0f; InventoryCount[1] = 0;
            Inventory[2] = SLOT_RESERVED; InventoryValue[2] = 0f; InventoryCount[2] = 0;
            return true;
        }

        if (cost == 2)
        {
            if (Inventory[0] == SLOT_EMPTY && Inventory[1] == SLOT_EMPTY)
            {
                Inventory[0] = (int)id;
                InventoryValue[0] = IsLiquid(id) ? Mathf.Clamp(value, 0f, 100f) : 0f;
                InventoryCount[0] = 1;

                Inventory[1] = SLOT_RESERVED; InventoryValue[1] = 0f; InventoryCount[1] = 0;
                return true;
            }

            if (Inventory[1] == SLOT_EMPTY && Inventory[2] == SLOT_EMPTY)
            {
                Inventory[1] = (int)id;
                InventoryValue[1] = IsLiquid(id) ? Mathf.Clamp(value, 0f, 100f) : 0f;
                InventoryCount[1] = 1;

                Inventory[2] = SLOT_RESERVED; InventoryValue[2] = 0f; InventoryCount[2] = 0;
                return true;
            }

            return false;
        }

        // cost==1 : stack
        int maxStack = GetMaxStackServer(id);
        if (maxStack <= 1)
        {
            for (int i = 0; i < SlotCount; i++)
            {
                if (Inventory[i] != SLOT_EMPTY) continue;

                Inventory[i] = (int)id;
                InventoryValue[i] = IsLiquid(id) ? Mathf.Clamp(value, 0f, 100f) : 0f;
                InventoryCount[i] = 1;
                return true;
            }
            return false;
        }

        int remaining = amount;

        // 1) remplir stack existant
        for (int i = 0; i < SlotCount; i++)
        {
            if (Inventory[i] != (int)id) continue;

            int cur = InventoryCount[i];
            if (cur <= 0) cur = 1;

            int cap = maxStack - cur;
            if (cap <= 0) continue;

            int add = Mathf.Min(remaining, cap);
            InventoryCount[i] = cur + add;

            remaining -= add;
            if (remaining <= 0) return true;
        }

        // 2) créer nouveaux stacks dans slots vides
        for (int i = 0; i < SlotCount; i++)
        {
            if (Inventory[i] != SLOT_EMPTY) continue;

            int put = Mathf.Min(remaining, maxStack);

            Inventory[i] = (int)id;
            InventoryValue[i] = 0f;
            InventoryCount[i] = put;

            remaining -= put;
            if (remaining <= 0) return true;
        }

        return false;
    }

    // RESTAURÉ (utilisé par CarObjective.cs)
    public bool TryConsumeOneServer(ItemId id)
    {
        if (!IsServer) return false;
        EnsureSlotsServer();

        int raw = (int)id;
        int cost = SlotCost(id);

        // cost==1 : stack (décrémente si >1 sinon clear)
        if (cost == 1)
        {
            for (int i = 0; i < SlotCount; i++)
            {
                if (Inventory[i] != raw) continue;

                int cur = InventoryCount[i];
                if (cur > 1)
                {
                    InventoryCount[i] = cur - 1;
                    return true;
                }

                ClearSlotServer(i);
                return true;
            }

            return false;
        }

        // multi-slot : clear + libérer reserved
        for (int i = 0; i < SlotCount; i++)
        {
            if (Inventory[i] != raw) continue;

            ClearSlotServer(i);

            for (int k = 1; k < cost; k++)
            {
                int j = i + k;
                if (j >= SlotCount) break;

                if (Inventory[j] == SLOT_RESERVED)
                    ClearSlotServer(j);
            }

            return true;
        }

        return false;
    }

    public bool TryDrainFuelServer(float amountPercent, out float drained)
    {
        drained = 0f;

        if (!IsServer) return false;
        EnsureSlotsServer();

        float need = Mathf.Max(0f, amountPercent);
        if (need <= 0f) return false;

        for (int i = 0; i < SlotCount; i++)
        {
            if (Inventory[i] == (int)ItemId.Essence)
            {
                float cur = Mathf.Clamp(InventoryValue[i], 0f, 100f);
                if (cur <= 0.0001f) continue;

                drained = Mathf.Min(cur, need);
                float next = cur - drained;

                if (next <= 0.0001f)
                {
                    ClearSlotServer(i);
                }
                else
                {
                    InventoryValue[i] = next;
                    if (InventoryCount[i] <= 0) InventoryCount[i] = 1;
                }

                return true;
            }
        }

        return false;
    }

    public bool TryDrainOilServer(float want, out float drained)
    {
        drained = 0f;
        if (!IsServer) return false;
        EnsureSlotsServer();

        float need = Mathf.Max(0f, want);
        if (need <= 0f) return false;

        for (int i = 0; i < SlotCount; i++)
        {
            if (Inventory[i] == (int)ItemId.HuileMoteur)
            {
                float cur = Mathf.Clamp(InventoryValue[i], 0f, 100f);
                if (cur <= 0.0001f) continue;

                drained = Mathf.Min(cur, need);
                float next = cur - drained;

                if (next <= 0.0001f)
                {
                    ClearSlotServer(i);
                }
                else
                {
                    InventoryValue[i] = next;
                    if (InventoryCount[i] <= 0) InventoryCount[i] = 1;
                }

                return true;
            }
        }

        return false;
    }

