        gc.TryKill(rpcParams.Receive.SenderClientId, targetClientId);
    }

    [Rpc(SendTo.Server, InvokePermission = RpcInvokePermission.Everyone)]
    public void RequestEscapeServerRpc(RpcParams rpcParams = default)
    {
        var gc = NetworkGameController.Instance;
