            return;

        _lastReportedRoom = roomId;
        _lastReportTime = Time.time;

        int oldRoom = CurrentRoom.Value;
        if (oldRoom == roomId)
        {
            if (debugRoomLogs)
                Debug.Log($"[Room][SERVER] NoChange owner={OwnerClientId} roomId={roomId}");
            return;
        }

        CurrentRoom.Value = roomId;

        if (debugRoomLogs)
            Debug.Log($"[Room][SERVER] Change owner={OwnerClientId} {oldRoom} -> {roomId} t={Time.time:F2}");
    }
