using Unity.Netcode;
using UnityEngine;

public class NetworkRootBridge : NetworkBehaviour
{
    [Header("Child qui contient CharacterController + Animator (PolygonSyntyCharacter)")]
    public Transform motor;                 // PolygonSyntyCharacter
    public CharacterController motorCC;     // CharacterController sur le child

    [Tooltip("Si true, on ne sync que la rotation Y (recommandé)")]
    public bool yRotationOnly = true;

    private void Awake()
    {
        if (motor != null && motorCC == null)
            motorCC = motor.GetComponent<CharacterController>();
    }

    public override void OnNetworkSpawn()
    {
        // IMPORTANT: le CC ne doit JAMAIS simuler sur les autres clients
        if (motorCC != null)
            motorCC.enabled = IsOwner;
    }

    private void LateUpdate()
    {
        if (motor == null) return;

        if (IsOwner)
        {
            // 1) On récupère la pose world du child (qui a bougé via CharacterController.Move)
            var pos = motor.position;
            var rot = motor.rotation;

            if (yRotationOnly)
                rot = Quaternion.Euler(0f, rot.eulerAngles.y, 0f);

            // 2) On pousse cette pose dans le root networké (NetworkTransform va la répliquer)
            transform.SetPositionAndRotation(pos, rot);

            // 3) On remet le child “collé” au root pour éviter accumulation d’offsets
            motor.localPosition = Vector3.zero;
            motor.localRotation = Quaternion.identity;
        }
        else
        {
            // Remote: le root est déjà sync, donc le child doit juste rester collé au root
            motor.localPosition = Vector3.zero;
            motor.localRotation = Quaternion.identity;
        }
    }
}

