// Place this script anywhere under an "Editor" folder.
#if UNITY_EDITOR

using UnityEngine;
using UnityEditor;
using System.Collections.Generic;

/// <summary>
/// Converts Built-in Render Pipeline (BRP/BIRP) materials to URP.
/// Place this script in an Editor folder and run from the Tools menu.
/// </summary>
public class BRPToURPMaterialConverter : EditorWindow
{
    private enum InputMode
    {
        Folder,
        DragDropList,
    }

    [SerializeField] private InputMode inputMode = InputMode.Folder;
    [SerializeField] private DefaultAsset materialsFolder;
    private string materialsPath = "Assets";
    private bool includeSubfolders = true;
    private bool createBackup = true;
    private bool convertEmissive = true;
    private int materialsFound = 0;
    private int materialsConverted = 0;
    private Vector2 scrollPosition;
    private List<string> conversionLog = new List<string>();

    [SerializeField] private List<Material> selectedMaterials = new List<Material>();

    private string[] FilterGuidsByFolder(string[] guids)
    {
        if (includeSubfolders || guids == null || guids.Length == 0)
            return guids;

        string rootFolder = (materialsPath ?? string.Empty).Replace('\\', '/').TrimEnd('/');
        var filtered = new List<string>(guids.Length);

        for (int i = 0; i < guids.Length; i++)
        {
            string assetPath = AssetDatabase.GUIDToAssetPath(guids[i]);
            if (string.IsNullOrEmpty(assetPath))
                continue;

            string dir = System.IO.Path.GetDirectoryName(assetPath);
            dir = (dir ?? string.Empty).Replace('\\', '/').TrimEnd('/');

            if (dir == rootFolder)
                filtered.Add(guids[i]);
        }

        return filtered.ToArray();
    }

    [MenuItem("Tools/Materials/Convert Built-in Materials to URP (Lit)", priority = 1500)]
    public static void ShowWindow()
    {
        var window = GetWindow<BRPToURPMaterialConverter>("BRP -> URP Converter");
        window.minSize = new Vector2(500, 400);
    }

    private void OnEnable()
    {
        // Best-effort sync of the folder object from the stored path.
        if (materialsFolder == null && !string.IsNullOrWhiteSpace(materialsPath))
        {
            materialsFolder = AssetDatabase.LoadAssetAtPath<DefaultAsset>(materialsPath);
        }

        // If a folder asset is set, prefer its path.
        if (materialsFolder != null)
        {
            string p = AssetDatabase.GetAssetPath(materialsFolder);
            if (!string.IsNullOrEmpty(p) && AssetDatabase.IsValidFolder(p))
                materialsPath = p;
        }
    }

    private void OnGUI()
    {
        EditorGUILayout.Space(10);
        EditorGUILayout.LabelField("BRP -> URP Material Converter", EditorStyles.boldLabel);
        EditorGUILayout.Space(5);

        EditorGUILayout.HelpBox(
            "Converts Built-in Render Pipeline materials to URP.\n" +
            "- Standard materials -> Universal Render Pipeline/Lit\n" +
            "- Emissive materials -> URP/Lit (with emission enabled)",
            MessageType.Info
        );

        EditorGUILayout.Space(10);

        EditorGUILayout.LabelField("Settings", EditorStyles.boldLabel);

        inputMode = (InputMode)EditorGUILayout.EnumPopup("Input Mode", inputMode);

        if (inputMode == InputMode.Folder)
        {
            var newFolder = (DefaultAsset)EditorGUILayout.ObjectField("Materials Folder", materialsFolder, typeof(DefaultAsset), false);
            if (newFolder != materialsFolder)
            {
                materialsFolder = newFolder;
                string p = materialsFolder != null ? AssetDatabase.GetAssetPath(materialsFolder) : string.Empty;
                if (!string.IsNullOrEmpty(p) && AssetDatabase.IsValidFolder(p))
                    materialsPath = p;
            }

            using (new EditorGUI.DisabledScope(true))
            {
                EditorGUILayout.TextField("Folder Path", materialsPath);
            }

            includeSubfolders = EditorGUILayout.Toggle("Include Subfolders", includeSubfolders);
        }
        else
        {
            DrawDragDropMaterialsUI();
        }

        createBackup = EditorGUILayout.Toggle("Create Backup", createBackup);
        convertEmissive = EditorGUILayout.Toggle("Convert Emissive Materials", convertEmissive);

        EditorGUILayout.Space(10);

        if (inputMode == InputMode.Folder)
        {
            if (GUILayout.Button("Scan for Materials", GUILayout.Height(30)))
            {
                ScanMaterials();
            }
        }
        else
        {
            // Keep count accurate.
            materialsFound = selectedMaterials != null ? selectedMaterials.Count : 0;
        }

        if (materialsFound > 0)
        {
            EditorGUILayout.Space(5);
            EditorGUILayout.HelpBox($"Found {materialsFound} materials ready to convert.", MessageType.Info);
        }

        EditorGUILayout.Space(10);

        GUI.enabled = materialsFound > 0;
        GUI.backgroundColor = Color.green;
        if (GUILayout.Button("Convert to URP", GUILayout.Height(40)))
        {
            if (EditorUtility.DisplayDialog(
                "Convert to URP",
                $"Convert {materialsFound} materials to URP shaders?\n\n" +
                (createBackup ? "A backup will be created." : "No backup will be created."),
                "Convert",
                "Cancel"))
            {
                if (inputMode == InputMode.Folder)
                    ConvertMaterialsFromFolder();
                else
                    ConvertMaterialsFromList();
            }
        }
        GUI.backgroundColor = Color.white;
        GUI.enabled = true;

        EditorGUILayout.Space(10);

        if (materialsConverted > 0)
        {
            EditorGUILayout.HelpBox($"Successfully converted {materialsConverted} materials!", MessageType.Info);
        }

        if (conversionLog.Count > 0)
        {
            EditorGUILayout.Space(10);
            EditorGUILayout.LabelField("Conversion Log:", EditorStyles.boldLabel);

            scrollPosition = EditorGUILayout.BeginScrollView(scrollPosition, GUILayout.Height(200));
            foreach (var log in conversionLog)
            {
                EditorGUILayout.LabelField(log, EditorStyles.miniLabel);
            }
            EditorGUILayout.EndScrollView();
        }
    }

    private void ScanMaterials()
    {
        conversionLog.Clear();
        materialsFound = 0;
        materialsConverted = 0;

        if (string.IsNullOrWhiteSpace(materialsPath) || !AssetDatabase.IsValidFolder(materialsPath))
        {
            conversionLog.Add("Materials folder not found: " + materialsPath);
            return;
        }

        string[] guids = AssetDatabase.FindAssets("t:Material", new[] { materialsPath });
        guids = FilterGuidsByFolder(guids);

        materialsFound = guids.Length;
        conversionLog.Add($"Scanning: {materialsPath}");
        conversionLog.Add($"Found {materialsFound} materials");

        Repaint();
    }

    private static bool IsFolder(UnityEngine.Object obj)
    {
        if (obj == null)
            return false;

        string path = AssetDatabase.GetAssetPath(obj);
        if (string.IsNullOrEmpty(path))
            return false;

        return AssetDatabase.IsValidFolder(path);
    }

    private void DrawDragDropMaterialsUI()
    {
        EditorGUILayout.Space(6);
        EditorGUILayout.LabelField("Drag & Drop Materials", EditorStyles.boldLabel);

        Rect dropArea = GUILayoutUtility.GetRect(0, 60, GUILayout.ExpandWidth(true));
        GUI.Box(dropArea, "Drop Materials (or folders) here\nYou can also use 'Add Selected'", EditorStyles.helpBox);

        HandleDragAndDrop(dropArea);

        EditorGUILayout.BeginHorizontal();
        if (GUILayout.Button("Add Selected", GUILayout.Height(24)))
        {
            AddMaterialsFromObjects(Selection.objects);
        }

        if (GUILayout.Button("Clear", GUILayout.Height(24)))
        {
            selectedMaterials.Clear();
            conversionLog.Clear();
            materialsFound = 0;
            materialsConverted = 0;
        }
        EditorGUILayout.EndHorizontal();

        EditorGUILayout.Space(6);

        if (selectedMaterials == null)
            selectedMaterials = new List<Material>();

        // De-dupe and remove nulls.
        var seen = new HashSet<Material>();
        for (int i = selectedMaterials.Count - 1; i >= 0; i--)
        {
            var m = selectedMaterials[i];
            if (m == null || !seen.Add(m))
                selectedMaterials.RemoveAt(i);
        }

        materialsFound = selectedMaterials.Count;

        EditorGUILayout.LabelField($"Materials in list: {materialsFound}");

        if (materialsFound == 0)
            return;

        EditorGUILayout.Space(4);
        using (var sv = new EditorGUILayout.ScrollViewScope(scrollPosition, GUILayout.Height(140)))
        {
            scrollPosition = sv.scrollPosition;
            for (int i = 0; i < selectedMaterials.Count; i++)
            {
                EditorGUILayout.BeginHorizontal();
                selectedMaterials[i] = (Material)EditorGUILayout.ObjectField(selectedMaterials[i], typeof(Material), false);
                if (GUILayout.Button("X", GUILayout.Width(22)))
                {
                    selectedMaterials.RemoveAt(i);
                    GUIUtility.ExitGUI();
                }
                EditorGUILayout.EndHorizontal();
            }
        }
    }

    private void HandleDragAndDrop(Rect dropArea)
    {
        Event evt = Event.current;
        if (evt == null)
            return;

        switch (evt.type)
        {
            case EventType.DragUpdated:
            case EventType.DragPerform:
                if (!dropArea.Contains(evt.mousePosition))
                    return;

                DragAndDrop.visualMode = DragAndDropVisualMode.Copy;
                if (evt.type == EventType.DragPerform)
                {
                    DragAndDrop.AcceptDrag();
                    AddMaterialsFromObjects(DragAndDrop.objectReferences);
                }
                evt.Use();
                break;
        }
    }

    private void AddMaterialsFromObjects(UnityEngine.Object[] objects)
    {
        if (objects == null || objects.Length == 0)
            return;

        if (selectedMaterials == null)
            selectedMaterials = new List<Material>();

        int before = selectedMaterials.Count;

        foreach (var obj in objects)
        {
            if (obj == null)
                continue;

            if (obj is Material mat)
            {
                selectedMaterials.Add(mat);
                continue;
            }

            if (IsFolder(obj))
            {
                string folder = AssetDatabase.GetAssetPath(obj);
                if (!string.IsNullOrEmpty(folder))
                {
                    string[] guids = AssetDatabase.FindAssets("t:Material", new[] { folder });
                    foreach (var g in guids)
                    {
                        string path = AssetDatabase.GUIDToAssetPath(g);
                        var m = AssetDatabase.LoadAssetAtPath<Material>(path);
                        if (m != null)
                            selectedMaterials.Add(m);
                    }
                }
            }
        }

        // De-dupe + drop nulls.
        var seen = new HashSet<Material>();
        for (int i = selectedMaterials.Count - 1; i >= 0; i--)
        {
            var m = selectedMaterials[i];
            if (m == null || !seen.Add(m))
                selectedMaterials.RemoveAt(i);
        }

        int added = selectedMaterials.Count - before;
        if (added > 0)
            conversionLog.Add($"Added {added} material(s) via drag/drop.");

        Repaint();
    }

    private void ConvertMaterialsFromFolder()
    {
        conversionLog.Clear();
        materialsConverted = 0;

        string[] guids = AssetDatabase.FindAssets("t:Material", new[] { materialsPath });
        guids = FilterGuidsByFolder(guids);

        var materials = new List<Material>(guids.Length);
        for (int i = 0; i < guids.Length; i++)
        {
            string path = AssetDatabase.GUIDToAssetPath(guids[i]);
            var mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat != null)
                materials.Add(mat);
        }

        ConvertMaterialsInternal(materials);
    }

    private void ConvertMaterialsFromList()
    {
        conversionLog.Clear();
        materialsConverted = 0;

        if (selectedMaterials == null)
        {
            conversionLog.Add("No materials selected.");
            return;
        }

        // Copy to avoid list modification issues.
        var materials = new List<Material>(selectedMaterials.Count);
        for (int i = 0; i < selectedMaterials.Count; i++)
        {
            if (selectedMaterials[i] != null)
                materials.Add(selectedMaterials[i]);
        }

        ConvertMaterialsInternal(materials);
    }

    private void ConvertMaterialsInternal(List<Material> materials)
    {
        if (materials == null || materials.Count == 0)
        {
            conversionLog.Add("No materials to convert.");
            return;
        }

        if (createBackup)
        {
            string backupFolder = "Assets/MaterialBackups/BRPToURP_" + System.DateTime.Now.ToString("yyyyMMdd_HHmmss");
            EnsureFolderExists("Assets/MaterialBackups");
            EnsureFolderExists(backupFolder);
            conversionLog.Add($"Creating backups in: {backupFolder}");

            AssetDatabase.StartAssetEditing();
            try
            {
                for (int i = 0; i < materials.Count; i++)
                {
                    var mat = materials[i];
                    if (mat == null)
                        continue;

                    string srcPath = AssetDatabase.GetAssetPath(mat);
                    if (string.IsNullOrEmpty(srcPath))
                        continue;

                    string fileName = System.IO.Path.GetFileName(srcPath);
                    string dstPath = AssetDatabase.GenerateUniqueAssetPath(backupFolder + "/" + fileName);
                    AssetDatabase.CopyAsset(srcPath, dstPath);
                }
            }
            finally
            {
                AssetDatabase.StopAssetEditing();
            }
        }

        Shader urpLitShader = Shader.Find("Universal Render Pipeline/Lit");
        if (urpLitShader == null)
        {
            conversionLog.Add("URP Lit shader not found! Is URP installed?");
            EditorUtility.DisplayDialog("Error", "URP Lit shader not found!\n\nMake sure URP is properly installed.", "OK");
            return;
        }

        conversionLog.Add("Starting conversion...");

        int total = materials.Count;
        try
        {
            AssetDatabase.StartAssetEditing();

            for (int i = 0; i < total; i++)
            {
                Material mat = materials[i];
                if (mat == null) continue;

                EditorUtility.DisplayProgressBar(
                    "Converting Materials",
                    $"Converting {mat.name}...",
                    total > 0 ? (float)(i + 1) / total : 1f);

                if (mat.shader != null && mat.shader.name != null && mat.shader.name.Contains("Universal Render Pipeline"))
                {
                    conversionLog.Add($"Skipped (already URP): {mat.name}");
                    continue;
                }

                bool isEmissive = mat.name.Contains("Emmisive") || mat.name.Contains("Emissive");
                if (isEmissive && !convertEmissive)
                {
                    conversionLog.Add($"Skipped (emissive): {mat.name}");
                    continue;
                }

                Texture mainTex = mat.GetTexture("_MainTex");
                if (mainTex == null) mainTex = mat.GetTexture("_BaseMap");

                Texture normalMap = mat.GetTexture("_BumpMap");
                if (normalMap == null) normalMap = mat.GetTexture("_NormalMap");

                Texture metallicMap = mat.GetTexture("_MetallicGlossMap");
                Texture emissionMap = mat.GetTexture("_EmissionMap");
                Color color = mat.HasProperty("_Color") ? mat.GetColor("_Color") : Color.white;
                Color emissionColor = mat.HasProperty("_EmissionColor") ? mat.GetColor("_EmissionColor") : Color.white;
                float smoothness = mat.HasProperty("_Glossiness") ? mat.GetFloat("_Glossiness") : 0.5f;
                float metallic = mat.HasProperty("_Metallic") ? mat.GetFloat("_Metallic") : 0f;

                mat.shader = urpLitShader;

                if (mainTex != null)
                    mat.SetTexture("_BaseMap", mainTex);

                if (normalMap != null)
                {
                    mat.SetTexture("_BumpMap", normalMap);
                    mat.EnableKeyword("_NORMALMAP");
                }

                if (metallicMap != null)
                    mat.SetTexture("_MetallicGlossMap", metallicMap);

                mat.SetColor("_BaseColor", color);
                mat.SetFloat("_Smoothness", smoothness);
                mat.SetFloat("_Metallic", metallic);

                if (isEmissive || emissionMap != null)
                {
                    mat.EnableKeyword("_EMISSION");
                    mat.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;

                    if (emissionMap != null)
                        mat.SetTexture("_EmissionMap", emissionMap);

                    if (emissionColor != Color.black)
                        mat.SetColor("_EmissionColor", emissionColor);
                    else
                        mat.SetColor("_EmissionColor", Color.white);
                }

                mat.enableInstancing = true;

                EditorUtility.SetDirty(mat);
                materialsConverted++;

                conversionLog.Add($"Converted: {mat.name}" + (isEmissive ? " (emissive)" : ""));
            }
        }
        finally
        {
            AssetDatabase.StopAssetEditing();
            EditorUtility.ClearProgressBar();
        }

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();

        conversionLog.Add("");
        conversionLog.Add($"Conversion complete! {materialsConverted} materials converted.");

        Repaint();
    }

    private static void EnsureFolderExists(string folderPath)
    {
        if (AssetDatabase.IsValidFolder(folderPath))
            return;

        string parent = System.IO.Path.GetDirectoryName(folderPath)?.Replace('\\', '/');
        string name = System.IO.Path.GetFileName(folderPath);

        if (string.IsNullOrEmpty(parent) || string.IsNullOrEmpty(name))
            return;

        if (!AssetDatabase.IsValidFolder(parent))
            EnsureFolderExists(parent);

        AssetDatabase.CreateFolder(parent, name);
    }
}

