using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEngine;

public static class RestoreMaterialsFromBackup
{
    // Ex: "Assets/MaterialBackups/BRPToURP_20260118_123456"
    private const string BackupRootDefault = "Assets/MaterialBackups";

    [MenuItem("Tools/Materials/Restore From Backup Folder (by name)")]
    public static void RestoreFromBackupFolder()
    {
        // Choisir un dossier de backup
        var folder = EditorUtility.OpenFolderPanel(
            "Select BRPToURP backup folder",
            Application.dataPath,
            ""
        );

        if (string.IsNullOrEmpty(folder))
            return;

        // Convert absolute path -> "Assets/..."
        if (!folder.Replace('\\','/').Contains("/Assets/"))
        {
            EditorUtility.DisplayDialog("Error", "Select a folder inside your project Assets/ ...", "OK");
            return;
        }

        var assetsIndex = folder.Replace('\\','/').LastIndexOf("/Assets/");
        var backupFolderAssetsPath = folder.Replace('\\','/').Substring(assetsIndex + 1); // "Assets/...."
        if (!AssetDatabase.IsValidFolder(backupFolderAssetsPath))
        {
            EditorUtility.DisplayDialog("Error", "Invalid Assets folder: " + backupFolderAssetsPath, "OK");
            return;
        }

        // 1) Indexer les matériaux backup par nom
        var backupMatsByName = new Dictionary<string, Material>();
        var backupGuids = AssetDatabase.FindAssets("t:Material", new[] { backupFolderAssetsPath });

        foreach (var guid in backupGuids)
        {
            var path = AssetDatabase.GUIDToAssetPath(guid);
            var mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null) continue;

            // On map par nom. Si doublon: on garde le premier.
            if (!backupMatsByName.ContainsKey(mat.name))
                backupMatsByName.Add(mat.name, mat);
        }

        if (backupMatsByName.Count == 0)
        {
            EditorUtility.DisplayDialog("Restore", "No materials found in: " + backupFolderAssetsPath, "OK");
            return;
        }

        // 2) Trouver tous les matériaux du projet (hors dossier backup) et restaurer si match par nom
        var allMatGuids = AssetDatabase.FindAssets("t:Material", new[] { "Assets" });

        int restored = 0;
        int scanned = 0;

        try
        {
            AssetDatabase.StartAssetEditing();

            for (int i = 0; i < allMatGuids.Length; i++)
            {
                var path = AssetDatabase.GUIDToAssetPath(allMatGuids[i]);

                // Skip backups themselves
                if (path.StartsWith(BackupRootDefault) || path.StartsWith(backupFolderAssetsPath))
                    continue;

                var mat = AssetDatabase.LoadAssetAtPath<Material>(path);
                if (mat == null) continue;

                scanned++;

                if (!backupMatsByName.TryGetValue(mat.name, out var backupMat) || backupMat == null)
                    continue;

                // Copie shader + propriétés (sans changer le GUID du matériau original)
                Undo.RecordObject(mat, "Restore Material From Backup");

                mat.shader = backupMat.shader;
                mat.CopyPropertiesFromMaterial(backupMat);

                // Important: activer keywords / passes comme dans le backup
                mat.shaderKeywords = backupMat.shaderKeywords;
                mat.renderQueue = backupMat.renderQueue;
                mat.globalIlluminationFlags = backupMat.globalIlluminationFlags;
                mat.enableInstancing = backupMat.enableInstancing;
                mat.doubleSidedGI = backupMat.doubleSidedGI;

                EditorUtility.SetDirty(mat);
                restored++;

                if (restored % 50 == 0)
                {
                    EditorUtility.DisplayProgressBar(
                        "Restoring Materials",
                        $"Restored {restored} (scanned {scanned}/{allMatGuids.Length})",
                        (float)i / allMatGuids.Length
                    );
                }
            }
        }
        finally
        {
            AssetDatabase.StopAssetEditing();
            EditorUtility.ClearProgressBar();
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
        }

        EditorUtility.DisplayDialog(
            "Restore Done",
            $"Backup folder: {backupFolderAssetsPath}\n" +
            $"Scanned: {scanned}\n" +
            $"Restored: {restored}\n\n" +
            "Note: Matching is by material NAME. If some materials have duplicate names, those may need manual fixes.",
            "OK"
        );
    }
}
