using System.Collections;
using UnityEngine;

public class DeathScreenUI : MonoBehaviour
{
    public static DeathScreenUI Instance { get; private set; }

    [SerializeField] private GameObject root;      // DeathScreen
    [SerializeField] private CanvasGroup group;    // optionnel (fade)

    private Coroutine _fadeCo;

    private void Awake()
    {
        Instance = this;
        if (root) root.SetActive(false);
        if (group) group.alpha = 0f;
    }

    public void Show()
    {
        if (!root) return;

        root.SetActive(true);

        if (group)
        {
            if (_fadeCo != null) StopCoroutine(_fadeCo);
            _fadeCo = StartCoroutine(FadeTo(1f, 0.15f));
        }
    }

    public void Hide()
    {
        if (!root) return;

        if (group)
        {
            if (_fadeCo != null) StopCoroutine(_fadeCo);
            _fadeCo = StartCoroutine(FadeTo(0f, 0.15f, () => root.SetActive(false)));
        }
        else
        {
            root.SetActive(false);
        }
    }

    private IEnumerator FadeTo(float target, float duration, System.Action onDone = null)
    {
        float start = group.alpha;
        float t = 0f;

        while (t < duration)
        {
            t += Time.unscaledDeltaTime;
            group.alpha = Mathf.Lerp(start, target, t / duration);
            yield return null;
        }

        group.alpha = target;
        onDone?.Invoke();
    }
}

