using TMPro;
using Unity.Netcode;
using UnityEngine;

public class HudGame : MonoBehaviour
{
    public TextMeshProUGUI hudState;
    public TextMeshProUGUI hudTimer;
    public TextMeshProUGUI hudBlackout;
    public TextMeshProUGUI hudRole; // optionnel

    private NetworkGameController _gc;
    private NetworkPlayerState _ps;

    void Start()
    {
        if (hudState) hudState.text = "";
        if (hudTimer) hudTimer.text = "";
        if (hudBlackout) hudBlackout.text = "";
        if (hudRole) hudRole.text = "";
    }

    void Update()
    {
        if (_gc == null) _gc = NetworkGameController.Instance;
        if (_gc == null || NetworkManager.Singleton == null) return;

        if (_ps == null)
        {
            var all = FindObjectsByType<NetworkObject>(FindObjectsInactive.Exclude, FindObjectsSortMode.None);
            foreach (var no in all)
            {
                if (no.IsSpawned && no.IsPlayerObject && no.IsOwner)
                {
                    _ps = no.GetComponent<NetworkPlayerState>();
                    break;
                }
            }
        }

        var state = (MatchState)_gc.State.Value;

        if (hudState) hudState.text = $"State: {state}";

        if (hudTimer)
        {
            double remaining = _gc.MatchEndTime.Value - NetworkManager.Singleton.ServerTime.Time;
            if (remaining < 0) remaining = 0;

            int sec = Mathf.RoundToInt((float)remaining);
            int mm = sec / 60;
            int ss = sec % 60;
            hudTimer.text = $"Time: {mm:00}:{ss:00}";
        }

        if (hudBlackout)
        {
            bool b = _gc.IsBlackout.Value;
            if (!b)
            {
                hudBlackout.text = "Blackout: OFF";
            }
            else
            {
                double r = _gc.BlackoutEndTime.Value - NetworkManager.Singleton.ServerTime.Time;
                if (r < 0) r = 0;
                hudBlackout.text = $"Blackout: ON ({r:0}s)";
            }
        }

        if (hudRole && _ps != null)
        {
            // Role est Owner-only => OK local
            hudRole.text = $"Role: {(PlayerRole)_ps.Role.Value}";
        }
    }
}

