using UnityEngine;
using UnityEngine.UI;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.Controls;
using TMPro;

public class InventoryHud : MonoBehaviour
{
    public ItemDatabase itemDb;

    [Tooltip("3 Images UGUI (slot 1..3)")]
    public Image[] slotImages = new Image[3];

    [Header("Stack Text (TMP)")]
    [Tooltip("3 TextMeshProUGUI (slot 1..3) pour afficher la quantité")]
    public TextMeshProUGUI[] slotCountTexts = new TextMeshProUGUI[3];

    [Header("Reserved (multi-slot placeholder)")]
    [SerializeField] private Sprite reservedSprite;
    [SerializeField] private Color reservedTint = Color.white;

    [Header("Fuel Progress Bars (Slider)")]
    [Tooltip("GameObject racine de la barre (pour hide/show), ex: Slot/FuelBar")]
    public GameObject[] slotFuelBarRoots = new GameObject[3];

    [Tooltip("Slider de la barre (min=0 max=1 interactable OFF)")]
    public Slider[] slotFuelBars = new Slider[3];

    [Tooltip("Si true, barre inversée (1 = vide, 0 = plein)")]
    public bool invertFuelBar = false;

    [Header("Fuel normalization")]
    [Tooltip("Si true: 10% => barre pleine (normalise sur 10). Si false: normalise sur 100.")]
    public bool normalizeFuelOnTen = true;

    [Tooltip("Valeur max utilisée si normalizeFuelOnTen=true (par défaut 10).")]
    public float fuelMaxForHud = 10f;

    [Header("Input (Input System)")]
    [SerializeField] private InputActionReference selectSlot1Action;
    [SerializeField] private InputActionReference selectSlot2Action;
    [SerializeField] private InputActionReference selectSlot3Action;

    [Tooltip("Fallback si les InputActions ne sont pas assignées (Input System, pas l'ancien Input).")]
    public Key fallbackSlot1Key = Key.Digit1;
    public Key fallbackSlot2Key = Key.Digit2;
    public Key fallbackSlot3Key = Key.Digit3;

    private NetworkObject _no;
    private NetworkPlayerState _ps;

    private int _selectedIndex = 0;
    private Vector3[] _baseScales;

    private InputAction _aSlot1;
    private InputAction _aSlot2;
    private InputAction _aSlot3;

    void Awake()
    {
        _no = GetComponentInParent<NetworkObject>();
        _ps = GetComponentInParent<NetworkPlayerState>();

        _aSlot1 = selectSlot1Action != null ? selectSlot1Action.action : null;
        _aSlot2 = selectSlot2Action != null ? selectSlot2Action.action : null;
        _aSlot3 = selectSlot3Action != null ? selectSlot3Action.action : null;

        if (_aSlot1 != null && !_aSlot1.enabled) _aSlot1.Enable();
        if (_aSlot2 != null && !_aSlot2.enabled) _aSlot2.Enable();
        if (_aSlot3 != null && !_aSlot3.enabled) _aSlot3.Enable();
    }

    void OnEnable()
    {
        if (_aSlot1 != null) _aSlot1.performed += OnSlot1;
        if (_aSlot2 != null) _aSlot2.performed += OnSlot2;
        if (_aSlot3 != null) _aSlot3.performed += OnSlot3;
    }

    void OnDisable()
    {
        if (_aSlot1 != null) _aSlot1.performed -= OnSlot1;
        if (_aSlot2 != null) _aSlot2.performed -= OnSlot2;
        if (_aSlot3 != null) _aSlot3.performed -= OnSlot3;
    }

    void Start()
    {
        _baseScales = new Vector3[slotImages.Length];
        for (int i = 0; i < slotImages.Length; i++)
            if (slotImages[i] != null) _baseScales[i] = slotImages[i].transform.localScale;

        if (_ps != null && _ps.Inventory != null)
            _ps.Inventory.OnListChanged += OnInventoryChanged;

        if (_ps != null && _ps.InventoryValue != null)
            _ps.InventoryValue.OnListChanged += OnInventoryValueChanged;

        if (_ps != null && _ps.InventoryCount != null)
            _ps.InventoryCount.OnListChanged += OnInventoryCountChanged;

        for (int i = 0; i < slotFuelBars.Length; i++)
        {
            var s = slotFuelBars[i];
            if (s == null) continue;
            s.interactable = false;
            s.minValue = 0f;
            s.maxValue = 1f;
        }

        for (int i = 0; i < slotFuelBarRoots.Length; i++)
            if (slotFuelBarRoots[i] != null) slotFuelBarRoots[i].SetActive(false);

        Refresh();
    }

    void OnDestroy()
    {
        if (_ps != null && _ps.Inventory != null)
            _ps.Inventory.OnListChanged -= OnInventoryChanged;

        if (_ps != null && _ps.InventoryValue != null)
            _ps.InventoryValue.OnListChanged -= OnInventoryValueChanged;

        if (_ps != null && _ps.InventoryCount != null)
            _ps.InventoryCount.OnListChanged -= OnInventoryCountChanged;
    }

    void Update()
    {
        if (_no == null || !_no.IsOwner) return;

        if (_aSlot1 == null && _aSlot2 == null && _aSlot3 == null)
        {
            var kb = Keyboard.current;
            if (kb == null) return;

            if (kb[fallbackSlot1Key].wasPressedThisFrame) { SelectSlot(0); }
            if (kb[fallbackSlot2Key].wasPressedThisFrame) { SelectSlot(1); }
            if (kb[fallbackSlot3Key].wasPressedThisFrame) { SelectSlot(2); }
        }
    }

    private void OnSlot1(InputAction.CallbackContext _) { if (IsOwner()) SelectSlot(0); }
    private void OnSlot2(InputAction.CallbackContext _) { if (IsOwner()) SelectSlot(1); }
    private void OnSlot3(InputAction.CallbackContext _) { if (IsOwner()) SelectSlot(2); }

    private bool IsOwner() => _no != null && _no.IsOwner;

    private void SelectSlot(int idx)
    {
        idx = Mathf.Clamp(idx, 0, 2);
        if (_selectedIndex == idx) return;
        _selectedIndex = idx;
        Refresh();
    }

    void OnInventoryChanged(NetworkListEvent<int> _) => Refresh();
    void OnInventoryValueChanged(NetworkListEvent<float> _) => Refresh();
    void OnInventoryCountChanged(NetworkListEvent<int> _) => Refresh();

    void Refresh()
    {
        if (_ps == null || _ps.Inventory == null) return;

        for (int i = 0; i < 3; i++)
        {
            int raw = (i < _ps.Inventory.Count) ? _ps.Inventory[i] : NetworkPlayerState.SLOT_EMPTY;

            // ---- ICON ----
            var img = (i < slotImages.Length) ? slotImages[i] : null;
            if (img != null)
            {
                if (raw == NetworkPlayerState.SLOT_EMPTY)
                {
                    img.enabled = false;
                    img.sprite = null;
                    img.color = Color.white;
                }
                else if (raw == NetworkPlayerState.SLOT_RESERVED)
                {
                    img.enabled = true;
                    img.sprite = reservedSprite;
                    img.color = reservedTint;
                }
                else
                {
                    var itemId = (ItemId)raw;
                    img.enabled = true;
                    img.color = Color.white;

                    if (itemDb != null && itemDb.TryGet(itemId, out var def))
                        img.sprite = def.icon;
                    else
                        img.sprite = null;
                }

                var baseScale = (i < _baseScales.Length) ? _baseScales[i] : Vector3.one;
                img.transform.localScale = (i == _selectedIndex) ? baseScale * 1.15f : baseScale;
            }

            // ---- STACK TEXT ----
            var txt = (i < slotCountTexts.Length) ? slotCountTexts[i] : null;
            if (txt != null)
            {
                if (raw == NetworkPlayerState.SLOT_EMPTY || raw == NetworkPlayerState.SLOT_RESERVED)
                {
                    txt.gameObject.SetActive(false);
                }
                else
                {
                    int count = (_ps.InventoryCount != null && i < _ps.InventoryCount.Count) ? _ps.InventoryCount[i] : 1;
                    if (count <= 0) count = 1;

                    var itemId = (ItemId)raw;
                    int maxStack = (itemDb != null) ? itemDb.GetMaxStack(itemId) : 1;

                    bool show = (maxStack > 1) && (count > 1);
                    txt.gameObject.SetActive(show);
                    if (show) txt.text = count.ToString();
                }
            }

            // ---- BAR (Essence OR Huile) ----
            var root = (i < slotFuelBarRoots.Length) ? slotFuelBarRoots[i] : null;
            var slider = (i < slotFuelBars.Length) ? slotFuelBars[i] : null;

            bool isFuelLike =
                (raw == (int)ItemId.Essence) ||
                (raw == (int)ItemId.HuileMoteur);

            if (root != null) root.SetActive(isFuelLike);

            if (slider != null)
            {
                if (!isFuelLike)
                {
                    slider.value = 0f;
                }
                else
                {
                    float v = (_ps.InventoryValue != null && i < _ps.InventoryValue.Count) ? _ps.InventoryValue[i] : 0f;

                    float denom = normalizeFuelOnTen ? Mathf.Max(0.0001f, fuelMaxForHud) : 100f;
                    float p = Mathf.Clamp01(v / denom);

                    slider.value = invertFuelBar ? (1f - p) : p;
                }
            }
        }
    }
}

