using TMPro;
using UnityEngine;

public class MatchTimerUI : MonoBehaviour
{
    [SerializeField] private TMP_Text timerText;

    void Update()
    {
        var gc = NetworkGameController.Instance;
        if (gc == null || timerText == null)
            return;

        int s = (int)gc.GetRemainingSeconds();
        int m = s / 60;
        int r = s % 60;

        timerText.text = $"{m:00}:{r:00}";
    }
}

