using Unity.Netcode;
using Unity.Netcode.Transports.UTP;
using UnityEngine;
using UnityEngine.UI;

public class NetworkUI : MonoBehaviour
{
    public Button hostButton;
    public Button clientButton;

    [Header("Localhost fallback (si Relay indisponible)")]
    public bool allowLocalhostFallback = true;

    void SetLocalhost()
    {
        var nm = NetworkManager.Singleton;
        if (nm == null) return;

        var utp = nm.GetComponent<UnityTransport>();
        if (utp == null)
        {
            Debug.LogError("[NetworkUI] UnityTransport manquant sur le NetworkManager.");
            return;
        }

        utp.SetConnectionData("127.0.0.1", 7777);
    }

    public void StartHost()
    {
        var nm = NetworkManager.Singleton;
        if (nm == null) { Debug.LogError("[NetworkUI] NetworkManager.Singleton null"); return; }
        if (nm.IsListening) { Debug.Log("[NetworkUI] Déjà démarré"); return; }

        // Relay (recommandé)
        if (RelayConnector.Instance != null)
        {
            RelayConnector.Instance.UI_StartHostWithRelay();
            return;
        }

        // Fallback localhost (optionnel)
        if (!allowLocalhostFallback)
        {
            Debug.LogError("[NetworkUI] RelayConnector.Instance est null et fallback localhost désactivé.");
            return;
        }

        Debug.LogWarning("[NetworkUI] RelayConnector.Instance est null, fallback localhost.");
        SetLocalhost();
        bool ok = nm.StartHost();
        Debug.Log($"[NetworkUI] StartHost() => {ok}");
    }

    public void StartClient()
    {
        var nm = NetworkManager.Singleton;
        if (nm == null) { Debug.LogError("[NetworkUI] NetworkManager.Singleton null"); return; }
        if (nm.IsListening) { Debug.Log("[NetworkUI] Déjà démarré"); return; }

        // Relay (recommandé)
        if (RelayConnector.Instance != null)
        {
            RelayConnector.Instance.UI_StartClientWithRelay();
            return;
        }

        // Fallback localhost (optionnel)
        if (!allowLocalhostFallback)
        {
            Debug.LogError("[NetworkUI] RelayConnector.Instance est null et fallback localhost désactivé.");
            return;
        }

        Debug.LogWarning("[NetworkUI] RelayConnector.Instance est null, fallback localhost.");
        SetLocalhost();
        bool ok = nm.StartClient();
        Debug.Log($"[NetworkUI] StartClient() => {ok}");
    }
}

