using UnityEngine;

public class UiGameSwitcher : MonoBehaviour
{
    public Camera menuCamera;
    public GameObject menuRoot; // contient Host/Client/StartGame
    public GameObject hudRoot;  // contient HudRoom/HudPhase/etc

    bool _switched;

    void Start()
    {
        if (menuRoot != null) menuRoot.SetActive(true);
        if (hudRoot != null) hudRoot.SetActive(false);
        if (menuCamera != null) menuCamera.enabled = true;
    }

    void Update()
    {
        if (_switched) return;

        
        var gc = Object.FindFirstObjectByType<NetworkGameController>();
        if (gc != null && gc.GameStarted.Value)
        {
            _switched = true;

            if (menuRoot != null) menuRoot.SetActive(false);
            if (hudRoot != null) hudRoot.SetActive(true);
            if (menuCamera != null) menuCamera.enabled = false;
        }
    }
}

