// UiStateGate.cs
using System.Collections;
using Unity.Netcode;
using UnityEngine;

public class UiStateGate : MonoBehaviour
{
    [Header("Refs (optionnel)")]
    public CanvasGroup canvasGroup;

    [Header("Visible quand...")]
    public bool showInLobby = true;
    public bool showInLoading = false;
    public bool showInRunning = false;
    public bool showInEnded = false;

    [Header("Behaviour")]
    public bool useCanvasGroupIfAvailable = true;
    public bool disableGameObjectIfHidden = false;
    public bool alsoDisableRaycasts = true;

    MatchLoadingCoordinator _coord;
    NetworkGameController _gc;

    bool _subCoord;
    bool _subGc;
    Coroutine _bindCo;

    void Awake()
    {
        if (canvasGroup == null) canvasGroup = GetComponent<CanvasGroup>();
    }

    void OnEnable()
    {
        ApplyHiddenImmediate();
        _bindCo = StartCoroutine(BindLoop());
    }

    void OnDisable()
    {
        if (_bindCo != null) { StopCoroutine(_bindCo); _bindCo = null; }
        Unsubscribe();
    }

    IEnumerator BindLoop()
    {
        while (true)
        {
            if (_coord == null)
                _coord = MatchLoadingCoordinator.Instance != null ? MatchLoadingCoordinator.Instance : FindUtil.FindFirst<MatchLoadingCoordinator>(includeInactive: true);

            if (_gc == null)
                _gc = NetworkGameController.Instance != null ? NetworkGameController.Instance : FindUtil.FindFirst<NetworkGameController>(includeInactive: true);

            if (_coord != null && !_subCoord)
            {
                _coord.State.OnValueChanged += OnAnyStateChanged;
                _subCoord = true;
            }

            if (_gc != null && !_subGc)
            {
                _gc.State.OnValueChanged += OnAnyStateChanged;
                _subGc = true;
            }

            ApplyFromCurrentState();
            yield return new WaitForSeconds(0.25f);
        }
    }

    void Unsubscribe()
    {
        if (_coord != null && _subCoord) _coord.State.OnValueChanged -= OnAnyStateChanged;
        if (_gc != null && _subGc) _gc.State.OnValueChanged -= OnAnyStateChanged;

        _subCoord = false;
        _subGc = false;
        _coord = null;
        _gc = null;
    }

    void OnAnyStateChanged(int previous, int next) => ApplyFromCurrentState();

    void ApplyFromCurrentState()
    {
        int stateInt = (int)MatchState.Lobby;

        // Priorité : Coordinator (existe pendant tout le chargement), sinon GC.
        if (_coord != null) stateInt = _coord.State.Value;
        else if (_gc != null) stateInt = _gc.State.Value;

        var st = (MatchState)stateInt;

        bool show =
            (st == MatchState.Lobby && showInLobby) ||
            (st == MatchState.Loading && showInLoading) ||
            (st == MatchState.Running && showInRunning) ||
            (st == MatchState.Ended && showInEnded);

        ApplyVisible(show);
    }

    void ApplyHiddenImmediate() => ApplyVisible(false);

    void ApplyVisible(bool show)
    {
        if (disableGameObjectIfHidden)
        {
            if (gameObject.activeSelf != show)
                gameObject.SetActive(show);
            return;
        }

        if (useCanvasGroupIfAvailable && canvasGroup != null)
        {
            canvasGroup.alpha = show ? 1f : 0f;
            if (alsoDisableRaycasts)
            {
                canvasGroup.blocksRaycasts = show;
                canvasGroup.interactable = show;
            }
        }
        else
        {
            // fallback : activer/désactiver enfants render/UI
            var children = transform.GetComponentsInChildren<Behaviour>(true);
            for (int i = 0; i < children.Length; i++)
            {
                var b = children[i];
                if (b == this) continue;
