using UnityEngine;
using UnityEngine.SceneManagement;

public class SceneBootstrapper : MonoBehaviour
{
    [SerializeField] private string mainMenuScene = "MainMenu";

    private void Start()
    {
        // Si on est déjà dans MainMenu (en additif), ne rien faire
        if (SceneManager.GetSceneByName(mainMenuScene).isLoaded)
            return;

        // Charge le menu en Single (remplace le contenu de scène),
        // Bootstrap reste vivant grâce à DontDestroyOnLoad.
        SceneManager.LoadScene(mainMenuScene, LoadSceneMode.Single);
    }
}

