using UnityEngine;
using Unity.Services.Core;
using Unity.Services.Authentication;

public class UGSBootstrap : MonoBehaviour
{
    public static UGSBootstrap Instance { get; private set; }

    [Header("Dev (Editor)")]
    [Tooltip("Optionnel. Si vide, on auto-génère un profil en Editor pour éviter les conflits en multi-instances.")]
    public string profile = "";

    public bool autoRandomProfileInEditor = true;

    public bool IsReady { get; private set; }

    async void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }

        Instance = this;
        DontDestroyOnLoad(gameObject);

        try
        {
            var options = new InitializationOptions();

#if UNITY_EDITOR
            var p = profile;
            if (string.IsNullOrWhiteSpace(p) && autoRandomProfileInEditor)
                p = "editor_" + Guid.NewGuid().ToString("N").Substring(0, 12);

            if (!string.IsNullOrWhiteSpace(p))
                options.SetProfile(p);
#else
            if (!string.IsNullOrWhiteSpace(profile))
                options.SetProfile(profile);
#endif

            await UnityServices.InitializeAsync(options);
            if (!AuthenticationService.Instance.IsSignedIn)
                await AuthenticationService.Instance.SignInAnonymouslyAsync();

            Debug.Log($"[UGS] Ready. PlayerId={AuthenticationService.Instance.PlayerId}");
            IsReady = true;
        }
        catch (Exception e)
        {
            Debug.LogException(e);
            IsReady = false;
        }
    }
}

