using UnityEngine;
using Unity.Netcode;
using UnityEngine.SceneManagement;

public class AudioManager : MonoBehaviour
{
    public static AudioManager Instance { get; private set; }

    [Header("Audio Sources")]
    public AudioSource musicSource;

    [Header("Music - Global")]
    [Tooltip("Musique pour le MainMenu (scène active).")]
    public AudioClip mainMenuMusic;

    [Tooltip("Musique pour le Lobby.")]
    public AudioClip lobbyMusic;

    [Header("Scene Names")]
    [Tooltip("Nom EXACT de ta scène MainMenu.")]
    public string mainMenuSceneName = "MainMenu";

    [Tooltip("Nom EXACT de ta scène Lobby (si dédiée).")]
    public string lobbySceneName = "Lobby";

    [Header("Fade Settings")]
    [Range(0f, 5f)]
    public float fadeTime = 1.5f;

    [Header("Debug")]
    public bool enableDebugLogs = true;

    private MapAudioSettings currentMapSettings;
    private AudioClip currentMusic;

    private bool isFading;
    private float fadeTimer;
    private AudioClip fadeTarget;
    private bool fadeToSilence;

    private float baseVolume = 1f;

    private MusicContext lastContext = MusicContext.Unknown;
    private enum MusicContext { Unknown, MainMenu, Lobby, InGame }

    private MatchLoadingCoordinator cachedCoordinator;
    private bool subscribedToCoordinator;

    void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        DontDestroyOnLoad(gameObject);
    }

    void OnEnable()
    {
        SceneManager.sceneLoaded += OnSceneLoaded;
    }

    void OnDisable()
    {
        SceneManager.sceneLoaded -= OnSceneLoaded;
        UnsubscribeFromCoordinator();
    }

    void Start()
    {
        InitMusicSource();
        TryBindMapSettings();
        TrySubscribeToCoordinator();
        UpdateMusicContext();
    }

    void Update()
    {
        if (musicSource == null) return;

        // Bind MapAudioSettings si pas encore fait
        if (currentMapSettings == null)
            TryBindMapSettings();

        // Subscribe au coordinator si pas encore fait
        if (!subscribedToCoordinator)
            TrySubscribeToCoordinator();

        // Update musique InGame seulement (les autres contextes sont gérés par events)
        if (lastContext == MusicContext.InGame)
            UpdateInGameMusic();

        // Gestion du fade
        if (isFading)
            HandleFade();
    }

    void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
        DebugLog($"[AudioManager] Scene loaded: {scene.name} (mode: {mode})");

        InitMusicSource();
        TryBindMapSettings();
        TrySubscribeToCoordinator();

        // Force refresh du contexte
        lastContext = MusicContext.Unknown;
        UpdateMusicContext();
    }

    void InitMusicSource()
    {
        if (musicSource == null) return;

        musicSource.loop = true;
        musicSource.playOnAwake = false;

        if (musicSource.volume <= 0f)
            musicSource.volume = 1f;

        baseVolume = musicSource.volume;
    }

    void TryBindMapSettings()
    {
#if UNITY_6000_0_OR_NEWER
        currentMapSettings = FindFirstObjectByType<MapAudioSettings>(FindObjectsInactive.Include);
#else
        currentMapSettings = FindObjectOfType<MapAudioSettings>(true);
#endif

        if (currentMapSettings != null)
            DebugLog($"[AudioManager] MapAudioSettings found!");
    }

    void TrySubscribeToCoordinator()
    {
        if (subscribedToCoordinator) return;

        var coord = GetMatchLoadingCoordinator();
        if (coord == null) return;

        if (cachedCoordinator != coord)
        {
            UnsubscribeFromCoordinator();
            cachedCoordinator = coord;
            cachedCoordinator.State.OnValueChanged += OnCoordinatorStateChanged;
            subscribedToCoordinator = true;
            DebugLog($"[AudioManager] Subscribed to MatchLoadingCoordinator.State");
        }
    }

    void UnsubscribeFromCoordinator()
    {
        if (cachedCoordinator != null && subscribedToCoordinator)
        {
            cachedCoordinator.State.OnValueChanged -= OnCoordinatorStateChanged;
            subscribedToCoordinator = false;
            DebugLog($"[AudioManager] Unsubscribed from MatchLoadingCoordinator.State");
        }
    }

    void OnCoordinatorStateChanged(int oldState, int newState)
    {
        DebugLog($"[AudioManager] Coordinator State changed: {(MatchState)oldState} → {(MatchState)newState}");

        // Force refresh du contexte
        lastContext = MusicContext.Unknown;
        UpdateMusicContext();
    }

    // -------------------------
    // CONTEXT DETECTION
    // -------------------------

    MusicContext GetCurrentContext()
    {
        var activeScene = SceneManager.GetActiveScene();
        string activeName = activeScene.IsValid() ? activeScene.name : "INVALID";

        DebugLog($"[AudioManager] --- Context Check ---");
        DebugLog($"[AudioManager] Active Scene: {activeName}");

        // SÉCURITÉ : Si on est dans BootStrap, attendre MainMenu (pas de musique)
        if (activeName == "BootStrap")
        {
            DebugLog($"[AudioManager] → Context = MAINMENU (BootStrap → waiting for MainMenu)");
            return MusicContext.MainMenu; // On force MainMenu (qui jouera quand MainMenu se chargera)
        }

        // PRIORITÉ 1 : Scène active = MainMenu
        if (activeName == mainMenuSceneName)
        {
            DebugLog($"[AudioManager] → Context = MAINMENU (active scene)");
            return MusicContext.MainMenu;
        }

        // PRIORITÉ 2 : Scène active = Lobby dédié
        if (!string.IsNullOrWhiteSpace(lobbySceneName) && activeName == lobbySceneName)
        {
            DebugLog($"[AudioManager] → Context = LOBBY (active scene)");
            return MusicContext.Lobby;
        }

        // PRIORITÉ 3 : Checker le Coordinator
        var coord = GetMatchLoadingCoordinator();

        if (coord != null)
        {
            var coordState = (MatchState)coord.State.Value;
            DebugLog($"[AudioManager] Coordinator State = {coordState}");

            if (coordState == MatchState.Lobby)
            {
                DebugLog($"[AudioManager] → Context = LOBBY (Coordinator)");
                return MusicContext.Lobby;
            }

            if (coordState == MatchState.Loading || coordState == MatchState.Running || coordState == MatchState.Ended)
            {
                DebugLog($"[AudioManager] → Context = INGAME (Coordinator)");
                return MusicContext.InGame;
            }
        }
        else
        {
            DebugLog($"[AudioManager] No Coordinator found");
        }

        // Fallback
        DebugLog($"[AudioManager] → Context = MAINMENU (fallback)");
        return MusicContext.MainMenu;
    }

    MatchLoadingCoordinator GetMatchLoadingCoordinator()
    {
        if (MatchLoadingCoordinator.Instance != null)
            return MatchLoadingCoordinator.Instance;

#if UNITY_6000_0_OR_NEWER
        return FindFirstObjectByType<MatchLoadingCoordinator>(FindObjectsInactive.Include);
#else
        return FindObjectOfType<MatchLoadingCoordinator>(true);
#endif
    }

    void UpdateMusicContext()
    {
        var context = GetCurrentContext();

        if (context == lastContext)
        {
            DebugLog($"[AudioManager] Context unchanged: {context}");
            return;
        }

        DebugLog($"[AudioManager] Context changed: {lastContext} → {context}");
        lastContext = context;

        switch (context)
        {
            case MusicContext.MainMenu:
                if (mainMenuMusic != null)
                {
                    DebugLog($"[AudioManager] → Playing MainMenu music: {mainMenuMusic.name}");
                    RequestMusicChange(mainMenuMusic);
                }
                else
                {
                    DebugLog($"[AudioManager] → MainMenu music NULL → Silence");
                    RequestSilence();
                }
                break;

            case MusicContext.Lobby:
                if (lobbyMusic != null)
                {
                    DebugLog($"[AudioManager] → Playing Lobby music: {lobbyMusic.name}");
                    RequestMusicChange(lobbyMusic);
                }
                else
                {
                    DebugLog($"[AudioManager] → Lobby music NULL → Silence");
                    RequestSilence();
                }
                break;

            case MusicContext.InGame:
                DebugLog($"[AudioManager] → InGame context");
                UpdateInGameMusic();
                break;
        }
    }

    void UpdateInGameMusic()
    {
        if (currentMapSettings == null)
        {
            DebugLog($"[AudioManager] InGame but no MapAudioSettings");
            return;
        }

        var gc = NetworkGameController.Instance;
        var localPlayer = GetLocalPlayerState();

        bool hasRuntimeState = (gc != null && localPlayer != null);

        bool isBlackout = hasRuntimeState && gc.IsBlackout.Value;
        bool isGhost = hasRuntimeState && !localPlayer.Alive.Value;
        bool isPossessed = hasRuntimeState && (PlayerRole)localPlayer.Role.Value == PlayerRole.Possede;
        bool isLastPlayerAlive = hasRuntimeState && localPlayer.Alive.Value && CountAlivePlayers() == 1;

        float matchProgress = 0f;
        if (hasRuntimeState)
            matchProgress = CalculateMatchProgress(gc);

        AudioClip desiredMusic = currentMapSettings.GetCurrentMusic(
            isBlackout,
            isGhost,
            isPossessed,
            isLastPlayerAlive,
            matchProgress
        );

        if (desiredMusic == null)
            desiredMusic = currentMapSettings.musicStart;

        if (desiredMusic != null && desiredMusic != currentMusic)
        {
            DebugLog($"[AudioManager] InGame music: {desiredMusic.name}");
            RequestMusicChange(desiredMusic);
        }
    }

    // -------------------------
    // MUSIC SWITCHING (avec protection anti-double-fade)
    // -------------------------

    void RequestMusicChange(AudioClip newClip)
    {
        if (musicSource == null || newClip == null) return;

        // Déjà en train de fader vers ce clip
        if (isFading && fadeTarget == newClip)
        {
            DebugLog($"[AudioManager] Already fading to {newClip.name}, skip");
            return;
        }

        // Déjà en train de jouer ce clip
        if (currentMusic == newClip && musicSource.isPlaying && musicSource.clip == newClip && !isFading)
        {
            DebugLog($"[AudioManager] Already playing {newClip.name}");
            return;
        }

        // Pas de musique en cours → direct
        if (musicSource.clip == null || !musicSource.isPlaying)
        {
            DebugLog($"[AudioManager] Playing direct: {newClip.name}");
            PlayMusicDirect(newClip);
            return;
        }

        // Crossfade
        DebugLog($"[AudioManager] Starting fade: {musicSource.clip?.name} → {newClip.name}");
        StartFade(newClip);
    }

    void RequestSilence()
    {
        if (musicSource == null) return;

        if (musicSource.clip == null || !musicSource.isPlaying)
        {
            DebugLog($"[AudioManager] Already silent");
            currentMusic = null;
            return;
        }

        DebugLog($"[AudioManager] Fading to silence");
        StartFadeToSilence();
    }

    void PlayMusicDirect(AudioClip clip)
    {
        if (musicSource == null || clip == null) return;

        StopFade();

        musicSource.clip = clip;
        musicSource.volume = baseVolume;
        musicSource.Play();

        currentMusic = clip;
    }

    void StartFade(AudioClip target)
    {
        fadeTarget = target;
        fadeToSilence = false;
        isFading = true;
        fadeTimer = 0f;
    }

    void StartFadeToSilence()
    {
        fadeTarget = null;
        fadeToSilence = true;
        isFading = true;
        fadeTimer = 0f;
    }

    void StopFade()
    {
        isFading = false;
        fadeTimer = 0f;
        fadeTarget = null;
        fadeToSilence = false;
    }

    void HandleFade()
    {
        if (musicSource == null) return;

        float duration = Mathf.Max(0.1f, fadeTime);
        fadeTimer += Time.deltaTime;

        float t = Mathf.Clamp01(fadeTimer / duration);

        if (t < 0.5f)
        {
            // Fade out
            musicSource.volume = Mathf.Lerp(baseVolume, 0f, t * 2f);
        }
        else
        {
            // Switch au milieu
            if (fadeToSilence)
            {
                if (musicSource.isPlaying)
                {
                    musicSource.Stop();
                    musicSource.clip = null;
                    currentMusic = null;
                }
            }
            else if (fadeTarget != null && musicSource.clip != fadeTarget)
            {
                musicSource.clip = fadeTarget;
                musicSource.Play();
                currentMusic = fadeTarget;
                DebugLog($"[AudioManager] Fade switch to: {fadeTarget.name}");
            }

            // Fade in
            float targetVol = fadeToSilence ? 0f : baseVolume;
            musicSource.volume = Mathf.Lerp(0f, targetVol, (t - 0.5f) * 2f);
        }

        if (t >= 1f)
        {
            musicSource.volume = baseVolume;
            DebugLog($"[AudioManager] Fade complete");
            StopFade();
        }
    }

    // -------------------------
    // NETWORK HELPERS
    // -------------------------

    NetworkPlayerState GetLocalPlayerState()
    {
        var nm = NetworkManager.Singleton;
        if (nm == null || !nm.IsClient) return null;

        var localObj = nm.SpawnManager?.GetLocalPlayerObject();
        if (localObj == null) return null;

        return localObj.GetComponent<NetworkPlayerState>();
    }

    int CountAlivePlayers()
    {
#if UNITY_6000_0_OR_NEWER
        var players = FindObjectsByType<NetworkPlayerState>(FindObjectsInactive.Include, FindObjectsSortMode.None);
#else
        var players = FindObjectsOfType<NetworkPlayerState>(true);
#endif
        int count = 0;
        foreach (var ps in players)
        {
            if (ps == null) continue;
            if (ps.Alive.Value && !ps.Escaped.Value) count++;
        }
        return count;
    }

    float CalculateMatchProgress(NetworkGameController gc)
    {
        if (gc == null) return 0f;
        if (gc.MatchStartTime.Value <= 0 || gc.MatchEndTime.Value <= gc.MatchStartTime.Value)
            return 0f;

        double now = NetworkManager.Singleton?.LocalTime.Time ?? Time.timeAsDouble;
        double elapsed = now - gc.MatchStartTime.Value;
        double total = gc.MatchEndTime.Value - gc.MatchStartTime.Value;

        return Mathf.Clamp01((float)(elapsed / total));
    }

    public void SetMapSettings(MapAudioSettings settings)
    {
        currentMapSettings = settings;
        if (lastContext == MusicContext.InGame)
            UpdateInGameMusic();
    }

    void DebugLog(string message)
    {
        if (enableDebugLogs)
            Debug.Log(message);
    }
}

