using UnityEngine;
using UnityEngine.SceneManagement;

public class BlackoutAudioDirector : MonoBehaviour
{
    [Header("Debug")]
    [SerializeField] private bool verboseLogs = true;
    [SerializeField] private bool autoFixMultipleAudioListeners = true;

    [Header("Scenes")]
    [SerializeField] private string mainMenuSceneName = "MainMenu";

    [Tooltip("IMPORTANT (Additive): mets ici TOUTES tes scènes 'jeu' susceptibles d'être chargées (Mapping/Lightning/Gameplay...).")]
    [SerializeField] private string[] gameSceneNames = { "MansionMapping", "MansionLightning", "MansionGameplay" };

    [Header("Sources (optionnel)")]
    public AudioSource musicSource;
    public AudioSource sfxSource;

    [Header("Clips")]
    public AudioClip normalMusic;
    public AudioClip blackoutMusic;
    public AudioClip screamSfx;

    [Header("Options")]
    [Range(0f, 1f)] public float musicVolumeNormal = 0.7f;
    [Range(0f, 1f)] public float musicVolumeBlackout = 0.7f;
    [Range(0f, 1f)] public float screamVolume = 1f;

    private static BlackoutAudioDirector _instance;

    private NetworkGameController _gc;
    private bool _subscribed;

    void Awake()
    {
        if (_instance != null && _instance != this)
        {
            Log($"Duplicate detected -> destroying '{name}'", LogType.Warning);
            Destroy(gameObject);
            return;
        }

        _instance = this;
        DontDestroyOnLoad(gameObject);

        Log($"Awake OK. ActiveScene={SceneManager.GetActiveScene().name}", LogType.Log);

        EnsureAudioSourcesExistOnThisObject();
        if (autoFixMultipleAudioListeners) FixAudioListeners();
    }

    void OnEnable()
    {
        SceneManager.activeSceneChanged += OnActiveSceneChanged;
        SceneManager.sceneLoaded += OnSceneLoaded;
        SceneManager.sceneUnloaded += OnSceneUnloaded;

        Log("OnEnable -> subscribed to scene events", LogType.Log);

        EvaluateContextAndApply(reason: "OnEnable");
    }

    void OnDisable()
    {
        SceneManager.activeSceneChanged -= OnActiveSceneChanged;
        SceneManager.sceneLoaded -= OnSceneLoaded;
        SceneManager.sceneUnloaded -= OnSceneUnloaded;

        Log("OnDisable -> unsubscribed from scene events", LogType.Log);

        UnsubscribeFromGameController();
    }

    void Update()
    {
        // Si le GC est détruit/recréé, on se remet en état "non abonné"
        if (_subscribed && _gc == null)
        {
            Log("Subscribed but _gc is null -> resetting subscription state", LogType.Warning);
            _subscribed = false;
        }

        // Tant qu’on n’est pas en game context, on ne hook pas le GC
        if (!IsInGameContext())
            return;

        if (!_subscribed)
            TryHookToGameController();
    }

    void OnActiveSceneChanged(Scene oldScene, Scene newScene)
    {
        Log($"Active scene changed: '{oldScene.name}' -> '{newScene.name}'", LogType.Log);

        if (autoFixMultipleAudioListeners) FixAudioListeners();

        // En Additive, la scène active peut changer (ex: Lightning) sans qu’on sorte du jeu.
        EvaluateContextAndApply(reason: $"activeSceneChanged -> {newScene.name}");
    }

    void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
        Log($"Scene loaded: '{scene.name}' (mode={mode})", LogType.Log);

        if (autoFixMultipleAudioListeners) FixAudioListeners();

        EvaluateContextAndApply(reason: $"sceneLoaded -> {scene.name}");
    }

    void OnSceneUnloaded(Scene scene)
    {
        Log($"Scene unloaded: '{scene.name}'", LogType.Log);

        if (autoFixMultipleAudioListeners) FixAudioListeners();

        EvaluateContextAndApply(reason: $"sceneUnloaded -> {scene.name}");
    }

    // ---------- Core logic ----------

    void EvaluateContextAndApply(string reason)
    {
        // Si menu chargé => on coupe net
        if (IsMainMenuLoadedOrActive())
        {
            Log($"Main menu detected -> stop music & unsubscribe ({reason})", LogType.Log);
            StopMusic();
            UnsubscribeFromGameController();
            return;
        }

        // Si aucune scène de jeu chargée => on coupe
        if (!IsInGameContext())
        {
            Log($"Not in game context -> stop music & unsubscribe ({reason})", LogType.Log);
            StopMusic();
            UnsubscribeFromGameController();
            return;
        }

        // Sinon on est "en jeu": au minimum, lancer une musique par défaut
        EnsureAudioSourcesExistOnThisObject();

        if (_gc != null)
        {
            ApplyBlackoutState(_gc.IsBlackout.Value, playScreamIfEntering: false, reason: $"{reason} (apply GC state)");
        }
        else
        {
            ApplyBlackoutState(isBlackout: false, playScreamIfEntering: false, reason: $"{reason} (default normal music)");
        }
    }

    bool IsMainMenuLoadedOrActive()
    {
        if (SceneManager.GetActiveScene().name == mainMenuSceneName)
            return true;

        for (int i = 0; i < SceneManager.sceneCount; i++)
        {
            var s = SceneManager.GetSceneAt(i);
            if (s.isLoaded && s.name == mainMenuSceneName)
                return true;
        }

        return false;
    }

    bool IsInGameContext()
    {
        // Hors menu, si la liste est vide => on considère que c'est "in game"
        if (gameSceneNames == null || gameSceneNames.Length == 0)
            return !IsMainMenuLoadedOrActive();

        // Additive: "in game" si AU MOINS une scène de jeu est chargée
        for (int i = 0; i < SceneManager.sceneCount; i++)
        {
            var s = SceneManager.GetSceneAt(i);
            if (!s.isLoaded) continue;

            for (int j = 0; j < gameSceneNames.Length; j++)
                if (s.name == gameSceneNames[j])
                    return true;
        }

        return false;
    }

    void TryHookToGameController()
    {
        if (_subscribed) return;

        // ✅ Unity 6: remplace FindObjectOfType<T>(true)
        _gc = UnityEngine.Object.FindFirstObjectByType<NetworkGameController>(FindObjectsInactive.Include);
        if (_gc == null)
        {
            Log("NetworkGameController not found yet (will retry).", LogType.Log);
            return;
        }

        _subscribed = true;
        _gc.IsBlackout.OnValueChanged += OnBlackoutChanged;

        Log($"Hooked to NetworkGameController. Current IsBlackout={_gc.IsBlackout.Value}", LogType.Log);

        ApplyBlackoutState(_gc.IsBlackout.Value, playScreamIfEntering: false, reason: "Hook -> apply current state");
    }

    void UnsubscribeFromGameController()
    {
        if (!_subscribed) return;

        if (_gc != null)
        {
            _gc.IsBlackout.OnValueChanged -= OnBlackoutChanged;
            Log("Unsubscribed from NetworkGameController.IsBlackout", LogType.Log);
        }

        _gc = null;
        _subscribed = false;
    }

    void OnBlackoutChanged(bool previous, bool next)
    {
        Log($"OnBlackoutChanged: {previous} -> {next}", LogType.Log);

        if (!IsInGameContext())
        {
            Log("Ignoring blackout change (not in game context).", LogType.Log);
            return;
        }

        if (next && !previous)
            ApplyBlackoutState(true, playScreamIfEntering: true, reason: "Entering blackout");
        else if (!next && previous)
            ApplyBlackoutState(false, playScreamIfEntering: false, reason: "Leaving blackout");
    }

    void ApplyBlackoutState(bool isBlackout, bool playScreamIfEntering, string reason)
    {
        if (!IsInGameContext())
        {
            Log($"ApplyBlackoutState ignored (not in game context). Reason={reason}", LogType.Log);
            return;
        }

        PlayMusicSafe(isBlackout, reason);

        if (playScreamIfEntering)
            PlayScreamSafe(reason);
    }

    void PlayMusicSafe(bool isBlackout, string reason)
    {
        if (musicSource == null)
        {
            Log($"musicSource is NULL -> cannot play music. Reason={reason}", LogType.Error);
            return;
        }

        AudioClip targetClip = isBlackout ? blackoutMusic : normalMusic;

        // Fallback si blackoutMusic manquant
        if (targetClip == null && normalMusic != null)
        {
            Log($"Target clip is NULL (isBlackout={isBlackout}), fallback to normalMusic. Reason={reason}", LogType.Warning);
            targetClip = normalMusic;
            isBlackout = false;
        }

        if (targetClip == null)
        {
            Log($"No music clip assigned (normalMusic/blackoutMusic are NULL). Reason={reason}", LogType.Error);
            return;
        }

        float targetVol = isBlackout ? musicVolumeBlackout : musicVolumeNormal;
        string groupName = musicSource.outputAudioMixerGroup != null ? musicSource.outputAudioMixerGroup.name : "None";

        Log($"Play music: clip='{targetClip.name}', vol={targetVol}, mixerGroup={groupName}, reason={reason}", LogType.Log);

        if (musicSource.clip != targetClip)
        {
            musicSource.clip = targetClip;
            musicSource.loop = true;
        }

        musicSource.volume = targetVol;

        if (!musicSource.isPlaying)
            musicSource.Play();
    }

    void PlayScreamSafe(string reason)
    {
        if (sfxSource == null)
        {
            Log($"sfxSource is NULL -> cannot play scream. Reason={reason}", LogType.Warning);
            return;
        }

        if (screamSfx == null)
        {
            Log($"screamSfx is NULL -> cannot PlayOneShot. Reason={reason}", LogType.Warning);
            return;
        }

        Log($"Play scream: clip='{screamSfx.name}', vol={screamVolume}, reason={reason}", LogType.Log);
        sfxSource.PlayOneShot(screamSfx, screamVolume);
    }

    void StopMusic()
    {
        if (musicSource == null)
        {
            Log("StopMusic: musicSource is NULL", LogType.Log);
            return;
        }

        Log("StopMusic: stopping and clearing clip", LogType.Log);
        musicSource.Stop();
        musicSource.clip = null;
    }

    // ---------- Utilities ----------

    void EnsureAudioSourcesExistOnThisObject()
    {
        // But: le plus fiable en Additive, c'est d'avoir les AudioSource sur l'objet DontDestroyOnLoad.
        if (musicSource == null)
        {
            var t = transform.Find("MusicSource");
            if (t == null)
            {
                var go = new GameObject("MusicSource");
                go.transform.SetParent(transform);
                musicSource = go.AddComponent<AudioSource>();
            }
            else musicSource = t.GetComponent<AudioSource>() ?? t.gameObject.AddComponent<AudioSource>();

            Log("Created/attached musicSource on AudioManager (DontDestroyOnLoad).", LogType.Log);
        }

        if (sfxSource == null)
        {
            var t = transform.Find("SfxSource");
            if (t == null)
            {
                var go = new GameObject("SfxSource");
                go.transform.SetParent(transform);
                sfxSource = go.AddComponent<AudioSource>();
            }
            else sfxSource = t.GetComponent<AudioSource>() ?? t.gameObject.AddComponent<AudioSource>();

            Log("Created/attached sfxSource on AudioManager (DontDestroyOnLoad).", LogType.Log);
        }
    }

    void FixAudioListeners()
    {
        // ✅ Unity 6: remplace FindObjectsOfType<AudioListener>(true)
        var listeners = UnityEngine.Object.FindObjectsByType<AudioListener>(
            FindObjectsInactive.Include,
            FindObjectsSortMode.None
        );

        if (listeners == null) return;
        if (listeners.Length <= 1) return;

        // On garde en priorité celui de la MainCamera, sinon le premier.
        AudioListener keep = null;
        for (int i = 0; i < listeners.Length; i++)
        {
            if (listeners[i] != null && listeners[i].CompareTag("MainCamera"))
            {
                keep = listeners[i];
                break;
            }
        }
        if (keep == null) keep = listeners[0];

        int disabled = 0;
        for (int i = 0; i < listeners.Length; i++)
        {
            var l = listeners[i];
            if (l == null) continue;
            if (l == keep) continue;

            if (l.enabled)
            {
                l.enabled = false;
                disabled++;
            }
        }

        if (disabled > 0)
            Log($"Multiple AudioListeners detected ({listeners.Length}). Disabled {disabled}, kept '{keep.name}'.", LogType.Warning);
    }

    void Log(string msg, LogType type)
    {
        if (!verboseLogs) return;

        string prefix = $"[BlackoutAudioDirector] {msg}";
        switch (type)
        {
            case LogType.Warning: Debug.LogWarning(prefix, this); break;
            case LogType.Error: Debug.LogError(prefix, this); break;
            default: Debug.Log(prefix, this); break;
        }
    }
}

