using System.Collections.Generic;
using UnityEngine;

public class AnimatorParameterMirror : MonoBehaviour
{
    [Header("Source (driven by gameplay scripts / NetworkAnimator)")]
    public Animator sourceAnimator;   // PolygonSyntyCharacter Animator

    [Header("Target (the spawned skin Animator)")]
    public Animator targetAnimator;   // Set at runtime by PlayerSkinSwapper

    [Tooltip("Copie aussi la vitesse de lecture de l'animator.")]
    public bool copySpeed = true;

    private readonly Dictionary<int, AnimatorControllerParameterType> _srcParams = new();
    private readonly Dictionary<int, AnimatorControllerParameterType> _tgtParams = new();
    private bool _cacheBuilt;

    public void SetTarget(Animator target)
    {
        targetAnimator = target;
        RebuildCache();
        SyncOnce();
    }

    public void RebuildCache()
    {
        _srcParams.Clear();
        _tgtParams.Clear();
        _cacheBuilt = false;

        if (sourceAnimator == null || targetAnimator == null) return;

        var sp = sourceAnimator.parameters;
        for (int i = 0; i < sp.Length; i++)
            _srcParams[sp[i].nameHash] = sp[i].type;

        var tp = targetAnimator.parameters;
        for (int i = 0; i < tp.Length; i++)
            _tgtParams[tp[i].nameHash] = tp[i].type;

        _cacheBuilt = true;
    }

    public void SyncOnce()
    {
        if (sourceAnimator == null || targetAnimator == null) return;
        if (!_cacheBuilt) RebuildCache();

        foreach (var kv in _srcParams)
        {
            int hash = kv.Key;
            var type = kv.Value;

            if (!_tgtParams.TryGetValue(hash, out var tgtType)) continue;
            if (tgtType != type) continue;

            switch (type)
            {
                case AnimatorControllerParameterType.Float:
                    targetAnimator.SetFloat(hash, sourceAnimator.GetFloat(hash));
                    break;

                case AnimatorControllerParameterType.Int:
                    targetAnimator.SetInteger(hash, sourceAnimator.GetInteger(hash));
                    break;

                case AnimatorControllerParameterType.Bool:
                    targetAnimator.SetBool(hash, sourceAnimator.GetBool(hash));
                    break;

                // Trigger: pas fiable à "lire", donc on ignore.
                case AnimatorControllerParameterType.Trigger:
                    break;
            }
        }

        if (copySpeed)
            targetAnimator.speed = sourceAnimator.speed;
    }

    private void LateUpdate()
    {
        if (sourceAnimator == null || targetAnimator == null) return;
        if (!_cacheBuilt) RebuildCache();

        SyncOnce();
    }
}

