public class SlotFollowWorld : MonoBehaviour
{
    public Camera worldCamera;          // caméra lobby 3D
    public RectTransform canvasRect;    // RectTransform du Canvas
    public Transform target;            // Stand_X/UiAnchor
    public Vector2 pixelOffset = new Vector2(0, 20);
    public bool hideIfBehindCamera = true;

    RectTransform _rt;

    void Awake()
    {
        _rt = (RectTransform)transform;
        if (canvasRect == null)
            canvasRect = GetComponentInParent<Canvas>().GetComponent<RectTransform>();
    }

    void LateUpdate()
    {
        if (worldCamera == null || target == null || canvasRect == null) return;

        Vector3 sp = worldCamera.WorldToScreenPoint(target.position);

        if (hideIfBehindCamera && sp.z < 0f)
        {
            if (_rt.gameObject.activeSelf) _rt.gameObject.SetActive(false);
            return;
        }

        if (!_rt.gameObject.activeSelf) _rt.gameObject.SetActive(true);

        RectTransformUtility.ScreenPointToLocalPointInRectangle(
            canvasRect,
            new Vector2(sp.x, sp.y) + pixelOffset,
            null, // Overlay
            out var localPos
        );

        _rt.anchoredPosition = localPos;
    }
}

