using System.Collections.Generic;
using System.Linq;
using UnityEngine;

public class BlackoutAffectable : MonoBehaviour
{
    [Header("Light components (lampe, plafonnier, bougie...)")]
    public List<Light> lights = new();

    [Header("Optional: flame particles (bougie)")]
    public List<ParticleSystem> particles = new();

    [Header("Optional: emissive renderers (ampoule qui brille / fenêtre)")]
    public List<Renderer> emissiveRenderers = new();

    [Header("Shader properties")]
    public string emissionProperty = "_EmissionColor";

    [Tooltip("Noircit aussi _BaseColor/_Color (utile pour Unlit/ShaderGraph et pour forcer extinction).")]
    public bool darkenBaseColorToo = true;

    [Header("Hard off (recommandé pour la flamme)")]
    [Tooltip("Désactive complètement certains Renderers pendant le blackout (ex: quads de flamme).")]
    public bool disableSpecificRenderersOnBlackout = true;

    public List<Renderer> renderersToDisable = new();

    [Header("Auto-fill if empty")]
    public bool autoFindInChildren = true;

    [Header("Debug")]
    public bool logAutoFill = false;

    // Cache état initial
    private readonly Dictionary<Light, bool> _lightEnabled = new();
    private readonly Dictionary<ParticleSystem, bool> _particleWasPlaying = new();
    private readonly Dictionary<Renderer, bool> _rendererEnabled = new();

    // Cache couleurs d'origine par (renderer, materialIndex)
    private readonly Dictionary<(Renderer r, int i), Color> _origEmission = new();
    private readonly Dictionary<(Renderer r, int i), Color> _origBaseColor = new();

    void Awake()
    {
        AutoFillIfNeeded();
        CacheInitialState();
    }

    // Appelé par BlackoutFX uniquement
    public void SetBlackout(bool blackout) => Apply(blackout);

    public void Apply(bool blackout)
    {
        // Lights
        foreach (var l in lights)
        {
            if (!l) continue;
            l.enabled = blackout ? false : (_lightEnabled.TryGetValue(l, out var en) ? en : true);
        }

        // Particles
        foreach (var p in particles)
        {
            if (!p) continue;

            if (blackout)
            {
                if (p.isPlaying)
                    p.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
            }
            else
            {
                if (_particleWasPlaying.TryGetValue(p, out var was) && was)
                    p.Play();
            }
        }

        // Hard disable renderers (flamme etc.)
        if (disableSpecificRenderersOnBlackout)
        {
            foreach (var r in renderersToDisable)
            {
                if (!r) continue;
                r.enabled = blackout ? false : (_rendererEnabled.TryGetValue(r, out var en) ? en : true);
            }
        }

        // Emission + BaseColor
        foreach (var r in emissiveRenderers)
        {
            if (!r) continue;

            var mats = r.materials; // instances runtime
            for (int i = 0; i < mats.Length; i++)
            {
                var m = mats[i];
                if (!m) continue;

                // Emission
                if (m.HasProperty(emissionProperty))
                {
                    if (blackout) m.SetColor(emissionProperty, Color.black);
                    else if (_origEmission.TryGetValue((r, i), out var e)) m.SetColor(emissionProperty, e);
                }

                // BaseColor / Color
                if (darkenBaseColorToo)
                {
                    if (m.HasProperty("_BaseColor"))
                    {
                        if (blackout) m.SetColor("_BaseColor", Color.black);
                        else if (_origBaseColor.TryGetValue((r, i), out var bc)) m.SetColor("_BaseColor", bc);
                    }
                    else if (m.HasProperty("_Color"))
                    {
                        if (blackout) m.SetColor("_Color", Color.black);
                        else if (_origBaseColor.TryGetValue((r, i), out var cc)) m.SetColor("_Color", cc);
                    }
                }
            }
        }
    }

    void AutoFillIfNeeded()
    {
        if (!autoFindInChildren) return;

        if (lights == null || lights.Count == 0)
            lights = GetComponentsInChildren<Light>(true).ToList();

        if (particles == null || particles.Count == 0)
            particles = GetComponentsInChildren<ParticleSystem>(true).ToList();

        if (emissiveRenderers == null || emissiveRenderers.Count == 0)
            emissiveRenderers = GetComponentsInChildren<Renderer>(true).ToList();

        if (logAutoFill)
            Debug.Log($"[BlackoutAffectable] '{name}' autofill -> lights={lights.Count} particles={particles.Count} emissiveRenderers={emissiveRenderers.Count} renderersToDisable={renderersToDisable?.Count ?? 0}");
    }

    void CacheInitialState()
    {
        _lightEnabled.Clear();
        _particleWasPlaying.Clear();
        _rendererEnabled.Clear();
        _origEmission.Clear();
        _origBaseColor.Clear();

        foreach (var l in lights) if (l) _lightEnabled[l] = l.enabled;
        foreach (var p in particles) if (p) _particleWasPlaying[p] = p.isPlaying;
        foreach (var r in renderersToDisable) if (r) _rendererEnabled[r] = r.enabled;

        foreach (var r in emissiveRenderers)
        {
            if (!r) continue;

            var mats = r.materials;
            for (int i = 0; i < mats.Length; i++)
            {
                var m = mats[i];
                if (!m) continue;

                if (m.HasProperty(emissionProperty))
                    _origEmission[(r, i)] = m.GetColor(emissionProperty);

                if (m.HasProperty("_BaseColor"))
                    _origBaseColor[(r, i)] = m.GetColor("_BaseColor");
                else if (m.HasProperty("_Color"))
                    _origBaseColor[(r, i)] = m.GetColor("_Color");
            }
        }
    }
}

