using System.Collections.Generic;
using Unity.Netcode;
using UnityEngine;
using UnityEngine.SceneManagement;

public class BlackoutFX : MonoBehaviour
{
    [Header("Optional overlay (peut être null)")]
    public CanvasGroup blackScreen;
    [Range(0f, 1f)] public float overlayAlpha = 0f; // si tu veux "noir garanti" => 1

    [Header("Auto-find all BlackoutAffectable in loaded scenes")]
    public bool autoFind = true;
    public bool refreshOnSceneLoaded = true;
    public List<BlackoutAffectable> affectables = new();

    private NetworkGameController _gc;
    private NetworkPlayerState _ps;

    private bool _lastEffective;

    void Awake()
    {
        if (autoFind) RefreshList();
        ApplyOverlay(false);
    }

    void OnEnable()
    {
        if (refreshOnSceneLoaded)
            SceneManager.sceneLoaded += OnSceneLoaded;
    }

    void OnDisable()
    {
        if (refreshOnSceneLoaded)
            SceneManager.sceneLoaded -= OnSceneLoaded;
    }

    void OnSceneLoaded(Scene s, LoadSceneMode m)
    {
        if (!autoFind) return;
        RefreshList();
        Recalc(force: true);
    }

    public void RefreshList()
    {
#if UNITY_2023_1_OR_NEWER
        affectables.Clear();
        affectables.AddRange(FindObjectsByType<BlackoutAffectable>(FindObjectsInactive.Include, FindObjectsSortMode.None));
#else
        affectables.Clear();
        affectables.AddRange(FindObjectsOfType<BlackoutAffectable>(true));
#endif
    }

    void Update()
    {
        if (NetworkManager.Singleton == null) return;

        if (_gc == null) _gc = NetworkGameController.Instance;
        if (_gc == null) return;

        if (_ps == null)
        {
            var po = NetworkManager.Singleton.SpawnManager.GetLocalPlayerObject();
            if (po != null) _ps = po.GetComponent<NetworkPlayerState>();
        }

        Recalc(force: false);
    }

    void Recalc(bool force)
    {
        if (_gc == null) return;

        bool running = (MatchState)_gc.State.Value == MatchState.Running;

        bool isPossede = _ps != null && (PlayerRole)_ps.Role.Value == PlayerRole.Possede;

        // Survivants uniquement => blackout "physique"
        bool effective = running && _gc.IsBlackout.Value && !isPossede;

        if (!force && effective == _lastEffective) return;
        _lastEffective = effective;

        for (int i = 0; i < affectables.Count; i++)
            if (affectables[i] != null) affectables[i].SetBlackout(effective);

        ApplyOverlay(effective);

        // Debug utile
        if (Time.frameCount % 120 == 0)
            Debug.Log($"[BlackoutFX] state={(MatchState)_gc.State.Value} blackout={_gc.IsBlackout.Value} role={(isPossede ? "Possede" : "Survivant")} => effective={effective}");
    }

    void ApplyOverlay(bool on)
    {
        if (blackScreen == null) return;

        blackScreen.gameObject.SetActive(on && overlayAlpha > 0f);
        if (!on || overlayAlpha <= 0f) return;

        blackScreen.alpha = overlayAlpha;
        blackScreen.blocksRaycasts = false;
        blackScreen.interactable = false;
    }
}

