using TMPro;
using Unity.Netcode;
using UnityEngine;

public class BlackoutUI : MonoBehaviour
{
    public CanvasGroup blackScreen; // ton panel noir plein écran + CanvasGroup
    public TMP_Text timerText;      // optionnel

    private NetworkGameController _gc;
    private NetworkPlayerState _ps;

    void Start()
    {
        SetBlack(false);
    }

    void Update()
    {
        if (_gc == null) _gc = NetworkGameController.Instance;
        if (_gc == null || NetworkManager.Singleton == null) return;

        if (_ps == null)
        {
            var all = FindObjectsByType<NetworkObject>(FindObjectsInactive.Exclude, FindObjectsSortMode.None);
            foreach (var no in all)
            {
                if (no.IsSpawned && no.IsPlayerObject && no.IsOwner)
                {
                    _ps = no.GetComponent<NetworkPlayerState>();
                    break;
                }
            }
        }

        bool blackout = _gc.IsBlackout.Value;

        // possédé = vision intégrale
        bool isPossede = _ps != null && (PlayerRole)_ps.Role.Value == PlayerRole.Possede;
        SetBlack(blackout && !isPossede);

        if (timerText != null && (MatchState)_gc.State.Value == MatchState.Running)
        {
            double remaining = _gc.MatchEndTime.Value - NetworkManager.Singleton.ServerTime.Time;
            if (remaining < 0) remaining = 0;
            timerText.text = $"{remaining:0}s";
        }
    }

    void SetBlack(bool on)
    {
        if (blackScreen == null) return;

        blackScreen.gameObject.SetActive(on);
        if (!on) return;

        blackScreen.alpha = 1f;
        blackScreen.blocksRaycasts = true;
        blackScreen.interactable = true;
    }
}

