using UnityEngine;
using System.Collections;
using Unity.Netcode;

namespace LightEffects
{
    public class HorrorLightBuzzController : NetworkBehaviour
    {
        [Header("Lumi�res normales")]
        [Tooltip("Multiplicateur d'intensit� pour toutes les lumi�res")]
        [Range(0f, 2f)]
        public float intensityMultiplier = 1.0f;

        [Header("�v�nements de Buzz")]
        [Tooltip("Temps minimum entre chaque buzz (secondes)")]
        [Range(5f, 120f)]
        public float minTimeBetweenBuzz = 15f;

        [Tooltip("Temps maximum entre chaque buzz (secondes)")]
        [Range(10f, 180f)]
        public float maxTimeBetweenBuzz = 45f;

        [Header("Intensit� du Buzz")]
        [Tooltip("R�duction d'intensit� pendant le buzz (0 = �teint, 1 = intensit� normale)")]
        [Range(0f, 1f)]
        public float buzzIntensityReduction = 0.3f;

        [Tooltip("Dur�e du buzz (secondes)")]
        [Range(0.1f, 2f)]
        public float buzzDuration = 0.6f;

        [Tooltip("Nombre de pulsations pendant le buzz")]
        [Range(1, 8)]
        public int buzzPulseCount = 3;

        [Header("Extinction permanente")]
        [Tooltip("Active la possibilit� d'extinction permanente")]
        public bool canShutdownPermanently = true;

        [Tooltip("Nombre de buzz avant extinction permanente")]
        [Range(2, 10)]
        public int buzzBeforeShutdown = 3;

        [Tooltip("Probabilit� d'extinction apr�s le nombre requis de buzz (0-1)")]
        [Range(0f, 1f)]
        public float shutdownProbability = 0.4f;

        [Header("Recherche des lumi�res")]
        [Tooltip("Cherche aussi dans les sous-enfants (r�cursif)")]
        public bool includeNestedLights = true;

        private LightData[] _lights;
        private float _nextBuzzTime;
        private int _buzzCount;
        private bool _isPermanentlyOff;
        private bool _isBuzzing;
        private bool _shutdownAttempted = false;  // Flag pour une seule tentative

        private class LightData
        {
            public Light light;
            public float baseIntensity;
        }

        private void Awake()
        {
            InitializeLights();
        }

        public override void OnNetworkSpawn()
        {
            base.OnNetworkSpawn();

            // Seul le serveur planifie les buzz
            if (IsServer)
            {
                ScheduleNextBuzz();
            }
        }

        private void InitializeLights()
        {
            Light[] foundLights;

            if (includeNestedLights)
            {
                foundLights = GetComponentsInChildren<Light>();
            }
            else
            {
                foundLights = GetComponentsInChildren<Light>(false);
                System.Collections.Generic.List<Light> directChildren = new System.Collections.Generic.List<Light>();

                foreach (Light light in foundLights)
                {
                    if (light.transform.parent == transform)
                    {
                        directChildren.Add(light);
                    }
                }

                foundLights = directChildren.ToArray();
            }

            _lights = new LightData[foundLights.Length];

            for (int i = 0; i < foundLights.Length; i++)
            {
                _lights[i] = new LightData
                {
                    light = foundLights[i],
                    baseIntensity = foundLights[i].intensity
                };
            }

            Debug.Log($"HorrorLightBuzzController: {_lights.Length} lumi�re(s) trouv�e(s)");
        }

        private void Update()
        {
            if (_lights == null || _lights.Length == 0 || _isPermanentlyOff || _isBuzzing)
                return;

            // Lumi�res normales
            foreach (var lightData in _lights)
            {
                if (lightData.light != null)
                {
                    lightData.light.intensity = lightData.baseIntensity * intensityMultiplier;
                }
            }

            // Seul le serveur v�rifie le timing pour d�clencher un buzz
            if (IsServer && Time.time >= _nextBuzzTime)
            {
                TriggerBuzzClientRpc();
            }
        }

        private void ScheduleNextBuzz()
        {
            // Seul le serveur g�n�re les valeurs al�atoires
            if (!IsServer) return;

            float delay = Random.Range(minTimeBetweenBuzz, maxTimeBetweenBuzz);
            _nextBuzzTime = Time.time + delay;
            Debug.Log($"Prochain buzz dans {delay:F1} secondes");
        }

        [Rpc(SendTo.ClientsAndHost)]
        private void TriggerBuzzClientRpc()
        {
            StartCoroutine(BuzzSequence());
        }

        private IEnumerator BuzzSequence()
        {
            _isBuzzing = true;
            _buzzCount++;

            Debug.Log($"BUZZ #{_buzzCount}");

            // Pulsations du buzz
            for (int i = 0; i < buzzPulseCount; i++)
            {
                float pulseDuration = buzzDuration / (buzzPulseCount * 2f);

                // Descente
                float elapsed = 0f;
                while (elapsed < pulseDuration)
                {
                    elapsed += Time.deltaTime;
                    float t = elapsed / pulseDuration;
                    float intensity = Mathf.Lerp(1f, buzzIntensityReduction, t);

                    foreach (var lightData in _lights)
                    {
                        if (lightData.light != null)
                        {
                            lightData.light.intensity = lightData.baseIntensity * intensityMultiplier * intensity;
                        }
                    }

                    yield return null;
                }

                // Mont�e
                elapsed = 0f;
                while (elapsed < pulseDuration)
                {
                    elapsed += Time.deltaTime;
                    float t = elapsed / pulseDuration;
                    float intensity = Mathf.Lerp(buzzIntensityReduction, 1f, t);

                    foreach (var lightData in _lights)
                    {
                        if (lightData.light != null)
                        {
                            lightData.light.intensity = lightData.baseIntensity * intensityMultiplier * intensity;
                        }
                    }

                    yield return null;
                }
            }

            // Une seule tentative d'extinction au buzz exact
            if (IsServer && canShutdownPermanently && !_shutdownAttempted && _buzzCount == buzzBeforeShutdown)
            {
                _shutdownAttempted = true;  // Marquer la tentative

                if (Random.value < shutdownProbability)
                {
                    Debug.Log("EXTINCTION PERMANENTE!");
                    TriggerPermanentShutdownClientRpc();
                    yield break;
                }
                else
                {
                    Debug.Log("Tentative d'extinction �chou�e - La lumi�re ne s'�teindra plus jamais");
                }
            }

            _isBuzzing = false;

            // Seul le serveur planifie le prochain buzz
            if (IsServer)
            {
                ScheduleNextBuzz();
            }
        }

        [Rpc(SendTo.ClientsAndHost)]
        private void TriggerPermanentShutdownClientRpc()
        {
            StartCoroutine(PermanentShutdown());
        }

        private IEnumerator PermanentShutdown()
        {
            // Extinction progressive
            float shutdownTime = 1.5f;
            float elapsed = 0f;

            while (elapsed < shutdownTime)
            {
                elapsed += Time.deltaTime;
                float t = elapsed / shutdownTime;
                float intensity = Mathf.Lerp(1f, 0f, t);

                foreach (var lightData in _lights)
                {
                    if (lightData.light != null)
                    {
                        lightData.light.intensity = lightData.baseIntensity * intensityMultiplier * intensity;
                    }
                }

                yield return null;
            }

            // �teindre compl�tement
            foreach (var lightData in _lights)
            {
                if (lightData.light != null)
                {
                    lightData.light.intensity = 0f;
                }
            }

            _isPermanentlyOff = true;
            _isBuzzing = false;
        }

        [ContextMenu("Rafra�chir les lumi�res")]
        public void RefreshLights()
        {
            InitializeLights();
        }

        [ContextMenu("Forcer un Buzz")]
        public void ForceBuzz()
        {
            if (!_isBuzzing && !_isPermanentlyOff)
            {
                if (IsServer)
                {
                    TriggerBuzzClientRpc();
                }
                else
                {
                    StartCoroutine(BuzzSequence());
                }
            }
        }

        [ContextMenu("R�initialiser")]
        public void Reset()
        {
            if (IsServer)
            {
                ResetStateClientRpc();
            }
            else
            {
                ResetLocalState();
            }
        }

        [Rpc(SendTo.ClientsAndHost)]
        private void ResetStateClientRpc()
        {
            ResetLocalState();
        }

        private void ResetLocalState()
        {
            _buzzCount = 0;
            _isPermanentlyOff = false;
            _isBuzzing = false;
            _shutdownAttempted = false;  // R�initialiser le flag de tentative

            foreach (var lightData in _lights)
            {
                if (lightData.light != null)
                {
                    lightData.light.intensity = lightData.baseIntensity * intensityMultiplier;
                }
            }

            if (IsServer)
            {
                ScheduleNextBuzz();
            }
        }

        public void SetIntensityMultiplier(float multiplier)
        {
            intensityMultiplier = Mathf.Max(0f, multiplier);
        }

        private void OnValidate()
        {
            if (maxTimeBetweenBuzz < minTimeBetweenBuzz)
            {
                maxTimeBetweenBuzz = minTimeBetweenBuzz + 5f;
            }
        }

#if UNITY_EDITOR
        private void OnDrawGizmos()
        {
            if (_lights == null) return;

            Gizmos.color = _isPermanentlyOff ? Color.red : (_isBuzzing ? Color.yellow : Color.green);
            
            foreach (var lightData in _lights)
            {
                if (lightData.light != null)
                {
                    Gizmos.DrawLine(transform.position, lightData.light.transform.position);
                }
            }
        }
#endif
    }
}

