using Unity.Netcode;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.SceneManagement;

public class PossedeVisionFX : MonoBehaviour
{
    [Header("Volume (assigner si possible)")]
    public Volume possedeVolume;

    [Header("Auto-resolve (si Volume pas assigné)")]
    [Tooltip("Tag à mettre sur l'objet Volume (ex: PossedeVolume). Laisse vide si pas utilisé.")]
    public string volumeTag = "PossedeVolume";

    [Tooltip("Optionnel: une partie du nom du GameObject Volume (ex: 'Possede').")]
    public string volumeNameContains = "Possede";

    [Tooltip("Optionnel: une partie du nom du VolumeProfile (ex: 'Possede').")]
    public string profileNameContains = "Possede";

    [Tooltip("Si false (recommandé), on ne prend JAMAIS 'le premier Volume global' (ça cause exactement ton bug).")]
    public bool allowFallbackToAnyGlobal = false;

    [Header("Rules")]
    public bool onlyDuringBlackout = true;

    [Header("Priority (pour passer au-dessus du Volume blackout)")]
    [Tooltip("Si > -1, on force cette priorité quand l'effet est actif.")]
    public int activePriority = 100;

    [Header("Safety")]
    [Tooltip("Recommandé: true. Désactive le script sur les clones non-owner si placé sur le prefab player.")]
    public bool ownerOnlyIfPlayerPrefab = true;

    private NetworkGameController _gc;
    private NetworkPlayerState _ps;

    private float _lastWeight = -1f;
    private bool _priorityCaptured = false;
    private float _originalPriority = 0f;

    private void Awake()
    {
        if (ownerOnlyIfPlayerPrefab)
        {
            var no = GetComponentInParent<NetworkObject>();
            if (no != null && !no.IsOwner)
            {
                enabled = false;
                return;
            }
        }
    }

    private void OnEnable()
    {
        SceneManager.sceneLoaded += OnSceneLoaded;

        ResolveVolumeIfNeeded(force: true);
        Apply(false); // force OFF
    }

    private void OnDisable()
    {
        SceneManager.sceneLoaded -= OnSceneLoaded;
        Apply(false); // force OFF
    }

    private void OnSceneLoaded(Scene s, LoadSceneMode m)
    {
        // Multi-scene/additive: le Volume peut être détruit/recréé.
        ResolveVolumeIfNeeded(force: true);
        Apply(false);
    }

    private void Update()
    {
        var nm = NetworkManager.Singleton;
        if (nm == null) { Apply(false); return; }

        ResolveVolumeIfNeeded();
        if (possedeVolume == null) { Apply(false); return; }

        if (_gc == null) _gc = NetworkGameController.Instance;
        if (_gc == null) { Apply(false); return; }

        // Récupère le player state local (robuste)
        if (_ps == null)
        {
            // 1) si script sur player prefab, prendre dans parent
            _ps = GetComponentInParent<NetworkPlayerState>();

            // 2) sinon fallback local player object
            if (_ps == null)
            {
                var po = nm.SpawnManager.GetLocalPlayerObject();
                if (po != null) _ps = po.GetComponent<NetworkPlayerState>();
            }
        }

        if (_ps == null) { Apply(false); return; }

        bool running = (MatchState)_gc.State.Value == MatchState.Running;
        bool isPossede = (PlayerRole)_ps.Role.Value == PlayerRole.Possede;
        bool blackoutOk = !onlyDuringBlackout || _gc.IsBlackout.Value;

        bool on = running && isPossede && blackoutOk;
        Apply(on);
    }

    private void Apply(bool on)
    {
        if (possedeVolume == null) return;

        // Priority: si on veut être au-dessus du blackout
        if (!_priorityCaptured)
        {
            _originalPriority = possedeVolume.priority;
            _priorityCaptured = true;
        }

        if (activePriority > -1)
            possedeVolume.priority = on ? activePriority : _originalPriority;

        // Weight
        float w = on ? 1f : 0f;
        if (!Mathf.Approximately(_lastWeight, w))
        {
            possedeVolume.weight = w;
            _lastWeight = w;
        }
    }

    private void ResolveVolumeIfNeeded(bool force = false)
    {
        if (!force && possedeVolume != null) return;

        // 1) Par tag (si tag existe)
        if (!string.IsNullOrEmpty(volumeTag))
        {
            try
            {
                var go = GameObject.FindGameObjectWithTag(volumeTag);
                if (go != null && go.TryGetComponent(out Volume v))
                {
                    possedeVolume = v;
                    _priorityCaptured = false;
                    return;
                }
            }
            catch
            {
                // Tag non défini dans Tags Manager -> ignore sans casser le jeu
            }
        }

        // 2) Par nom de GameObject / Profile
#if UNITY_2023_1_OR_NEWER
        var volumes = FindObjectsByType<Volume>(FindObjectsInactive.Include, FindObjectsSortMode.None);
#else
        var volumes = FindObjectsOfType<Volume>(true);
#endif
        Volume best = null;

        foreach (var v in volumes)
        {
            if (v == null) continue;

            bool nameOk = string.IsNullOrEmpty(volumeNameContains) ||
                          v.gameObject.name.ToLowerInvariant().Contains(volumeNameContains.ToLowerInvariant());

            bool profileOk = true;
            if (!string.IsNullOrEmpty(profileNameContains))
            {
                profileOk = (v.sharedProfile != null && v.sharedProfile.name.ToLowerInvariant().Contains(profileNameContains.ToLowerInvariant())) ||
                            (v.profile != null && v.profile.name.ToLowerInvariant().Contains(profileNameContains.ToLowerInvariant()));
            }

            if (nameOk && profileOk)
            {
                best = v;
                break;
            }
        }

        if (best != null)
        {
            possedeVolume = best;
            _priorityCaptured = false;
            return;
        }

        // 3) Fallback optionnel (désactivé par défaut)
        if (allowFallbackToAnyGlobal)
        {
            foreach (var v in volumes)
            {
                if (v != null && v.isGlobal)
                {
                    possedeVolume = v;
                    _priorityCaptured = false;
                    return;
                }
            }
        }
    }
}

