using System.Collections.Generic;
using Unity.Netcode;
using UnityEngine;
using UnityEngine.SceneManagement;

public class PossedeWorldTint : MonoBehaviour
{
    [Header("Tint")]
    public Color tintColor = Color.red;
    [Range(0f, 1f)] public float strength = 0.7f;

    [Tooltip("Recommandé: true. La teinte n'apparaît que pendant blackout.")]
    public bool onlyDuringBlackout = true;

    [Header("Selection")]
    public bool autoFindRenderers = true;
    public bool refreshOnSceneLoaded = true;
    public string excludeTag = "NoPossedeTint";

    private enum TintPropKind { Color, Vector }

    private struct RendInfo
    {
        public Renderer r;
        public int materialIndex;
        public int propId;
        public TintPropKind kind;
        public Vector4 original; // Color ou Vector4
        public bool valid;
    }

    private readonly List<RendInfo> _renderers = new();
    private MaterialPropertyBlock _mpb;

    private NetworkGameController _gc;
    private NetworkPlayerState _localPs;
    private bool _applied;

    private static readonly int BaseColorId = Shader.PropertyToID("_BaseColor"); // URP/Lit
    private static readonly int ColorId     = Shader.PropertyToID("_Color");     // Legacy

    void Awake()
    {
        _mpb = new MaterialPropertyBlock();
        if (autoFindRenderers) CacheRenderers();
    }

    void OnEnable()
    {
        if (refreshOnSceneLoaded)
            SceneManager.sceneLoaded += OnSceneLoaded;
    }

    void OnDisable()
    {
        if (refreshOnSceneLoaded)
            SceneManager.sceneLoaded -= OnSceneLoaded;

        ForceOff();
    }

    void OnSceneLoaded(Scene s, LoadSceneMode m)
    {
        if (!autoFindRenderers) return;

        CacheRenderers();
        if (_applied) ApplyTint();
    }

    static bool IsBadColorPropName(string n)
    {
        if (string.IsNullOrEmpty(n)) return true;
        n = n.ToLowerInvariant();
        return n.Contains("emission") || n.Contains("spec") || n.Contains("metal") || n.Contains("smooth");
    }

    bool TryFindTintProperty(Material mat, out int propId, out TintPropKind kind, out Vector4 original)
    {
        propId = 0;
        kind = TintPropKind.Color;
        original = Vector4.one;

        if (mat == null) return false;

        // URP/Lit + Legacy
        if (mat.HasProperty(BaseColorId)) { propId = BaseColorId; kind = TintPropKind.Color; original = mat.GetColor(propId); return true; }
        if (mat.HasProperty(ColorId))     { propId = ColorId;     kind = TintPropKind.Color; original = mat.GetColor(propId); return true; }

        var sh = mat.shader;
        if (sh == null) return false;

        int count = sh.GetPropertyCount();

        // 1) Color "acceptable"
        for (int i = 0; i < count; i++)
        {
            if (sh.GetPropertyType(i) != UnityEngine.Rendering.ShaderPropertyType.Color)
                continue;

            string name = sh.GetPropertyName(i);
            if (IsBadColorPropName(name))
                continue;

            int id = Shader.PropertyToID(name);
            if (!mat.HasProperty(id))
                continue;

            propId = id;
            kind = TintPropKind.Color;
            original = mat.GetColor(id);
            return true;
        }

        // 2) Vector4 "tint-like" (souvent le cas sur Synty/ShaderGraph)
        for (int i = 0; i < count; i++)
        {
            if (sh.GetPropertyType(i) != UnityEngine.Rendering.ShaderPropertyType.Vector)
                continue;

            string name = sh.GetPropertyName(i);
            string low = name.ToLowerInvariant();
            if (!(low.Contains("tint") || low.Contains("color") || low.Contains("albedo") || low.Contains("main")))
                continue;

            int id = Shader.PropertyToID(name);
            if (!mat.HasProperty(id))
                continue;

            propId = id;
            kind = TintPropKind.Vector;
            original = mat.GetVector(id);
            return true;
        }

        return false;
    }

    bool HasExcludeTagInParents(Transform t)
    {
        while (t != null)
        {
            if (t.CompareTag(excludeTag))
                return true;
            t = t.parent;
        }
        return false;
    }

    void CacheRenderers()
    {
        _renderers.Clear();

#if UNITY_2023_1_OR_NEWER
        var all = FindObjectsByType<Renderer>(FindObjectsInactive.Exclude, FindObjectsSortMode.None);
#else
        var all = FindObjectsOfType<Renderer>(true);
#endif

        foreach (var r in all)
        {
            if (r == null) continue;
            if (!string.IsNullOrEmpty(excludeTag) && HasExcludeTagInParents(r.transform)) continue;

            var mats = r.sharedMaterials;
            if (mats == null || mats.Length == 0) continue;

            for (int mi = 0; mi < mats.Length; mi++)
            {
                var mat = mats[mi];
                if (mat == null) continue;

                if (!TryFindTintProperty(mat, out int propId, out var kind, out var orig))
                    continue;

                _renderers.Add(new RendInfo
                {
                    r = r,
                    materialIndex = mi,
                    propId = propId,
                    kind = kind,
                    original = orig,
                    valid = true
                });
            }
        }
    }

    void Update()
    {
        var nm = NetworkManager.Singleton;
        if (nm == null) { ForceOff(); return; }

        if (_gc == null) _gc = NetworkGameController.Instance;
        if (_gc == null) { ForceOff(); return; }

        bool running = (MatchState)_gc.State.Value == MatchState.Running;
        if (!running) { ForceOff(); return; }

        if (_localPs == null)
        {
            var localObj = nm.SpawnManager.GetLocalPlayerObject();
            if (localObj != null)
                _localPs = localObj.GetComponent<NetworkPlayerState>();
        }

        bool isPossede = _localPs != null && (PlayerRole)_localPs.Role.Value == PlayerRole.Possede;
        bool blackoutOk = !onlyDuringBlackout || _gc.IsBlackout.Value;

        bool shouldApply = isPossede && blackoutOk;

        if (shouldApply && !_applied) ApplyTint();
        else if (!shouldApply && _applied) RemoveTint();
    }

    void ApplyTint()
    {
        _applied = true;

        foreach (var info in _renderers)
        {
            if (!info.valid || info.r == null) continue;

            _mpb.Clear();

            if (info.kind == TintPropKind.Color)
            {
                var orig = (Color)info.original;
                var tinted = new Color(orig.r * tintColor.r, orig.g * tintColor.g, orig.b * tintColor.b, orig.a);
                var final = Color.Lerp(orig, tinted, strength);
                _mpb.SetColor(info.propId, final);
            }
            else
            {
                var orig = info.original; // xyz = rgb, w conservé
                var tinted = new Vector4(orig.x * tintColor.r, orig.y * tintColor.g, orig.z * tintColor.b, orig.w);
                var final = Vector4.Lerp(orig, tinted, strength);
                _mpb.SetVector(info.propId, final);
            }

            info.r.SetPropertyBlock(_mpb, info.materialIndex);
        }
    }

    void RemoveTint()
    {
        _applied = false;

        foreach (var info in _renderers)
        {
            if (!info.valid || info.r == null) continue;

            _mpb.Clear();
            if (info.kind == TintPropKind.Color) _mpb.SetColor(info.propId, (Color)info.original);
            else _mpb.SetVector(info.propId, info.original);

            info.r.SetPropertyBlock(_mpb, info.materialIndex);
        }
    }

    void ForceOff()
    {
        if (_applied) RemoveTint();
    }
}

