{
    /// <summary>Si true, ExecuteServer() sera appel� c�t� serveur apr�s validation.</summary>
    public virtual bool RunOnServer => true;

    /// <summary>Si true, ExecuteClient() sera appel� via ClientRpc (effets/VFX/SFX).</summary>
    public virtual bool RunOnClients => true;

    /// <summary>Logique autoritaire (gameplay) c�t� serveur.</summary>
