// GhostActionboard.cs
using Synty.AnimationBaseLocomotion.Samples;
using System.Collections.Generic;
using Unity.Netcode;
using UnityEngine;
using UnityEngine.InputSystem;

/// <summary>
/// Syst�me d'actionboard pour les fant�mes.
/// M�me principe que GhostSoundboard, mais d�clenche des GhostAction (ScriptableObject).
/// Cooldown + nombre d'utilisations max (server-authoritative).
/// </summary>
public class GhostActionboard : NetworkBehaviour
{
    [Header("Configuration")]
    [SerializeField] private List<GhostActionboardSlot> slots = new();

    [Header("Input (New Input System)")]
    [SerializeField] private InputActionReference openMenuAction;

    [Header("Camera")]
    [SerializeField] private SampleCameraController cameraController;

    [Header("Debug")]
    [SerializeField] private bool debugLogs = false;

    // Serveur: cooldowns + uses par client
    private readonly Dictionary<ulong, double[]> _serverCooldowns = new();
    private readonly Dictionary<ulong, int[]> _serverUsesRemaining = new();

    // Local owner: cooldowns + uses pour UI
    private double[] _localCooldownEndTimes;
    private int[] _localUsesRemaining;

    private NetworkPlayerState _ps;

    private GhostActionboardUI _ui;
    private bool _menuOpen;

    public List<GhostActionboardSlot> Slots => slots;
    public bool IsMenuOpen => _menuOpen;

    private InputAction OpenMenuInput => openMenuAction != null ? openMenuAction.action : null;

    public string OpenMenuBindingDisplay
    {
        get
        {
            var action = OpenMenuInput;
            if (action == null) return "?";

            for (int i = 0; i < action.bindings.Count; i++)
            {
                var b = action.bindings[i];
                if (b.isComposite || b.isPartOfComposite) continue;

                var path = b.effectivePath;
                if (string.IsNullOrEmpty(path)) continue;

                return InputControlPath.ToHumanReadableString(
                    path,
                    InputControlPath.HumanReadableStringOptions.OmitDevice
                );
            }

            return action.name;
        }
    }

    private void Awake()
    {
        _ps = GetComponent<NetworkPlayerState>() ?? GetComponentInParent<NetworkPlayerState>();

        _localCooldownEndTimes = new double[8];
        _localUsesRemaining = new int[8];

        // Init local uses (sera corrig� par le serveur via ClientRpc apr�s chaque usage)
        for (int i = 0; i < 8; i++)
        {
            if (i < slots.Count) _localUsesRemaining[i] = slots[i].maxUses;
            else _localUsesRemaining[i] = 0;
        }

        // M�me principe que ton soundboard: d�sactiv� par d�faut (activ� c�t� owner quand mort)
        enabled = false;
    }

    public override void OnNetworkSpawn()
    {
        base.OnNetworkSpawn();

        if (IsServer)
        {
            InitServerState(OwnerClientId);
        }
    }

    private void OnEnable()
    {
        if (!IsOwner)
        {
            enabled = false;
            return;
        }

        if (OpenMenuInput != null && !OpenMenuInput.enabled)
            OpenMenuInput.Enable();

        FindOrCreateUI();
    }

    private void OnDisable()
    {
        CloseMenu();

        if (OpenMenuInput != null && OpenMenuInput.enabled)
            OpenMenuInput.Disable();
    }

    private void Update()
    {
        if (!IsOwner) return;

        // Ghost only
        if (_ps != null && _ps.Alive.Value)
        {
            CloseMenu();
            return;
        }

        HandleInput();
    }

    private void HandleInput()
    {
        var action = OpenMenuInput;
        if (action == null) return;

        if (action.WasPressedThisFrame())
            OpenMenu();

        if (action.WasReleasedThisFrame() && _menuOpen)
        {
            if (_ui != null)
            {
                int selectedSlot = _ui.GetSelectedSlotIndex();
                if (selectedSlot >= 0 && selectedSlot < slots.Count)
                    TryUseAction(selectedSlot);
            }

            CloseMenu();
        }
    }

    private void OpenMenu()
    {
        if (_menuOpen) return;
        _menuOpen = true;

        if (_ui != null)
            _ui.Show(this);

        if (cameraController == null)
            cameraController = FindFirstObjectByType<SampleCameraController>();
        if (cameraController != null)
            cameraController.enabled = false;

        Cursor.lockState = CursorLockMode.None;
        Cursor.visible = true;
    }

    private void CloseMenu()
    {
        if (!_menuOpen) return;
        _menuOpen = false;

        if (_ui != null)
            _ui.Hide();

        if (cameraController != null)
            cameraController.enabled = true;

        Cursor.lockState = CursorLockMode.Locked;
        Cursor.visible = false;
    }

    public void TryUseAction(int slotIndex)
    {
        if (!IsOwner) return;
        if (slotIndex < 0 || slotIndex >= slots.Count) return;

        if (!IsSlotReadyLocal(slotIndex))
        {
            if (debugLogs) Debug.Log($"[GhostActionboard] Slot {slotIndex} not ready locally (cooldown/uses).");
            return;
        }

        RequestUseActionServerRpc(slotIndex);
    }

    // ===== UI helpers (local) =====

    private double LocalNow()
    {
        if (NetworkManager.Singleton != null) return NetworkManager.Singleton.LocalTime.Time;
        return Time.timeAsDouble;
    }

    public bool IsSlotExhaustedLocal(int slotIndex)
    {
        if (slotIndex < 0 || slotIndex >= 8) return true;
        int max = slotIndex < slots.Count ? slots[slotIndex].maxUses : 0;
        if (max < 0) return false; // illimit�
        return _localUsesRemaining[slotIndex] <= 0;
    }

    public bool IsSlotReadyLocal(int slotIndex)
    {
        if (slotIndex < 0 || slotIndex >= 8) return false;
        if (slotIndex >= slots.Count) return false;

        if (IsSlotExhaustedLocal(slotIndex)) return false;

        return LocalNow() >= _localCooldownEndTimes[slotIndex];
    }

    public float GetSlotCooldownRemaining(int slotIndex)
    {
        if (slotIndex < 0 || slotIndex >= 8) return 0f;
        double remaining = _localCooldownEndTimes[slotIndex] - LocalNow();
        return Mathf.Max(0f, (float)remaining);
    }

    public int GetSlotUsesRemainingLocal(int slotIndex)
    {
        if (slotIndex < 0 || slotIndex >= 8) return 0;
        if (slotIndex >= slots.Count) return 0;
        return _localUsesRemaining[slotIndex];
    }

    // ===== RPC =====

    [ServerRpc]
    private void RequestUseActionServerRpc(int slotIndex, ServerRpcParams rpcParams = default)
    {
        ulong clientId = rpcParams.Receive.SenderClientId;

        if (slotIndex < 0 || slotIndex >= slots.Count) return;

        // Ghost only
        if (_ps != null && _ps.Alive.Value) return;

        var slot = slots[slotIndex];
        if (slot.action == null) return;

        if (!TryConsumeServer(clientId, slotIndex, out int remainingUsesAfter))
            return;

        Vector3 position = transform.position;

        // Ex�cution serveur (gameplay)
        if (slot.action.RunOnServer)
        {
            slot.action.ExecuteServer(new GhostActionContext
            {
                SourceClientId = clientId,
                SourceNetworkObjectId = NetworkObjectId,
                Position = position,
                IsLocalSource = false
            });
        }

        // Broadcast clients (effets)
        ExecuteActionClientRpc(slotIndex, position, clientId, remainingUsesAfter);

        if (debugLogs)
            Debug.Log($"[GhostActionboard][SERVER] Used slot {slotIndex} by {clientId} -> usesLeft={remainingUsesAfter}");
    }

    [ClientRpc]
    private void ExecuteActionClientRpc(int slotIndex, Vector3 position, ulong sourceClientId, int remainingUsesForSource)
    {
        if (slotIndex < 0 || slotIndex >= slots.Count) return;

        var slot = slots[slotIndex];
        if (slot.action == null) return;

        bool isSource = NetworkManager.Singleton != null && NetworkManager.Singleton.LocalClientId == sourceClientId;

        // Mettre � jour l'�tat local pour l'owner (cooldown + uses)
        if (IsOwner && isSource)
        {
            if (slotIndex < 8)
            {
                _localCooldownEndTimes[slotIndex] = LocalNow() + slot.cooldown;
                _localUsesRemaining[slotIndex] = remainingUsesForSource;
            }
        }

        // Ex�cution client (VFX/SFX/UI) si demand�
        if (!slot.action.RunOnClients) return;

        // Ne pas jouer pour la source si playForSelf == false
        if (isSource && !slot.playForSelf) return;

        slot.action.ExecuteClient(new GhostActionContext
        {
            SourceClientId = sourceClientId,
            SourceNetworkObjectId = NetworkObjectId,
            Position = position,
            IsLocalSource = isSource
        });
    }

    // ===== Server state =====

    private double ServerNow()
    {
        if (NetworkManager.Singleton != null) return NetworkManager.Singleton.ServerTime.Time;
        return Time.timeAsDouble;
    }

    private void InitServerState(ulong clientId)
    {
        if (!_serverCooldowns.ContainsKey(clientId))
            _serverCooldowns[clientId] = new double[8];

        if (!_serverUsesRemaining.ContainsKey(clientId))
        {
            var arr = new int[8];
            for (int i = 0; i < 8; i++)
                arr[i] = i < slots.Count ? slots[i].maxUses : 0;
            _serverUsesRemaining[clientId] = arr;
        }
    }

    private bool TryConsumeServer(ulong clientId, int slotIndex, out int remainingUsesAfter)
    {
        remainingUsesAfter = 0;

        if (!IsServer) return false;
        if (slotIndex < 0 || slotIndex >= slots.Count) return false;

        InitServerState(clientId);

        var cds = _serverCooldowns[clientId];
        var uses = _serverUsesRemaining[clientId];

        double now = ServerNow();

        // Cooldown check
        if (now < cds[slotIndex])
            return false;

        int maxUses = slots[slotIndex].maxUses;
        int current = uses[slotIndex];

        // Uses check (si limit�)
        if (maxUses >= 0)
        {
            if (current <= 0) return false;
            current -= 1;
            uses[slotIndex] = current;
            remainingUsesAfter = current;
        }
        else
        {
            // illimit�
            remainingUsesAfter = -1;
            uses[slotIndex] = -1;
        }

        cds[slotIndex] = now + slots[slotIndex].cooldown;
        return true;
    }

    // ===== UI lookup =====

    private void FindOrCreateUI()
    {
        if (_ui != null) return;

        _ui = GetComponentInChildren<GhostActionboardUI>(true);
        if (_ui == null)
            _ui = Object.FindFirstObjectByType<GhostActionboardUI>(FindObjectsInactive.Include);

        if (_ui == null && debugLogs)
            Debug.LogWarning("[GhostActionboard] GhostActionboardUI introuvable (m�me inactive). Place-la sous le PlayerCanvas du joueur owner.");
    }
}

