// GhostActionboardUI.cs
using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.UI;

/// <summary>
/// UI du menu radial actionboard pour les fantômes.
/// Même prefab / même disposition que GhostSoundboardUI.
/// </summary>
public class GhostActionboardUI : MonoBehaviour
{
    [Header("References")]
    [SerializeField] private GameObject menuContainer;
    [SerializeField] private RectTransform slotsParent;
    [SerializeField] private GameObject slotPrefab;

    [Header("Layout")]
    [SerializeField] private float radius = 150f;
    [SerializeField] private float startAngle = 90f;

    [Header("Visual Feedback")]
    [SerializeField] private Color normalColor = new Color(0.2f, 0.2f, 0.2f, 0.8f);
    [SerializeField] private Color selectedColor = new Color(0.4f, 0.7f, 1f, 0.9f);
    [SerializeField] private Color cooldownColor = new Color(0.5f, 0.2f, 0.2f, 0.8f);
    [SerializeField] private Color exhaustedColor = new Color(0.15f, 0.15f, 0.15f, 0.85f);

    [Header("Center Display")]
    [SerializeField] private TextMeshProUGUI centerText;
    [SerializeField] private Image centerIndicator;

    [Header("Slot UI Elements (auto-filled if using prefab)")]
    [SerializeField] private string iconImageName = "Icon";
    [SerializeField] private string backgroundImageName = "Background";
    [SerializeField] private string cooldownOverlayName = "CooldownOverlay";
    [SerializeField] private string cooldownTextName = "CooldownText";

    private GhostActionboard _actionboard;
    private readonly List<SlotUIElements> _slotElements = new();
    private int _selectedIndex = -1;
    private bool _isVisible;

    private class SlotUIElements
    {
        public RectTransform root;
        public Image background;
        public Image icon;
        public Image cooldownOverlay;
        public TextMeshProUGUI cooldownText;
        public int slotIndex;
    }

    private void Awake()
    {
        if (menuContainer != null)
            menuContainer.SetActive(false);
    }

    private void Update()
    {
        if (!_isVisible || _actionboard == null) return;

        UpdateSelection();
        UpdateCooldowns();
    }

    public void Show(GhostActionboard actionboard)
    {
        _actionboard = actionboard;
        _isVisible = true;
        _selectedIndex = -1;

        if (menuContainer != null)
            menuContainer.SetActive(true);

        RebuildSlots();
        UpdateCenterDisplay();
    }

    public void Hide()
    {
        _isVisible = false;
        _selectedIndex = -1;

        if (menuContainer != null)
            menuContainer.SetActive(false);
    }

    public int GetSelectedSlotIndex() => _selectedIndex;

    private void RebuildSlots()
    {
        foreach (var elem in _slotElements)
            if (elem.root != null) Destroy(elem.root.gameObject);
        _slotElements.Clear();

        if (_actionboard == null || slotsParent == null || slotPrefab == null) return;

        var slots = _actionboard.Slots;
        int count = Mathf.Min(slots.Count, 8);
        float angleStep = 360f / Mathf.Max(count, 1);

        for (int i = 0; i < count; i++)
        {
            var slot = slots[i];

            // Instancier un root UI garanti
            RectTransform rt;
            GameObject go;

            // Si le prefab est déjà un UI element (RectTransform à la racine)
            if (slotPrefab.transform is RectTransform)
            {
                go = Instantiate(slotPrefab, slotsParent);
                rt = (RectTransform)go.transform;
            }
            else
            {
                // Wrapper UI (RectTransform) qui sera positionné en radial
                var wrapper = new GameObject($"{slotPrefab.name}_Wrapper", typeof(RectTransform));
                rt = wrapper.GetComponent<RectTransform>();
                rt.SetParent(slotsParent, false);

                // Le prefab devient enfant du wrapper
                go = Instantiate(slotPrefab, rt);
                go.transform.localPosition = Vector3.zero;
                go.transform.localRotation = Quaternion.identity;
                go.transform.localScale = Vector3.one;
            }

            // Config RectTransform (positionnement radial)
            rt.anchorMin = new Vector2(0.5f, 0.5f);
            rt.anchorMax = new Vector2(0.5f, 0.5f);
            rt.pivot = new Vector2(0.5f, 0.5f);


            float angle = (startAngle - i * angleStep) * Mathf.Deg2Rad;
            Vector2 pos = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * radius;
            rt.anchoredPosition = pos;

            var elem = new SlotUIElements
            {
                root = rt,
                slotIndex = i,
                background = FindChildImage(go, backgroundImageName),
                icon = FindChildImage(go, iconImageName),
                cooldownOverlay = FindChildImage(go, cooldownOverlayName),
                cooldownText = FindChildText(go, cooldownTextName)
            };

            if (elem.icon != null)
            {
                if (slot.icon != null)
                {
                    elem.icon.sprite = slot.icon;
                    elem.icon.enabled = true;
                }
                else
                {
                    elem.icon.enabled = false;
                }
            }

            if (elem.background != null)
                elem.background.color = normalColor;

            if (elem.cooldownOverlay != null)
            {
                elem.cooldownOverlay.fillAmount = 0f;
                elem.cooldownOverlay.type = Image.Type.Filled;
                elem.cooldownOverlay.fillMethod = Image.FillMethod.Radial360;
                elem.cooldownOverlay.fillClockwise = false;
            }

            if (elem.cooldownText != null)
                elem.cooldownText.text = "";

            _slotElements.Add(elem);
        }
    }

    private void UpdateSelection()
    {
        if (_slotElements.Count == 0) return;

        var mouse = Mouse.current;
        if (mouse == null)
        {
            SetSelectedIndex(-1);
            return;
        }

        Vector2 mousePos = mouse.position.ReadValue();
        Vector2 screenCenter = new Vector2(Screen.width / 2f, Screen.height / 2f);
        Vector2 dir = mousePos - screenCenter;

        float distFromCenter = dir.magnitude;
        float deadZone = 50f;
        if (distFromCenter < deadZone)
        {
            SetSelectedIndex(-1);
            return;
        }

        float mouseAngle = Mathf.Atan2(dir.y, dir.x) * Mathf.Rad2Deg;
        if (mouseAngle < 0) mouseAngle += 360f;

        int count = _slotElements.Count;
        float angleStep = 360f / count;

        int bestIndex = -1;
        float bestAngleDiff = float.MaxValue;

        for (int i = 0; i < count; i++)
        {
            float slotAngle = startAngle - i * angleStep;
            if (slotAngle < 0) slotAngle += 360f;

            float diff = Mathf.Abs(Mathf.DeltaAngle(mouseAngle, slotAngle));
            if (diff < bestAngleDiff)
            {
                bestAngleDiff = diff;
                bestIndex = i;
            }
        }

        float threshold = angleStep / 2f + 5f;
        SetSelectedIndex(bestAngleDiff <= threshold ? bestIndex : -1);
    }

    private void SetSelectedIndex(int index)
    {
        if (_selectedIndex == index) return;
        _selectedIndex = index;

        for (int i = 0; i < _slotElements.Count; i++)
        {
            var elem = _slotElements[i];
            if (elem.background == null) continue;

            bool isSelected = (i == _selectedIndex);
            bool exhausted = _actionboard.IsSlotExhaustedLocal(i);
            bool ready = _actionboard.IsSlotReadyLocal(i);
            bool onCooldown = !ready && !exhausted;

            if (exhausted)
                elem.background.color = exhaustedColor;
            else if (onCooldown)
                elem.background.color = cooldownColor;
            else if (isSelected)
                elem.background.color = selectedColor;
            else
                elem.background.color = normalColor;
        }

        UpdateCenterDisplay();
    }

    private void UpdateCenterDisplay()
    {
        if (centerText == null || _actionboard == null) return;

        if (_selectedIndex >= 0 && _selectedIndex < _actionboard.Slots.Count)
        {
            var slot = _actionboard.Slots[_selectedIndex];
            string name = string.IsNullOrEmpty(slot.displayName) ? $"Action {_selectedIndex + 1}" : slot.displayName;

            int uses = _actionboard.GetSlotUsesRemainingLocal(_selectedIndex);
            string usesTxt = uses < 0 ? "(∞)" : $"({uses})";
            string label = $"{name} {usesTxt}";

            bool exhausted = _actionboard.IsSlotExhaustedLocal(_selectedIndex);
            if (exhausted)
            {
                centerText.text = $"{label}\n<size=70%><color=#ff6666>Plus d'utilisations</color></size>";
                return;
            }

            bool onCooldown = !_actionboard.IsSlotReadyLocal(_selectedIndex);
            if (onCooldown)
            {
                float remaining = _actionboard.GetSlotCooldownRemaining(_selectedIndex);
                centerText.text = $"{label}\n<size=70%><color=#ff6666>Cooldown: {remaining:F1}s</color></size>";
            }
            else
            {
                centerText.text = label;
            }
        }
        else
        {
            centerText.text = $"Maintenir {_actionboard.OpenMenuBindingDisplay}\npuis relâcher pour agir";
        }
    }

    private void UpdateCooldowns()
    {
        for (int i = 0; i < _slotElements.Count; i++)
        {
            var elem = _slotElements[i];
            if (elem.slotIndex >= _actionboard.Slots.Count) continue;

            var slot = _actionboard.Slots[elem.slotIndex];

            bool exhausted = _actionboard.IsSlotExhaustedLocal(elem.slotIndex);
            float remaining = _actionboard.GetSlotCooldownRemaining(elem.slotIndex);
            bool onCooldown = remaining > 0f;

            if (elem.cooldownOverlay != null)
            {
                if (onCooldown && slot.cooldown > 0f)
                    elem.cooldownOverlay.fillAmount = remaining / slot.cooldown;
                else
                    elem.cooldownOverlay.fillAmount = 0f;
            }

            if (elem.cooldownText != null)
                elem.cooldownText.text = onCooldown ? remaining.ToString("F1") : "";

            if (elem.background != null)
            {
                bool isSelected = (i == _selectedIndex);
                if (exhausted)
                    elem.background.color = exhaustedColor;
                else if (onCooldown)
                    elem.background.color = cooldownColor;
                else if (isSelected)
                    elem.background.color = selectedColor;
                else
                    elem.background.color = normalColor;
            }
        }
    }

    private Image FindChildImage(GameObject parent, string childName)
    {
        if (string.IsNullOrEmpty(childName)) return null;
        Transform child = parent.transform.Find(childName);
        if (child != null) return child.GetComponent<Image>();
        if (parent.name == childName) return parent.GetComponent<Image>();
        return null;
    }

    private TextMeshProUGUI FindChildText(GameObject parent, string childName)
    {
        if (string.IsNullOrEmpty(childName)) return null;
        Transform child = parent.transform.Find(childName);
        if (child != null) return child.GetComponent<TextMeshProUGUI>();
        return null;
    }
}

