using Unity.Netcode;
using UnityEngine;

public class GhostVisualCulling : MonoBehaviour
{
    [SerializeField] private Camera _camera;
    [SerializeField] private string _ghostVisualLayerName = "GhostVisual";

    private NetworkPlayerState _localPs;
    private int _ghostVisualBit;
    private int _baseMask;

    private void Awake()
    {
        if (_camera == null) _camera = Camera.main;
    }

    private void OnEnable()
    {
        int layer = LayerMask.NameToLayer(_ghostVisualLayerName);
        if (layer < 0)
        {
            Debug.LogError($"[GhostVisualCulling] Layer '{_ghostVisualLayerName}' introuvable.");
            enabled = false;
            return;
        }

        _ghostVisualBit = 1 << layer;
        _baseMask = _camera.cullingMask;
    }

    private void Update()
    {
        if (_localPs == null)
        {
            if (NetworkManager.Singleton == null) return;
            var po = NetworkManager.Singleton.SpawnManager.GetLocalPlayerObject();
            if (po == null) return;

            _localPs = po.GetComponent<NetworkPlayerState>();
            if (_localPs == null) return;

            _localPs.Alive.OnValueChanged += OnAliveChanged;
            Apply(_localPs.Alive.Value);
        }
    }

    private void OnDisable()
    {
        if (_localPs != null)
            _localPs.Alive.OnValueChanged -= OnAliveChanged;
    }

    private void OnAliveChanged(bool oldV, bool newV) => Apply(newV);

    private void Apply(bool alive)
    {
        // vivants: on cache GhostVisual
        // fant�mes: on montre GhostVisual
        if (alive)
            _camera.cullingMask = (_baseMask & ~_ghostVisualBit);
        else
            _camera.cullingMask = (_baseMask | _ghostVisualBit);
    }
}

