using Synty.AnimationBaseLocomotion.Samples;
using System.Collections.Generic;
using Unity.Netcode;
using UnityEngine;
using UnityEngine.InputSystem;

/// <summary>
/// Système de soundboard pour les fantômes.
/// Gère les demandes de sons via RPCs avec validation côté serveur (cooldowns anti-triche).
/// </summary>
public class GhostSoundboard : NetworkBehaviour
{
    [Header("Configuration")]
    [Tooltip("Liste des slots du soundboard (jusqu'à 8 recommandés pour le menu radial).")]
    [SerializeField] private List<GhostSoundboardSlot> slots = new List<GhostSoundboardSlot>();

    [Header("Audio")]
    [Tooltip("Prefab AudioSource pour jouer les sons spatialisés. Si null, un sera créé dynamiquement.")]
    [SerializeField] private AudioSource audioSourcePrefab;

    [Header("Input (New Input System)")]
    [Tooltip("InputActionReference (Button) pour ouvrir/fermer le menu radial (press + release).")]
    [SerializeField] private InputActionReference openMenuAction;

    [Header("Camera")]
    [Tooltip("Référence au SampleCameraController pour désactiver la rotation caméra pendant le menu.")]
    [SerializeField] private SampleCameraController cameraController;

    [Header("Debug")]
    [SerializeField] private bool debugLogs = false;

    // Cooldowns serveur (anti-triche) - clé = clientId, valeur = tableau des timestamps de dernier usage
    private Dictionary<ulong, double[]> _serverCooldowns = new Dictionary<ulong, double[]>();

    // Cooldowns locaux pour l'UI
    private double[] _localCooldownEndTimes;

    // Référence au PlayerState pour vérifier si le joueur est fantôme
    private NetworkPlayerState _ps;

    // UI
    private GhostSoundboardUI _ui;
    private bool _menuOpen;

    // Pool d'AudioSources pour le spatial sound
    private List<AudioSource> _audioSourcePool = new List<AudioSource>();

    public List<GhostSoundboardSlot> Slots => slots;
    public bool IsMenuOpen => _menuOpen;

    private InputAction OpenMenuInput => openMenuAction != null ? openMenuAction.action : null;

    /// <summary>
    /// Texte lisible (UI) du binding de l'action d'ouverture du menu (ex: "E", "Mouse Left", ...).
    /// </summary>
    public string OpenMenuBindingDisplay
    {
        get
        {
            var action = OpenMenuInput;
            if (action == null) return "?";

            // Prend le 1er binding non-composite
            for (int i = 0; i < action.bindings.Count; i++)
            {
                var b = action.bindings[i];
                if (b.isComposite || b.isPartOfComposite) continue;

                var path = b.effectivePath;
                if (string.IsNullOrEmpty(path)) continue;

                return InputControlPath.ToHumanReadableString(
                    path,
                    InputControlPath.HumanReadableStringOptions.OmitDevice
                );
            }

            return action.name;
        }
    }

    private void Awake()
    {
        _ps = GetComponent<NetworkPlayerState>() ?? GetComponentInParent<NetworkPlayerState>();
        _localCooldownEndTimes = new double[8];

        // Désactiver par défaut (sera activé par PlayerDeathListener quand le joueur meurt)
        enabled = false;
    }

    public override void OnNetworkSpawn()
    {
        base.OnNetworkSpawn();

        if (IsServer)
        {
            // Initialiser les cooldowns serveur pour ce joueur
            InitServerCooldowns(OwnerClientId);
        }
    }

    private void OnEnable()
    {
        if (!IsOwner)
        {
            enabled = false;
            return;
        }

        // Input
        if (OpenMenuInput != null && !OpenMenuInput.enabled)
            OpenMenuInput.Enable();

        // Trouver ou créer l'UI
        FindOrCreateUI();

        if (debugLogs)
            Debug.Log($"[GhostSoundboard] Enabled for owner {OwnerClientId}");
    }

    private void OnDisable()
    {
        CloseMenu();

        // Input
        if (OpenMenuInput != null && OpenMenuInput.enabled)
            OpenMenuInput.Disable();

        if (debugLogs)
            Debug.Log($"[GhostSoundboard] Disabled");
    }

    private void Update()
    {
        if (!IsOwner) return;

        // Debug: log every second to verify Update is running
        if (Time.frameCount % 60 == 0)
        {
            Debug.Log($"[GhostSoundboard] Update running - enabled:{enabled}, Alive:{(_ps != null ? _ps.Alive.Value.ToString() : "null")}");
        }

        // Vérifier si le joueur est bien mort (fantôme)
        if (_ps != null && _ps.Alive.Value)
        {
            CloseMenu();
            return;
        }

        HandleInput();
    }

    private void HandleInput()
    {
        var action = OpenMenuInput;
        if (action == null) return;

        // Press -> Open
        if (action.WasPressedThisFrame())
        {
            if (debugLogs)
                Debug.Log($"[GhostSoundboard] OpenMenu action pressed!");
            OpenMenu();
        }

        // Release -> Validate + Close
        if (action.WasReleasedThisFrame() && _menuOpen)
        {
            if (_ui != null)
            {
                int selectedSlot = _ui.GetSelectedSlotIndex();
                if (selectedSlot >= 0 && selectedSlot < slots.Count)
                {
                    TryPlaySound(selectedSlot);
                }
            }

            CloseMenu();
        }
    }

    private void OpenMenu()
    {
        if (_menuOpen) return;
        _menuOpen = true;

        if (debugLogs)
            Debug.Log($"[GhostSoundboard] Opening menu...");

        if (_ui != null)
        {
            if (debugLogs)
                Debug.Log($"[GhostSoundboard] Calling _ui.Show()");
            _ui.Show(this);
        }
        else
        {
            Debug.LogWarning($"[GhostSoundboard] _ui is null! Cannot show menu.");
        }

        // Désactiver la rotation de la caméra pendant le menu
        if (cameraController == null)
            cameraController = FindFirstObjectByType<SampleCameraController>();
        if (cameraController != null)
            cameraController.enabled = false;

        // Débloquer la souris pour la sélection
        Cursor.lockState = CursorLockMode.None;
        Cursor.visible = true;

        if (debugLogs)
            Debug.Log($"[GhostSoundboard] Menu opened successfully");
    }

    private void CloseMenu()
    {
        if (!_menuOpen) return;
        _menuOpen = false;

        if (debugLogs)
            Debug.Log($"[GhostSoundboard] Closing menu...");

        if (_ui != null)
            _ui.Hide();

        // Réactiver la rotation de la caméra
        if (cameraController != null)
            cameraController.enabled = true;

        // Re-lock la souris
        Cursor.lockState = CursorLockMode.Locked;
        Cursor.visible = false;

        if (debugLogs)
            Debug.Log($"[GhostSoundboard] Menu closed");
    }

    /// <summary>
    /// Tente de jouer un son (appelé par l'UI ou l'input).
    /// </summary>
    public void TryPlaySound(int slotIndex)
    {
        if (!IsOwner) return;
        if (slotIndex < 0 || slotIndex >= slots.Count) return;

        // Vérifier cooldown local (feedback immédiat)
        if (!IsSlotReadyLocal(slotIndex))
        {
            if (debugLogs)
                Debug.Log($"[GhostSoundboard] Slot {slotIndex} still on cooldown locally");
            return;
        }

        // Demander au serveur
        RequestPlaySoundServerRpc(slotIndex);
    }

    /// <summary>
    /// Vérifie si un slot est prêt localement (pour l'UI).
    /// </summary>
    public bool IsSlotReadyLocal(int slotIndex)
    {
        if (slotIndex < 0 || slotIndex >= _localCooldownEndTimes.Length) return false;
        return NetworkManager.Singleton.LocalTime.Time >= _localCooldownEndTimes[slotIndex];
    }

    /// <summary>
    /// Retourne le temps restant de cooldown pour un slot (pour l'UI).
    /// </summary>
    public float GetSlotCooldownRemaining(int slotIndex)
    {
        if (slotIndex < 0 || slotIndex >= _localCooldownEndTimes.Length) return 0f;
        double remaining = _localCooldownEndTimes[slotIndex] - NetworkManager.Singleton.LocalTime.Time;
        return Mathf.Max(0f, (float)remaining);
    }

    // ========================================
    // RÉSEAU - RPCs
    // ========================================

    [ServerRpc]
    private void RequestPlaySoundServerRpc(int slotIndex, ServerRpcParams rpcParams = default)
    {
        ulong clientId = rpcParams.Receive.SenderClientId;

        if (debugLogs)
            Debug.Log($"[GhostSoundboard][SERVER] Client {clientId} requests slot {slotIndex}");

        // Validation: slot valide
        if (slotIndex < 0 || slotIndex >= slots.Count)
        {
            if (debugLogs)
                Debug.LogWarning($"[GhostSoundboard][SERVER] Invalid slot index: {slotIndex}");
            return;
        }

        // Validation: joueur bien mort (fantôme)
        if (_ps != null && _ps.Alive.Value)
        {
            if (debugLogs)
                Debug.LogWarning($"[GhostSoundboard][SERVER] Player {clientId} is alive, cannot use soundboard");
            return;
        }

        // Validation: cooldown serveur
        if (!CheckAndApplyServerCooldown(clientId, slotIndex))
        {
            if (debugLogs)
                Debug.Log($"[GhostSoundboard][SERVER] Slot {slotIndex} on cooldown for client {clientId}");
            return;
        }

        var slot = slots[slotIndex];
        if (slot.audioClip == null)
        {
            if (debugLogs)
                Debug.LogWarning($"[GhostSoundboard][SERVER] Slot {slotIndex} has no audio clip");
            return;
        }

        // Broadcast à tous les clients
        Vector3 position = transform.position;
        PlaySoundClientRpc(slotIndex, position, clientId);

        if (debugLogs)
            Debug.Log($"[GhostSoundboard][SERVER] Broadcasting slot {slotIndex} from position {position}");
    }

    [ClientRpc]
    private void PlaySoundClientRpc(int slotIndex, Vector3 position, ulong sourceClientId)
    {
        if (slotIndex < 0 || slotIndex >= slots.Count) return;

        var slot = slots[slotIndex];
        if (slot.audioClip == null) return;

        // Mettre à jour le cooldown local si c'est notre son
        if (IsOwner)
        {
            if (slotIndex < _localCooldownEndTimes.Length)
            {
                _localCooldownEndTimes[slotIndex] = NetworkManager.Singleton.LocalTime.Time + slot.cooldown;
            }
        }

        // Ne pas jouer pour le propriétaire si playForSelf = false
        bool isSource = NetworkManager.Singleton.LocalClientId == sourceClientId;
        if (isSource && !slot.playForSelf)
        {
            if (debugLogs)
                Debug.Log($"[GhostSoundboard] Not playing own sound (playForSelf=false)");
            return;
        }

        // Jouer le son spatialisé
        PlaySpatialSound(slot, position);

        if (debugLogs)
            Debug.Log($"[GhostSoundboard][CLIENT] Playing slot {slotIndex} at {position}");
    }

    // ========================================
    // SERVEUR - Cooldowns
    // ========================================

    private void InitServerCooldowns(ulong clientId)
    {
        if (!_serverCooldowns.ContainsKey(clientId))
        {
            _serverCooldowns[clientId] = new double[8];
        }
    }

    private bool CheckAndApplyServerCooldown(ulong clientId, int slotIndex)
    {
        if (!IsServer) return false;
        if (slotIndex < 0 || slotIndex >= slots.Count) return false;

        InitServerCooldowns(clientId);

        double now = NetworkManager.Singleton.ServerTime.Time;
        double[] cooldowns = _serverCooldowns[clientId];

        if (slotIndex >= cooldowns.Length) return false;

        // Vérifier si le cooldown est passé
        if (now < cooldowns[slotIndex])
        {
            return false;
        }

        // Appliquer le nouveau cooldown
        var slot = slots[slotIndex];
        cooldowns[slotIndex] = now + slot.cooldown;

        return true;
    }

    // ========================================
    // AUDIO
    // ========================================

    private void PlaySpatialSound(GhostSoundboardSlot slot, Vector3 position)
    {
        AudioSource source = GetPooledAudioSource();

        source.transform.position = position;
        source.clip = slot.audioClip;
        source.volume = slot.volume;
        source.spatialBlend = 1f; // Full 3D
        source.maxDistance = slot.maxDistance;
        source.rolloffMode = AudioRolloffMode.Linear;
        source.Play();
    }

    private AudioSource GetPooledAudioSource()
    {
        // Chercher une source disponible dans le pool
        foreach (var source in _audioSourcePool)
        {
            if (source != null && !source.isPlaying)
            {
                source.gameObject.SetActive(true);
                return source;
            }
        }

        // Créer une nouvelle source
        GameObject go = new GameObject("GhostSoundSource");
        go.transform.SetParent(null);
        DontDestroyOnLoad(go);

        AudioSource newSource;
        if (audioSourcePrefab != null)
        {
            newSource = Instantiate(audioSourcePrefab, go.transform);
        }
        else
        {
            newSource = go.AddComponent<AudioSource>();
            newSource.playOnAwake = false;
            newSource.spatialBlend = 1f;
        }

        _audioSourcePool.Add(newSource);
        return newSource;
    }

    // ========================================
    // UI
    // ========================================

    private void FindOrCreateUI()
    {
        if (_ui != null) return;

        // 1) Priorité : UI dans le prefab du joueur owner (même si inactive)
        _ui = GetComponentInChildren<GhostSoundboardUI>(true);

        // 2) Fallback : recherche scène en incluant les inactifs (Unity 6)
        if (_ui == null)
            _ui = Object.FindFirstObjectByType<GhostSoundboardUI>(FindObjectsInactive.Include);

        if (_ui == null)
            Debug.LogWarning("[GhostSoundboard] GhostSoundboardUI introuvable (même inactive). Place-la sous le PlayerCanvas du joueur owner.");
    }
}

