using UnityEngine;

/// <summary>
/// Configuration d'un slot du soundboard fantôme.
/// Chaque slot représente un son que le fantôme peut jouer.
/// </summary>
[System.Serializable]
public class GhostSoundboardSlot
{
    [Tooltip("Nom affiché dans le menu radial (optionnel).")]
    public string displayName = "Son";

    [Tooltip("Icône affichée dans le menu radial (optionnel).")]
    public Sprite icon;

    [Tooltip("Clip audio à jouer quand ce slot est activé.")]
    public AudioClip audioClip;

    [Tooltip("Cooldown en secondes avant de pouvoir rejouer ce son.")]
    [Range(0.5f, 60f)]
    public float cooldown = 5f;

    [Tooltip("Volume du son (0-1).")]
    [Range(0f, 1f)]
    public float volume = 1f;

    [Tooltip("Portée maximale du son (distance en mètres).")]
    [Range(1f, 100f)]
    public float maxDistance = 30f;

    [Tooltip("Si true, le fantôme entend aussi son propre son.")]
    public bool playForSelf = true;
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;
using UnityEngine.InputSystem;

/// <summary>
/// Interface utilisateur du menu radial soundboard pour les fantômes.
/// Affiche jusqu'à 8 slots en cercle, avec sélection à la souris.
/// </summary>
public class GhostSoundboardUI : MonoBehaviour
{
    [Header("References")]
    [Tooltip("Le container principal du menu (sera activé/désactivé).")]
    [SerializeField] private GameObject menuContainer;

    [Tooltip("Transform parent où les slots UI seront instanciés.")]
    [SerializeField] private RectTransform slotsParent;

    [Tooltip("Prefab pour un slot du menu radial.")]
    [SerializeField] private GameObject slotPrefab;

    [Header("Layout")]
    [Tooltip("Rayon du cercle des slots (en pixels UI).")]
    [SerializeField] private float radius = 150f;

    [Tooltip("Angle de départ (0 = droite, 90 = haut).")]
    [SerializeField] private float startAngle = 90f;

    [Header("Visual Feedback")]
    [Tooltip("Couleur normale des slots.")]
    [SerializeField] private Color normalColor = new Color(0.2f, 0.2f, 0.2f, 0.8f);

    [Tooltip("Couleur du slot sélectionné.")]
    [SerializeField] private Color selectedColor = new Color(0.4f, 0.7f, 1f, 0.9f);

    [Tooltip("Couleur du slot en cooldown.")]
    [SerializeField] private Color cooldownColor = new Color(0.5f, 0.2f, 0.2f, 0.8f);

    [Header("Center Display")]
    [Tooltip("Texte au centre affichant le nom du slot sélectionné.")]
    [SerializeField] private TextMeshProUGUI centerText;

    [Tooltip("Indicateur au centre (optionnel).")]
    [SerializeField] private Image centerIndicator;

    [Header("Slot UI Elements (auto-filled if using prefab)")]
    [Tooltip("Si le prefab a ces éléments, ils seront utilisés.")]
    [SerializeField] private string iconImageName = "Icon";
    [SerializeField] private string backgroundImageName = "Background";
    [SerializeField] private string cooldownOverlayName = "CooldownOverlay";
    [SerializeField] private string cooldownTextName = "CooldownText";

    // Runtime
    private GhostSoundboard _soundboard;
    private readonly List<SlotUIElements> _slotElements = new List<SlotUIElements>();
    private int _selectedIndex = -1;
    private bool _isVisible;

    private class SlotUIElements
    {
        public RectTransform root;
        public Image background;
        public Image icon;
        public Image cooldownOverlay;
        public TextMeshProUGUI cooldownText;
        public int slotIndex;
    }

    private void Awake()
    {
        if (menuContainer != null)
            menuContainer.SetActive(false);
    }

    private void Update()
    {
        if (!_isVisible || _soundboard == null) return;

        UpdateSelection();
        UpdateCooldowns();
    }

    /// <summary>
    /// Affiche le menu radial avec les slots du soundboard.
    /// </summary>
    public void Show(GhostSoundboard soundboard)
    {
        Debug.Log($"[GhostSoundboardUI] Show() called");
        _soundboard = soundboard;
        _isVisible = true;
        _selectedIndex = -1;

        if (menuContainer != null)
        {
            menuContainer.SetActive(true);
            Debug.Log($"[GhostSoundboardUI] menuContainer activated: {menuContainer.activeInHierarchy}");
        }
        else
        {
            Debug.LogWarning($"[GhostSoundboardUI] menuContainer is null!");
        }

        RebuildSlots();
        UpdateCenterDisplay();
        Debug.Log($"[GhostSoundboardUI] Show() complete - slots count: {_slotElements.Count}");
    }

    /// <summary>
    /// Cache le menu radial.
    /// </summary>
    public void Hide()
    {
        _isVisible = false;
        _selectedIndex = -1;

        if (menuContainer != null)
            menuContainer.SetActive(false);
    }

    /// <summary>
    /// Retourne l'index du slot actuellement sélectionné (-1 si aucun).
    /// </summary>
    public int GetSelectedSlotIndex()
    {
        return _selectedIndex;
    }

    private void RebuildSlots()
    {
        Debug.Log($"[GhostSoundboardUI] RebuildSlots() called");

        // Nettoyer les anciens slots
        foreach (var elem in _slotElements)
        {
            if (elem.root != null)
                Destroy(elem.root.gameObject);
        }
        _slotElements.Clear();

        if (_soundboard == null)
        {
            Debug.LogWarning($"[GhostSoundboardUI] _soundboard is null!");
            return;
        }
        if (slotsParent == null)
        {
            Debug.LogWarning($"[GhostSoundboardUI] slotsParent is null!");
            return;
        }
        if (slotPrefab == null)
        {
            Debug.LogWarning($"[GhostSoundboardUI] slotPrefab is null!");
            return;
        }

        var slots = _soundboard.Slots;
        Debug.Log($"[GhostSoundboardUI] _soundboard.Slots count: {slots.Count}");
        int count = Mathf.Min(slots.Count, 8);

        float angleStep = 360f / Mathf.Max(count, 1);

        for (int i = 0; i < count; i++)
        {
            var slot = slots[i];

            // Instancier un root UI garanti
            RectTransform rt;
            GameObject go;

            // Si le prefab est déjà un UI element (RectTransform à la racine)
            if (slotPrefab.transform is RectTransform)
            {
                go = Instantiate(slotPrefab, slotsParent);
                rt = (RectTransform)go.transform;
            }
            else
            {
                // Wrapper UI (RectTransform) qui sera positionné en radial
                var wrapper = new GameObject($"{slotPrefab.name}_Wrapper", typeof(RectTransform));
                rt = wrapper.GetComponent<RectTransform>();
                rt.SetParent(slotsParent, false);

                // Le prefab devient enfant du wrapper
                go = Instantiate(slotPrefab, rt);
                go.transform.localPosition = Vector3.zero;
                go.transform.localRotation = Quaternion.identity;
                go.transform.localScale = Vector3.one;
            }

            // Config RectTransform (positionnement radial)
            rt.anchorMin = new Vector2(0.5f, 0.5f);
            rt.anchorMax = new Vector2(0.5f, 0.5f);
            rt.pivot = new Vector2(0.5f, 0.5f);

            // Positionner en cercle
            float angle = (startAngle - i * angleStep) * Mathf.Deg2Rad;
            Vector2 pos = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * radius;
            rt.anchoredPosition = pos;

            // Récupérer les éléments UI
            var elem = new SlotUIElements
            {
                root = rt,
                slotIndex = i,
                background = FindChildImage(go, backgroundImageName),
                icon = FindChildImage(go, iconImageName),
                cooldownOverlay = FindChildImage(go, cooldownOverlayName),
                cooldownText = FindChildText(go, cooldownTextName)
            };

            // Configurer l'icône
            if (elem.icon != null)
            {
                if (slot.icon != null)
                {
                    elem.icon.sprite = slot.icon;
                    elem.icon.enabled = true;
                }
                else
                {
                    elem.icon.enabled = false;
                }
            }

            // Initialiser les visuels
            if (elem.background != null)
                elem.background.color = normalColor;

            if (elem.cooldownOverlay != null)
            {
                elem.cooldownOverlay.fillAmount = 0f;
                elem.cooldownOverlay.type = Image.Type.Filled;
                elem.cooldownOverlay.fillMethod = Image.FillMethod.Radial360;
                elem.cooldownOverlay.fillClockwise = false;
            }

            if (elem.cooldownText != null)
                elem.cooldownText.text = "";

            _slotElements.Add(elem);
            Debug.Log($"[GhostSoundboardUI] Created slot {i} at position {pos}");
        }

        Debug.Log($"[GhostSoundboardUI] RebuildSlots() complete - created {_slotElements.Count} slots");
    }

    private void UpdateSelection()
    {
        if (_slotElements.Count == 0) return;

        // New Input System: Mouse position (évite UnityEngine.Input)
        var mouse = Mouse.current;
        if (mouse == null)
        {
            SetSelectedIndex(-1);
            return;
        }

        Vector2 mousePos = mouse.position.ReadValue();

        // Calculer la direction depuis le centre de l'écran vers la souris
        Vector2 screenCenter = new Vector2(Screen.width / 2f, Screen.height / 2f);
        Vector2 dir = mousePos - screenCenter;

        float distFromCenter = dir.magnitude;

        // Zone morte au centre (pas de sélection)
        float deadZone = 50f;
        if (distFromCenter < deadZone)
        {
            SetSelectedIndex(-1);
            return;
        }

        // Calculer l'angle de la souris
        float mouseAngle = Mathf.Atan2(dir.y, dir.x) * Mathf.Rad2Deg;
        if (mouseAngle < 0) mouseAngle += 360f;

        // Trouver le slot le plus proche de cet angle
        int count = _slotElements.Count;
        float angleStep = 360f / count;

        int bestIndex = -1;
        float bestAngleDiff = float.MaxValue;

        for (int i = 0; i < count; i++)
        {
            float slotAngle = startAngle - i * angleStep;
            if (slotAngle < 0) slotAngle += 360f;

            float diff = Mathf.Abs(Mathf.DeltaAngle(mouseAngle, slotAngle));
            if (diff < bestAngleDiff)
            {
                bestAngleDiff = diff;
                bestIndex = i;
            }
        }

        // Seuil de sélection (moitié de l'angle entre deux slots)
        float threshold = angleStep / 2f + 5f;
        if (bestAngleDiff <= threshold)
            SetSelectedIndex(bestIndex);
        else
            SetSelectedIndex(-1);
    }

    private void SetSelectedIndex(int index)
    {
        if (_selectedIndex == index) return;
        _selectedIndex = index;

        // Mettre à jour les visuels
        for (int i = 0; i < _slotElements.Count; i++)
        {
            var elem = _slotElements[i];
            if (elem.background == null) continue;

            bool isSelected = (i == _selectedIndex);
            bool onCooldown = !_soundboard.IsSlotReadyLocal(i);

            if (onCooldown)
                elem.background.color = cooldownColor;
            else if (isSelected)
                elem.background.color = selectedColor;
            else
                elem.background.color = normalColor;
        }

        UpdateCenterDisplay();
    }

    private void UpdateCenterDisplay()
    {
        if (centerText == null) return;

        if (_selectedIndex >= 0 && _selectedIndex < _soundboard.Slots.Count)
        {
            var slot = _soundboard.Slots[_selectedIndex];
            string name = string.IsNullOrEmpty(slot.displayName) ? $"Son {_selectedIndex + 1}" : slot.displayName;

            bool onCooldown = !_soundboard.IsSlotReadyLocal(_selectedIndex);
            if (onCooldown)
            {
                float remaining = _soundboard.GetSlotCooldownRemaining(_selectedIndex);
                centerText.text = $"{name}\n<size=70%><color=#ff6666>Cooldown: {remaining:F1}s</color></size>";
            }
            else
            {
                centerText.text = name;
            }
        }
        else
        {
            centerText.text = $"Maintenir {_soundboard.OpenMenuBindingDisplay}\npuis relâcher pour jouer";
        }
    }

    private void UpdateCooldowns()
    {
        for (int i = 0; i < _slotElements.Count; i++)
        {
            var elem = _slotElements[i];
            if (elem.slotIndex >= _soundboard.Slots.Count) continue;

            var slot = _soundboard.Slots[elem.slotIndex];
            float remaining = _soundboard.GetSlotCooldownRemaining(elem.slotIndex);
            bool onCooldown = remaining > 0f;

            // Overlay de cooldown
            if (elem.cooldownOverlay != null)
            {
                if (onCooldown)
                {
                    float fill = remaining / slot.cooldown;
                    elem.cooldownOverlay.fillAmount = fill;
                }
                else
                {
                    elem.cooldownOverlay.fillAmount = 0f;
                }
            }

            // Texte de cooldown
            if (elem.cooldownText != null)
            {
                elem.cooldownText.text = onCooldown ? remaining.ToString("F1") : "";
            }

            // Couleur de fond
            if (elem.background != null)
            {
                bool isSelected = (i == _selectedIndex);
                if (onCooldown)
                    elem.background.color = cooldownColor;
                else if (isSelected)
                    elem.background.color = selectedColor;
                else
                    elem.background.color = normalColor;
            }
        }
    }

    private Image FindChildImage(GameObject parent, string childName)
    {
        if (string.IsNullOrEmpty(childName)) return null;

        Transform child = parent.transform.Find(childName);
        if (child != null)
            return child.GetComponent<Image>();

        // Essayer le parent lui-même
        if (parent.name == childName)
            return parent.GetComponent<Image>();

        return null;
    }

    private TextMeshProUGUI FindChildText(GameObject parent, string childName)
    {
        if (string.IsNullOrEmpty(childName)) return null;

        Transform child = parent.transform.Find(childName);
        if (child != null)
            return child.GetComponent<TextMeshProUGUI>();

        return null;
    }
}

