using Unity.Netcode;
using UnityEngine;

public class EscapeDoor : NetworkBehaviour
{
    [Header("Interaction")]
    [Tooltip("Point utilisé pour la distance. Si null, utilise transform.position.")]
    public Transform interactPoint;

    [Min(0.1f)]
    public float interactDistance = 2.25f;

    [Header("Key requirement")]
    [Tooltip("Si true: n'importe quelle clé (id 20..29) fonctionne.")]
    public bool requireAnyKey = true;

    [Tooltip("Min inclus (par défaut 20).")]
    public int keyMinInclusive = 20;

    [Tooltip("Max exclus (par défaut 30).")]
    public int keyMaxExclusive = 30;

    [Tooltip("Si >= 0, force une clé spécifique (raw id exact), et ignore requireAnyKey.")]
    public int requiredItemRaw = -1;

    [Header("Optional - require door open")]
    public bool requireDoorOpen = false;
    public NetworkDoor door;

    public bool HasKeyLocal(NetworkPlayerState ps) => HasKeyInInventory(ps);

    bool HasKeyInInventory(NetworkPlayerState ps)
    {
        if (ps == null || ps.Inventory == null) return false;

        for (int i = 0; i < ps.Inventory.Count; i++)
        {
            int raw = ps.Inventory[i];
            if (raw < 0) continue;

            if (requiredItemRaw >= 0)
            {
                if (raw == requiredItemRaw) return true;
                continue;
            }

            if (requireAnyKey && raw >= keyMinInclusive && raw < keyMaxExclusive)
                return true;
        }

        return false;
    }

    bool CloseEnough(Transform player)
    {
        if (player == null) return false;
        Vector3 p = interactPoint != null ? interactPoint.position : transform.position;
        return Vector3.Distance(player.position, p) <= interactDistance;
    }

    [Rpc(SendTo.Server, InvokePermission = RpcInvokePermission.Everyone)]
    public void RequestEscapeServerRpc(RpcParams rpcParams = default)
    {
        if (!IsServer) return;

        var gc = NetworkGameController.Instance;
        if (gc == null) return;
        if ((MatchState)gc.State.Value != MatchState.Running) return;
        if (gc.WinnerSide.Value != (int)WinSide.None) return;

        ulong clientId = rpcParams.Receive.SenderClientId;

        var nm = NetworkManager.Singleton;
        if (nm == null) return;
        if (!nm.ConnectedClients.TryGetValue(clientId, out var client)) return;
        if (client.PlayerObject == null) return;

        var ps = client.PlayerObject.GetComponent<NetworkPlayerState>();
        if (ps == null) return;
        if (!ps.Alive.Value || ps.Escaped.Value) return;

        var tr = client.PlayerObject.transform;
        if (!CloseEnough(tr)) return;

        if (requireDoorOpen)
        {
            var d = door != null ? door : GetComponentInParent<NetworkDoor>();
            if (d == null || !d.IsOpen.Value) return;
        }

        if (!HasKeyInInventory(ps)) return;

        gc.TryEscape(clientId);
    }
}

