// Interactor.cs
// (corrigé: stack-aware pickup via ItemDatabase + fix Keyboard.current import + petits garde-fous)
using Unity.Netcode;
using UnityEngine;
using TMPro;
using UnityEngine.InputSystem;

public class Interactor : MonoBehaviour
{
    public Camera cam;
    public float range = 3f;

    [Header("Input (Input System)")]
    [Tooltip("Référence à l'action Interact (ex: Player/Interact). Remappable in-game.")]
    public InputActionReference interactAction;

    [Tooltip("Fallback clavier (Input System). Laisse sur None si tu veux forcer l'Action uniquement.")]
    public Key interactFallbackKey = Key.None;

    [Header("Raycast")]
    public LayerMask interactMask = ~0;
    public float raycastForwardOffset = 0.15f;

    [Tooltip("Radius du cast (0 = Raycast). Recommandé: 0.15 - 0.25 pour éviter l'effet 'il faut être pile dans le collider'.")]
    public float castRadius = 0.20f;

    [Header("Car - Local gating")]
    [Tooltip("Respecte la distance CarObjective.interactDistance côté client (UI + action).")]
    public bool carEnforceDistance = true;

    [Tooltip("Oblige à viser le point (angle) pour afficher l'interaction voiture (évite le 'Pas d'huile' même quand tu regardes ailleurs).")]
    public bool carEnforceAimAngle = true;

    [Range(0f, 89f)]
    public float carMaxAimAngle = 35f;

    [Header("UI")]
    public TMP_Text promptText;

    [Header("Pickup")]
    public ItemDatabase itemDb;
    public string pickupPromptFormat = "Ramasser {0} ({1})";
    public string inventoryFullPrompt = "Inventaire plein";

    [Header("Search")]
    public string searchPrompt = "Fouiller ({0})";
    public string searchDepletedPrompt = "";
    public string searchingPrompt = "Recherche...";
    public SearchProgressUI searchUi;

    [Header("Kill")]
    public string killPromptFormat = "Tuer ({0})";
    public string cannotKillPrompt = "";

    [Header("Car")]
    public string carNeedItemPrompt = "Il manque un élément";
    public string carDonePrompt = "Voiture prête";
    public string carBatteryPrompt = "Installer batterie ({0})";
    public string carEnginePrompt = "Installer moteur ({0})";
    public string carCablePrompt = "Installer câble ({0})";
    public string carFuelPrompt = "Remplir essence (maintenir {0})";
    public string carNoFuelPrompt = "Pas d'essence";
    public string carOilPrompt = "Mettre huile (maintenir {0})";
    public string carNoOilPrompt = "Pas d'huile";

    [Header("Door")]
    public string doorOpenPrompt = "Ouvrir ({0})";
    public string doorClosePrompt = "Fermer ({0})";

    [Header("Escape Door")]
    public string escapePrompt = "Sortir ({0})";
    public string escapeNeedKeyPrompt = "Il faut une clé";

    [Header("Fueling UI")]
    public FuelingProgressUI fuelingUi;

    private NetworkObject _no;
    private NetworkPlayerState _ps;
    private PlayerInput _playerInput;

    private PropPickup _propInFront;
    private NetworkObject _propNoInFront;

    private SearchableLoot _searchInFront;
    private NetworkObject _searchNoInFront;
    private bool _isSearching;

    private CarInteractZone _carZoneInFront;
    private CarObjective _carInFront;
    private CarObjective _fuelingCar;
    private CarObjective _oilingCar;

    private EscapeDoor _escapeDoorInFront;
    private NetworkDoor _doorInFront;

    private NetworkPlayerState _killTargetPs;
    private ulong _killTargetClientId;

    private InputAction _interact;
    private bool _inputBound;

    private void Awake()
    {
        _no = GetComponentInParent<NetworkObject>();
        _ps = GetComponentInParent<NetworkPlayerState>();
        _playerInput = GetComponentInParent<PlayerInput>();

        if (cam == null)
            cam = GetComponentInChildren<Camera>(true);

        if (cam == null)
            cam = Camera.main;

        if (fuelingUi != null) fuelingUi.Hide();
        if (searchUi != null) searchUi.Hide();
        ClearPrompt();
    }

    private void OnEnable() => TryBindInputIfOwner();

    private void OnDisable()
    {
        UnbindInput();
        StopFuelingIfNeeded();
        StopSearchingUI();
        ClearPrompt();
    }

    private void OnDestroy()
    {
        UnbindInput();
        StopFuelingIfNeeded();
        StopSearchingUI();
    }

    private void Update()
    {
        if (!IsLocalOwner())
        {
            if (_inputBound) UnbindInput();
            return;
        }

        TryBindInputIfOwner();

        if (_isSearching)
        {
            SetPrompt(searchingPrompt);
            return;
        }

        FindInteractable();

        // fallback clavier (Input System)
        if (_interact == null && interactFallbackKey != Key.None)
        {
            var kb = Keyboard.current;
            if (kb != null)
            {
                var keyCtrl = kb[interactFallbackKey];
                if (keyCtrl != null)
                {
                    if (keyCtrl.wasPressedThisFrame) HandleInteractDown();
                    if (keyCtrl.wasReleasedThisFrame) HandleInteractUp();
                }
            }
        }
    }

    private bool IsLocalOwner()
    {
        if (_no == null) return true;
        if (!_no.IsSpawned) return false;
        return _no.IsOwner;
    }

    private void TryBindInputIfOwner()
    {
        if (_inputBound) return;
        if (!IsLocalOwner()) return;

        _interact = interactAction != null ? interactAction.action : null;
        if (_interact == null) return;

        _interact.started += OnInteractStarted;
        _interact.canceled += OnInteractCanceled;

        // si pas de PlayerInput, on gère nous-même Enable/Disable
        if (_playerInput == null && !_interact.enabled)
            _interact.Enable();

        _inputBound = true;
    }

    private void UnbindInput()
    {
        if (!_inputBound) return;

        if (_interact != null)
        {
            _interact.started -= OnInteractStarted;
            _interact.canceled -= OnInteractCanceled;

            if (_playerInput == null && _interact.enabled)
                _interact.Disable();
        }

        _interact = null;
        _inputBound = false;
    }

    private void OnInteractStarted(InputAction.CallbackContext _) => HandleInteractDown();
    private void OnInteractCanceled(InputAction.CallbackContext _) => HandleInteractUp();

    private Transform GetLocalPlayerTransformForDistance()
    {
        if (_no != null) return _no.transform;
        if (_ps != null) return _ps.transform;
        return transform.root != null ? transform.root : transform;
    }

    private bool PassCarLocalGates(CarInteractZone zone, out Transform point)
    {
        point = null;

        if (zone == null || zone.car == null) return false;
        if (_ps == null) return false;
        if (!_ps.Alive.Value || _ps.Escaped.Value) return false;

        point = zone.car.GetPoint(zone.kind);
        if (point == null) return false;

        // distance
        if (carEnforceDistance)
        {
            var meTr = GetLocalPlayerTransformForDistance();
            float d = zone.car.interactDistance;
            if ((meTr.position - point.position).sqrMagnitude > d * d)
                return false;
        }

        // angle
        if (carEnforceAimAngle && cam != null)
        {
            Vector3 to = point.position - cam.transform.position;
            if (to.sqrMagnitude > 0.0001f)
            {
                float ang = Vector3.Angle(cam.transform.forward, to);
                if (ang > carMaxAimAngle)
                    return false;
            }
        }

        return true;
    }

    private void HandleInteractDown()
    {
        if (!IsLocalOwner()) return;
        if (_isSearching) return;

        FindInteractable();

        // 1) KILL
        if (_killTargetPs != null && _ps != null)
        {
            _ps.RequestKillServerRpc(_killTargetClientId);
            return;
        }

        // 2) Car
        if (_carZoneInFront != null && _carInFront != null)
        {
            if (!PassCarLocalGates(_carZoneInFront, out _))
                return;

            if (_carZoneInFront.kind == CarInteractKind.Fuel)
            {
                if (!_ps.HasFuelLocal()) return;

                _carInFront.StartFuelingServerRpc();
                _fuelingCar = _carInFront;

                if (fuelingUi != null) fuelingUi.Show(_fuelingCar);
            }
            else if (_carZoneInFront.kind == CarInteractKind.Oil)
            {
                if (!_ps.HasItemLocal((int)ItemId.HuileMoteur)) return;

                _carInFront.StartOilingServerRpc();
                _oilingCar = _carInFront;
            }
            else
            {
                _carInFront.TryInstallAtServerRpc((int)_carZoneInFront.kind);
            }

            return;
        }

        // 3) EscapeDoor
        if (_escapeDoorInFront != null)
        {
            _escapeDoorInFront.RequestEscapeServerRpc();
            return;
        }

        // 4) Door
        if (_doorInFront != null)
        {
            _doorInFront.RequestToggleServerRpc();
            return;
        }

        // 5) Search
        if (_searchInFront != null && _searchNoInFront != null)
        {
            if (_searchInFront.Depleted.Value) return;

            // Search: item inconnu -> exige un slot vide
            if (!HasAnyEmptySlotLocal())
            {
                SetPrompt(inventoryFullPrompt);
                return;
            }

            _searchInFront.RequestSearchServerRpc();
            _isSearching = true;

            if (searchUi != null)
                searchUi.Show(_searchInFront.searchDuration, "");

            Invoke(nameof(StopSearchingUI), Mathf.Max(0.01f, _searchInFront.searchDuration));
            return;
        }

        // 6) Pickup (stack-aware local check)
        if (_propInFront != null && _propNoInFront != null && _ps != null)
        {
            if (!_ps.HasSpaceLocalFor(_propInFront.itemId, itemDb, 1))
            {
                SetPrompt(inventoryFullPrompt);
                return;
            }

            _ps.RequestPickupServerRpc(_propNoInFront.NetworkObjectId);
        }
    }

    private void HandleInteractUp()
    {
        if (!IsLocalOwner()) return;
        StopFuelingIfNeeded();
    }

    private void StopSearchingUI()
    {
        _isSearching = false;
        if (searchUi != null) searchUi.Hide();
    }

    private void StopFuelingIfNeeded()
    {
        if (_fuelingCar != null)
        {
            _fuelingCar.StopFuelingServerRpc();
            _fuelingCar = null;
            if (fuelingUi != null) fuelingUi.Hide();
        }

        if (_oilingCar != null)
        {
            _oilingCar.StopOilingServerRpc();
            _oilingCar = null;
        }
    }

    private bool HasAnyEmptySlotLocal()
    {
        if (_ps == null || _ps.Inventory == null) return false;
        for (int i = 0; i < _ps.Inventory.Count; i++)
            if (_ps.Inventory[i] == NetworkPlayerState.SLOT_EMPTY)
                return true;
        return false;
    }

    private bool HasAnyKeyLocal()
    {
        if (_ps == null || _ps.Inventory == null) return false;

        for (int i = 0; i < _ps.Inventory.Count; i++)
        {
            int raw = _ps.Inventory[i];
            if (raw >= 20 && raw < 30) return true;
        }

        return false;
    }

    private string FormatPrompt(string format, params object[] args)
    {
        if (string.IsNullOrEmpty(format)) return string.Empty;
        try { return string.Format(format, args); }
        catch { return format; }
    }

    private string GetInteractDisplay()
    {
        if (_interact != null)
        {
            var s = _interact.GetBindingDisplayString();
            return string.IsNullOrEmpty(s) ? "Interact" : s;
        }

        if (interactFallbackKey != Key.None)
            return interactFallbackKey.ToString();

        return "Interact";
    }

    private void FindInteractable()
    {
        _propInFront = null;
        _propNoInFront = null;

        _searchInFront = null;
        _searchNoInFront = null;

        _carZoneInFront = null;
        _carInFront = null;

        _escapeDoorInFront = null;
        _doorInFront = null;

        _killTargetPs = null;
        _killTargetClientId = 0;

        if (cam == null)
        {
            SetPrompt("");
            return;
        }

        Vector3 origin = cam.transform.position + cam.transform.forward * raycastForwardOffset;
        Vector3 dir = cam.transform.forward;

        RaycastHit[] hits;
        if (castRadius > 0.001f)
            hits = Physics.SphereCastAll(origin, castRadius, dir, range, interactMask, QueryTriggerInteraction.Collide);
        else
            hits = Physics.RaycastAll(origin, dir, range, interactMask, QueryTriggerInteraction.Collide);

        if (hits == null || hits.Length == 0)
        {
            SetPrompt("");
            return;
        }

        System.Array.Sort(hits, (a, b) => a.distance.CompareTo(b.distance));

        for (int i = 0; i < hits.Length; i++)
        {
            var hit = hits[i];
            if (hit.collider == null) continue;

            var hitNo = hit.collider.GetComponentInParent<NetworkObject>();
            if (hitNo != null && _no != null && hitNo == _no)
                continue;

            // 1) Car
            var zone = hit.collider.GetComponentInParent<CarInteractZone>();
            if (zone != null && zone.car != null)
            {
                if (_ps == null) { SetPrompt(""); return; }

                if (!PassCarLocalGates(zone, out _))
                    continue;

                _carZoneInFront = zone;
                _carInFront = zone.car;

                if (_carInFront.IsReady())
                {
                    SetPrompt(carDonePrompt);
                    return;
                }

                switch (zone.kind)
                {
                    case CarInteractKind.Battery:
                        SetPrompt(FormatPrompt(_ps.HasItemLocal((int)ItemId.Batterie) ? carBatteryPrompt : carNeedItemPrompt, GetInteractDisplay()));
                        return;
                    case CarInteractKind.Engine:
                        SetPrompt(FormatPrompt(_ps.HasItemLocal((int)ItemId.Moteur) ? carEnginePrompt : carNeedItemPrompt, GetInteractDisplay()));
                        return;
                    case CarInteractKind.Cable:
                        SetPrompt(FormatPrompt(_ps.HasItemLocal((int)ItemId.Cables) ? carCablePrompt : carNeedItemPrompt, GetInteractDisplay()));
                        return;
                    case CarInteractKind.Fuel:
                        SetPrompt(_ps.HasFuelLocal() ? FormatPrompt(carFuelPrompt, GetInteractDisplay()) : carNoFuelPrompt);
                        return;
                    case CarInteractKind.Oil:
                        SetPrompt(_ps.HasItemLocal((int)ItemId.HuileMoteur) ? FormatPrompt(carOilPrompt, GetInteractDisplay()) : carNoOilPrompt);
                        return;
                }

                continue;
            }

            // 2) EscapeDoor
            var escape = hit.collider.GetComponentInParent<EscapeDoor>();
            if (escape != null)
            {
                _escapeDoorInFront = escape;

                if (_ps == null) { SetPrompt(""); return; }

                bool hasKey = escape.HasKeyLocal(_ps) || HasAnyKeyLocal();
                SetPrompt(hasKey ? FormatPrompt(escapePrompt, GetInteractDisplay()) : escapeNeedKeyPrompt);
                return;
            }

            // 3) Door
            var door = hit.collider.GetComponentInParent<NetworkDoor>();
            if (door != null)
            {
                _doorInFront = door;
                SetPrompt(FormatPrompt(door.IsOpen.Value ? doorClosePrompt : doorOpenPrompt, GetInteractDisplay()));
                return;
            }

            // 4) Searchable
            var search = hit.collider.GetComponentInParent<SearchableLoot>();
            if (search != null)
            {
                var searchNo = search.GetComponentInParent<NetworkObject>();
                if (searchNo != null && searchNo.IsSpawned)
                {
                    _searchInFront = search;
                    _searchNoInFront = searchNo;

                    if (search.Depleted.Value && !string.IsNullOrEmpty(searchDepletedPrompt))
                        SetPrompt(searchDepletedPrompt);
                    else
                        SetPrompt(FormatPrompt(searchPrompt, GetInteractDisplay()));

                    return;
                }

                continue;
            }

            // 5) Prop pickup (stack-aware prompt)
            var prop = hit.collider.GetComponentInParent<PropPickup>();
            if (prop != null)
            {
                var propNo = prop.GetComponentInParent<NetworkObject>();
                if (propNo != null && propNo.IsSpawned)
                {
                    _propInFront = prop;
                    _propNoInFront = propNo;

                    if (_ps != null && !_ps.HasSpaceLocalFor(prop.itemId, itemDb, 1))
                        SetPrompt(inventoryFullPrompt);
                    else
                        SetPrompt(FormatPrompt(pickupPromptFormat, prop.GetDisplayName(itemDb), GetInteractDisplay()));

                    return;
                }

                continue;
            }

            // 6) Player kill
            if (hitNo != null && hitNo.IsSpawned)
            {
                var targetPs = hitNo.GetComponentInParent<NetworkPlayerState>();
                if (targetPs != null && _ps != null)
                {
                    if (CanShowKillPromptLocal(_ps, targetPs))
                    {
                        _killTargetPs = targetPs;
                        _killTargetClientId = hitNo.OwnerClientId;
                        SetPrompt(FormatPrompt(killPromptFormat, GetInteractDisplay()));
                        return;
                    }
                    else if (!string.IsNullOrEmpty(cannotKillPrompt))
                    {
                        SetPrompt(cannotKillPrompt);
                        return;
                    }
                }
            }
        }

        SetPrompt("");
    }

    private bool CanShowKillPromptLocal(NetworkPlayerState me, NetworkPlayerState target)
    {
        if (me == null || target == null) return false;

        if ((PlayerRole)me.Role.Value != PlayerRole.Possede) return false;

        if (!target.Alive.Value) return false;
        if (target.Escaped.Value) return false;

        if (me.CurrentRoom.Value != target.CurrentRoom.Value) return false;

        var gc = NetworkGameController.Instance;
        if (gc != null && gc.possedeKillsOnlyDuringBlackout && !gc.IsBlackout.Value) return false;

        return true;
    }

    private void SetPrompt(string text)
    {
        if (promptText == null) return;
        promptText.text = text;
    }

    private void ClearPrompt()
    {
        if (promptText != null) promptText.text = "";
    }
}

