using Unity.Netcode;
using UnityEngine;

public class KillTargetInteractable : MonoBehaviour, IInteractable
{
    public string prompt = "Tuer (E)";
    public int Priority => 50;

    private NetworkObject _no;
    private NetworkPlayerState _ps;

    void Awake()
    {
        _no = GetComponentInParent<NetworkObject>();
        _ps = GetComponentInParent<NetworkPlayerState>();
    }

    public bool TryGetPrompt(InteractContext ctx, out string outPrompt)
    {
        outPrompt = "";

        if (ctx.ActorPs == null || ctx.Game == null) return false;
        if (_no == null || _ps == null) return false;

        // pas soi-même
        if (ctx.ActorNo != null && _no.OwnerClientId == ctx.ActorNo.OwnerClientId) return false;

        // acteur
        if (!ctx.ActorPs.Alive.Value) return false;
        if ((PlayerRole)ctx.ActorPs.Role.Value != PlayerRole.Possede) return false;
        if (!ctx.Game.IsBlackout.Value) return false;

        // cible
        if (!_ps.Alive.Value) return false;
        if ((PlayerRole)_ps.Role.Value != PlayerRole.Survivant) return false;

        // même pièce
        if (_ps.CurrentRoom.Value != ctx.ActorPs.CurrentRoom.Value) return false;

        outPrompt = prompt;
        return true;
    }

    public bool CanInteract(InteractContext ctx) => TryGetPrompt(ctx, out _);

    public void Interact(InteractContext ctx)
    {
        if (_no == null) return;
        ctx.ActorPs.RequestKillServerRpc(_no.OwnerClientId);
    }
}

