// PropPickup.cs
using Unity.Netcode;
using UnityEngine;

[RequireComponent(typeof(NetworkObject))]
public class PropPickup : NetworkBehaviour
{
    [Header("Item")]
    public ItemId itemId = ItemId.Junk;

    [Tooltip("Optionnel: si vide, on prend le nom depuis ItemDatabase.")]
    public string displayNameOverride = "";

    [Min(0.1f)]
    public float maxPickupDistance = 3f;

    public string GetDisplayName(ItemDatabase db)
    {
        if (!string.IsNullOrWhiteSpace(displayNameOverride))
            return displayNameOverride;

        if (db != null && db.TryGet(itemId, out var def) && !string.IsNullOrWhiteSpace(def.displayName))
            return def.displayName;

        return itemId.ToString();
    }
}

