using UnityEngine;

[DisallowMultipleComponent]
public class PropPickupInteractionHitbox : MonoBehaviour
{
    [Header("Interaction hitbox")]
    [Tooltip("Taille minimale (en m�tres) de la zone cliquable/visable.")]
    [Min(0.01f)] public float minSize = 0.2f; // au lieu de 0.6f


    [Tooltip("Si true: utilise les Renderer.bounds (taille visuelle). Sinon: utilise les Collider.bounds (physique).")]
    public bool useRenderersBounds = true;

    [Tooltip("Inclure les renderers/colliders inactifs (souvent inutile).")]
    public bool includeInactive = false;

    [Tooltip("Optionnel: layer � appliquer � la hitbox (ex: layer Interactable). -1 = ne change rien.")]
    public int hitboxLayer = -1;

    [SerializeField, HideInInspector] private BoxCollider _hitbox;

    private void Reset()
    {
        EnsureHitbox();
        Rebuild();
    }

    private void OnValidate()
    {
        EnsureHitbox();
        Rebuild();
    }

    private void Awake()
    {
        EnsureHitbox();
        Rebuild();
    }

    private void EnsureHitbox()
    {
        if (_hitbox != null) return;

        Transform t = transform.Find("__InteractHitbox__");
        if (t == null)
        {
            var go = new GameObject("__InteractHitbox__");
            go.transform.SetParent(transform, false);
            go.transform.localPosition = Vector3.zero;
            go.transform.localRotation = Quaternion.identity;
            go.transform.localScale = Vector3.one;
            t = go.transform;
        }

        _hitbox = t.GetComponent<BoxCollider>();
        if (_hitbox == null) _hitbox = t.gameObject.AddComponent<BoxCollider>();
        _hitbox.isTrigger = true;

        if (hitboxLayer >= 0 && hitboxLayer <= 31)
            t.gameObject.layer = hitboxLayer;
    }

    public void Rebuild()
    {
        if (_hitbox == null) return;

        if (!TryGetWorldBounds(out var b))
        {
            _hitbox.center = Vector3.zero;
            _hitbox.size = Vector3.one * minSize;
            return;
        }

        // Convertit les 8 coins des bounds monde dans l'espace local de la hitbox
        var hbT = _hitbox.transform;

        Vector3 c = b.center;
        Vector3 e = b.extents;

        Vector3[] corners =
        {
            c + new Vector3( e.x,  e.y,  e.z),
            c + new Vector3( e.x,  e.y, -e.z),
            c + new Vector3( e.x, -e.y,  e.z),
            c + new Vector3( e.x, -e.y, -e.z),
            c + new Vector3(-e.x,  e.y,  e.z),
            c + new Vector3(-e.x,  e.y, -e.z),
            c + new Vector3(-e.x, -e.y,  e.z),
            c + new Vector3(-e.x, -e.y, -e.z),
        };

        Vector3 min = new Vector3(float.PositiveInfinity, float.PositiveInfinity, float.PositiveInfinity);
        Vector3 max = new Vector3(float.NegativeInfinity, float.NegativeInfinity, float.NegativeInfinity);

        for (int i = 0; i < corners.Length; i++)
        {
            Vector3 local = hbT.InverseTransformPoint(corners[i]);
            min = Vector3.Min(min, local);
            max = Vector3.Max(max, local);
        }

        Vector3 size = max - min;
        Vector3 center = (min + max) * 0.5f;

        // Applique la taille minimale (mais laisse plus grand si l'objet l'est)
        size.x = Mathf.Max(size.x, minSize);
        size.y = Mathf.Max(size.y, minSize);
        size.z = Mathf.Max(size.z, minSize);

        _hitbox.center = center;
        _hitbox.size = size;
    }

    private bool TryGetWorldBounds(out Bounds bounds)
    {
        bounds = default;
        bool has = false;

        if (useRenderersBounds)
        {
            var rends = GetComponentsInChildren<Renderer>(includeInactive);
            for (int i = 0; i < rends.Length; i++)
            {
                if (!has) { bounds = rends[i].bounds; has = true; }
                else bounds.Encapsulate(rends[i].bounds);
            }
        }
        else
        {
            var cols = GetComponentsInChildren<Collider>(includeInactive);
            for (int i = 0; i < cols.Length; i++)
            {
                if (cols[i].isTrigger) continue;
                if (!has) { bounds = cols[i].bounds; has = true; }
                else bounds.Encapsulate(cols[i].bounds);
            }
        }

        return has;
    }
}

