using System;
using UnityEngine;

public class Footsteps : MonoBehaviour
{
    [Serializable]
    public class SurfaceSet
    {
        public PhysicsMaterial physicsMaterial;
        public AudioClip[] clips;
    }

    [Header("Foot Transforms")]
    public Transform leftFoot;
    public Transform rightFoot;

    [Header("Ground Detection")]
    public LayerMask groundMask = ~0;
    public float raycastHeight = 0.2f;
    public float raycastDistance = 1.2f;

    [Header("Audio")]
    public AudioSource audio3D; // Spatial Blend = 1

    [Header("Surface Sounds")]
    public SurfaceSet[] surfaces;
    public AudioClip[] defaultClips;

    [Header("Variation")]
    public float pitchMin = 0.95f;
    public float pitchMax = 1.05f;
    public float volumeMin = 0.9f;
    public float volumeMax = 1.0f;

    int lastClipIndex = -1;

    // Appel�es par Animation Events
    public void Footstep_L() => PlayFootstep(leftFoot);
    public void Footstep_R() => PlayFootstep(rightFoot);

    void PlayFootstep(Transform foot)
    {
        if (foot == null || audio3D == null) return;

        Vector3 origin = foot.position + Vector3.up * raycastHeight;
        if (!Physics.Raycast(origin, Vector3.down, out RaycastHit hit, raycastDistance, groundMask))
            return;

        AudioClip[] clips = ResolveClips(hit.collider.sharedMaterial);
        if (clips == null || clips.Length == 0) return;

        // Choisir un clip sans r�p�ter exactement le pr�c�dent
        int index = UnityEngine.Random.Range(0, clips.Length);
        if (clips.Length > 1 && index == lastClipIndex)
            index = (index + 1) % clips.Length;
        lastClipIndex = index;

        AudioClip clip = clips[index];
        if (clip == null) return;

        // Placer la source au point de contact pour un son 3D cr�dible
        audio3D.transform.position = hit.point;

        // Variations
        audio3D.pitch = UnityEngine.Random.Range(pitchMin, pitchMax);
        float vol = UnityEngine.Random.Range(volumeMin, volumeMax);

        audio3D.PlayOneShot(clip, vol);
    }

    AudioClip[] ResolveClips(PhysicsMaterial pm)
    {
        if (pm != null && surfaces != null)
        {
            foreach (var s in surfaces)
            {
                if (s != null && s.physicsMaterial == pm)
                    return s.clips;
            }
        }
        return defaultClips;
    }
}

