using System;
using UnityEngine;

public class FootstepsProcedural : MonoBehaviour
{
    [Serializable]
    public class SurfaceSet
    {
        public PhysicsMaterial physicsMaterial;
        public AudioClip[] clips;
    }

    public enum StepMode { Contact, Distance3Gaits }

    [Header("MODE")]
    public StepMode mode = StepMode.Distance3Gaits;

    [Header("DEBUG")]
    public bool debugLogs = true;
    public bool debugRay = true;
    public float debugLogInterval = 0.5f;

    [Header("References")]
    public CharacterController controller;
    public Transform leftFoot;
    public Transform rightFoot;
    public AudioSource audio3D;

    [Header("Surface sounds")]
    public SurfaceSet[] surfaces;
    public AudioClip[] defaultClips;

    [Header("Raycast ground detection")]
    public LayerMask groundMask = ~0;
    public float raycastHeight = 0.05f;
    public float raycastDistance = 2.5f;

    [Header("Trigger gating")]
    public float minMoveSpeed = 0.15f;
    public bool requireGroundedForTrigger = true;
    public float groundedGraceTime = 0.12f;

    [Header("Distance mode (3 gaits)")]
    [Tooltip("Vitesse (m/s) � partir de laquelle on consid�re que c'est du jog/trot.")]
    public float jogSpeed = 2.5f;

    [Tooltip("Vitesse (m/s) � partir de laquelle on consid�re que c'est du run/course.")]
    public float runSpeed = 4.5f;

    [Tooltip("Distance par pas en marche (m).")]
    public float stepDistWalk = 0.75f;

    [Tooltip("Distance par pas en trot (m).")]
    public float stepDistJog = 0.62f;

    [Tooltip("Distance par pas en course (m).")]
    public float stepDistRun = 0.52f;

    [Tooltip("Lissage de la distance cible (0=pas de lissage, 1=tr�s liss�).")]
    [Range(0f, 1f)] public float stepDistSmoothing = 0.25f;

    [Tooltip("Anti-spam minimal en secondes.")]
    public float minStepInterval = 0.08f;

    [Tooltip("R�initialise l'accumulateur quand on n'est pas grounded (�vite un pas instant � l'atterrissage).")]
    public bool resetAccumulatorWhenAirborne = true;

    [Header("Contact mode (legacy)")]
    public float contactEnter = 0.02f;
    public float contactExit = 0.05f;
    public float stepCooldown = 0.12f;

    [Header("Variation")]
    public float pitchMin = 0.95f;
    public float pitchMax = 1.05f;
    public float volumeMin = 0.9f;
    public float volumeMax = 1.0f;

    // State
    bool leftWasClose;
    bool rightWasClose;
    float leftCd;
    float rightCd;

    int lastClipIndex = -1;
    Vector3 lastPos;

    float nextLogTime;
    float groundedGrace;

    // distance-mode state
    float distAcc;
    bool nextLeft = true;
    float nextAllowedStepTime;
    float smoothedStepDist;

    void Reset()
    {
        controller = GetComponent<CharacterController>();
        audio3D = GetComponent<AudioSource>();
    }

    void Start()
    {
        lastPos = transform.position;
        smoothedStepDist = stepDistWalk;

        Log($"Start. mode={mode} mask={groundMask.value} rayH={raycastHeight} rayD={raycastDistance} minSpeed={minMoveSpeed} jogSpeed={jogSpeed} runSpeed={runSpeed}");
        if (audio3D != null)
            Log($"AudioSource: spatialBlend={audio3D.spatialBlend} minDist={audio3D.minDistance} maxDist={audio3D.maxDistance} rolloff={audio3D.rolloffMode}");
    }

    void Update()
    {
        if (controller == null || audio3D == null || leftFoot == null || rightFoot == null)
        {
            if (Time.time >= nextLogTime)
            {
                nextLogTime = Time.time + debugLogInterval;
                LogWarning($"Missing refs: controller={(controller != null)} audio3D={(audio3D != null)} leftFoot={(leftFoot != null)} rightFoot={(rightFoot != null)}");
            }
            return;
        }

        // Horizontal speed
        Vector3 delta = transform.position - lastPos;
        lastPos = transform.position;
        delta.y = 0f;
        float moved = delta.magnitude;
        float speed = moved / Mathf.Max(Time.deltaTime, 0.0001f);

        // Grounded smoothing
        if (controller.isGrounded) groundedGrace = groundedGraceTime;
        else groundedGrace = Mathf.Max(0f, groundedGrace - Time.deltaTime);
        bool groundedStable = groundedGrace > 0f;

        // cooldowns (contact mode)
        leftCd -= Time.deltaTime;
        rightCd -= Time.deltaTime;

        bool canSpeed = speed >= minMoveSpeed;
        bool canGround = !requireGroundedForTrigger || groundedStable;
        bool allowTrigger = canSpeed && canGround;

        if (Time.time >= nextLogTime)
        {
            nextLogTime = Time.time + debugLogInterval;
            Log($"Status: speed={speed:0.00} moved={moved:0.000} grounded={controller.isGrounded} groundedStable={groundedStable} allow={allowTrigger} distAcc={distAcc:0.000} stepDist={smoothedStepDist:0.000}");
        }

        if (!allowTrigger)
        {
            if (mode == StepMode.Distance3Gaits && resetAccumulatorWhenAirborne && !groundedStable)
                distAcc = 0f;
            return;
        }

        if (mode == StepMode.Distance3Gaits)
        {
            // 1) Choix de l'allure
            float targetStepDist;
            if (speed < jogSpeed) targetStepDist = stepDistWalk;
            else if (speed < runSpeed) targetStepDist = stepDistJog;
            else targetStepDist = stepDistRun;

            // 2) Lissage (�vite les sauts de cadence)
            smoothedStepDist = Mathf.Lerp(smoothedStepDist, targetStepDist, 1f - Mathf.Pow(1f - stepDistSmoothing, Time.deltaTime * 60f));

            // 3) Accumule la distance parcourue
            distAcc += moved;

            // 4) Anti spam temps minimal
            if (Time.time < nextAllowedStepTime) return;

            // 5) Trigger d�s qu'on d�passe la distance
            if (distAcc >= smoothedStepDist)
            {
                distAcc -= smoothedStepDist;
                nextAllowedStepTime = Time.time + minStepInterval;

                Transform foot = nextLeft ? leftFoot : rightFoot;
                string label = nextLeft ? "L" : "R";
                nextLeft = !nextLeft;

                if (TryRaycastUnderFoot(foot, out RaycastHit hit))
                {
                    Log($"{label}: DIST TRIGGER gaitDist={smoothedStepDist:0.000} speed={speed:0.00}");
                    PlayFootstep(hit, label);
                }
                else if (TryRaycastUnderPoint(transform.position, out RaycastHit hit2))
                {
                    Log($"{label}: DIST TRIGGER fallback(center) gaitDist={smoothedStepDist:0.000} speed={speed:0.00}");
                    PlayFootstep(hit2, label);
                }
            }

            return;
        }

        // Legacy contact mode
        CheckFoot(leftFoot, "L", ref leftWasClose, ref leftCd);
        CheckFoot(rightFoot, "R", ref rightWasClose, ref rightCd);
    }

    bool TryRaycastUnderFoot(Transform foot, out RaycastHit hit)
    {
        Vector3 origin = foot.position + Vector3.up * raycastHeight;
        if (debugRay) Debug.DrawRay(origin, Vector3.down * raycastDistance, Color.cyan, 0.02f);
        return Physics.Raycast(origin, Vector3.down, out hit, raycastDistance, groundMask);
    }

    bool TryRaycastUnderPoint(Vector3 point, out RaycastHit hit)
    {
        Vector3 origin = point + Vector3.up * 0.5f;
        return Physics.Raycast(origin, Vector3.down, out hit, 5f, groundMask);
    }

    void CheckFoot(Transform foot, string label, ref bool wasClose, ref float cd)
    {
        Vector3 origin = foot.position + Vector3.up * raycastHeight;
        if (debugRay) Debug.DrawRay(origin, Vector3.down * raycastDistance, Color.cyan, 0.02f);

        bool hitSomething = Physics.Raycast(origin, Vector3.down, out RaycastHit hit, raycastDistance, groundMask);
        if (!hitSomething) { wasClose = false; return; }

        float distToFoot = hit.distance - raycastHeight;

        bool isCloseNow = wasClose ? (distToFoot <= contactExit) : (distToFoot <= contactEnter);

        if (!wasClose && isCloseNow && cd <= 0f)
        {
            Log($"{label}: CONTACT TRIGGER");
            PlayFootstep(hit, label);
            cd = stepCooldown;
        }

        wasClose = isCloseNow;
    }

    void PlayFootstep(RaycastHit hit, string label)
    {
        PhysicsMaterial pm = hit.collider.sharedMaterial;
        AudioClip[] clips = ResolveClips(pm);

        if (clips == null || clips.Length == 0)
        {
            LogWarning($"{label}: NO CLIPS FOUND");
            return;
        }

        int index = UnityEngine.Random.Range(0, clips.Length);
        if (clips.Length > 1 && index == lastClipIndex)
            index = (index + 1) % clips.Length;
        lastClipIndex = index;

        AudioClip clip = clips[index];
        if (clip == null) { LogWarning($"{label}: NULL clip"); return; }

        audio3D.transform.position = hit.point;
        audio3D.pitch = UnityEngine.Random.Range(pitchMin, pitchMax);
        float vol = UnityEngine.Random.Range(volumeMin, volumeMax);

        audio3D.PlayOneShot(clip, vol);
    }

    AudioClip[] ResolveClips(PhysicsMaterial pm)
    {
        if (pm != null && surfaces != null)
        {
            foreach (var s in surfaces)
                if (s != null && s.physicsMaterial == pm)
                    return s.clips;
        }
        return defaultClips;
    }

    void Log(string msg)
    {
        if (!debugLogs) return;
        Debug.Log($"[Footsteps] {msg}", this.gameObject);
    }

    void LogWarning(string msg)
    {
        if (!debugLogs) return;
        Debug.LogWarning($"[Footsteps] {msg}", this.gameObject);
    }
}

