// PlayerDeathListener.cs
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerDeathListener : MonoBehaviour
{
    [SerializeField] private NetworkPlayerState ps;

    [Header("Composants à désactiver quand mort (scripts + CharacterController + PlayerInput, etc.)")]
    [SerializeField] private Behaviour[] disableWhenDead;

    [Header("Death effect (material override)")]
    [SerializeField] private Material deathEffectMaterial;

    [Tooltip("Si vide, le script prendra tous les Renderer dans les enfants au spawn.")]
    [SerializeField] private Renderer[] renderersToAffect;

    [Header("Ghost Mode")]
    [SerializeField] private GhostSoundboard ghostSoundboard;
    [SerializeField] private GhostActionboard ghostActionboard;

    [Header("Robustness")]
    [Tooltip("Ré-applique en LateUpdate pour contrer les scripts qui remettent les materials (SkinSwapper, etc.).")]
    [SerializeField] private bool enforceVisualStateEveryFrame = true;

    // Originals par renderer
    private readonly Dictionary<Renderer, Material[]> _originalSharedByRenderer = new();

    private bool _bound;
    private bool _targetAlive = true;

    private void Reset()
    {
        ps = GetComponentInParent<NetworkPlayerState>();
    }

    private void OnEnable()
    {
        if (ps == null)
            ps = GetComponentInParent<NetworkPlayerState>();

        StartCoroutine(BindWhenReady());
    }

    private void OnDisable()
    {
        Unbind();
    }

    private IEnumerator BindWhenReady()
    {
        while (isActiveAndEnabled && !_bound)
        {
            if (ps == null)
                ps = GetComponentInParent<NetworkPlayerState>();

            if (ps != null && ps.IsSpawned)
            {
                ps.Alive.OnValueChanged += OnAliveChanged;
                ps.SkinId.OnValueChanged += OnSkinChanged;

                if (ghostSoundboard == null)
                    ghostSoundboard = GetComponentInParent<GhostSoundboard>();
                if (ghostActionboard == null)
                    ghostActionboard = GetComponentInParent<GhostActionboard>();

                _bound = true;

                CollectRenderersAndCacheOriginals();
                Apply(ps.Alive.Value);

                // souvent le skin est instancié 1-2 frames après
                yield return null;
                yield return null;

                CollectRenderersAndCacheOriginals();
                Apply(ps.Alive.Value);
                yield break;
            }

            yield return null;
        }
    }

    private void Unbind()
    {
        if (!_bound) return;

        if (ps != null)
        {
            ps.Alive.OnValueChanged -= OnAliveChanged;
            ps.SkinId.OnValueChanged -= OnSkinChanged;
        }

        _bound = false;
    }

    private void OnAliveChanged(bool oldValue, bool newValue) => Apply(newValue);

    private void OnSkinChanged(int prev, int next)
    {
        // le skin swap peut recréer/remplacer des renderers
        CollectRenderersAndCacheOriginals();
        Apply(ps != null ? ps.Alive.Value : _targetAlive);
    }

    private void LateUpdate()
    {
        if (!enforceVisualStateEveryFrame) return;
        if (!_bound || ps == null) return;
        if (!ps.IsClient) return;

        var r0 = GetFirstVisibleRenderer();
        if (r0 == null) return;

        bool shouldBeGhost = !ps.Alive.Value;
        bool isGhostNow = RendererLooksGhost(r0);

        if (shouldBeGhost && !isGhostNow)
            Apply(false);
        else if (!shouldBeGhost && isGhostNow)
            Apply(true);
    }

    private Renderer GetFirstVisibleRenderer()
    {
        if (renderersToAffect == null || renderersToAffect.Length == 0)
            return null;

        for (int i = 0; i < renderersToAffect.Length; i++)
        {
            var r = renderersToAffect[i];
            if (r == null) continue;
            if (!r.gameObject.activeInHierarchy) continue;
            if (!r.enabled) continue; // IMPORTANT: ne pas réactiver ceux que le swapper a désactivés
            return r;
        }

        return null;
    }

    private bool RendererLooksGhost(Renderer r)
    {
        if (r == null) return false;
        var mats = r.sharedMaterials;
        if (mats == null || mats.Length == 0) return false;
        return deathEffectMaterial != null && ReferenceEquals(mats[0], deathEffectMaterial);
    }

    private void CollectRenderersAndCacheOriginals()
    {
        // IMPORTANT: false => ne prend pas les renderers d'objets inactifs (évite l'ancien skin)
        if (renderersToAffect == null || renderersToAffect.Length == 0)
            renderersToAffect = GetComponentsInChildren<Renderer>(false);

        if (renderersToAffect == null) return;

        for (int i = 0; i < renderersToAffect.Length; i++)
        {
            var r = renderersToAffect[i];
            if (r == null) continue;

            // Ne cache que les renderers "visibles/actifs" (évite de mémoriser des skins désactivés)
            if (!r.gameObject.activeInHierarchy) continue;

            if (!_originalSharedByRenderer.ContainsKey(r))
                _originalSharedByRenderer[r] = r.sharedMaterials;
        }
    }

    private void Apply(bool alive)
    {
        _targetAlive = alive;
        if (ps == null) return;

        // UI uniquement pour le joueur local
        if (ps.IsOwner && DeathScreenUI.Instance != null)
        {
            if (!alive) DeathScreenUI.Instance.Show();
            else DeathScreenUI.Instance.Hide();
        }

        // Désactivation des contrôles uniquement pour le joueur local
        if (ps.IsOwner && disableWhenDead != null)
        {
            for (int i = 0; i < disableWhenDead.Length; i++)
                if (disableWhenDead[i] != null)
                    disableWhenDead[i].enabled = alive;
        }

        // GhostSoundboard (owner uniquement)
        if (ps.IsOwner && ghostSoundboard != null)
            ghostSoundboard.enabled = !alive;

        // GhostActionboard (owner uniquement)
        if (ps.IsOwner && ghostActionboard != null)
            ghostActionboard.enabled = !alive;



        // Visuel sur TOUS les clients (host inclus)
        if (!ps.IsClient) return;

        CollectRenderersAndCacheOriginals();
        if (renderersToAffect == null || renderersToAffect.Length == 0) return;

        if (!alive && deathEffectMaterial != null)
        {
            for (int i = 0; i < renderersToAffect.Length; i++)
            {
                var r = renderersToAffect[i];
                if (r == null) continue;

                // IMPORTANT: ne pas réactiver les renderers désactivés par le SkinSwapper
                if (!r.gameObject.activeInHierarchy) continue;
                if (!r.enabled) continue;

                var current = r.sharedMaterials;
                if (current == null || current.Length == 0) continue;

                var overridden = new Material[current.Length];
                for (int m = 0; m < overridden.Length; m++)
                    overridden[m] = deathEffectMaterial;

                r.sharedMaterials = overridden;
            }
        }
        else
        {
            for (int i = 0; i < renderersToAffect.Length; i++)
            {
                var r = renderersToAffect[i];
                if (r == null) continue;
                if (!r.gameObject.activeInHierarchy) continue;

                if (_originalSharedByRenderer.TryGetValue(r, out var originals) && originals != null)
                    r.sharedMaterials = originals;
            }
        }
    }
}

