using System;
using System.Collections;
using System.Collections.Generic;
using Unity.Netcode;
using UnityEngine;

public class SearchableLoot : NetworkBehaviour
{
    [Serializable]
    public class LootEntry
    {
        public ItemId item;

        [Min(0f)] public float weight = 1f;

        [Header("Quantity")]
        [Min(1)] public int minQty = 1;
        [Min(1)] public int maxQty = 1;

        [Header("Inventory footprint")]
        [Min(1)] public int slotsRequired = 1; // 1=normal, 2/3 = multi-slot (RESERVED)

        [Header("Optional value (Essence/Huile)")]
        public bool usesValue = false;
        public float minValue = 0f;
        public float maxValue = 0f;
    }

    [Header("Search")]
    [Min(0.1f)] public float searchDuration = 2f;
    [Min(0.1f)] public float interactDistance = 2f;
    public Transform interactPoint;

    [Header("Roll")]
    [Tooltip("Chance relative de ne rien trouver.")]
    [Min(0f)] public float emptyWeight = 0f;

    public List<LootEntry> lootTable = new();

    [Header("State")]
    public bool oneTimeOnly = true;

    public NetworkVariable<bool> Depleted = new(
        false,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    private bool _busy;
    private ulong _busyClientId;
    private Coroutine _co;

    private Transform Point => interactPoint != null ? interactPoint : transform;

    private bool CloseEnough(Transform player)
    {
        if (player == null) return false;
        return Vector3.Distance(player.position, Point.position) <= interactDistance;
    }

    private bool TryGetPlayer(ulong clientId, out NetworkPlayerState ps, out Transform tr)
    {
        ps = null;
        tr = null;

        var nm = NetworkManager.Singleton;
        if (nm == null) return false;

        if (!nm.ConnectedClients.TryGetValue(clientId, out var client)) return false;
        var po = client.PlayerObject;
        if (po == null) return false;

        ps = po.GetComponent<NetworkPlayerState>();
        tr = po.transform;
        return ps != null;
    }

    // IMPORTANT: c'est CE NOM que ton Interactor appelle.
    [Rpc(SendTo.Server, InvokePermission = RpcInvokePermission.Everyone)]
    public void RequestSearchServerRpc(RpcParams rpcParams = default)
    {
        if (!IsServer) return;
        if (oneTimeOnly && Depleted.Value) return;

        ulong clientId = rpcParams.Receive.SenderClientId;

        if (_busy) return;

        if (!TryGetPlayer(clientId, out var ps, out var tr)) return;
        if (!ps.Alive.Value || ps.Escaped.Value) return;
        if (!CloseEnough(tr)) return;

        _busy = true;
        _busyClientId = clientId;

        if (_co != null) StopCoroutine(_co);
        _co = StartCoroutine(SearchRoutine(clientId));
    }

    private IEnumerator SearchRoutine(ulong clientId)
    {
        yield return new WaitForSeconds(Mathf.Max(0.01f, searchDuration));

        if (!IsServer)
        {
            ClearBusy();
            yield break;
        }

        // re-validate
        if (!TryGetPlayer(clientId, out var ps, out var tr) || !ps.Alive.Value || ps.Escaped.Value || !CloseEnough(tr))
        {
            ClearBusy();
            yield break;
        }

        var entry = Roll(out bool rolledNothing);

        if (rolledNothing || entry == null)
        {
            if (oneTimeOnly) Depleted.Value = true;
            ClearBusy();
            yield break;
        }

        int minQ = Mathf.Min(entry.minQty, entry.maxQty);
        int maxQ = Mathf.Max(entry.minQty, entry.maxQty);
        int qty = Mathf.Max(1, UnityEngine.Random.Range(minQ, maxQ + 1));

        float value = 0f;
        if (entry.usesValue)
        {
            float a = entry.minValue, b = entry.maxValue;
            if (b < a) (a, b) = (b, a);
            value = UnityEngine.Random.Range(a, b);
        }

        int slotsReq = Mathf.Max(1, entry.slotsRequired);

        int added = AddToInventoryServer(ps, entry.item, slotsReq, qty, entry.usesValue, value);

        // inventaire plein => on ne consomme pas (tu peux revenir plus tard)
        if (added <= 0)
        {
            ClearBusy();
            yield break;
        }

        if (oneTimeOnly) Depleted.Value = true;
        ClearBusy();
    }

    private void ClearBusy()
    {
        _busy = false;
        _busyClientId = 0;
        _co = null;
    }

    private LootEntry Roll(out bool rolledNothing)
    {
        rolledNothing = false;

        float total = Mathf.Max(0f, emptyWeight);
        for (int i = 0; i < lootTable.Count; i++)
        {
            var e = lootTable[i];
            if (e == null || e.weight <= 0f) continue;
            total += e.weight;
        }

        if (total <= 0.0001f)
        {
            rolledNothing = true;
            return null;
        }

        float r = UnityEngine.Random.value * total;

        if (emptyWeight > 0f && r < emptyWeight)
        {
            rolledNothing = true;
            return null;
        }

        r -= emptyWeight;

        for (int i = 0; i < lootTable.Count; i++)
        {
            var e = lootTable[i];
            if (e == null || e.weight <= 0f) continue;

            if (r < e.weight) return e;
            r -= e.weight;
        }

        return lootTable.Count > 0 ? lootTable[lootTable.Count - 1] : null;
    }

    private static void EnsureSizes(NetworkPlayerState ps)
    {
        if (ps == null) return;

        // On garde la taille "inventaire actuel" (chez toi c'est 3), sans grandir indéfiniment.
        int n = ps.Inventory != null ? ps.Inventory.Count : 0;
        if (n <= 0) return;

        if (ps.InventoryValue != null)
        {
            while (ps.InventoryValue.Count < n) ps.InventoryValue.Add(0f);
            while (ps.InventoryValue.Count > n) ps.InventoryValue.RemoveAt(ps.InventoryValue.Count - 1);
        }

        if (ps.InventoryCount != null)
        {
            while (ps.InventoryCount.Count < n) ps.InventoryCount.Add(0);
            while (ps.InventoryCount.Count > n) ps.InventoryCount.RemoveAt(ps.InventoryCount.Count - 1);
        }
    }

    private static bool TryFindEmptyBlock(NetworkPlayerState ps, int slotsRequired, out int startIndex)
    {
        startIndex = -1;
        if (ps == null || ps.Inventory == null) return false;

        int n = ps.Inventory.Count;
        if (slotsRequired <= 0 || slotsRequired > n) return false;

        for (int i = 0; i <= n - slotsRequired; i++)
        {
            bool ok = true;
            for (int k = 0; k < slotsRequired; k++)
            {
                if (ps.Inventory[i + k] != NetworkPlayerState.SLOT_EMPTY)
                {
                    ok = false;
                    break;
                }
            }

            if (ok)
            {
                startIndex = i;
                return true;
            }
        }

        return false;
    }

    // ✅ CORRIGÉ : stack si slotsRequired==1 via NetworkPlayerState.TryAddItemServer
    // ✅ CORRIGÉ : multi-slot écrit InventoryCount correctement
    private static int AddToInventoryServer(NetworkPlayerState ps, ItemId item, int slotsRequired, int qty, bool usesValue, float value)
    {
        if (ps == null || ps.Inventory == null) return 0;
        if (!ps.IsServer) return 0;

        qty = Mathf.Max(1, qty);
        slotsRequired = Mathf.Max(1, slotsRequired);

        EnsureSizes(ps);

        int added = 0;

        // 1) SLOT NORMAL => utiliser la logique stack du PlayerState
        if (slotsRequired == 1)
        {
            // Important: TryAddItemServer(id, amount>1) n'est pas "atomique" chez toi et
            // gère mal amount>1 pour les non-stack. Donc on ajoute 1 par 1.
            for (int j = 0; j < qty; j++)
            {
                // Si ton item est un liquide, value est utilisé (0..100)
                float v = usesValue ? value : 0f;

                // HasSpaceServerFor stack-aware (si serverItemDb est bien assignée)
                if (!ps.HasSpaceServerFor(item, 1))
                    break;

                if (!ps.TryAddItemServer(item, 1, v))
                    break;

                added++;
            }

            return added;
        }

        // 2) MULTI-SLOT => on place un "bloc vide" + RESERVED (et on remplit InventoryCount!)
        for (int j = 0; j < qty; j++)
        {
            if (!TryFindEmptyBlock(ps, slotsRequired, out int idx))
                break;

            ps.Inventory[idx] = (int)item;

            // main slot
            if (ps.InventoryCount != null) ps.InventoryCount[idx] = 1;
            if (ps.InventoryValue != null) ps.InventoryValue[idx] = usesValue ? value : 0f;

            // reserved slots
            for (int k = 1; k < slotsRequired; k++)
            {
                int s = idx + k;
                ps.Inventory[s] = NetworkPlayerState.SLOT_RESERVED;

                if (ps.InventoryCount != null) ps.InventoryCount[s] = 0;
                if (ps.InventoryValue != null) ps.InventoryValue[s] = 0f;
            }

            added++;
        }

        return added;
    }
}

