using System;
using TMPro;
using Unity.Netcode;
using Unity.Netcode.Transports.UTP;
using Unity.Services.Relay;
using Unity.Services.Relay.Models;
using UnityEngine;

public class RelayConnector : MonoBehaviour
{
    public static RelayConnector Instance { get; private set; }

    public event Action<string> JoinCodeChanged;

    [Header("References")]
    public NetworkManager networkManager;
    public UnityTransport transport;

    [Header("Scenes")]
    public string lobbySceneName = "Lobby";

    [Header("UI (optionnel - si RelayConnector est dans Bootstrap, laisse ces refs vides)")]
    public TMP_Text joinCodeText;
    public TMP_InputField joinCodeInput;

    [Header("Relay")]
    [Min(1)] public int maxConnections = 8;
    public string connectionType = "dtls"; // udp / dtls / wss

    public string LastJoinCode { get; private set; } = "";

    private void Awake()
    {
        // Singleton + persistance (Bootstrap)
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }

        Instance = this;
        DontDestroyOnLoad(gameObject);

        // ✅ Unity 6: remplace FindObjectOfType<NetworkManager>(true) (obsolète)
        if (networkManager == null)
            networkManager = UnityEngine.Object.FindFirstObjectByType<NetworkManager>(FindObjectsInactive.Include);

        if (transport == null && networkManager != null)
            transport = networkManager.GetComponent<UnityTransport>();

        if (networkManager == null) Debug.LogError("[RelayConnector] NetworkManager manquant.");
        if (transport == null) Debug.LogError("[RelayConnector] UnityTransport manquant sur le NetworkManager.");
    }

    public async void UI_StartHostWithRelay()
    {
        try
        {
            if (!EnsureReady()) return;

            Allocation allocation = await RelayService.Instance.CreateAllocationAsync(maxConnections);
            transport.SetRelayServerData(AllocationUtils.ToRelayServerData(allocation, connectionType));

            var joinCode = await RelayService.Instance.GetJoinCodeAsync(allocation.AllocationId);
            SetJoinCode(joinCode);

            bool ok = networkManager.StartHost();
            Debug.Log(ok ? $"[Relay] Host started. JoinCode={LastJoinCode}" : "[Relay] StartHost failed.");

            if (ok)
            {
                // Host charge la scène lobby et tous les clients suivront automatiquement
                if (networkManager.SceneManager != null)
                    networkManager.SceneManager.LoadScene(lobbySceneName, UnityEngine.SceneManagement.LoadSceneMode.Single);
                else
                    Debug.LogError("[Relay] SceneManager null (Enable Scene Management ?).");
            }
        }
        catch (Exception e)
        {
            Debug.LogException(e);
        }
    }

    public async void UI_StartClientWithRelay()
    {
        try
        {
            if (!EnsureReady()) return;

            string code = joinCodeInput != null ? joinCodeInput.text.Trim() : "";
            if (string.IsNullOrWhiteSpace(code))
            {
                Debug.LogWarning("[Relay] Join code vide.");
                return;
            }

            JoinAllocation allocation = await RelayService.Instance.JoinAllocationAsync(code);
            transport.SetRelayServerData(AllocationUtils.ToRelayServerData(allocation, connectionType));

            bool ok = networkManager.StartClient();
            Debug.Log(ok ? $"[Relay] Client started. JoinCode={code}" : "[Relay] StartClient failed.");
        }
        catch (Exception e)
        {
            Debug.LogException(e);
        }
    }

    public void SetJoinCode(string code)
    {
        LastJoinCode = (code ?? "").Trim();

        // Si jamais tu gardes une UI directement sur l'objet (optionnel)
        if (joinCodeText != null)
            joinCodeText.text = string.IsNullOrEmpty(LastJoinCode) ? "-" : $"CODE: {LastJoinCode}";

        JoinCodeChanged?.Invoke(LastJoinCode);
    }

    private bool EnsureReady()
    {
        if (networkManager == null || transport == null) return false;

        if (UGSBootstrap.Instance == null || !UGSBootstrap.Instance.IsReady)
        {
            Debug.LogWarning("[Relay] UGSBootstrap pas prêt (Initialize/SignIn).");
            return false;
        }

        return true;
    }
}

