using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;

public class ClientActiveSceneBinder : MonoBehaviour
{
    [Header("Fallback (si jamais le coordinator n'a pas encore rempli GameplayScene)")]
    [SerializeField] private string fallbackGameplaySceneName = "Mansion_Gameplay";

    [Tooltip("Fréquence de vérification (s)")]
    [SerializeField] private float pollInterval = 0.25f;

    private MatchLoadingCoordinator _coord;

    private void OnEnable()
    {
        StartCoroutine(BindLoop());
    }

    private IEnumerator BindLoop()
    {
        var wait = new WaitForSeconds(pollInterval);

        while (true)
        {
            if (_coord == null)
                _coord = MatchLoadingCoordinator.Instance != null
                    ? MatchLoadingCoordinator.Instance
                    : FindUtil.FindFirst<MatchLoadingCoordinator>(includeInactive: true);

            if (_coord == null)
            {
                yield return wait;
                continue;
            }

            // Tant qu'on n'est pas en Lobby, on force l'Active Scene sur la scène Gameplay (côté client aussi).
            var st = (MatchState)_coord.State.Value;
            if (st != MatchState.Lobby)
            {
                string gameplayName = _coord.GameplayScene.Value.ToString();
                if (string.IsNullOrWhiteSpace(gameplayName))
                    gameplayName = fallbackGameplaySceneName;

                if (!string.IsNullOrWhiteSpace(gameplayName))
                {
                    var sc = SceneManager.GetSceneByName(gameplayName);
                    if (sc.IsValid() && sc.isLoaded && SceneManager.GetActiveScene() != sc)
                        SceneManager.SetActiveScene(sc);
                }
            }

            yield return wait;
        }
    }
}

