using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;

public class ClientActiveSceneFromCoordinator : MonoBehaviour
{
    [Header("Priorité Active Scene")]
    [Tooltip("Si true, on force l'Active Scene sur la scène Lighting (si chargée). Sinon sur Gameplay.")]
    public bool preferLightingScene = true;

    [Min(0.05f)]
    public float pollInterval = 0.2f;

    MatchLoadingCoordinator _coord;

    void OnEnable()
    {
        StartCoroutine(Loop());
    }

    IEnumerator Loop()
    {
        var wait = new WaitForSeconds(pollInterval);

        while (true)
        {
            if (_coord == null)
                _coord = MatchLoadingCoordinator.Instance != null
                    ? MatchLoadingCoordinator.Instance
                    : FindUtil.FindFirst<MatchLoadingCoordinator>(includeInactive: true);

            if (_coord == null)
            {
                yield return wait;
                continue;
            }

            var st = (MatchState)_coord.State.Value;

            // Dès qu'on quitte le Lobby, on force l'Active Scene vers la scène qui porte tes LightingSettings.
            if (st == MatchState.Loading || st == MatchState.Running || st == MatchState.Ended)
            {
                string mapping = _coord.MappingScene.Value.ToString();
                string lighting = _coord.LightingScene.Value.ToString();
                string gameplay = _coord.GameplayScene.Value.ToString();

                if (preferLightingScene)
                {
                    if (!TrySetActiveIfLoaded(lighting))
                        TrySetActiveIfLoaded(gameplay);
                }
                else
                {
                    if (!TrySetActiveIfLoaded(gameplay))
                        TrySetActiveIfLoaded(lighting);
                }
            }

            yield return wait;
        }
    }

    static bool TrySetActiveIfLoaded(string sceneName)
    {
        if (string.IsNullOrWhiteSpace(sceneName)) return false;

        var sc = SceneManager.GetSceneByName(sceneName);
        if (!sc.IsValid() || !sc.isLoaded) return false;

        if (SceneManager.GetActiveScene() != sc)
            SceneManager.SetActiveScene(sc);

        return true;
    }
}

