public class MatchLoadingCoordinator : NetworkBehaviour
{
    public static MatchLoadingCoordinator Instance { get; private set; }

    [Header("State (réseau)")]
    public NetworkVariable<int> State = new(
        (int)MatchState.Lobby,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    public NetworkVariable<int> LoadToken = new(
        0,
