    );

    public NetworkVariable<FixedString64Bytes> ProgressHint = new(
        default,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    public NetworkVariable<double> LoadingStartServerTime = new(
        0d,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    public NetworkVariable<float> MinimumLoadingSecondsNet = new(
        0f,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    public NetworkVariable<FixedString64Bytes> MappingScene = new(
        default,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    public NetworkVariable<FixedString64Bytes> LightingScene = new(
        default,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    public NetworkVariable<FixedString64Bytes> GameplayScene = new(
        default,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    public NetworkVariable<FixedString64Bytes> PropsScene = new(
    default,
    NetworkVariableReadPermission.Everyone,
    NetworkVariableWritePermission.Server
);

    public NetworkVariable<bool> UnloadLobbyAfterStart = new(
        true,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    [Header("Config")]
    [Min(5f)] public float loadingTimeoutSeconds = 60f;

    [Tooltip("Temps de loading minimum (en secondes). Exemple: 10.")]
    [Min(0f)] public float minimumLoadingSeconds = 10f;

    [SerializeField] private string lobbySceneName = "Lobby";

    readonly HashSet<ulong> _ready = new();

    Coroutine _flowCo;
    Coroutine _tickCo;
    bool _hooked;
    bool _allScenesLoaded;

    void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }

        Instance = this;
    }

    public override void OnNetworkSpawn()
    {
        base.OnNetworkSpawn();
        if (IsServer) HookNetworkManager();
    }

    public override void OnNetworkDespawn()
    {
        if (IsServer) UnhookNetworkManager();
        StopAllServerCoroutines();
        base.OnNetworkDespawn();
    }

    // ✅ Corrige CS0114: override + appel base.OnDestroy()
    public override void OnDestroy()
    {
        // Sécurité: au moment du destroy, IsServer peut déjà être faux, donc on désabonne sans condition.
        UnhookNetworkManager();
        StopAllServerCoroutines();

        if (Instance == this) Instance = null;

        base.OnDestroy();
    }

    void HookNetworkManager()
    {
        if (_hooked) return;
        var nm = NetworkManager.Singleton;
        if (nm == null) return;

        nm.OnClientDisconnectCallback += OnClientDisconnected;
        _hooked = true;
    }

    void UnhookNetworkManager()
    {
        if (!_hooked) return;
        var nm = NetworkManager.Singleton;
        if (nm != null) nm.OnClientDisconnectCallback -= OnClientDisconnected;
        _hooked = false;
    }

    void StopAllServerCoroutines()
    {
        if (_flowCo != null) { StopCoroutine(_flowCo); _flowCo = null; }
        if (_tickCo != null) { StopCoroutine(_tickCo); _tickCo = null; }
    }

    void OnClientDisconnected(ulong clientId)
    {
        if (!IsServer) return;

        if (_ready.Remove(clientId))
            ReadyPlayers.Value = _ready.Count;

        var nm = NetworkManager.Singleton;
        if (nm != null && nm.IsListening)
            ExpectedPlayers.Value = nm.ConnectedClientsIds.Count;
    }

    // Host: appelle ça AVANT de commencer à charger les scènes additifs
    public void BeginLoadingServer(string mapping, string lighting, string gameplay, string props, bool unloadLobbyAfterStart)
    {
        if (!IsServer) return;

        var nm = NetworkManager.Singleton;
        if (nm == null || !nm.IsListening) return;

        State.Value = (int)MatchState.Loading;
        LoadToken.Value = LoadToken.Value + 1;

        _ready.Clear();
        ReadyPlayers.Value = 0;
        ExpectedPlayers.Value = nm.ConnectedClientsIds.Count;

        MappingScene.Value = new FixedString64Bytes(mapping ?? "");
        LightingScene.Value = new FixedString64Bytes(lighting ?? "");
        GameplayScene.Value = new FixedString64Bytes(gameplay ?? "");
        PropsScene.Value = new FixedString64Bytes(props ?? "");

        UnloadLobbyAfterStart.Value = unloadLobbyAfterStart;

        LoadedScenes.Value = 0;
        _allScenesLoaded = false;

        LoadingStartServerTime.Value = nm.ServerTime.Time;
        MinimumLoadingSecondsNet.Value = Mathf.Max(0f, minimumLoadingSeconds);

        ProgressHint.Value = new FixedString64Bytes("Chargement des scènes...");
        Progress01.Value = 0f;

        StopAllServerCoroutines();

        // tick UI (progress honnête)
        _tickCo = StartCoroutine(TickProgressServer(LoadToken.Value));
    }

    // Host: appelle ça à chaque scene load complete (mapping/lighting/gameplay)
    public void NotifyOneSceneLoadedServer(string sceneName)
    {
        if (!IsServer) return;
        if ((MatchState)State.Value != MatchState.Loading) return;

        LoadedScenes.Value = Mathf.Clamp(LoadedScenes.Value + 1, 0, 3);

        if (!string.IsNullOrEmpty(sceneName))
            ProgressHint.Value = new FixedString64Bytes($"Scène chargée: {sceneName}");
    }

    // Host: appelle ça quand les 3 scènes ont fini de se charger via Netcode SceneManager
    public void NotifyScenesLoadedServer()
    {
        if (!IsServer) return;
        if ((MatchState)State.Value != MatchState.Loading) return;

        _allScenesLoaded = true;
        ProgressHint.Value = new FixedString64Bytes("Synchronisation joueurs...");

        // Lance le flow serveur (prepare -> wait ready -> wait min -> start)
        if (_flowCo != null) { StopCoroutine(_flowCo); _flowCo = null; }
        _flowCo = StartCoroutine(FlowServer(LoadToken.Value));
    }

    IEnumerator TickProgressServer(int token)
    {
        // Tick régulier pour rendre l'étape "Attente minimum" fluide
        var wait = new WaitForSeconds(0.1f);

        while (true)
        {
            if (!IsServer) yield break;
            if ((MatchState)State.Value != MatchState.Loading) yield break;
            if (LoadToken.Value != token) yield break;

            UpdateExpectedCountServer();
            UpdateProgressHonestServer();

            yield return wait;
        }
    }

    void UpdateExpectedCountServer()
    {
        var nm = NetworkManager.Singleton;
        if (nm == null || !nm.IsListening) return;

        int expected = nm.ConnectedClientsIds.Count;
        ExpectedPlayers.Value = expected;

        _ready.RemoveWhere(id => !IsStillConnected(nm, id));
        ReadyPlayers.Value = _ready.Count;
    }

    void UpdateProgressHonestServer()
    {
        // Progression honnête par étapes:
        // 0.00 -> 0.60 : scènes (0/3 -> 3/3)
        // 0.60 -> 0.90 : joueurs prêts (x/y)
        // 0.90 -> 1.00 : attente minimum (temps)
        // 1.00 : Running

        var nm = NetworkManager.Singleton;

        int loaded = Mathf.Clamp(LoadedScenes.Value, 0, 3);
        float scenes01 = loaded / 3f;

        int expected = Mathf.Max(0, ExpectedPlayers.Value);
        int ready = Mathf.Clamp(ReadyPlayers.Value, 0, expected);
        bool allReady = expected > 0 && ready >= expected;

        float p;

        if (loaded < 3)
        {
            ProgressHint.Value = new FixedString64Bytes("Chargement des scènes...");
            p = Mathf.Lerp(0.00f, 0.60f, scenes01);
            p = Mathf.Min(p, 0.59f);
        }
        else if (!_allScenesLoaded)
        {
            // sécurité: si LoadedScenes==3 mais NotifyScenesLoadedServer pas encore appelé
            ProgressHint.Value = new FixedString64Bytes("Finalisation scènes...");
            p = 0.60f;
        }
        else if (!allReady)
        {
            ProgressHint.Value = new FixedString64Bytes("Synchronisation joueurs...");
            float r01 = expected > 0 ? (ready / (float)expected) : 0f;
            p = Mathf.Lerp(0.60f, 0.90f, r01);
            p = Mathf.Min(p, 0.89f);
        }
        else
        {
            // Tous prêts -> on remplit uniquement selon le temps minimum restant (honnête)
            float min = Mathf.Max(0f, MinimumLoadingSecondsNet.Value);

            if (min <= 0.001f || nm == null || !nm.IsListening)
            {
                ProgressHint.Value = new FixedString64Bytes("Démarrage...");
                p = 0.99f;
            }
            else
            {
                double start = LoadingStartServerTime.Value;
                double now = nm.ServerTime.Time;

                double endMin = start + min;
                if (now >= endMin)
                {
                    ProgressHint.Value = new FixedString64Bytes("Démarrage...");
                    p = 0.99f;
                }
                else
                {
                    ProgressHint.Value = new FixedString64Bytes("Attente minimum...");
                    float t = Mathf.Clamp01((float)((now - start) / min));
                    p = Mathf.Lerp(0.90f, 0.99f, t);
                }
            }
        }

        Progress01.Value = Mathf.Clamp01(p);
    }

    IEnumerator FlowServer(int token)
    {
        // 1) attendre NetworkGameController (dans xx_gameplay) + préparer match
        NetworkGameController gc = null;
        float t0 = Time.realtimeSinceStartup;

        while (true)
        {
            if (!IsServer) yield break;
            if ((MatchState)State.Value != MatchState.Loading) yield break;
            if (LoadToken.Value != token) yield break;

            gc = NetworkGameController.Instance != null
                ? NetworkGameController.Instance
                : FindUtil.FindFirst<NetworkGameController>(includeInactive: true);

            if (gc != null && gc.IsSpawned && gc.IsServer)
                break;

            if (Time.realtimeSinceStartup - t0 > 10f)
            {
                t0 = Time.realtimeSinceStartup;
                Debug.LogWarning("[LoadingCoordinator] NetworkGameController introuvable (attente)...");
            }

            yield return null;
        }

        // important: ne pas supprimer tes méthodes => on appelle seulement celles qui existent déjà chez toi
        gc.State.Value = (int)MatchState.Loading;
        gc.GameStarted.Value = false;
        gc.PrepareMatchServer();

        // 2) attendre tous prêts + timeout
        float startWait = Time.realtimeSinceStartup;

        while (true)
        {
            if (!IsServer) yield break;
            if ((MatchState)State.Value != MatchState.Loading) yield break;
            if (LoadToken.Value != token) yield break;

            UpdateExpectedCountServer();

            int expected = Mathf.Max(0, ExpectedPlayers.Value);
            bool allReady = expected > 0 && ReadyPlayers.Value >= expected;

            if (allReady)
                break;

            if (Time.realtimeSinceStartup - startWait >= Mathf.Max(5f, loadingTimeoutSeconds))
            {
                Debug.LogWarning($"[LoadingCoordinator] Timeout {loadingTimeoutSeconds}s -> start forcé. ready={ReadyPlayers.Value}/{expected}");
                break;
            }

            yield return null;
        }

        // 3) attendre la durée minimum (si pas déjà dépassée)
        var nm = NetworkManager.Singleton;
        if (nm != null && nm.IsListening)
        {
            double start = LoadingStartServerTime.Value;
            double endMin = start + Mathf.Max(0f, MinimumLoadingSecondsNet.Value);

            while (nm.ServerTime.Time < endMin)
            {
                if (!IsServer) yield break;
                if ((MatchState)State.Value != MatchState.Loading) yield break;
                if (LoadToken.Value != token) yield break;

                yield return null;
            }
        }

        // 4) start match
        gc.StartMatchServer();

        State.Value = (int)MatchState.Running;
        Progress01.Value = 1f;
        ProgressHint.Value = new FixedString64Bytes("En jeu");

        if (UnloadLobbyAfterStart.Value)
            TryUnloadLobbyNetcode();

        // stop tick
        StopAllServerCoroutines();
    }

    bool IsStillConnected(NetworkManager nm, ulong clientId)
    {
        if (nm == null) return false;
        var ids = nm.ConnectedClientsIds;
        for (int i = 0; i < ids.Count; i++)
            if (ids[i] == clientId) return true;
        return false;
    }

    void TryUnloadLobbyNetcode()
    {
        var nm = NetworkManager.Singleton;
        if (nm == null || nm.SceneManager == null) return;

        var lobby = SceneManager.GetSceneByName(lobbySceneName);
        if (!lobby.IsValid() || !lobby.isLoaded) return;

        nm.SceneManager.UnloadScene(lobby);
    }

    // ✅ Remplace [ServerRpc(RequireOwnership = false)] (obsolète)
    [Rpc(SendTo.Server, InvokePermission = RpcInvokePermission.Everyone)]
    public void ReportClientReadyServerRpc(int token, RpcParams rpcParams = default)
    {
        if (!IsServer) return;
        if ((MatchState)State.Value != MatchState.Loading) return;
        if (LoadToken.Value != token) return;

        var nm = NetworkManager.Singleton;
        if (nm == null || !nm.IsListening) return;

        ulong sender = rpcParams.Receive.SenderClientId;
        if (!_ready.Add(sender)) return;

        ReadyPlayers.Value = _ready.Count;
    }
}

