// LoadingScreenUI.cs
using TMPro;
using UnityEngine;
using UnityEngine.UI;

public class LoadingScreenUI : MonoBehaviour
{
    [Header("UI")]
    [SerializeField] private CanvasGroup root;
    [SerializeField] private TMP_Text titleText;
    [SerializeField] private TMP_Text detailText;
    [SerializeField] private Slider progressBar;

    [Header("Text")]
    [SerializeField] private string loadingTitle = "Chargement...";
    [SerializeField] private string syncingTitle = "Synchronisation...";

    MatchLoadingCoordinator _lc;

    void Awake()
    {
        if (root == null) root = GetComponentInChildren<CanvasGroup>(true);
        ApplyVisible(false);
    }

    void Update()
    {
        if (_lc == null)
            _lc = MatchLoadingCoordinator.Instance != null ? MatchLoadingCoordinator.Instance : FindUtil.FindFirst<MatchLoadingCoordinator>(includeInactive: true);

        if (_lc == null)
        {
            ApplyVisible(false);
            return;
        }

        bool show = (MatchState)_lc.State.Value == MatchState.Loading;
        ApplyVisible(show);

        if (!show) return;

        int expected = Mathf.Max(0, _lc.ExpectedPlayers.Value);
        int ready = Mathf.Clamp(_lc.ReadyPlayers.Value, 0, expected > 0 ? expected : int.MaxValue);

        if (titleText != null)
            titleText.text = (ready < expected) ? loadingTitle : syncingTitle;

        string mapping = _lc.MappingScene.Value.ToString();
        string lighting = _lc.LightingScene.Value.ToString();
        string gameplay = _lc.GameplayScene.Value.ToString();

        if (detailText != null)
        {
            string playersLine = expected > 0 ? $"Joueurs prêts: {ready}/{expected}" : "Joueurs prêts: ...";
            string scenesLine = $"Scènes: {mapping}, {lighting}, {gameplay}";
            detailText.text = playersLine + "\n" + scenesLine;
        }

        if (progressBar != null)
        {
            float v = (expected <= 0) ? 0f : (ready / (float)expected);
            progressBar.value = Mathf.Clamp01(v);
        }
    }

    void ApplyVisible(bool show)
    {
        if (root == null) return;
        root.alpha = show ? 1f : 0f;
        root.interactable = show;
        root.blocksRaycasts = show;
    }
}

