using TMPro;
using UnityEngine;

public class InviteCodeUI : MonoBehaviour
{
    [SerializeField] private TMP_Text inviteCodeText;

    private void Awake()
    {
        if (inviteCodeText == null)
            inviteCodeText = GetComponentInChildren<TMP_Text>(true);
    }

    private void OnEnable()
    {
        Bind();
    }

    private void OnDisable()
    {
        if (RelayConnector.Instance != null)
            RelayConnector.Instance.JoinCodeChanged -= OnJoinCodeChanged;
    }

    private void Bind()
    {
        var relay = RelayConnector.Instance;
        if (relay == null)
        {
            // Bootstrap pas encore prêt (rare), on laisse "-"
            if (inviteCodeText != null) inviteCodeText.text = "CODE: -";
            return;
        }

        relay.JoinCodeChanged -= OnJoinCodeChanged;
        relay.JoinCodeChanged += OnJoinCodeChanged;

        // Affiche le code déjà existant (si Host l'a déjà généré)
        OnJoinCodeChanged(relay.LastJoinCode);
    }

    private void OnJoinCodeChanged(string code)
    {
        if (inviteCodeText == null) return;

        inviteCodeText.text = string.IsNullOrEmpty(code)
            ? "CODE: -"
            : $"CODE: {code}";
    }
}

