using TMPro;
using Unity.Netcode;
using UnityEngine;
using UnityEngine.UI;

public class LobbyMySkinPickerUI : MonoBehaviour
{
    [System.Serializable]
    public class SlotPicker
    {
        public GameObject root;  // Slot_X/SkinPicker
        public Button left;
        public Button right;
        public TMP_Text label;   // Txt_SkinName (optionnel)
    }

    [Header("Database")]
    public SkinDatabase skinDb;

    [Header("Pickers (size 8)")]
    public SlotPicker[] pickers = new SlotPicker[8];

    private int _mySlot = -1;
    private int _mySkinId = 0;

    private void OnEnable()
    {
        Bind();
        Refresh();
    }

    private void OnDisable()
    {
        UnbindButtons();

        if (LobbyState.Instance != null && LobbyState.Instance.Players != null)
            LobbyState.Instance.Players.OnListChanged -= OnPlayersChanged;
    }

    private void Bind()
    {
        if (LobbyState.Instance != null && LobbyState.Instance.Players != null)
        {
            LobbyState.Instance.Players.OnListChanged -= OnPlayersChanged;
            LobbyState.Instance.Players.OnListChanged += OnPlayersChanged;
        }
    }

    private void OnPlayersChanged(NetworkListEvent<LobbyPlayerData> _)
    {
        Refresh();
    }

    private void Refresh()
    {
        if (NetworkManager.Singleton == null || !NetworkManager.Singleton.IsClient || LobbyState.Instance == null)
        {
            HideAll();
            return;
        }

        ulong me = NetworkManager.Singleton.LocalClientId;

        _mySlot = -1;
        _mySkinId = 0;

        var list = LobbyState.Instance.Players;
        for (int i = 0; i < list.Count; i++)
        {
            if (list[i].ClientId == me)
            {
                _mySlot = list[i].SlotIndex;
                _mySkinId = list[i].SkinId;
                break;
            }
        }

        // Visibilité: uniquement MON picker localement
        for (int i = 0; i < pickers.Length; i++)
        {
            if (pickers[i] == null || pickers[i].root == null) continue;
            pickers[i].root.SetActive(i == _mySlot);
        }

        // Rebind boutons uniquement sur mon picker
        UnbindButtons();

        if (_mySlot >= 0 && _mySlot < pickers.Length && pickers[_mySlot] != null)
        {
            var p = pickers[_mySlot];
            if (p.left != null) p.left.onClick.AddListener(Prev);
            if (p.right != null) p.right.onClick.AddListener(Next);
            UpdateLabel();
        }
    }

    private void HideAll()
    {
        for (int i = 0; i < pickers.Length; i++)
            if (pickers[i] != null && pickers[i].root != null)
                pickers[i].root.SetActive(false);
    }

    private void UnbindButtons()
    {
        for (int i = 0; i < pickers.Length; i++)
        {
            if (pickers[i] == null) continue;
            if (pickers[i].left != null) pickers[i].left.onClick.RemoveListener(Prev);
            if (pickers[i].right != null) pickers[i].right.onClick.RemoveListener(Next);
        }
    }

    private int DbCount()
    {
        return (skinDb != null && skinDb.skins != null) ? skinDb.skins.Length : 0;
    }

    private int WrapIndex(int idx)
    {
        int n = DbCount();
        if (n <= 0) return 0;
        idx %= n;
        if (idx < 0) idx += n;
        return idx;
    }

    private int CurrentIndexFromId(int id)
    {
        if (skinDb == null || skinDb.skins == null) return 0;
        for (int i = 0; i < skinDb.skins.Length; i++)
            if (skinDb.skins[i].id == id) return i;
        return 0;
    }

    private void Prev()
    {
        if (LobbyState.Instance == null || !NetworkManager.Singleton.IsClient) return;

        int n = DbCount();
        if (n <= 0) return;

        int idx = CurrentIndexFromId(_mySkinId);
        idx = WrapIndex(idx - 1);

        _mySkinId = skinDb.skins[idx].id;
        LobbyState.Instance.SetSkinServerRpc(_mySkinId);
        UpdateLabel();
    }

    private void Next()
    {
        if (LobbyState.Instance == null || !NetworkManager.Singleton.IsClient) return;

        int n = DbCount();
        if (n <= 0) return;

        int idx = CurrentIndexFromId(_mySkinId);
        idx = WrapIndex(idx + 1);

        _mySkinId = skinDb.skins[idx].id;
        LobbyState.Instance.SetSkinServerRpc(_mySkinId);
        UpdateLabel();
    }

    private void UpdateLabel()
    {
        if (_mySlot < 0 || _mySlot >= pickers.Length) return;
        var p = pickers[_mySlot];
        if (p == null || p.label == null) return;

        string name = $"Skin {_mySkinId}";
        if (skinDb != null)
        {
            var prefab = skinDb.Get(_mySkinId);
            if (prefab != null) name = prefab.name;
        }

        p.label.text = name;
    }
}

