using Unity.Netcode;
using UnityEngine;

public class LobbySkinStandPreview : MonoBehaviour
{
    [Header("Database")]
    public SkinDatabase skinDb;

    [Header("Stands")]
    public Transform[] standRoots = new Transform[8];

    [Header("Preview Animation")]
    public RuntimeAnimatorController previewController;
    public bool alwaysAnimate = true;

    private GameObject[] _spawned = new GameObject[8];
    private int[] _lastSkinId = new int[8];

    private void Awake()
    {
        for (int i = 0; i < _lastSkinId.Length; i++)
            _lastSkinId[i] = int.MinValue;
    }

    private void OnEnable()
    {
        if (LobbyState.Instance != null && LobbyState.Instance.Players != null)
            LobbyState.Instance.Players.OnListChanged += OnPlayersChanged;

        Refresh();
    }

    private void OnDisable()
    {
        if (LobbyState.Instance != null && LobbyState.Instance.Players != null)
            LobbyState.Instance.Players.OnListChanged -= OnPlayersChanged;
    }

    private void OnPlayersChanged(NetworkListEvent<LobbyPlayerData> _)
    {
        Refresh();
    }

    private void Refresh()
    {
        bool[] occupied = new bool[8];

        var ls = LobbyState.Instance;
        if (ls != null && ls.Players != null)
        {
            var list = ls.Players;

            for (int i = 0; i < list.Count; i++)
            {
                int slot = list[i].SlotIndex;
                if (slot < 0 || slot >= 8) continue;

                occupied[slot] = true;

                int skinId = list[i].SkinId;

                if (_lastSkinId[slot] != skinId)
                {
                    ClearSlot(slot);
                    SpawnSlot(slot, skinId);
                    _lastSkinId[slot] = skinId;
                }
            }
        }

        for (int s = 0; s < 8; s++)
        {
            if (!occupied[s])
            {
                ClearSlot(s);
                _lastSkinId[s] = int.MinValue;
            }
        }
    }

    private void SpawnSlot(int slot, int skinId)
    {
        if (skinDb == null) return;
        if (standRoots == null || slot >= standRoots.Length) return;

        var root = standRoots[slot];
        if (root == null) return;

        var prefab = skinDb.Get(skinId);
        if (prefab == null) return;

        var go = Instantiate(prefab, root);
        go.transform.localPosition = Vector3.zero;
        go.transform.localRotation = Quaternion.identity;
        go.transform.localScale = Vector3.one;

        SetupPreviewAnimator(go);

        _spawned[slot] = go;
    }

    private void SetupPreviewAnimator(GameObject go)
    {
        var anim = go.GetComponentInChildren<Animator>(true);
        if (anim == null) return;

        if (previewController != null)
            anim.runtimeAnimatorController = previewController;

        if (alwaysAnimate)
            anim.cullingMode = AnimatorCullingMode.AlwaysAnimate;

        anim.Rebind();
        anim.Update(0f);
    }

    private void ClearSlot(int slot)
    {
        if (_spawned[slot] != null)
        {
            Destroy(_spawned[slot]);
            _spawned[slot] = null;
        }
    }
}

