using TMPro;
using UnityEngine;

public class LobbySlotsUI : MonoBehaviour
{
    [System.Serializable]
    public class Slot
    {
        public GameObject root;   // Slot_0 etc
        public TMP_Text label;    // "Joueur X" / "Vide"
    }

    [Header("Fixed slots (size 8)")]
    public Slot[] slots = new Slot[8];

    [Header("Config")]
    public LobbyConfig config;
    public bool hideUnusedSlotsBeyondMax = true;   // cache slot 5..8 si maxPlayers=4
    public bool hideEmptySlots = false;            // cache les vides (si tu veux)

    void OnEnable()
    {
        TryBind();
        Refresh();
    }

    void OnDisable()
    {
        if (LobbyState.Instance != null)
            LobbyState.Instance.Players.OnListChanged -= OnPlayersChanged;
    }

    void TryBind()
    {
        if (LobbyState.Instance == null) return;

        LobbyState.Instance.Players.OnListChanged -= OnPlayersChanged;
        LobbyState.Instance.Players.OnListChanged += OnPlayersChanged;
    }

    void OnPlayersChanged(Unity.Netcode.NetworkListEvent<LobbyPlayerData> _)
    {
        Refresh();
    }

    public void Refresh()
    {
        int maxPlayers = config != null ? Mathf.Clamp(config.maxPlayers, 4, 8) : 4;

        // 1) Reset visuel
        for (int i = 0; i < slots.Length; i++)
        {
            if (slots[i].root == null) continue;

            bool inRange = i < maxPlayers;
            if (hideUnusedSlotsBeyondMax && !inRange)
            {
                slots[i].root.SetActive(false);
                continue;
            }

            slots[i].root.SetActive(true);

            if (slots[i].label != null)
                slots[i].label.text = $"Vide ({i + 1})";
        }

        if (LobbyState.Instance == null) return;

        // 2) Remplir les occupés
        var list = LobbyState.Instance.Players;
        for (int i = 0; i < list.Count; i++)
        {
            int slotIndex = list[i].SlotIndex;
            if (slotIndex < 0 || slotIndex >= slots.Length) continue;

            if (slots[slotIndex].label != null)
                slots[slotIndex].label.text = $"Joueur {list[i].PlayerNumber}";

            if (hideEmptySlots && slots[slotIndex].root != null)
                slots[slotIndex].root.SetActive(true);
        }

        // 3) Si hideEmptySlots = true, on cache ceux restés vides (dans la limite max)
        if (hideEmptySlots)
        {
            for (int i = 0; i < Mathf.Min(maxPlayers, slots.Length); i++)
            {
                bool occupied = false;
                for (int j = 0; j < list.Count; j++)
                    if (list[j].SlotIndex == i) { occupied = true; break; }

                if (!occupied && slots[i].root != null)
                    slots[i].root.SetActive(false);
            }
        }
    }
}

