using System;
using Unity.Netcode;
using UnityEngine;

public struct LobbyPlayerData : INetworkSerializable, IEquatable<LobbyPlayerData>
{
    public ulong ClientId;
    public int SlotIndex;     // 0..7
    public int PlayerNumber;  // 1..8
    public int SkinId;

    public void NetworkSerialize<T>(BufferSerializer<T> serializer) where T : IReaderWriter
    {
        serializer.SerializeValue(ref ClientId);
        serializer.SerializeValue(ref SlotIndex);
        serializer.SerializeValue(ref PlayerNumber);
        serializer.SerializeValue(ref SkinId);
    }

    public bool Equals(LobbyPlayerData other) =>
        ClientId == other.ClientId &&
        SlotIndex == other.SlotIndex &&
        PlayerNumber == other.PlayerNumber &&
        SkinId == other.SkinId;
}

public class LobbyState : NetworkBehaviour
{
    public static LobbyState Instance { get; private set; }

    [Header("Config")]
    public LobbyConfig config;

    public NetworkList<LobbyPlayerData> Players;

    // Server-only occupancy (stable slots)
    private bool[] _occupied;

    private int MaxPlayers => config != null ? Mathf.Clamp(config.maxPlayers, 4, 8) : 4;

    private void Awake()
    {
        Instance = this;
        Players = new NetworkList<LobbyPlayerData>();
        _occupied = new bool[8];
    }

    public override void OnDestroy()
    {
        if (Instance == this) Instance = null;

        if (Players != null)
        {
            Players.Dispose();
            Players = null;
        }

        base.OnDestroy();
    }

    public override void OnNetworkSpawn()
    {
        base.OnNetworkSpawn();

        if (NetworkManager != null)
        {
            NetworkManager.OnClientConnectedCallback += OnClientConnected;
            NetworkManager.OnClientDisconnectCallback += OnClientDisconnected;
        }

        if (IsServer)
            TryAssignHostSlot();
    }

    public override void OnNetworkDespawn()
    {
        if (NetworkManager != null)
        {
            NetworkManager.OnClientConnectedCallback -= OnClientConnected;
            NetworkManager.OnClientDisconnectCallback -= OnClientDisconnected;
        }

        base.OnNetworkDespawn();
    }

    private void TryAssignHostSlot()
    {
        if (!IsServer) return;

        ulong hostId = NetworkManager.ServerClientId;
        if (!HasClient(hostId))
            AddClientToSlot(hostId, 0);
    }

    private void OnClientConnected(ulong clientId)
    {
        if (!IsServer) return;

        if (NetworkManager.ConnectedClientsIds.Count > MaxPlayers)
        {
            NetworkManager.DisconnectClient(clientId);
            return;
        }

        if (clientId == NetworkManager.ServerClientId)
        {
            if (!HasClient(clientId))
                AddClientToSlot(clientId, 0);
            return;
        }

        if (HasClient(clientId)) return;

        int slot = FindFirstFreeSlot(startIndex: 1, endExclusive: MaxPlayers);
        if (slot < 0)
        {
            NetworkManager.DisconnectClient(clientId);
            return;
        }

        AddClientToSlot(clientId, slot);
    }

    private void OnClientDisconnected(ulong clientId)
    {
        if (!IsServer) return;
        RemoveClient(clientId);
    }

    private int FindFirstFreeSlot(int startIndex, int endExclusive)
    {
        startIndex = Mathf.Clamp(startIndex, 0, 8);
        endExclusive = Mathf.Clamp(endExclusive, 0, 8);

        for (int i = startIndex; i < endExclusive; i++)
            if (!_occupied[i]) return i;

        return -1;
    }

    private bool HasClient(ulong clientId)
    {
        for (int i = 0; i < Players.Count; i++)
            if (Players[i].ClientId == clientId) return true;
        return false;
    }

    private void AddClientToSlot(ulong clientId, int slotIndex)
    {
        slotIndex = Mathf.Clamp(slotIndex, 0, 7);

        _occupied[slotIndex] = true;

        Players.Add(new LobbyPlayerData
        {
            ClientId = clientId,
            SlotIndex = slotIndex,
            PlayerNumber = slotIndex + 1,
            SkinId = 0
        });

        SkinSelectionCache.ServerSet(clientId, 0);
        Debug.Log($"[LobbyState][SERVER] Add client={clientId} slot={slotIndex} skin=0");
    }

    private void RemoveClient(ulong clientId)
    {
        bool removed = false;

        for (int i = Players.Count - 1; i >= 0; i--)
        {
            if (Players[i].ClientId == clientId)
            {
                int slot = Players[i].SlotIndex;
                if (slot >= 0 && slot < _occupied.Length) _occupied[slot] = false;

                Players.RemoveAt(i);
                removed = true;
                break;
            }
        }

        SkinSelectionCache.ServerClear(clientId);
        Debug.Log($"[LobbyState][SERVER] Remove client={clientId} removed={removed}");
    }

    // ✅ Remplace [ServerRpc(RequireOwnership = false)] (obsolète)
    [Rpc(SendTo.Server, InvokePermission = RpcInvokePermission.Everyone)]
    public void SetSkinServerRpc(int skinId, RpcParams rpcParams = default)
    {
        if (!IsServer) return;

        if (skinId < 0) skinId = 0;

        ulong sender = rpcParams.Receive.SenderClientId;

        bool found = false;
        for (int i = 0; i < Players.Count; i++)
        {
            var p = Players[i];
            if (p.ClientId != sender) continue;

            p.SkinId = skinId;
            Players[i] = p;
            found = true;
            break;
        }

        SkinSelectionCache.ServerSet(sender, skinId);

        Debug.Log($"[LobbyState][SERVER] SetSkin client={sender} skinId={skinId} listFound={found}");

        // Si le PlayerObject existe déjà: applique direct
        if (NetworkManager != null &&
            NetworkManager.ConnectedClients != null &&
            NetworkManager.ConnectedClients.TryGetValue(sender, out var client) &&
            client.PlayerObject != null)
        {
            var st = client.PlayerObject.GetComponent<NetworkPlayerState>();
            if (st != null)
            {
                st.SkinId.Value = skinId;
                Debug.Log($"[LobbyState][SERVER] Applied to PlayerObject client={sender} skinId={skinId}");
            }
        }
    }

    public bool TryGetSkin(ulong clientId, out int skinId)
    {
        skinId = 0;
        for (int i = 0; i < Players.Count; i++)
        {
            if (Players[i].ClientId == clientId)
            {
                skinId = Players[i].SkinId;
                return true;
            }
        }
        return false;
    }
}

