// StartGameButton.cs
using System.Collections.Generic;
using Unity.Netcode;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

[RequireComponent(typeof(Button))]
public class StartGameButton : MonoBehaviour
{
    [Header("Map database (3 scènes additifs)")]
    [SerializeField] private MapDatabase mapDb;

    [Tooltip("Index de la map dans MapDatabase (chez toi: 0)")]
    [SerializeField] private int mapIndex = 0;

    [Header("Options")]
    [SerializeField] private bool unloadLobbyAfterLoad = true;

    private Button _btn;
    private CanvasGroup _cg;

    private readonly Queue<string> _queue = new Queue<string>();
    private readonly HashSet<string> _expected = new HashSet<string>();

    private string _gameplaySceneName;
    private bool _loading;

    private MatchLoadingCoordinator _coord;

    private void Awake()
    {
        _btn = GetComponent<Button>();

        _cg = GetComponent<CanvasGroup>();
        if (_cg == null) _cg = gameObject.AddComponent<CanvasGroup>();

        ApplyVisible(false);
    }

    private void Update()
    {
        var nm = NetworkManager.Singleton;
        bool show = nm != null && nm.IsListening && nm.IsHost;
        ApplyVisible(show);
    }

    private void ApplyVisible(bool show)
    {
        _cg.alpha = show ? 1f : 0f;
        _cg.interactable = show;
        _cg.blocksRaycasts = show;
    }

    public void Click()
    {
        var nm = NetworkManager.Singleton;
        if (nm == null) { Debug.LogError("[StartGame] NetworkManager null"); return; }
        if (!nm.IsListening || !nm.IsHost) { Debug.LogWarning("[StartGame] Not host/listening"); return; }
        if (nm.SceneManager == null) { Debug.LogError("[StartGame] SceneManagement Netcode désactivé (Enable Scene Management)."); return; }

        if (mapDb == null || mapDb.maps == null || mapDb.maps.Length == 0)
        {
            Debug.LogError("[StartGame] MapDatabase vide ou manquant.");
            return;
        }

        if (mapIndex < 0 || mapIndex >= mapDb.maps.Length || mapDb.maps[mapIndex] == null)
        {
            Debug.LogError($"[StartGame] mapIndex invalide: {mapIndex}");
            return;
        }

        var entry = mapDb.maps[mapIndex];

        _queue.Clear();
        _expected.Clear();

        _expected.Add(entry.mappingScene);
        _expected.Add(entry.lightingScene);
        _expected.Add(entry.gameplayScene);
        _expected.Add(entry.propsScene);

        _queue.Enqueue(entry.mappingScene);
        _queue.Enqueue(entry.lightingScene);
        _queue.Enqueue(entry.gameplayScene);
        _queue.Enqueue(entry.propsScene);

        _gameplaySceneName = entry.gameplayScene;
        _loading = true;

        _coord = MatchLoadingCoordinator.Instance != null
            ? MatchLoadingCoordinator.Instance
            : FindUtil.FindFirst<MatchLoadingCoordinator>(includeInactive: true);

        if (_coord == null || !_coord.IsSpawned || !_coord.IsServer)
        {
            Debug.LogError("[StartGame] MatchLoadingCoordinator introuvable ou non spawn côté host.");
            _loading = false;
            return;
        }

        _coord.BeginLoadingServer(entry.mappingScene, entry.lightingScene, entry.gameplayScene, entry.propsScene, unloadLobbyAfterLoad);

        Debug.Log($"[StartGame] Loading map '{entry.displayName}' SEQ: " +
                  $"{entry.mappingScene} -> {entry.lightingScene} -> {entry.gameplayScene}");

        nm.SceneManager.OnLoadEventCompleted -= OnLoadEventCompleted;
        nm.SceneManager.OnLoadEventCompleted += OnLoadEventCompleted;

        LoadNext();
    }

    private void LoadNext()
    {
        var nm = NetworkManager.Singleton;
        if (nm == null || nm.SceneManager == null) return;

        while (_queue.Count > 0)
        {
            var next = _queue.Peek();

            var sc = SceneManager.GetSceneByName(next);
            if (sc.IsValid() && sc.isLoaded)
            {
                Debug.Log($"[StartGame] Already loaded, skip: {next}");
                _queue.Dequeue();

                // progress scene déjà chargée
                if (_coord != null && _coord.IsServer) _coord.NotifyOneSceneLoadedServer(next);
                continue;
            }

            Debug.Log($"[StartGame] LoadScene(Additive) => {next}");
            nm.SceneManager.LoadScene(next, LoadSceneMode.Additive);
            return;
        }

        FinalizeLoad();
    }

    private void OnLoadEventCompleted(string sceneName, LoadSceneMode mode,
        List<ulong> clientsCompleted, List<ulong> clientsTimedOut)
    {
        if (!_loading) return;
        if (!_expected.Contains(sceneName)) return;

        Debug.Log($"[StartGame] Loaded scene={sceneName} clientsCompleted={clientsCompleted.Count} timedOut={clientsTimedOut.Count}");

        // Compte la progression "scènes"
        if (_coord != null && _coord.IsServer)
            _coord.NotifyOneSceneLoadedServer(sceneName);

        if (_queue.Count > 0 && _queue.Peek() == sceneName)
        {
            _queue.Dequeue();
        }
        else
        {
            var tmp = new Queue<string>();
            while (_queue.Count > 0)
            {
                var s = _queue.Dequeue();
                if (s != sceneName) tmp.Enqueue(s);
            }
            while (tmp.Count > 0) _queue.Enqueue(tmp.Dequeue());
        }

        LoadNext();
    }

    private void FinalizeLoad()
    {
        _loading = false;

        var nm = NetworkManager.Singleton;
        if (nm == null || !nm.IsHost) return;

        nm.SceneManager.OnLoadEventCompleted -= OnLoadEventCompleted;

        // Active Scene => Gameplay
        var gameplay = SceneManager.GetSceneByName(_gameplaySceneName);
        if (gameplay.IsValid() && gameplay.isLoaded)
        {
            SceneManager.SetActiveScene(gameplay);
            Debug.Log($"[StartGame] Active scene set => {_gameplaySceneName}");
        }
        else
        {
            Debug.LogWarning($"[StartGame] Gameplay scene not loaded? => {_gameplaySceneName}");
        }

        // IMPORTANT:
        // - On NE décharge PAS le lobby ici (sinon le bouton/logic peut être détruit avant la synchro).
        // - Le coordinator gère l'unload après StartMatch (si option active).
        if (_coord != null && _coord.IsServer)
            _coord.NotifyScenesLoadedServer();
        else
            Debug.LogError("[StartGame] Coordinator null/non-server à FinalizeLoad.");
    }
}

