using TMPro;
using UnityEngine;
using UnityEngine.UI;

public class MainMenuUIController : MonoBehaviour
{
    [Header("Buttons")]
    public Button createBtn;
    public Button joinBtn;
    public Button quitBtn;

    [Header("Join Popup")]
    public GameObject joinPopup;
    public TMP_InputField joinCodeInput;
    public Button joinConfirmBtn;
    public Button joinCancelBtn;

    private void Awake()
    {
        joinPopup.SetActive(false);

        createBtn.onClick.AddListener(OnCreate);
        joinBtn.onClick.AddListener(() => OpenJoinPopup(true));
        quitBtn.onClick.AddListener(Application.Quit);

        joinConfirmBtn.onClick.AddListener(OnJoinConfirm);
        joinCancelBtn.onClick.AddListener(() => OpenJoinPopup(false));
    }

    private void Start()
    {
        // Bind input au RelayConnector (équivalent à ton RelayUIBinder, mais ici c’est le menu)
        if (RelayConnector.Instance != null)
            RelayConnector.Instance.joinCodeInput = joinCodeInput;
    }

    void OnCreate()
    {
        if (RelayConnector.Instance == null) return;
        RelayConnector.Instance.UI_StartHostWithRelay(); // Host -> charge Lobby via NetworkSceneManager (étape 1)
    }

    void OnJoinConfirm()
    {
        if (RelayConnector.Instance == null) return;

        // UI_StartClientWithRelay lit RelayConnector.joinCodeInput.text
        RelayConnector.Instance.joinCodeInput = joinCodeInput;
        RelayConnector.Instance.UI_StartClientWithRelay(); // Client -> attend que le host charge Lobby
    }

    void OpenJoinPopup(bool open)
    {
        joinPopup.SetActive(open);
        if (open)
        {
            joinCodeInput.text = "";
            joinCodeInput.Select();
        }
    }
}

