// GhostLayerOverrideRunner.cs
using System.Collections;
using System.Collections.Generic;
using Unity.Netcode;
using UnityEngine;

/// <summary>
/// Applique un override de layer temporaire sur un NetworkObject (le joueur).
/// Pendant l'override, r�-applique le layer chaque LateUpdate (robuste contre d'autres scripts).
/// </summary>
public class GhostLayerOverrideRunner : MonoBehaviour
{
    [Header("Targets")]
    [Tooltip("Si vrai, change le layer de TOUS les enfants (hors Canvas). Sinon, seulement objets avec Renderer/Collider.")]
    [SerializeField] private bool affectAllChildren = false;

    [Tooltip("Inclure les objets inactifs lors de la recherche.")]
    [SerializeField] private bool includeInactive = false;

    [Header("Audio (optional)")]
    [SerializeField] private AudioSource audioSource;

    private readonly List<GameObject> _targets = new();
    private Coroutine _routine;

    private bool _active;
    private int _forcedLayer = -1;
    private int _restoreGhostLayer = -1;
    private int _restoreDefaultLayer = -1;
    private float _endTime;

    private NetworkPlayerState _ps;

    private void Awake()
    {
        _ps = GetComponent<NetworkPlayerState>() ?? GetComponentInParent<NetworkPlayerState>();
    }

    /// <summary>
    /// Force le layer "Default" pendant duration, puis remet "Ghost" (ou Default si le joueur est redevenu Alive).
    /// </summary>
    public void StartTemporaryDefault(
        int defaultLayer,
        int ghostLayer,
        float durationSeconds,
        AudioClip startClip,
        float volume,
        float spatialBlend,
        float maxDistance
    )
    {
        if (defaultLayer < 0 || ghostLayer < 0) return;

        _restoreDefaultLayer = defaultLayer;
        _restoreGhostLayer = ghostLayer;

        if (_routine != null)
            StopCoroutine(_routine);

        BuildTargets();

        // Appliquer imm�diatement
        _active = true;
        _forcedLayer = defaultLayer;
        _endTime = Time.time + Mathf.Max(0.01f, durationSeconds);
        ApplyLayer(_forcedLayer);

        // Son local (client + host)
        if (startClip != null)
            PlaySound(startClip, volume, spatialBlend, maxDistance);

        _routine = StartCoroutine(RunTimer());
    }

    private IEnumerator RunTimer()
    {
        while (Time.time < _endTime)
            yield return null;

        // Fin : remettre ghost si toujours mort, sinon default
        int layerToRestore = (_ps != null && _ps.Alive.Value) ? _restoreDefaultLayer : _restoreGhostLayer;

        _active = false;
        _forcedLayer = -1;
        ApplyLayer(layerToRestore);

        _routine = null;
    }

    private void LateUpdate()
    {
        if (!_active) return;
        if (_forcedLayer < 0) return;

        // Robuste: r�-applique le layer en LateUpdate (contre scripts qui le remettent)
        ApplyLayer(_forcedLayer);
    }

    private void BuildTargets()
    {
        _targets.Clear();

        if (affectAllChildren)
        {
            var trs = GetComponentsInChildren<Transform>(includeInactive);
            for (int i = 0; i < trs.Length; i++)
            {
                var go = trs[i].gameObject;
                if (IsUi(go)) continue;
                _targets.Add(go);
            }
            return;
        }

        // Sinon: seulement objets ayant Renderer/Collider (�vite UI)
        var renderers = GetComponentsInChildren<Renderer>(includeInactive);
        for (int i = 0; i < renderers.Length; i++)
        {
            var go = renderers[i].gameObject;
            if (IsUi(go)) continue;
            if (!_targets.Contains(go)) _targets.Add(go);
        }

        var colliders = GetComponentsInChildren<Collider>(includeInactive);
        for (int i = 0; i < colliders.Length; i++)
        {
            var go = colliders[i].gameObject;
            if (IsUi(go)) continue;
            if (!_targets.Contains(go)) _targets.Add(go);
        }

        // Au minimum, inclure la racine
        if (!_targets.Contains(gameObject))
            _targets.Add(gameObject);
    }

    private static bool IsUi(GameObject go)
    {
        // Ne pas toucher aux Canvas/UGUI
        return go.GetComponentInParent<Canvas>() != null;
    }

    private void ApplyLayer(int layer)
    {
        for (int i = 0; i < _targets.Count; i++)
        {
            var go = _targets[i];
            if (go == null) continue;
            go.layer = layer;
        }
    }

    private void PlaySound(AudioClip clip, float volume, float spatialBlend, float maxDistance)
    {
        if (audioSource == null)
        {
            var go = new GameObject("GhostActionAudio");
            go.transform.SetParent(transform, false);
            audioSource = go.AddComponent<AudioSource>();
            audioSource.playOnAwake = false;
        }

        audioSource.transform.position = transform.position;
        audioSource.spatialBlend = Mathf.Clamp01(spatialBlend);
        audioSource.rolloffMode = AudioRolloffMode.Linear;
        audioSource.maxDistance = Mathf.Max(1f, maxDistance);
        audioSource.volume = Mathf.Clamp01(volume);
        audioSource.PlayOneShot(clip);
    }
}

