using Unity.Netcode;
using UnityEngine;

[CreateAssetMenu(menuName = "Possede/Ghost Actions/Temporary Default Layer", fileName = "GA_TempDefaultLayer")]
public class GhostAction_TemporaryDefaultLayer : GhostAction
{
    [Header("Layers")]
    [Tooltip("Nom du layer normal (ex: Default).")]
    public string defaultLayerName = "Default";

    [Tooltip("Nom du layer ghost (ex: Ghost).")]
    public string ghostLayerName = "Ghost";

    [Header("Timing")]
    [Min(0.1f)] public float durationSeconds = 3f;

    [Header("Sound (played at start)")]
    public AudioClip startSound;
    [Range(0f, 1f)] public float volume = 1f;
    [Range(0f, 1f)] public float spatialBlend = 1f;
    [Min(1f)] public float maxDistance = 12f;

    public override bool RunOnServer => true;
    public override bool RunOnClients => true;

    public override void ExecuteServer(GhostActionContext ctx)
    {
        // Appliquer aussi c�t� serveur (collisions/raycasts serveur si utilis�s)
        if (NetworkManager.Singleton == null) return;
        if (!NetworkManager.Singleton.SpawnManager.SpawnedObjects.TryGetValue(ctx.SourceNetworkObjectId, out var no)) return;

        int defaultLayer = LayerMask.NameToLayer(defaultLayerName);
        int ghostLayer = LayerMask.NameToLayer(ghostLayerName);
        if (defaultLayer < 0 || ghostLayer < 0)
        {
            Debug.LogWarning($"[GA_TempDefaultLayer][SERVER] Layer introuvable. default='{defaultLayerName}' ghost='{ghostLayerName}'");
            return;
        }

        var runner = no.GetComponent<GhostLayerOverrideRunner>();
        if (runner == null) runner = no.gameObject.AddComponent<GhostLayerOverrideRunner>();

        runner.StartTemporaryDefault(
            defaultLayer,
            ghostLayer,
            durationSeconds,
            null, // pas de son sur serveur
            volume,
            spatialBlend,
            maxDistance
        );
    }

    public override void ExecuteClient(GhostActionContext ctx)
    {
        if (NetworkManager.Singleton == null) return;
        if (!NetworkManager.Singleton.SpawnManager.SpawnedObjects.TryGetValue(ctx.SourceNetworkObjectId, out var no)) return;

        int defaultLayer = LayerMask.NameToLayer(defaultLayerName);
        int ghostLayer = LayerMask.NameToLayer(ghostLayerName);
        if (defaultLayer < 0 || ghostLayer < 0)
        {
            Debug.LogWarning($"[GA_TempDefaultLayer][CLIENT] Layer introuvable. default='{defaultLayerName}' ghost='{ghostLayerName}'");
            return;
        }

        var runner = no.GetComponent<GhostLayerOverrideRunner>();
        if (runner == null) runner = no.gameObject.AddComponent<GhostLayerOverrideRunner>();

        runner.StartTemporaryDefault(
            defaultLayer,
            ghostLayer,
            durationSeconds,
            startSound,
            volume,
            spatialBlend,
            maxDistance
        );
    }
}

