using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using Unity.Netcode;
using Unity.Netcode.Components;
using UnityEngine;

public class PlayerSkinLoader : NetworkBehaviour
{
    [Header("Refs")]
    [Tooltip("Enfant de PolygonSyntyCharacter. Ex: PolygonSyntyCharacter/SkinVisualRoot (vide).")]
    public Transform visualRoot;

    [Tooltip("Animator DRIVER (sur PolygonSyntyCharacter). C'est lui qui est piloté par tes scripts (SamplePlayerAnimationController).")]
    public Animator targetAnimator;

    [Tooltip("NetworkAnimator sur le root NetworkObject.")]
    public NetworkAnimator netAnim;

    public SkinDatabase skinDb;

    [Header("Base dummy (on masque uniquement les Renderers, pas les GOs)")]
    [Tooltip("Racine du dummy visuel de base (ex: SK_DUMMY_POLYGON_01). Sert à cacher ses meshes.")]
    public Transform baseDummyVisualRoot;

    [Tooltip("Racine des BONES du squelette de base (ex: PolygonSyntyCharacter/Root).")]
    public Transform baseSkeletonRoot;

    [Header("Default behavior")]
    public bool useBuiltInDummyAsDefault = false;
    public int defaultSkinId = 0;

    [Header("Mesh Rebind (IMPORTANT)")]
    public bool rebindSkinMeshesToBaseSkeleton = true;

    [Header("Optional safety")]
    public RuntimeAnimatorController fallbackController;

    // Instances actuelles (meshes copiés/rebindés)
    private readonly List<GameObject> _spawnedSkinParts = new();

    private Renderer[] _baseDummyRenderers = Array.Empty<Renderer>();

    // Base bone caches
    private Dictionary<string, List<Transform>> _baseBonesExact = new();
    private Dictionary<string, List<Transform>> _baseBonesNormalized = new();
    private Dictionary<HumanBodyBones, Transform> _baseHumanBones = new();

    private static readonly Regex TrailingNumberRegex = new Regex(@"\s+\d+$", RegexOptions.Compiled);

    private static string NormalizeBoneName(string name)
    {
        if (string.IsNullOrEmpty(name)) return name;
        return TrailingNumberRegex.Replace(name, ""); // "Thumb_01 1" -> "Thumb_01"
    }

    private void Awake()
    {
        if (netAnim == null) netAnim = GetComponent<NetworkAnimator>();
        if (targetAnimator == null) targetAnimator = GetComponentInChildren<Animator>(true);

        RebuildCaches();

        if (netAnim != null && targetAnimator != null)
            netAnim.Animator = targetAnimator;
    }

    public override void OnNetworkSpawn()
    {
        base.OnNetworkSpawn();

        if (netAnim == null) netAnim = GetComponent<NetworkAnimator>();
        if (targetAnimator == null) targetAnimator = GetComponentInChildren<Animator>(true);

        RebuildCaches();

        if (netAnim != null && targetAnimator != null)
            netAnim.Animator = targetAnimator;
    }

    public override void OnNetworkDespawn()
    {
        ClearSkin();
        base.OnNetworkDespawn();
    }

    private void RebuildCaches()
    {
        CacheBaseDummyRenderers();
        CacheBaseBones();

        Debug.Log(
            $"[SkinLoader] Caches: dummyRenderers={_baseDummyRenderers.Length} " +
            $"baseBonesExactKeys={_baseBonesExact.Count} baseHumanBones={_baseHumanBones.Count} " +
            $"visualRoot={(visualRoot ? visualRoot.name : "NULL")} " +
            $"baseDummy={(baseDummyVisualRoot ? baseDummyVisualRoot.name : "NULL")} " +
            $"baseSkeleton={(baseSkeletonRoot ? baseSkeletonRoot.name : "NULL")}"
        );
    }

    private void CacheBaseDummyRenderers()
    {
        if (baseDummyVisualRoot == null)
        {
            _baseDummyRenderers = Array.Empty<Renderer>();
            return;
        }

        var all = baseDummyVisualRoot.GetComponentsInChildren<Renderer>(true);

        // Exclure les renderers qui sont sous visualRoot (sinon tu cacheras le skin)
        if (visualRoot == null)
        {
            _baseDummyRenderers = all;
            return;
        }

        var list = new List<Renderer>(all.Length);
        for (int i = 0; i < all.Length; i++)
        {
            var r = all[i];
            if (r == null) continue;
            if (r.transform.IsChildOf(visualRoot)) continue;
            list.Add(r);
        }

        _baseDummyRenderers = list.ToArray();
    }

    private void SetBaseDummyVisible(bool visible)
    {
        for (int i = 0; i < _baseDummyRenderers.Length; i++)
        {
            var r = _baseDummyRenderers[i];
            if (r != null) r.enabled = visible;
        }
    }

    private void CacheBaseBones()
    {
        _baseBonesExact = new Dictionary<string, List<Transform>>(256);
        _baseBonesNormalized = new Dictionary<string, List<Transform>>(256);
        _baseHumanBones = new Dictionary<HumanBodyBones, Transform>(64);

        if (baseSkeletonRoot == null)
            return;

        var bones = baseSkeletonRoot.GetComponentsInChildren<Transform>(true);

        for (int i = 0; i < bones.Length; i++)
        {
            var t = bones[i];
            if (t == null) continue;

            // exact
            if (!_baseBonesExact.TryGetValue(t.name, out var listExact))
            {
                listExact = new List<Transform>(1);
                _baseBonesExact.Add(t.name, listExact);
            }
            listExact.Add(t);

            // normalized
            var n = NormalizeBoneName(t.name);
            if (!_baseBonesNormalized.TryGetValue(n, out var listNorm))
            {
                listNorm = new List<Transform>(1);
                _baseBonesNormalized.Add(n, listNorm);
            }
            listNorm.Add(t);
        }

        // Humanoid mapping si possible
        if (targetAnimator != null && targetAnimator.isHuman)
        {
            foreach (HumanBodyBones hb in Enum.GetValues(typeof(HumanBodyBones)))
            {
                if (hb == HumanBodyBones.LastBone) continue;
                var tr = targetAnimator.GetBoneTransform(hb);
                if (tr != null && !_baseHumanBones.ContainsKey(hb))
                    _baseHumanBones.Add(hb, tr);
            }
        }
    }

    private void EnsureAnimatorReady()
    {
        if (targetAnimator == null) return;

        targetAnimator.enabled = true;

        if (targetAnimator.runtimeAnimatorController == null && fallbackController != null)
            targetAnimator.runtimeAnimatorController = fallbackController;
    }

    public void ApplySkin(int skinId)
    {
        if (targetAnimator == null)
        {
            Debug.LogError("[SkinLoader] targetAnimator is NULL.");
            return;
        }

        bool hadNetAnim = netAnim != null;
        if (hadNetAnim) netAnim.enabled = false;

        try
        {
            EnsureAnimatorReady();

            if (skinDb == null || visualRoot == null)
            {
                Debug.LogError("[SkinLoader] skinDb or visualRoot missing.");
                ClearSkin();
                return;
            }

            // Cas dummy intégré
            if (useBuiltInDummyAsDefault && skinId == defaultSkinId)
            {
                ClearSkinPartsOnly();
                SetBaseDummyVisible(true);
                targetAnimator.Rebind();
                targetAnimator.Update(0f);
                Debug.Log($"[SkinLoader] ApplySkin default(dummy) skinId={skinId}");
                return;
            }

            var prefab = skinDb.Get(skinId);
            if (prefab == null)
            {
                Debug.LogError($"[SkinLoader] Skin id={skinId} not found in SkinDatabase.");
                ClearSkin();
                return;
            }

            if (!rebindSkinMeshesToBaseSkeleton)
            {
                Debug.LogWarning("[SkinLoader] rebindSkinMeshesToBaseSkeleton=false -> ce mode n'est pas compatible si ton Animator driver reste sur PolygonSyntyCharacter.");
            }

            if (baseSkeletonRoot == null)
            {
                Debug.LogError("[SkinLoader] baseSkeletonRoot is NULL. Assigne PolygonSyntyCharacter/Root (la racine des bones).");
                ClearSkin();
                return;
            }

            // On masque le dummy mesh, mais on garde l'Animator/base skeleton actif
            SetBaseDummyVisible(false);

            // Nettoie l'ancien skin (meshes copiés)
            ClearSkinPartsOnly();

            // Instancie le prefab (temporaire) sous visualRoot
            var temp = Instantiate(prefab, visualRoot);
            temp.transform.localPosition = Vector3.zero;
            temp.transform.localRotation = Quaternion.identity;
            temp.transform.localScale = Vector3.one;

            // Skin humanoid mapping (si possible)
            Dictionary<Transform, HumanBodyBones> skinTransformToHuman = null;
            var skinAnimator = temp.GetComponentInChildren<Animator>(true);
            if (skinAnimator != null && skinAnimator.isHuman)
            {
                skinTransformToHuman = new Dictionary<Transform, HumanBodyBones>(64);
                foreach (HumanBodyBones hb in Enum.GetValues(typeof(HumanBodyBones)))
                {
                    if (hb == HumanBodyBones.LastBone) continue;
                    var tr = skinAnimator.GetBoneTransform(hb);
                    if (tr != null && !skinTransformToHuman.ContainsKey(tr))
                        skinTransformToHuman.Add(tr, hb);
                }
            }

            int missingBones = 0;
            int skinnedCount = 0;
            int staticCount = 0;

            Transform MapBone(Transform skinBone)
            {
                if (skinBone == null) return null;

                // 1) Humanoid mapping (le plus fiable)
                if (skinTransformToHuman != null &&
                    skinTransformToHuman.TryGetValue(skinBone, out var hb) &&
                    _baseHumanBones.TryGetValue(hb, out var baseHb))
                {
                    return baseHb;
                }

                // 2) Exact name
                if (_baseBonesExact.TryGetValue(skinBone.name, out var exactList) && exactList.Count > 0)
                    return exactList[0];

                // 3) Normalized name (strip " 1")
                var norm = NormalizeBoneName(skinBone.name);
                if (_baseBonesNormalized.TryGetValue(norm, out var normList) && normList.Count > 0)
                    return normList[0];

                // Missing -> fallback
                missingBones++;
                if (missingBones <= 12) // spam-control
                    Debug.LogWarning($"[SkinLoader] Missing bone '{skinBone.name}' for skinId={skinId} (fallback to baseSkeletonRoot).");

                return baseSkeletonRoot;
            }

            // Rebind: copie des skinned meshes sur bones base
            var smrs = temp.GetComponentsInChildren<SkinnedMeshRenderer>(true);
            for (int i = 0; i < smrs.Length; i++)
            {
                var src = smrs[i];
                if (src == null || src.sharedMesh == null) continue;

                skinnedCount++;

                var part = new GameObject(src.gameObject.name);
                part.transform.SetParent(visualRoot, false);
                part.transform.localPosition = Vector3.zero;
                part.transform.localRotation = Quaternion.identity;
                part.transform.localScale = Vector3.one;

                var dst = part.AddComponent<SkinnedMeshRenderer>();
                dst.sharedMesh = src.sharedMesh;
                dst.sharedMaterials = src.sharedMaterials;
                dst.updateWhenOffscreen = src.updateWhenOffscreen;
                dst.quality = src.quality;
                dst.shadowCastingMode = src.shadowCastingMode;
                dst.receiveShadows = src.receiveShadows;

                dst.rootBone = MapBone(src.rootBone);

                var srcBones = src.bones;
                var dstBones = new Transform[srcBones.Length];
                for (int b = 0; b < srcBones.Length; b++)
                    dstBones[b] = MapBone(srcBones[b]);

                dst.bones = dstBones;

                _spawnedSkinParts.Add(part);
            }

            // (Optionnel) MeshRenderer non skinned
            var mrs = temp.GetComponentsInChildren<MeshRenderer>(true);
            for (int i = 0; i < mrs.Length; i++)
            {
                var srcMr = mrs[i];
                var mf = srcMr.GetComponent<MeshFilter>();
                if (mf == null || mf.sharedMesh == null) continue;

                staticCount++;

                var part = new GameObject(srcMr.gameObject.name);
                part.transform.SetParent(visualRoot, false);
                part.transform.localPosition = srcMr.transform.localPosition;
                part.transform.localRotation = srcMr.transform.localRotation;
                part.transform.localScale = srcMr.transform.localScale;

                var dstMf = part.AddComponent<MeshFilter>();
                dstMf.sharedMesh = mf.sharedMesh;

                var dstMr = part.AddComponent<MeshRenderer>();
                dstMr.sharedMaterials = srcMr.sharedMaterials;

                _spawnedSkinParts.Add(part);
            }

            Destroy(temp);

            targetAnimator.Rebind();
            targetAnimator.Update(0f);

            Debug.Log(
                $"[SkinLoader] ApplySkin skinId={skinId} prefab={prefab.name} parts={_spawnedSkinParts.Count} " +
                $"skinned={skinnedCount} static={staticCount} missingBones={missingBones} " +
                $"baseIsHuman={(targetAnimator.isHuman ? "YES" : "NO")} skinIsHuman={(skinAnimator != null && skinAnimator.isHuman ? "YES" : "NO")}"
            );
        }
        finally
        {
            if (hadNetAnim)
            {
                if (netAnim.Animator != targetAnimator)
                    netAnim.Animator = targetAnimator;

                netAnim.enabled = true;
            }
        }
    }

    private void ClearSkin()
    {
        ClearSkinPartsOnly();
        SetBaseDummyVisible(true);

        if (targetAnimator != null)
        {
            EnsureAnimatorReady();
            targetAnimator.Rebind();
            targetAnimator.Update(0f);
        }
    }

    private void ClearSkinPartsOnly()
    {
        for (int i = _spawnedSkinParts.Count - 1; i >= 0; i--)
        {
            var go = _spawnedSkinParts[i];
            if (go != null) Destroy(go);
            _spawnedSkinParts.RemoveAt(i);
        }
    }
}

