// PlayerSkinSwapper.cs
using UnityEngine;
using Unity.Netcode.Components;

public class PlayerSkinSwapper : MonoBehaviour
{
    [Header("Where to spawn the skin")]
    public Transform skinRoot;                 // SkinVisualRoot

    [Header("Hide base dummy")]
    public Transform baseDummyVisualRoot;      // SK_DUMMY_POLYGON_01
    public bool hideBaseDummy = true;

    [Header("Skin Database")]
    public SkinDatabase skinDb;

    [Header("Animator behaviour")]
    [Tooltip("Si true, écrase le controller du skin (NON recommandé si Homme/Femme ont leurs propres controllers).")]
    public bool overrideSkinController = false;

    [Tooltip("Controller à appliquer si overrideSkinController = true, ou en fallback si le driver n'a aucun controller.")]
    public RuntimeAnimatorController sharedController;

    [Tooltip("Si true, le driver (Animator du prefab player) prendra le même controller que le skin choisi. Recommandé avec AnimatorParameterMirror + NetworkAnimator.")]
    public bool copySkinControllerToDriver = true;

    [Tooltip("Si true, le driver prendra aussi l'Avatar du skin (utile si tes controllers sont Humanoid).")]
    public bool syncDriverAvatar = true;

    public bool alwaysAnimate = true;

    [Header("Default")]
    public int defaultSkinId = 0;

    private GameObject _currentInstance;
    private Animator _currentAnimator;

    private Renderer[] _dummyRenderers;

    private AnimatorParameterMirror _mirror;
    private Animator _driverAnimator;                 // Animator du prefab player (root)
    private NetworkAnimator _netAnimator;             // NetworkAnimator du prefab player (root)
    private PlayerSkinVisual _skinVisualRefOnRoot;    // Optionnel : un script sur le root qui expose "Animator animator;"

    private void Awake()
    {
        _driverAnimator = GetComponent<Animator>();
        _netAnimator = GetComponent<NetworkAnimator>();
        _skinVisualRefOnRoot = GetComponent<PlayerSkinVisual>();

        _mirror = GetComponent<AnimatorParameterMirror>();
        if (_mirror == null) _mirror = GetComponentInChildren<AnimatorParameterMirror>(true);
        if (_mirror == null) _mirror = GetComponentInParent<AnimatorParameterMirror>();

        CacheDummyRenderers();
        ApplyDummyVisibility();

        if (skinRoot == null) Debug.LogError("[SkinSwapper] skinRoot not set");
        if (skinDb == null) Debug.LogError("[SkinSwapper] skinDb not set");

        // IMPORTANT: le driver doit avoir un controller au moins au démarrage
        // (NetworkAnimator et/ou Mirror ont besoin d'une liste de paramètres existante).
        if (_driverAnimator != null && _driverAnimator.runtimeAnimatorController == null && sharedController != null)
        {
            _driverAnimator.runtimeAnimatorController = sharedController;
            _driverAnimator.Rebind();
            _driverAnimator.Update(0f);
        }

        if (alwaysAnimate && _driverAnimator != null)
            _driverAnimator.cullingMode = AnimatorCullingMode.AlwaysAnimate;

        // Assure que NetworkAnimator pointe sur l'Animator du root (driver)
        if (_netAnimator != null && _driverAnimator != null)
            _netAnimator.Animator = _driverAnimator;
    }

    private void OnDestroy()
    {
        if (_currentInstance != null) Destroy(_currentInstance);
    }

    private void CacheDummyRenderers()
    {
        if (baseDummyVisualRoot == null) return;
        _dummyRenderers = baseDummyVisualRoot.GetComponentsInChildren<Renderer>(true);
    }

    private void ApplyDummyVisibility()
    {
        if (!hideBaseDummy) return;
        if (_dummyRenderers == null) return;

        for (int i = 0; i < _dummyRenderers.Length; i++)
            if (_dummyRenderers[i] != null)
                _dummyRenderers[i].enabled = false;
    }

    public void ApplySkin(int skinId)
    {
        if (skinDb == null || skinRoot == null)
        {
            Debug.LogError("[SkinSwapper] Missing refs (skinDb/skinRoot).");
            return;
        }

        ApplyDummyVisibility();

        var prefab = skinDb.Get(skinId);
        if (prefab == null)
        {
            Debug.LogWarning($"[SkinSwapper] SkinId={skinId} not found, fallback to {defaultSkinId}");
            prefab = skinDb.Get(defaultSkinId);
        }
        if (prefab == null)
        {
            Debug.LogError("[SkinSwapper] No prefab found (db empty?).");
            return;
        }

        if (_currentInstance != null) Destroy(_currentInstance);

        _currentInstance = Instantiate(prefab, skinRoot);
        _currentInstance.transform.localPosition = Vector3.zero;
        _currentInstance.transform.localRotation = Quaternion.identity;
        _currentInstance.transform.localScale = Vector3.one;

        _currentAnimator = _currentInstance.GetComponentInChildren<Animator>(true);
        if (_currentAnimator == null)
        {
            Debug.LogError($"[SkinSwapper] Spawned skin '{prefab.name}' has no Animator in children.");
            return;
        }

        // POINT CLÉ: si tu veux HommeController / FemmeController selon le skin,
        // NE PAS écraser le controller du skin.
        if (overrideSkinController && sharedController != null)
            _currentAnimator.runtimeAnimatorController = sharedController;

        if (alwaysAnimate)
            _currentAnimator.cullingMode = AnimatorCullingMode.AlwaysAnimate;

        // Optionnel mais recommandé dans ton architecture (driver root + mirror + networkanim):
        // le driver prend le controller du skin choisi (Homme ou Femme).
        if (copySkinControllerToDriver && _driverAnimator != null)
        {
            _driverAnimator.runtimeAnimatorController = _currentAnimator.runtimeAnimatorController;

            if (syncDriverAvatar)
                _driverAnimator.avatar = _currentAnimator.avatar;

            if (alwaysAnimate)
                _driverAnimator.cullingMode = AnimatorCullingMode.AlwaysAnimate;

            _driverAnimator.enabled = true;
            _driverAnimator.Rebind();
            _driverAnimator.Update(0f);
        }

        // Rebind côté skin
        _currentAnimator.enabled = true;
        _currentAnimator.Rebind();
        _currentAnimator.Update(0f);

        // Si tu as un PlayerSkinVisual sur le ROOT (optionnel), on le met à jour
        if (_skinVisualRefOnRoot != null)
            _skinVisualRefOnRoot.animator = _currentAnimator;

        // Mirror des paramètres depuis l'Animator "source" (driver/root) vers le skin
        if (_mirror != null)
        {
            _mirror.SetTarget(_currentAnimator);
        }
        else
        {
            Debug.LogWarning("[SkinSwapper] AnimatorParameterMirror not found -> le skin ne recevra pas les params.");
        }

        Debug.Log($"[SkinSwapper] Applied skinId={skinId} prefab={prefab.name} animator={_currentAnimator.name} controller={_currentAnimator.runtimeAnimatorController?.name}");
    }

    public Animator CurrentAnimator => _currentAnimator;
}

