// CarObjective.cs
using Unity.Netcode;
using UnityEngine;

public class CarObjective : NetworkBehaviour
{
    [Header("Interact points (assign Point_ transforms)")]
    public Transform cablePoint;
    public Transform fuelPoint;
    public Transform oilPoint;

    [Header("Distance")]
    public float interactDistance = 2.0f;

    [Header("Fuel")]
    public float fuelTransferRatePercentPerSecond = 10f;

    [Header("Oil")]
    public float oilTransferRatePercentPerSecond = 10f;

    [Tooltip("Si vrai, l'huile est requise pour que la voiture soit pr�te.")]
    public bool requireOil = true;

    [Header("Visuals (optional)")]
    public GameObject[] cableVisuals; // up to 20

    public NetworkVariable<int> CablesRequired = new(3, NetworkVariableReadPermission.Everyone, NetworkVariableWritePermission.Server);
    public NetworkVariable<int> CablesInstalled = new(0, NetworkVariableReadPermission.Everyone, NetworkVariableWritePermission.Server);

    public NetworkVariable<float> FuelPercent = new(0f, NetworkVariableReadPermission.Everyone, NetworkVariableWritePermission.Server);
    public NetworkVariable<float> OilPercent = new(0f, NetworkVariableReadPermission.Everyone, NetworkVariableWritePermission.Server);

    private bool _isFueling;
    private ulong _fuelingClientId;

    private bool _isOiling;
    private ulong _oilingClientId;

    public override void OnNetworkSpawn()
    {
        CablesInstalled.OnValueChanged += (_, __) => { RefreshVisuals(); CheckWinServer(); };
        CablesRequired.OnValueChanged += (_, __) => { RefreshVisuals(); CheckWinServer(); };
        FuelPercent.OnValueChanged += (_, __) => { CheckWinServer(); };
        OilPercent.OnValueChanged += (_, __) => { CheckWinServer(); };

        RefreshVisuals();
    }

    public Transform GetPoint(CarInteractKind kind)
    {
        switch (kind)
        {
            case CarInteractKind.Cable: return cablePoint;
            case CarInteractKind.Fuel: return fuelPoint;
            case CarInteractKind.Oil: return oilPoint;
            default: return null;
        }
    }

    public bool IsCloseEnoughFor(Transform player, CarInteractKind kind)
    {
        var p = GetPoint(kind);
        return CloseEnough(player, p);
    }

    private bool CloseEnough(Transform player, Transform point)
    {
        if (player == null || point == null) return false;
        float d = interactDistance;
        return (player.position - point.position).sqrMagnitude <= d * d;
    }

    public bool IsReady()
    {
        bool oilOk = true;
        if (requireOil && oilPoint != null)
            oilOk = OilPercent.Value >= 100f - 0.01f;

        return (CablesInstalled.Value >= CablesRequired.Value)
               && (FuelPercent.Value >= 100f - 0.01f)
               && oilOk;
    }

    private void CheckWinServer()
    {
        if (!IsServer) return;

        var gc = NetworkGameController.Instance;
        if (gc == null) return;

        if ((MatchState)gc.State.Value != MatchState.Running) return;
        if (gc.WinnerSide.Value != (int)WinSide.None) return;

        if (IsReady())
        {
            gc.WinnerSide.Value = (int)WinSide.Survivants;
            gc.EndMatchFromServer_Announce("car_ready");
        }
    }

    public void ResetForMatchServer()
    {
        if (!IsServer) return;

        CablesInstalled.Value = 0;

        FuelPercent.Value = 0f;
        _isFueling = false;
        _fuelingClientId = 0;

        OilPercent.Value = 0f;
        _isOiling = false;
        _oilingClientId = 0;
    }

    private void RefreshVisuals()
    {
        if (cableVisuals == null || cableVisuals.Length == 0) return;

        int req = Mathf.Clamp(CablesRequired.Value, 0, cableVisuals.Length);
        int inst = Mathf.Clamp(CablesInstalled.Value, 0, req);

        for (int i = 0; i < cableVisuals.Length; i++)
        {
            bool shouldExist = i < req;
            bool isInstalled = i < inst;
            cableVisuals[i].SetActive(shouldExist && isInstalled);
        }
    }

    private bool TryGetPlayerState(ulong clientId, out NetworkPlayerState ps, out Transform tr)
    {
        ps = null;
        tr = null;

        var nm = NetworkManager.Singleton;
        if (nm == null) return false;

        if (!nm.ConnectedClients.TryGetValue(clientId, out var client)) return false;
        var po = client.PlayerObject;
        if (po == null) return false;

        ps = po.GetComponentInChildren<NetworkPlayerState>(true);
        if (ps == null) return false;

        tr = ps.transform;
        return tr != null;
    }

    [Rpc(SendTo.Server, InvokePermission = RpcInvokePermission.Everyone)]
    public void TryInstallAtServerRpc(int kind, RpcParams rpcParams = default)
    {
        if (!IsServer) return;

        var gc = NetworkGameController.Instance;
        if (gc == null) return;
        if ((MatchState)gc.State.Value != MatchState.Running) return;
        if (gc.WinnerSide.Value != (int)WinSide.None) return;

        ulong clientId = rpcParams.Receive.SenderClientId;
        if (!TryGetPlayerState(clientId, out var ps, out var tr)) return;
        if (!ps.Alive.Value || ps.Escaped.Value) return;

        var k = (CarInteractKind)kind;

        // Objectif ici : C�BLES
        if (k == CarInteractKind.Cable)
        {
            if (!CloseEnough(tr, cablePoint)) return;
            if (CablesInstalled.Value >= CablesRequired.Value) return;
            if (!ps.HasItemLocal((int)ItemId.Cables)) return;

            if (!ps.TryConsumeOneServer(ItemId.Cables)) return;
            CablesInstalled.Value += 1;
            CheckWinServer();
        }
    }

    [Rpc(SendTo.Server, InvokePermission = RpcInvokePermission.Everyone)]
    public void StartFuelingServerRpc(RpcParams rpcParams = default)
    {
        if (!IsServer) return;

        var gc = NetworkGameController.Instance;
        if (gc == null) return;
        if ((MatchState)gc.State.Value != MatchState.Running) return;
        if (gc.WinnerSide.Value != (int)WinSide.None) return;

        ulong clientId = rpcParams.Receive.SenderClientId;
        if (!TryGetPlayerState(clientId, out var ps, out var tr)) return;
        if (!ps.Alive.Value || ps.Escaped.Value) return;

        if (!CloseEnough(tr, fuelPoint)) return;
        if (FuelPercent.Value >= 100f - 0.01f) return;
        if (!ps.HasItemLocal((int)ItemId.Essence)) return;

        _isFueling = true;
        _fuelingClientId = clientId;

        _isOiling = false;
        _oilingClientId = 0;
    }

    [Rpc(SendTo.Server, InvokePermission = RpcInvokePermission.Everyone)]
    public void StopFuelingServerRpc(RpcParams rpcParams = default)
    {
        if (!IsServer) return;
        if (!_isFueling) return;
        if (rpcParams.Receive.SenderClientId != _fuelingClientId) return;

        _isFueling = false;
        _fuelingClientId = 0;
    }

    [Rpc(SendTo.Server, InvokePermission = RpcInvokePermission.Everyone)]
    public void StartOilingServerRpc(RpcParams rpcParams = default)
    {
        if (!IsServer) return;

        var gc = NetworkGameController.Instance;
        if (gc == null) return;
        if ((MatchState)gc.State.Value != MatchState.Running) return;
        if (gc.WinnerSide.Value != (int)WinSide.None) return;

        if (oilPoint == null) return;

        ulong clientId = rpcParams.Receive.SenderClientId;
        if (!TryGetPlayerState(clientId, out var ps, out var tr)) return;
        if (!ps.Alive.Value || ps.Escaped.Value) return;

        if (!CloseEnough(tr, oilPoint)) return;
        if (OilPercent.Value >= 100f - 0.01f) return;
        if (!ps.HasItemLocal((int)ItemId.HuileMoteur)) return;

        _isOiling = true;
        _oilingClientId = clientId;

        _isFueling = false;
        _fuelingClientId = 0;
    }

    [Rpc(SendTo.Server, InvokePermission = RpcInvokePermission.Everyone)]
    public void StopOilingServerRpc(RpcParams rpcParams = default)
    {
        if (!IsServer) return;
        if (!_isOiling) return;
        if (rpcParams.Receive.SenderClientId != _oilingClientId) return;

        _isOiling = false;
        _oilingClientId = 0;
    }

    private void Update()
    {
        if (!IsServer) return;

        var gc = NetworkGameController.Instance;
        if (gc == null || (MatchState)gc.State.Value != MatchState.Running || gc.WinnerSide.Value != (int)WinSide.None)
        {
            _isFueling = false;
            _fuelingClientId = 0;

            _isOiling = false;
            _oilingClientId = 0;
            return;
        }

        // -------- FUEL UPDATE --------
        if (_isFueling)
        {
            if (!TryGetPlayerState(_fuelingClientId, out var psFuel, out var trFuel))
            {
                _isFueling = false;
                _fuelingClientId = 0;
            }
            else if (!CloseEnough(trFuel, fuelPoint))
            {
                _isFueling = false;
                _fuelingClientId = 0;
            }
            else if (FuelPercent.Value >= 100f - 0.01f)
            {
                FuelPercent.Value = 100f;
                _isFueling = false;
                _fuelingClientId = 0;
                CheckWinServer();
            }
            else
            {
                float wantFuel = fuelTransferRatePercentPerSecond * Time.deltaTime;
                wantFuel = Mathf.Min(wantFuel, 100f - FuelPercent.Value);

                if (!psFuel.TryDrainFuelServer(wantFuel, out float drainedFuel) || drainedFuel <= 0.0001f)
                {
                    _isFueling = false;
                    _fuelingClientId = 0;
                }
                else
                {
                    FuelPercent.Value = Mathf.Min(100f, FuelPercent.Value + drainedFuel);

                    if (FuelPercent.Value >= 100f - 0.01f)
                    {
                        FuelPercent.Value = 100f;
                        _isFueling = false;
                        _fuelingClientId = 0;
                        CheckWinServer();
                    }
                }
            }
        }

        // -------- OIL UPDATE --------
        if (_isOiling)
        {
            if (oilPoint == null)
            {
                _isOiling = false;
                _oilingClientId = 0;
                return;
            }

            if (!TryGetPlayerState(_oilingClientId, out var psOil, out var trOil))
            {
                _isOiling = false;
                _oilingClientId = 0;
            }
            else if (!CloseEnough(trOil, oilPoint))
            {
                _isOiling = false;
                _oilingClientId = 0;
            }
            else if (OilPercent.Value >= 100f - 0.01f)
            {
                OilPercent.Value = 100f;
                _isOiling = false;
                _oilingClientId = 0;
                CheckWinServer();
            }
            else
            {
                float wantOil = oilTransferRatePercentPerSecond * Time.deltaTime;
                wantOil = Mathf.Min(wantOil, 100f - OilPercent.Value);

                if (!psOil.TryDrainOilServer(wantOil, out float drainedOil) || drainedOil <= 0.0001f)
                {
                    _isOiling = false;
                    _oilingClientId = 0;
                }
                else
                {
                    OilPercent.Value = Mathf.Min(100f, OilPercent.Value + drainedOil);

                    if (OilPercent.Value >= 100f - 0.01f)
                    {
                        OilPercent.Value = 100f;
                        _isOiling = false;
                        _oilingClientId = 0;
                        CheckWinServer();
                    }
                }
            }
        }
    }

#if UNITY_EDITOR
    private void OnValidate()
    {
        // Hierarchie attendue:
        // CarObjective/Cable/InteractPoint
        // CarObjective/Fuel/InteractPoint
        // CarObjective/Oil/InteractPoint
        if (cablePoint == null)
        {
            var t = transform.Find("Cable/InteractPoint");
            if (t != null) cablePoint = t;
        }

        if (fuelPoint == null)
        {
            var t = transform.Find("Fuel/InteractPoint");
            if (t != null) fuelPoint = t;
        }

        if (oilPoint == null)
        {
            var t = transform.Find("Oil/InteractPoint");
            if (t != null) oilPoint = t;
        }
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = new Color(0f, 1f, 1f, 0.35f);

        void Draw(Transform t)
        {
            if (t == null) return;
            Gizmos.DrawWireSphere(t.position, interactDistance);
        }

        Draw(cablePoint);
        Draw(fuelPoint);
        Draw(oilPoint);
    }
#endif
}

