using System.Collections;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

public class SearchProgressUI : MonoBehaviour
{
    public GameObject root;
    public Slider bar;
    public TMP_Text label;

    private Coroutine _co;

    void Awake()
    {
        Hide();

        if (bar != null)
        {
            bar.minValue = 0f;
            bar.maxValue = 1f;
            bar.interactable = false;
        }
    }

    public void Show(float duration, string text = null)
    {
        if (root != null) root.SetActive(true);
        if (label != null) label.text = text ?? "";

        if (_co != null) StopCoroutine(_co);
        _co = StartCoroutine(Run(duration));
    }

    public void Hide()
    {
        if (_co != null) StopCoroutine(_co);
        _co = null;

        if (bar != null) bar.value = 0f;
        if (root != null) root.SetActive(false);
        if (label != null) label.text = "";
    }

    private IEnumerator Run(float duration)
    {
        float t = Mathf.Max(0.01f, duration);
        float start = Time.time;

        while (true)
        {
            float p = Mathf.Clamp01((Time.time - start) / t);
            if (bar != null) bar.value = p;
            if (p >= 1f) break;
            yield return null;
        }

        _co = null;
        Hide();
    }
}

