using Unity.Netcode;
using UnityEngine;
using UnityEngine.SceneManagement;

public class MapLoader : MonoBehaviour
{
    public static MapLoader Instance { get; private set; }

    [Header("Database")]
    public MapDatabase mapDb;

    [Header("Selected map id")]
    public string selectedMapId = "Mansion";

    void Awake()
    {
        if (Instance != null && Instance != this) { Destroy(gameObject); return; }
        Instance = this;
        DontDestroyOnLoad(gameObject);
    }

    public void LoadSelectedMapForAll()
    {
        var nm = NetworkManager.Singleton;
        if (nm == null || !nm.IsServer)
        {
            Debug.LogWarning("[MapLoader] LoadSelectedMapForAll appelé mais pas serveur.");
            return;
        }

        if (mapDb == null)
        {
            Debug.LogError("[MapLoader] mapDb null.");
            return;
        }

        var entry = mapDb.Get(selectedMapId);
        if (entry == null)
        {
            Debug.LogError($"[MapLoader] Map id introuvable: {selectedMapId}");
            return;
        }

        if (nm.SceneManager == null)
        {
            Debug.LogError("[MapLoader] NetworkSceneManager null. Active Enable Scene Management sur NetworkManager.");
            return;
        }

        // Charge les 3 scènes additivement (répliqué aux clients)
        nm.SceneManager.LoadScene(entry.mappingScene, LoadSceneMode.Additive);
        nm.SceneManager.LoadScene(entry.lightingScene, LoadSceneMode.Additive);
        nm.SceneManager.LoadScene(entry.gameplayScene, LoadSceneMode.Additive);
        nm.SceneManager.LoadScene(entry.propsScene, LoadSceneMode.Additive);

        Debug.Log($"[MapLoader] Loading map '{entry.id}' scenes: {entry.mappingScene}, {entry.lightingScene}, {entry.gameplayScene}, {entry.propsScene}");
    }
}

