using Unity.Netcode;
using UnityEngine;

[DisallowMultipleComponent]
public class NetworkDoor : NetworkBehaviour
{
    [Header("Debug")]
    public bool debugLogs = true;

    [Header("Setup")]
    [Tooltip("Transform qui tourne (pivot charnière).")]
    public Transform doorPivot;

    [Tooltip("Axe local de rotation sur le pivot (souvent Y).")]
    public Vector3 localAxis = Vector3.up;

    [Range(0f, 180f)]
    public float openAngle = 90f;

    public float speedDegPerSec = 360f;
    public float interactDistance = 3f;

    [Header("Push Direction")]
    [Tooltip("Point sur la feuille (poignée/centre). Sert à choisir le sens qui s'éloigne du joueur.")]
    public Transform samplePoint;

    [Tooltip("Si samplePoint est vide, essaie d'auto-déduire via un collider enfant.")]
    public bool autoSampleFromChildCollider = true;

    [Header("Room Link (House Lock)")]
    [Tooltip("Id de la pièce côté A (ex: Chambre=2).")]
    public int roomAId = 0;

    [Tooltip("Id de la pièce côté B (ex: Couloir=1). Mets -1 si non utilisé.")]
    public int roomBId = -1;

    [Tooltip("Si true, cette porte sera verrouillée quand la maison désigne la pièce.")]
    public bool lockIfHouseKillRoom = true;

    [Tooltip("Optionnel: colliders supplémentaires à activer quand verrouillé (blocker).")]
    public Collider[] extraBlockersWhenLocked;

    public NetworkVariable<bool> IsOpen = new(
        false,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    public NetworkVariable<int> OpenDir = new(
        1,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    public NetworkVariable<bool> IsLocked = new(
        false,
        NetworkVariableReadPermission.Everyone,
        NetworkVariableWritePermission.Server
    );

    Quaternion _closedLocalRot;
    Vector3 _axisLocalN;

    float _currentSignedAngle;
    float _targetSignedAngle;

    Vector3 _sampleLocal; // position locale du point sample dans l'espace du pivot, à l'état fermé

    void Awake()
    {
        if (doorPivot == null) doorPivot = transform;

        _closedLocalRot = doorPivot.localRotation;
        _axisLocalN = localAxis.sqrMagnitude > 0.0001f ? localAxis.normalized : Vector3.up;
    }

    public override void OnNetworkSpawn()
    {
        base.OnNetworkSpawn();

        if (doorPivot == null) doorPivot = transform;

        _closedLocalRot = doorPivot.localRotation;
        _axisLocalN = localAxis.sqrMagnitude > 0.0001f ? localAxis.normalized : Vector3.up;

        CacheSampleLocal();

        if (debugLogs)
            Debug.Log($"[Door] OnNetworkSpawn name={name} isServer={IsServer} isClient={IsClient}");

        IsOpen.OnValueChanged += (_, __) => RecomputeTarget();
        OpenDir.OnValueChanged += (_, __) => RecomputeTarget();

        IsLocked.OnValueChanged += (_, n) =>
        {
            ApplyLockedVisuals(n);
            if (IsServer && n)
            {
                // verrou => fermer progressivement
                IsOpen.Value = false;
                // ❌ PAS de force instantanée
            }
        };

        ApplyLockedVisuals(IsLocked.Value);

        RecomputeTarget();
        _currentSignedAngle = _targetSignedAngle;
        ApplyAngle(_currentSignedAngle);
    }

    public bool BelongsToRoom(int roomId)
    {
        return roomAId == roomId || roomBId == roomId;
    }

    public void SetLockedServer(bool locked)
    {
        if (!IsServer) return;
        Debug.Log($"[DOOR] SetLockedServer appelé sur '{name}': locked={locked} (roomA={roomAId}, roomB={roomBId})");

        IsLocked.Value = locked;

        if (locked)
        {
            IsOpen.Value = false;
        }
    }

    void ApplyLockedVisuals(bool locked)
    {
        if (extraBlockersWhenLocked != null)
        {
            for (int i = 0; i < extraBlockersWhenLocked.Length; i++)
            {
                if (extraBlockersWhenLocked[i] != null)
                    extraBlockersWhenLocked[i].enabled = locked;
            }
        }
    }

    void CacheSampleLocal()
    {
        if (doorPivot == null) return;

        if (samplePoint != null)
        {
            _sampleLocal = doorPivot.InverseTransformPoint(samplePoint.position);
            return;
        }

        if (autoSampleFromChildCollider)
        {
            var col = doorPivot.GetComponentInChildren<Collider>();
            if (col != null)
            {
                _sampleLocal = doorPivot.InverseTransformPoint(col.bounds.center);
                return;
            }
        }

        _sampleLocal = Vector3.forward * 0.5f;
    }

    void Update()
    {
        float step = speedDegPerSec * Time.deltaTime;
        _currentSignedAngle = Mathf.MoveTowards(_currentSignedAngle, _targetSignedAngle, step);
        ApplyAngle(_currentSignedAngle);
    }

    void RecomputeTarget()
    {
        int dir = OpenDir.Value;
        if (dir != 1 && dir != -1) dir = 1;
        _targetSignedAngle = IsOpen.Value ? openAngle * dir : 0f;
    }

    void ApplyAngle(float signedAngle)
    {
        if (doorPivot == null) return;
        doorPivot.localRotation = _closedLocalRot * Quaternion.AngleAxis(signedAngle, _axisLocalN);
    }

    // ✅ Remplace [ServerRpc(RequireOwnership = false)] (obsolète)
    [Rpc(SendTo.Server, InvokePermission = RpcInvokePermission.Everyone)]
    public void RequestToggleServerRpc(RpcParams rpcParams = default)
    {
        if (!IsServer) return;

        if (IsLocked.Value)
        {
            if (debugLogs) Debug.LogWarning($"[Door] Reject: locked door name={name}");
            return;
        }

        var clientId = rpcParams.Receive.SenderClientId;

        if (NetworkManager.Singleton == null ||
            !NetworkManager.Singleton.ConnectedClients.TryGetValue(clientId, out var cc) ||
            cc.PlayerObject == null)
        {
            if (debugLogs) Debug.LogWarning($"[Door] Reject: no PlayerObject for clientId={clientId}");
            return;
        }

        Transform opener = cc.PlayerObject.transform;

        if (doorPivot == null)
        {
            if (debugLogs) Debug.LogWarning("[Door] Reject: doorPivot null");
            return;
        }

        float dist = Vector3.Distance(opener.position, doorPivot.position);
        if (dist > interactDistance)
        {
            if (debugLogs) Debug.LogWarning($"[Door] Reject: too far dist={dist:F2} max={interactDistance:F2}");
            return;
        }

        bool wantOpen = !IsOpen.Value;

        if (wantOpen)
        {
            OpenDir.Value = ComputePushOpenDir(opener.position);
            IsOpen.Value = true;
            if (debugLogs) Debug.Log($"[Door] OPEN dir={OpenDir.Value} by clientId={clientId}");
        }
        else
        {
            IsOpen.Value = false;
            if (debugLogs) Debug.Log($"[Door] CLOSE by clientId={clientId}");
        }
    }

    int ComputePushOpenDir(Vector3 openerPos)
    {
        Vector3 samplePosPlus = PredictSampleWorldPos(+openAngle);
        Vector3 samplePosMinus = PredictSampleWorldPos(-openAngle);

        float dPlus = (samplePosPlus - openerPos).sqrMagnitude;
        float dMinus = (samplePosMinus - openerPos).sqrMagnitude;

        return (dPlus > dMinus) ? 1 : -1;
    }

    Vector3 PredictSampleWorldPos(float signedAngle)
    {
        Quaternion delta = Quaternion.AngleAxis(signedAngle, _axisLocalN);

        Quaternion parentWorld = doorPivot.parent != null ? doorPivot.parent.rotation : Quaternion.identity;
        Quaternion predictedWorldRot = parentWorld * (_closedLocalRot * delta);

        Vector3 pivotWorldPos = doorPivot.position;
        return pivotWorldPos + predictedWorldRot * _sampleLocal;
    }
}

