using System;
using System.Collections.Generic;
using System.Linq;
using Unity.Netcode;
using UnityEngine;

public class PropRandomSpawner : MonoBehaviour
{
    [Serializable]
    public class MaxPerItemRule
    {
        public ItemId itemId;
        [Min(0)] public int maxPerMatch = 0; // 0 = illimité
    }

    [Header("Points")]
    public bool autoFindPointsInScene = true;
    public List<PropSpawnPoint> points = new();

    [Header("Match")]
    public bool clearPreviousPropsOnSpawn = true;

    [Header("Minimum spawns")]
    [Tooltip("Nombre minimum d'objets à faire apparaître sur la carte (meilleur effort). 0 = aucun minimum.")]
    [Min(0)] public int minTotalSpawns = 0;

    [Header("Caps (0 = illimité)")]
    public List<MaxPerItemRule> maxPerItem = new();

    private readonly List<NetworkObject> _spawned = new();

    private Dictionary<ItemId, int> _caps;
    private Dictionary<ItemId, int> _counts;

    private bool IsServerReady()
    {
        return NetworkManager.Singleton != null
            && NetworkManager.Singleton.IsServer
            && NetworkManager.Singleton.IsListening;
    }

    private List<PropSpawnPoint> ResolvePointsRuntime()
    {
        if (!autoFindPointsInScene)
        {
            return points != null ? points.Where(p => p != null).ToList() : new List<PropSpawnPoint>();
        }

#if UNITY_2023_1_OR_NEWER || UNITY_2022_2_OR_NEWER
        return FindObjectsByType<PropSpawnPoint>(FindObjectsInactive.Include, FindObjectsSortMode.None)
            .Where(p => p != null)
            .ToList();
#else
        return Resources.FindObjectsOfTypeAll<PropSpawnPoint>()
            .Where(p => p != null && p.gameObject.scene.IsValid())
            .ToList();
#endif
    }

    public void SpawnForMatch()
    {
        if (!IsServerReady()) return;

        points = ResolvePointsRuntime();
        Debug.Log($"[PropRandomSpawner] SpawnForMatch: points trouvés = {points.Count} (autoFind={autoFindPointsInScene})");

        if (points == null || points.Count == 0)
        {
            Debug.LogError("[PropRandomSpawner] Aucun PropSpawnPoint trouvé -> rien ne spawn.");
            return;
        }

        if (clearPreviousPropsOnSpawn)
            DespawnAll();

        BuildCaps();
        _counts = new Dictionary<ItemId, int>();

        var usable = points
            .Where(p => p != null && !p.disabled)
            .ToList();

        // Shuffle points
        for (int i = 0; i < usable.Count; i++)
        {
            int j = UnityEngine.Random.Range(i, usable.Count);
            (usable[i], usable[j]) = (usable[j], usable[i]);
        }

        int spawned = 0;
        int skipped = 0;

        // Points restés vides / non utilisés (pour le pass "minimum")
        var leftovers = new List<PropSpawnPoint>();

        // PASS 1: comportement normal (emptyWeight respecté)
        foreach (var p in usable)
        {
            var opt = PickOption(p, allowEmpty: true);
            if (opt == null || opt.prefab == null) { skipped++; leftovers.Add(p); continue; }

            if (!CanSpawnPrefab(opt.prefab)) { skipped++; leftovers.Add(p); continue; }

            if (!TrySpawn(p, opt))
            {
                skipped++;
                leftovers.Add(p);
                continue;
            }

            spawned++;
        }

        // PASS 2: si on n'atteint pas le minimum, on force sur les leftovers (emptyWeight ignoré)
        if (minTotalSpawns > 0 && spawned < minTotalSpawns && leftovers.Count > 0)
        {
            // Shuffle leftovers
            for (int i = 0; i < leftovers.Count; i++)
            {
                int j = UnityEngine.Random.Range(i, leftovers.Count);
                (leftovers[i], leftovers[j]) = (leftovers[j], leftovers[i]);
            }

            foreach (var p in leftovers)
            {
                if (spawned >= minTotalSpawns) break;

                var opt = PickOption(p, allowEmpty: false); // ignore emptyWeight
                if (opt == null || opt.prefab == null) continue;
                if (!CanSpawnPrefab(opt.prefab)) continue;

                if (!TrySpawn(p, opt)) continue;

                spawned++;
                skipped = Mathf.Max(0, skipped - 1); // optionnel: on "récupère" un skip
            }
        }

        if (minTotalSpawns > 0 && spawned < minTotalSpawns)
        {
            Debug.LogWarning($"[PropRandomSpawner] Minimum non atteint: spawned={spawned} < minTotalSpawns={minTotalSpawns}. " +
                             $"Causes probables: pas assez de points, caps trop stricts, ou options vides.");
        }

        Debug.Log($"[PropRandomSpawner] SpawnForMatch terminé: spawned={spawned} skipped={skipped} usablePoints={usable.Count}");
    }

    private bool TrySpawn(PropSpawnPoint p, PropSpawnPoint.SpawnOption opt)
    {
        var prefab = opt.prefab;

        // Position: offset local par rapport au point
        Vector3 pos = p.transform.TransformPoint(opt.positionOffset);

        // Rotation: rotation du point (ou pas) + offset
        Quaternion baseRot = opt.usePointRotation ? p.transform.rotation : Quaternion.identity;
        Quaternion rot = baseRot * Quaternion.Euler(opt.rotationOffsetEuler);

        var go = Instantiate(prefab, pos, rot);

        // Scale: multiplier (par item)
        go.transform.localScale = Vector3.Scale(go.transform.localScale, opt.scaleMultiplier);

        // IMPORTANT: si NetworkObject est sur un child, on le récupère quand même
        var no = go.GetComponentInChildren<NetworkObject>(true);
        if (no == null)
        {
            Debug.LogError($"[PropRandomSpawner] Prefab '{prefab.name}' n'a pas de NetworkObject (root ou child).");
            Destroy(go);
            return false;
        }

        // auto fuel fill si jerrican (child ok)
        var fuel = go.GetComponentInChildren<FuelCanisterProp>(true);
        if (fuel != null && NetworkGameController.Instance != null)
        {
            fuel.FuelPercent.Value = NetworkGameController.Instance.RollFuelCanFillPercentServer();
        }

        no.Spawn(true);
        _spawned.Add(no);

        // incrémenter compteur itemId si possible (child ok)
        var prop = go.GetComponentInChildren<PropPickup>(true);
        if (prop != null)
        {
            if (!_counts.ContainsKey(prop.itemId)) _counts[prop.itemId] = 0;
            _counts[prop.itemId]++;
        }

        return true;
    }

    void BuildCaps()
    {
        _caps = new Dictionary<ItemId, int>();
        if (maxPerItem == null) return;

        for (int i = 0; i < maxPerItem.Count; i++)
        {
            var r = maxPerItem[i];
            if (r == null) continue;
            if (r.maxPerMatch <= 0) continue;
            _caps[r.itemId] = r.maxPerMatch;
        }
    }

    bool CanSpawnItem(ItemId id)
    {
        if (_caps == null || !_caps.TryGetValue(id, out int cap)) return true;
        _counts.TryGetValue(id, out int cur);
        return cur < cap;
    }

    bool CanSpawnPrefab(GameObject prefab)
    {
        var prop = prefab.GetComponentInChildren<PropPickup>(true);
        if (prop == null) return true;
        return CanSpawnItem(prop.itemId);
    }

    PropSpawnPoint.SpawnOption PickOption(PropSpawnPoint p, bool allowEmpty)
    {
        if (p.options == null || p.options.Count == 0)
            return null;

        float emptyW = allowEmpty ? Mathf.Max(0f, p.emptyWeight) : 0f;
        float total = emptyW;

        for (int i = 0; i < p.options.Count; i++)
        {
            var opt = p.options[i];
            if (opt == null || opt.prefab == null) continue;
            if (!CanSpawnPrefab(opt.prefab)) continue;

            total += Mathf.Max(0f, opt.weight);
        }

        if (total <= 0f)
            return null;

        float r = UnityEngine.Random.value * total;

        if (emptyW > 0f && r < emptyW)
            return null;

        r -= emptyW;

        for (int i = 0; i < p.options.Count; i++)
        {
            var opt = p.options[i];
            if (opt == null || opt.prefab == null) continue;
            if (!CanSpawnPrefab(opt.prefab)) continue;

            float w = Mathf.Max(0f, opt.weight);
            if (w <= 0f) continue;

            if (r < w) return opt;
            r -= w;
        }

        return null;
    }

    public void DespawnAll()
    {
        if (!IsServerReady()) return;

        for (int i = _spawned.Count - 1; i >= 0; i--)
        {
            var no = _spawned[i];
            if (no != null && no.IsSpawned)
                no.Despawn(true);
        }

        _spawned.Clear();
    }
}

