using System.Collections.Generic;
using System.Linq;
using Unity.Netcode;
using UnityEngine;

public class RoomManager : MonoBehaviour
{
    public static RoomManager Instance { get; private set; }

    [Header("Rooms (auto si vide)")]
    public List<Room> rooms = new List<Room>();

    public int CurrentRoomId { get; private set; }

    private Dictionary<int, Room> _roomById;

    private void Awake()
    {
        if (Instance != null && Instance != this) { Destroy(gameObject); return; }
        Instance = this;

        // ✅ Unity 6: remplace FindObjectsOfType<Room>(true) (obsolète)
        if (rooms == null || rooms.Count == 0)
            rooms = new List<Room>(
                Object.FindObjectsByType<Room>(FindObjectsInactive.Include, FindObjectsSortMode.None)
            );

        _roomById = new Dictionary<int, Room>();
        foreach (var r in rooms)
        {
            if (r == null) continue;

            if (_roomById.ContainsKey(r.id))
                Debug.LogWarning($"[RoomManager] Duplicate room id={r.id} ({r.name}).");

            _roomById[r.id] = r;
        }
    }

    public List<int> GetRoomsWithSpawn()
    {
        if (_roomById == null) return new List<int>();
        return rooms.Where(r => r != null && r.spawnPoint != null).Select(r => r.id).ToList();
    }

    public bool TryGetSpawn(int roomId, out Vector3 pos)
    {
        pos = default;

        if (_roomById == null || !_roomById.TryGetValue(roomId, out var room) || room == null || room.spawnPoint == null)
            return false;

        pos = room.spawnPoint.position;
        return true;
    }

    public void ApplyTeleportLocalFromServer(int roomId)
    {
        if (_roomById == null || !_roomById.TryGetValue(roomId, out var room) || room == null || room.spawnPoint == null)
        {
            Debug.LogError($"[RoomManager] room/spawnPoint manquant pour id={roomId}");
            return;
        }

        var ownedPlayer = Object.FindObjectsByType<NetworkObject>(FindObjectsInactive.Exclude, FindObjectsSortMode.None)
            .FirstOrDefault(no => no.IsSpawned && no.IsPlayerObject && no.IsOwner);

        if (ownedPlayer == null)
        {
            Debug.LogWarning("[RoomManager] Aucun Player owner trouvé pour téléportation.");
            return;
        }

        var cc = ownedPlayer.GetComponent<CharacterController>();
        if (cc != null) cc.enabled = false;

        ownedPlayer.transform.position = room.spawnPoint.position;

        if (cc != null) cc.enabled = true;

        CurrentRoomId = roomId;
    }

    public void RequestTeleportToRoom(int roomId)
    {
        var gc = NetworkGameController.Instance;
        if (gc == null) return;

        if (NetworkManager.Singleton == null || !NetworkManager.Singleton.IsConnectedClient) return;

        gc.DebugTeleportToRoomServerRpc(roomId);
    }
}

