using System.Collections.Generic;
using Unity.Netcode;
using UnityEngine;

[RequireComponent(typeof(BoxCollider))]
public class RoomPortal : MonoBehaviour
{
    [Header("Rooms")]
    public int roomAId;
    public int roomBId;

    [Header("Detection")]
    public LayerMask playerMask;                  // mets "Player"
    [Min(0.01f)] public float deadZone = 0.08f;   // zone neutre autour du plan
    [Min(0f)] public float switchCooldown = 0.20f;// anti-oscillation
    [Min(0.05f)] public float minPortalDepth = 0.6f; // IMPORTANT: �paisseur mini du volume de d�tection (m)
    public bool includeTriggerColliders = false;

    [Header("Debug")]
    public bool debugLogs = true;

    private BoxCollider _box;

    private readonly Collider[] _hits = new Collider[32];
    private readonly HashSet<ulong> _processedThisTick = new();

    // c�t� r�ellement "valid�" (= room actuelle)
    private readonly Dictionary<ulong, float> _confirmedSide = new();  // -1 ou +1
    // c�t� d�tect� pendant cooldown, � appliquer quand possible
    private readonly Dictionary<ulong, float> _pendingSide = new();    // -1 ou +1 ou 0
    private readonly Dictionary<ulong, double> _nextAllowedSwitch = new();

    void Awake()
    {
        _box = GetComponent<BoxCollider>();
        if (_box == null) _box = gameObject.AddComponent<BoxCollider>();
    }

    void FixedUpdate()
    {
        var nm = NetworkManager.Singleton;
        if (nm == null || !nm.IsServer) return;

        _processedThisTick.Clear();

        Vector3 center = transform.TransformPoint(_box.center);
        Vector3 halfExtents = Vector3.Scale(_box.size * 0.5f, transform.lossyScale);

        // �vite de rater une travers�e si le portail est tr�s fin
        halfExtents.z = Mathf.Max(halfExtents.z, minPortalDepth * 0.5f);

        Quaternion rot = transform.rotation;

        int n = Physics.OverlapBoxNonAlloc(
            center,
            halfExtents,
            _hits,
            rot,
            playerMask,
            includeTriggerColliders ? QueryTriggerInteraction.Collide : QueryTriggerInteraction.Ignore
        );

        double now = nm.ServerTime.Time;

        for (int i = 0; i < n; i++)
        {
            var col = _hits[i];
            if (col == null) continue;

            var no = col.GetComponentInParent<NetworkObject>();
            if (no == null) continue;

            ulong cid = no.OwnerClientId;

            // Un m�me joueur peut avoir plusieurs colliders => on le traite 1 seule fois par tick
            if (!_processedThisTick.Add(cid)) continue;

            var ps = no.GetComponent<NetworkPlayerState>();
            if (ps == null) continue;

            // ignore morts/�chapp�s
            if (!ps.Alive.Value || ps.Escaped.Value) continue;

            // Utilise le centre du CharacterController si possible (plus stable que transform.position)
            Vector3 p = ps.transform.position;
            var cc = ps.GetComponent<CharacterController>();
            if (cc != null)
                p = ps.transform.TransformPoint(cc.center);

            float d = Vector3.Dot(transform.forward, (p - transform.position));

            // trop proche du plan => on ne d�cide rien
            if (Mathf.Abs(d) < deadZone)
                continue;

            float side = Mathf.Sign(d); // +1 => c�t� B, -1 => c�t� A

            // init si premi�re fois
            if (!_confirmedSide.TryGetValue(cid, out float confirmed) || confirmed == 0f)
            {
                _confirmedSide[cid] = side;
                ApplyRoom(ps, cid, side);
                continue;
            }

            // Si on avait une demande en attente et que le cooldown est fini, on l'applique
            if (_pendingSide.TryGetValue(cid, out float pending) && pending != 0f)
            {
                if (!_nextAllowedSwitch.TryGetValue(cid, out double nextOk) || now >= nextOk)
                {
                    // on applique uniquement si le joueur est encore du c�t� pending
                    if (side == pending && pending != confirmed)
                    {
                        _confirmedSide[cid] = pending;
                        ApplyRoom(ps, cid, pending);

                        _pendingSide[cid] = 0f;
                        _nextAllowedSwitch[cid] = switchCooldown > 0f ? now + switchCooldown : 0;
                        continue;
                    }

                    // si le joueur est revenu, on annule le pending
                    if (side == confirmed)
                        _pendingSide[cid] = 0f;
                }
            }

            // pas de changement => rien � faire
            if (side == confirmed)
                continue;

            // changement d�tect�
            if (_nextAllowedSwitch.TryGetValue(cid, out double nextAllowed) && now < nextAllowed)
            {
                // IMPORTANT: on ne change PAS confirmedSide pendant cooldown
                // on garde juste une intention "pending"
                _pendingSide[cid] = side;
                continue;
            }

            // cooldown OK => on applique imm�diatement
            _confirmedSide[cid] = side;
            ApplyRoom(ps, cid, side);

            _pendingSide[cid] = 0f;
            _nextAllowedSwitch[cid] = switchCooldown > 0f ? now + switchCooldown : 0;
        }
    }

    private void ApplyRoom(NetworkPlayerState ps, ulong cid, float side)
    {
        int newRoom = (side > 0f) ? roomBId : roomAId;

        if (ps.CurrentRoom.Value != newRoom)
        {
            ps.CurrentRoom.Value = newRoom;

            if (debugLogs)
                Debug.Log($"[PORTAL][SERVER] {name} client={cid} -> room={newRoom} (side={(side > 0 ? "B" : "A")})");
        }
    }

    void OnDrawGizmosSelected()
    {
        var b = GetComponent<BoxCollider>();
        if (b == null) return;

        Gizmos.matrix = Matrix4x4.TRS(transform.position, transform.rotation, transform.lossyScale);
        Gizmos.color = Color.cyan;
        Gizmos.DrawWireCube(b.center, b.size);

        Gizmos.color = Color.blue;
        Gizmos.DrawLine(Vector3.zero, Vector3.forward * 1.0f);
    }
}

