using Unity.Netcode;
using UnityEngine;

public class RoomVolume : MonoBehaviour
{
    public int roomId;

    [Header("Debug")]
    public bool debugLogs = true;

    private void OnTriggerEnter(Collider other)
    {
        var no = other.GetComponentInParent<NetworkObject>();
        if (no == null) return;

        // On ne reporte qu'avec l'owner (sinon chaque client spam le serveur)
        if (!no.IsOwner) return;

        var ps = no.GetComponent<NetworkPlayerState>();
        if (ps == null) return;

        if (debugLogs)
        {
            Debug.Log($"[RoomVolume][CLIENT] Enter roomId={roomId} by ownerClientId={no.OwnerClientId} volume={name} t={Time.time:F2}");
        }

        ps.ReportRoomServerRpc(roomId);
    }
}

