using Synty.AnimationBaseLocomotion.Samples.InputSystem;
using UnityEngine;

namespace Synty.AnimationBaseLocomotion.Samples
{
    public class SampleCameraController : MonoBehaviour
    {
        private const int _LAG_DELTA_TIME_ADJUSTMENT = 20;

        [Header("Refs")]
        [SerializeField] private GameObject _syntyCharacter;
        [SerializeField] private Camera _mainCamera;

        [SerializeField] private Transform _playerTarget;
        [SerializeField] private Transform _lockOnTarget;

        [Header("Input")]
        [SerializeField] private bool _invertCamera;
        [SerializeField] private bool _hideCursor;
        [SerializeField] private bool _isLockedOn;
        [SerializeField] private float _mouseSensitivity = 5f;

        [Header("TPS Offsets (base)")]
        [SerializeField] private float _cameraDistance = 5f;
        [SerializeField] private float _cameraHeightOffset = 1.6f;
        [SerializeField] private float _cameraHorizontalOffset = 0.35f;
        [SerializeField] private float _cameraTiltOffset = 0f;
        [SerializeField] private Vector2 _cameraTiltBounds = new Vector2(-10f, 45f);

        [Header("Lag")]
        [SerializeField] private float _positionalCameraLag = 1f;
        [SerializeField] private float _rotationalCameraLag = 1f;

        [Header("Collision (distance solver)")]
        [Tooltip("Obstacles seulement (Environment/Props). Le self est ignor� m�me si tu laisses Everything.")]
        [SerializeField] private LayerMask _collisionMask = ~0;

        [SerializeField] private float _collisionRadius = 0.30f;
        [SerializeField] private float _collisionBuffer = 0.08f;

        [Tooltip("Distance mini (coll� au mur => quasi FPS).")]
        [SerializeField] private float _minDistance = 0.05f;

        [Tooltip("Rentr�e (collision) : rapide.")]
        [SerializeField] private float _pullInSpeed = 60f;

        [Tooltip("Sortie (retour TPS) : lent (anti rollback).")]
        [SerializeField] private float _pushOutSpeed = 10f;

        [Tooltip("On garde la distance r�duite pendant X sec apr�s collision.")]
        [SerializeField] private float _holdTime = 0.08f;

        [Tooltip("Il faut X sec sans collision avant de pousser vers l'arri�re.")]
        [SerializeField] private float _releaseDelay = 0.12f;

        [Header("Anti-peek (�crans larges)")]
        [Tooltip("R�duit l'offset �paule vers 0 quand la cam�ra est proche (emp�che de voir autour des murs sur �crans larges).")]
        [SerializeField] private bool _reduceShoulderOffsetWhenClose = true;

        [Tooltip("� partir de cette distance, on commence � r�duire l'offset �paule.")]
        [SerializeField] private float _shoulderReduceStartDistance = 2.0f;

        [Tooltip("� cette distance (tr�s proche), l'offset �paule devient 0 (cam�ra centr�e).")]
        [SerializeField] private float _shoulderReduceEndDistance = 0.3f;

        [Tooltip("Smoothing de l'offset (�vite jitter lat�ral).")]
        [SerializeField] private float _shoulderSmoothing = 25f;

        [Header("FOV (anti wallpeek ultrawide)")]
        [Tooltip("Verrouille le FOV horizontal pour �viter le wallpeek sur �crans ultrawide.")]
        [SerializeField] private bool _lockHorizontalFOV = true;

        [Tooltip("FOV horizontal maximum (recommand�: 90-100).")]
        [SerializeField] private float _targetHorizontalFOV = 90f;

        [Header("Frustum Corner Checks")]
        [Tooltip("V�rifie les coins du frustum pour d�tecter le wallpeek sur les bords.")]
        [SerializeField] private bool _checkFrustumCorners = true;

        [Tooltip("Distance du near plane pour v�rifier les coins (recommand�: 0.5-1.0).")]
        [SerializeField] private float _frustumCheckDistance = 0.8f;

        [Header("Near Clip (�vite voir � travers quand proche)")]
        [SerializeField] private bool _dynamicNearClip = true;
        [SerializeField] private float _nearClipFar = 0.20f;
        [SerializeField] private float _nearClipNear = 0.01f;
        [SerializeField] private float _nearClipSmoothing = 20f;

        private float _cameraInversion;
        private InputReader _inputReader;

        private float _lastAngleX;
        private float _lastAngleY;
        private float _newAngleX;
        private float _newAngleY;

        private Vector3 _lastPosition;
        private Vector3 _newPosition;

        private Transform _syntyCamera;

        private float _currentDistance;
        private float _holdRemaining;
        private float _noCollisionTime;

        private float _effectiveHorizontalOffset;

        private Vector3 _lastCamWorld;

        private float _defaultNear;
        private float _currentNear;

        private readonly RaycastHit[] _hits = new RaycastHit[16];

        private void Start()
        {
            _syntyCamera = transform.GetChild(0);

            if (_mainCamera == null && _syntyCamera != null)
                _mainCamera = _syntyCamera.GetComponentInChildren<Camera>(true);

            _inputReader = _syntyCharacter != null ? _syntyCharacter.GetComponent<InputReader>() : null;
            _playerTarget = _syntyCharacter != null ? _syntyCharacter.transform.Find("SyntyPlayer_LookAt") : null;
            _lockOnTarget = _syntyCharacter != null ? _syntyCharacter.transform.Find("TargetLockOnPos") : null;

            if (_hideCursor)
            {
                Cursor.visible = false;
                Cursor.lockState = CursorLockMode.Locked;
            }

            _cameraInversion = _invertCamera ? 1f : -1f;

            if (_playerTarget != null)
            {
                transform.position = _playerTarget.position;
                transform.rotation = _playerTarget.rotation;
            }

            _lastPosition = transform.position;

            _currentDistance = Mathf.Max(_minDistance, _cameraDistance);
            _holdRemaining = 0f;
            _noCollisionTime = 999f;

            _effectiveHorizontalOffset = _cameraHorizontalOffset;

            ApplyLocalCameraTransform(_currentDistance, _effectiveHorizontalOffset);

            _lastCamWorld = _syntyCamera.position;

            if (_mainCamera != null)
            {
                _defaultNear = _mainCamera.nearClipPlane;
                _currentNear = _dynamicNearClip ? _nearClipFar : _defaultNear;
                _mainCamera.nearClipPlane = _currentNear;

                if (_lockHorizontalFOV)
                {
                    AdjustFOVForAspectRatio();
                }
            }
        }

        private void OnDisable()
        {
            if (_mainCamera != null && _defaultNear > 0f)
                _mainCamera.nearClipPlane = _defaultNear;
        }

        private void LateUpdate()
        {
            if (_inputReader == null || _playerTarget == null || _syntyCamera == null)
                return;

            float dt = Time.deltaTime;

            float positionalFollowSpeed = 1f / (_positionalCameraLag / _LAG_DELTA_TIME_ADJUSTMENT);
            float rotationalFollowSpeed = 1f / (_rotationalCameraLag / _LAG_DELTA_TIME_ADJUSTMENT);

            float rotX = _inputReader._mouseDelta.y * _cameraInversion * _mouseSensitivity;
            float rotY = _inputReader._mouseDelta.x * _mouseSensitivity;

            _newAngleX += rotX;
            _newAngleX = Mathf.Clamp(_newAngleX, _cameraTiltBounds.x, _cameraTiltBounds.y);
            _newAngleX = Mathf.Lerp(_lastAngleX, _newAngleX, rotationalFollowSpeed * dt);

            if (_isLockedOn && _lockOnTarget != null)
            {
                Vector3 aimVector = _lockOnTarget.position - _playerTarget.position;
                Quaternion targetRotation = Quaternion.LookRotation(aimVector);
                targetRotation = Quaternion.Lerp(transform.rotation, targetRotation, rotationalFollowSpeed * dt);
                _newAngleY = targetRotation.eulerAngles.y;
            }
            else
            {
                _newAngleY += rotY;
                _newAngleY = Mathf.Lerp(_lastAngleY, _newAngleY, rotationalFollowSpeed * dt);
            }

            _newPosition = _playerTarget.position;
            _newPosition = Vector3.Lerp(_lastPosition, _newPosition, positionalFollowSpeed * dt);

            transform.position = _newPosition;
            transform.eulerAngles = new Vector3(_newAngleX, _newAngleY, 0f);

            float desiredDistance = Mathf.Max(_minDistance, _cameraDistance);

            bool collided;
            float solvedDistance = SolveDistance(desiredDistance, _effectiveHorizontalOffset, out collided);

            if (collided)
            {
                _holdRemaining = _holdTime;
                _noCollisionTime = 0f;
            }
            else
            {
                _noCollisionTime += dt;
            }

            if (_holdRemaining > 0f)
                _holdRemaining -= dt;

            bool canPushOut = (_holdRemaining <= 0f) && (_noCollisionTime >= _releaseDelay);

            if (solvedDistance < _currentDistance)
            {
                _currentDistance = Mathf.MoveTowards(_currentDistance, solvedDistance, _pullInSpeed * dt);
            }
            else if (canPushOut)
            {
                _currentDistance = Mathf.MoveTowards(_currentDistance, solvedDistance, _pushOutSpeed * dt);
            }
            else
            {
                _currentDistance = Mathf.Min(_currentDistance, solvedDistance);
            }

            float targetOffsetX = _cameraHorizontalOffset;

            if (_reduceShoulderOffsetWhenClose)
            {
                float t = Mathf.InverseLerp(_shoulderReduceEndDistance, _shoulderReduceStartDistance, _currentDistance);
                t = Mathf.Clamp01(t);
                targetOffsetX = Mathf.Lerp(0f, _cameraHorizontalOffset, t);
            }

            _effectiveHorizontalOffset = Mathf.Lerp(_effectiveHorizontalOffset, targetOffsetX, _shoulderSmoothing * dt);

            ApplyLocalCameraTransform(_currentDistance, _effectiveHorizontalOffset);

            UpdateNearClip(dt);

            _lastPosition = _newPosition;
            _lastAngleX = _newAngleX;
            _lastAngleY = _newAngleY;
            _lastCamWorld = _syntyCamera.position;
        }

        private void ApplyLocalCameraTransform(float distance, float offsetX)
        {
            _syntyCamera.localPosition = new Vector3(offsetX, _cameraHeightOffset, -distance);
            _syntyCamera.localEulerAngles = new Vector3(_cameraTiltOffset, 0f, 0f);
        }

        private float SolveDistance(float desiredDistance, float offsetX, out bool collided)
        {
            desiredDistance = Mathf.Max(_minDistance, desiredDistance);

            Vector3 origin = transform.TransformPoint(new Vector3(offsetX, _cameraHeightOffset, 0f));
            Vector3 desiredWorld = transform.TransformPoint(new Vector3(offsetX, _cameraHeightOffset, -desiredDistance));

            Vector3 toCam = desiredWorld - origin;
            float dist = toCam.magnitude;

            collided = false;

            if (dist <= 0.0001f)
                return _minDistance;

            Vector3 dir = toCam / dist;

            float allowed = desiredDistance;

            float hitDist;
            if (SphereCastFiltered(origin, dir, dist, out hitDist))
            {
                allowed = Mathf.Clamp(hitDist - _collisionBuffer, _minDistance, desiredDistance);
                collided = true;
            }

            if (_checkFrustumCorners && _mainCamera != null)
            {
                float frustumDist = CheckFrustumCorners(origin, desiredWorld);
                if (frustumDist < allowed)
                {
                    allowed = Mathf.Max(_minDistance, frustumDist);
                    collided = true;
                }
            }

            Vector3 sweep = desiredWorld - _lastCamWorld;
            float sweepDist = sweep.magnitude;
            if (sweepDist > 0.0001f)
            {
                Vector3 sweepDir = sweep / sweepDist;
                float sweepHitDist;
                if (SphereCastFiltered(_lastCamWorld, sweepDir, sweepDist, out sweepHitDist))
                {
                    collided = true;
                }
            }

            return allowed;
        }

        private float CheckFrustumCorners(Vector3 pivotPos, Vector3 camPos)
        {
            float minDist = float.PositiveInfinity;

            float halfHeight = Mathf.Tan(_mainCamera.fieldOfView * 0.5f * Mathf.Deg2Rad) * _frustumCheckDistance;
            float halfWidth = halfHeight * _mainCamera.aspect;

            Vector3[] corners = new Vector3[4]
            {
                new Vector3(-halfWidth, -halfHeight, _frustumCheckDistance),
                new Vector3(halfWidth, -halfHeight, _frustumCheckDistance),
                new Vector3(-halfWidth, halfHeight, _frustumCheckDistance),
                new Vector3(halfWidth, halfHeight, _frustumCheckDistance)
            };

            Vector3 camToCheck = Vector3.Lerp(pivotPos, camPos, 0.95f);
            Quaternion camRot = Quaternion.Euler(_newAngleX + _cameraTiltOffset, _newAngleY, 0f);

            foreach (var corner in corners)
            {
                Vector3 worldCorner = camToCheck + camRot * corner;
                Vector3 dirToCorner = (worldCorner - pivotPos).normalized;
                float distToCheck = Vector3.Distance(pivotPos, worldCorner);

                RaycastHit hit;
                if (Physics.Raycast(pivotPos, dirToCorner, out hit, distToCheck, _collisionMask, QueryTriggerInteraction.Ignore))
                {
                    Transform self = _syntyCharacter != null ? _syntyCharacter.transform : null;
                    if (self == null || !hit.collider.transform.IsChildOf(self))
                    {
                        float safeDist = hit.distance - _collisionBuffer;
                        if (safeDist < minDist) minDist = safeDist;
                    }
                }
            }

            return minDist;
        }

        private bool SphereCastFiltered(Vector3 origin, Vector3 dir, float dist, out float nearestHitDistance)
        {
            nearestHitDistance = float.PositiveInfinity;

            int count = Physics.SphereCastNonAlloc(
                origin,
                _collisionRadius,
                dir,
                _hits,
                dist,
                _collisionMask,
                QueryTriggerInteraction.Ignore
            );

            if (count <= 0) return false;

